C ================================================================
C UEL_TWOPHASE_UPS.for
C
C First compilable skeleton for a 2D plane-strain
C u - pw - Sn three-field user element.
C
C This file is intentionally written as a development skeleton:
C   - keep the data flow and block structure explicit;
C   - keep the UEL callable and compilable;
C   - leave clear replacement points for the real weak form,
C     consistent tangent, constitutive update and coupling terms.
C
C Units used throughout this file:
C   length   : m
C   mass     : kg
C   time     : s
C   stress   : Pa
C ================================================================

      SUBROUTINE UEL(RHS,AMATRX,SVARS,ENERGY,NDOFEL,NRHS,NSVARS,
     1 PROPS,NPROPS,COORDS,MCRD,NNODE,U,DU,V,A,JTYPE,TIME,DTIME,
     2 KSTEP,KINC,JELEM,PARAMS,NDLOAD,JDLTYP,ADLMAG,PREDEF,NPREDF,
     3 LFLAGS,MLVARX,DDLMAG,MDLOAD,PNEWDT,JPROPS,NJPROP,PERIOD)

      INCLUDE 'ABA_PARAM.INC'

C ---------------------------
C Abaqus interface variables
C ---------------------------
C These are the standard arguments passed in by Abaqus/Standard.
C Keep their meaning unchanged so the file stays compatible with the
C official UEL calling convention and can later be dropped into an
C Abaqus job without changing the interface signature.
      INTEGER NDOFEL, NRHS, NSVARS, NPROPS, MCRD, NNODE
      INTEGER JTYPE, KSTEP, KINC, JELEM, NDLOAD, NPREDF
      INTEGER MLVARX, MDLOAD, NJPROP
      INTEGER JDLTYP(MDLOAD,*), LFLAGS(*), JPROPS(*)
      INTEGER DEBUG_UEL

      DOUBLE PRECISION RHS(MLVARX,NRHS)
      DOUBLE PRECISION AMATRX(NDOFEL,NDOFEL)
      DOUBLE PRECISION SVARS(NSVARS), ENERGY(8)
      DOUBLE PRECISION PROPS(*), COORDS(MCRD,NNODE)
      DOUBLE PRECISION U(NDOFEL), DU(MLVARX,NRHS)
      DOUBLE PRECISION V(NDOFEL), A(NDOFEL)
      DOUBLE PRECISION TIME(2), DTIME, PARAMS(*)
      DOUBLE PRECISION ADLMAG(MDLOAD,*), PREDEF(2,NPREDF,NNODE)
      DOUBLE PRECISION DDLMAG(MDLOAD,*), PNEWDT, PERIOD

C ---------------------------
C Local constants
C ---------------------------
C The constants below define the first-stage element shape and the
C minimal array dimensions used by the skeleton. If future versions
C move to another element topology or a different number of degrees
C of freedom, this is one of the first blocks that must be updated.
C UEL_BUILD_STAMP = CP189B1_LOCALPICARD_ENGPARITY_4185_4260_R4320
C CAPRAMP_KEYS = DBG_R1B_PEQ_CAPREF_RAMP DBG_CAPRAMP_MODE
C CAPRAMP_KEYS = DBG_CAPRAMP_LAMBDA DBG_CAPRAMP_TIME DBG_CAPRAMP_AUDIT
C CAPRAMP_KEYS = DBG_CAPRAMP_TANGENT_SCALE DBG_CAPRAMP_FORCE_SCALE
C CAPRAMP_KEYS = DBG_CAPRAMP_FORCE_SIGN
C CAPRAMP_KEYS = DBG_CP179B2_TAN_RAMP DBG_CP179B2_TAN_RAMP_START
C CAPRAMP_KEYS = DBG_CP179B2_TAN_RAMP_END
C CAPRAMP_KEYS = DBG_CAPRAMP_WELLB_FORCE_REG DBG_CAPRAMP_WELLB_REG_RADIUS
C CAPRAMP_KEYS = DBG_CAPRAMP_PC_FRONT_REG DBG_CAPRAMP_PC_FRONT_MIN
      INTEGER NDIM, NNODEL, NDOFN, NSTR, NGAUSS, NSVARGP
      PARAMETER (NDIM=2)
      PARAMETER (NNODEL=4)
      PARAMETER (NDOFN=4)
      PARAMETER (NSTR=3)
      PARAMETER (NGAUSS=4)
      PARAMETER (NSVARGP=48)

      DOUBLE PRECISION ZERO, ONE, HALF, EPS, KSTAB
      PARAMETER (ZERO=0.0D0)
      PARAMETER (ONE =1.0D0)
      PARAMETER (HALF=0.5D0)
      PARAMETER (EPS =1.0D-12)
      PARAMETER (KSTAB=1.0D-12)
      DOUBLE PRECISION DTIME_MIN
      PARAMETER (DTIME_MIN=1.0D-12)

C ---------------------------
C PROPS layout for the current development stage
C ---------------------------
C Keep the material / closure parameter order fixed so the UEL, the
C Python driver and the future input-deck generator stay synchronized.
C
C   PROPS(1)  = E_MOD        ! Young's modulus [Pa]
C   PROPS(2)  = NU_MOD       ! Poisson ratio [-]
C   PROPS(3)  = ALPHA_BIOT   ! Biot coefficient [-]
C   PROPS(4)  = STORW0       ! Wetting-phase storage coefficient [-]
C   PROPS(5)  = MU_W0        ! Wetting-phase viscosity [Pa*s]
C   PROPS(6)  = RHO_N0       ! Non-wetting-phase density [kg/m^3]
C   PROPS(7)  = MU_N0        ! Non-wetting-phase viscosity [Pa*s]
C   PROPS(8)  = SWR          ! Residual wetting saturation [-]
C   PROPS(9)  = SNR          ! Residual non-wetting saturation [-]
C   PROPS(10) = PB           ! Capillary entry pressure [Pa]
C   PROPS(11) = LAMBDA_BC    ! Brooks-Corey pore-size index [-]
C   PROPS(12) = NW           ! Corey exponent for wetting rel. perm. [-]
C   PROPS(13) = NN           ! Corey exponent for non-wetting rel. perm. [-]
C   PROPS(14) = BETA_PHI     ! Porosity-volumetric-strain coupling [-]
C   PROPS(15) = SN_SEED      ! Mini-case seed for the active-zone patch
C   PROPS(16) = K0_ABS       ! Reference absolute permeability [m^2]
C   PROPS(17) = SIGMA0_EFF   ! Reference mean effective stress (Abaqus sign)
C   PROPS(18) = A_SIGMA      ! Stress sensitivity coefficient (>0)
C   PROPS(19) = CB0          ! Reference cementation / damage proxy
C   PROPS(20) = A_CB         ! Cb sensitivity coefficient (stage-2 placeholder)
C   PROPS(21) = KABS_MIN     ! Lower bound of absolute permeability [m^2]
C   PROPS(22) = KABS_MAX     ! Upper bound of absolute permeability [m^2]
C   PROPS(23) = MECH_SV_FREEZE ! Debug switch: freeze mech-related SVARS
C   PROPS(24) = STATE_WRITEBACK_FREEZE ! Debug switch: freeze all SVARS
C   PROPS(25) = MECH_ONLY_COMPRESS ! Debug switch: keep only RU/KUU in
C                                  ! compression-step diagnostics
C   PROPS(26) = STRICT_MECH_COMPRESS ! Debug switch: bypass all flow
C                                  ! assembly in compression step
C   PROPS(27) = NO_WRITEBACK_COMPRESS ! Debug switch: skip Gauss-point
C                                  ! state writeback in compression step
C
C The numbering is intentionally frozen in this first UEL series. If a
C future version needs more parameters, append them after PROPS(22)
C instead of reshuffling the existing slots.

C ---------------------------
C Local element-level vars
C ---------------------------
C These variables live at the element level and are used by the UEL
C main routine to hold the current element residual, tangent, local
C degrees of freedom and the field-block assembly matrices.
      INTEGER I, J, IGP
