      CALL GET_ENVIRONMENT_VARIABLE('DBG_S_ANCHOR_SNREF', DBG_LOC_TAG)
      IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
         READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT) DBG_S_ANCHOR_SNREF
         IF (DBG_IOSTAT .NE. 0) DBG_S_ANCHOR_SNREF = 1.0D-1
      END IF
      IF (DBG_FIELD_CAPACITY_REG .GT. 0.5D0) THEN
         DBG_P_CAPACITY_REG = 1.0D0
         DBG_S_CAPACITY_REG = 1.0D0
         IF (DBG_P_CAPACITY_ETA .LE. 0.0D0)
     1      DBG_P_CAPACITY_ETA = DBG_FIELD_CAPACITY_ETA
         IF (DBG_S_CAPACITY_ETA .LE. 0.0D0)
     1      DBG_S_CAPACITY_ETA = DBG_FIELD_CAPACITY_ETA
      END IF
      IF (DBG_FIELD_ANCHOR_REG .GT. 0.5D0) THEN
         DBG_P_ANCHOR_REG = 1.0D0
         DBG_S_ANCHOR_REG = 1.0D0
         IF (DBG_P_ANCHOR_ETA .LE. 0.0D0)
     1      DBG_P_ANCHOR_ETA = DBG_FIELD_ANCHOR_ETA
         IF (DBG_S_ANCHOR_ETA .LE. 0.0D0)
     1      DBG_S_ANCHOR_ETA = DBG_FIELD_ANCHOR_ETA
      END IF
      CALL GET_ENVIRONMENT_VARIABLE('DBG_LOC_MINIMAL', DBG_LOC_TAG)
      IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
         READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT) DBG_LOC_MINIMAL
         IF (DBG_IOSTAT .NE. 0) DBG_LOC_MINIMAL = 0.0D0
      END IF
      IF (DBG_SVARS_SANITIZE_INIT .EQ. 0) THEN
         DBG_SVARS_SANITIZE_FILE = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_SVARS_SANITIZE_MODE',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
            IF (DBG_LOC_TAG .EQ. 'pivot_ring') THEN
               DBG_SVARS_SANITIZE_MODE_I = 1
            ELSE
               DBG_SVARS_SANITIZE_MODE_I = 0
            END IF
         END IF
         CALL GET_ENVIRONMENT_VARIABLE('DBG_SVARS_SANITIZE_FILE',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) DBG_SVARS_SANITIZE_FILE =
     1        DBG_LOC_TAG
         CALL GET_ENVIRONMENT_VARIABLE('DBG_SVARS_PW_TOP',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
            READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT)
     1           DBG_SVARS_SANITIZE_PW_TOP
            IF (DBG_IOSTAT .NE. 0) DBG_SVARS_SANITIZE_PW_TOP = 1.0D7
         END IF
         CALL GET_ENVIRONMENT_VARIABLE('DBG_SVARS_PW_BOTTOM',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
            READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT)
     1           DBG_SVARS_SANITIZE_PW_BOTTOM
            IF (DBG_IOSTAT .NE. 0) DBG_SVARS_SANITIZE_PW_BOTTOM =
     1           2.0D7
         END IF
         CALL GET_ENVIRONMENT_VARIABLE('DBG_SVARS_Y_MIN',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
            READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT)
     1           DBG_SVARS_SANITIZE_Y_MIN
            IF (DBG_IOSTAT .NE. 0) DBG_SVARS_SANITIZE_Y_MIN = 0.0D0
         END IF
         CALL GET_ENVIRONMENT_VARIABLE('DBG_SVARS_Y_MAX',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
            READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT)
     1           DBG_SVARS_SANITIZE_Y_MAX
            IF (DBG_IOSTAT .NE. 0) DBG_SVARS_SANITIZE_Y_MAX = 1.0D3
         END IF
         IF (DBG_SVARS_SANITIZE_MODE_I .EQ. 1) THEN
            CALL UPS_LOAD_INT_LIST_FILE(DBG_SVARS_SANITIZE_FILE,
     1           DBG_SVARS_SANITIZE_ELEMS, 256,
     2           DBG_SVARS_SANITIZE_NELEM, DBG_SVARS_SANITIZE_IOS)
            IF (DBG_SVARS_SANITIZE_IOS .NE. 0 .OR.
     1          DBG_SVARS_SANITIZE_NELEM .LE. 0) THEN
               WRITE(*,*) '!!! SVARS sanitize mode disabled: failed to ',
     1              'load whitelist from ', DBG_SVARS_SANITIZE_FILE
               DBG_SVARS_SANITIZE_MODE_I = 0
               DBG_SVARS_SANITIZE_NELEM = 0
            ELSE
               WRITE(*,*) '>> DBG_SVARS_SANITIZE_MODE = pivot_ring'
               WRITE(*,*) '>> DBG_SVARS_SANITIZE_FILE = ',
     1              DBG_SVARS_SANITIZE_FILE
               WRITE(*,*) '>> DBG_SVARS_SANITIZE_NELEM = ',
     1              DBG_SVARS_SANITIZE_NELEM
               WRITE(*,*) '>> DBG_SVARS_PW_TOP = ',
     1              DBG_SVARS_SANITIZE_PW_TOP
               WRITE(*,*) '>> DBG_SVARS_PW_BOTTOM = ',
     1              DBG_SVARS_SANITIZE_PW_BOTTOM
               WRITE(*,*) '>> DBG_SVARS_Y_MIN = ',
     1              DBG_SVARS_SANITIZE_Y_MIN
               WRITE(*,*) '>> DBG_SVARS_Y_MAX = ',
     1              DBG_SVARS_SANITIZE_Y_MAX
            END IF
         END IF
         DBG_SVARS_SANITIZE_INIT = 1
      END IF
      IF (DBG_SVARS_SANITIZE_MODE_I .NE. 0) THEN
         WRITE(*,*) 'ERROR cp189A1 forbids physics-used SVARS sanitize'
         STOP
      END IF

      BOOT_HOLD = 0
C        BOOT_HOLD retired debug hook: kept disabled for the
C        released baseline so the bootstrap does not modify the
C        first increment any more.

      IF (DBG_LOC_INIT .EQ. 0) THEN
         DBG_LOC_ELEM_FILE = ' '
         DBG_LOC_OUTFILE =
     1        'C:/Users/Ldd/AppData/Local/Temp/uel_local_matrix_diag.txt'
         CALL GET_ENVIRONMENT_VARIABLE('DBG_LOC_ELEM_FILE',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) DBG_LOC_ELEM_FILE = DBG_LOC_TAG
         CALL GET_ENVIRONMENT_VARIABLE('DBG_LOC_OUTFILE',
     1        DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) DBG_LOC_OUTFILE = DBG_LOC_TAG
         CALL GET_ENVIRONMENT_VARIABLE('DBG_LOC_STEP', DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
            READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT) DBG_LOC_STEP
            IF (DBG_IOSTAT .NE. 0) DBG_LOC_STEP = 4
         END IF
         CALL GET_ENVIRONMENT_VARIABLE('DBG_LOC_INC', DBG_LOC_TAG)
         IF (LEN_TRIM(DBG_LOC_TAG) .GT. 0) THEN
            READ(DBG_LOC_TAG,*,IOSTAT=DBG_IOSTAT) DBG_LOC_INC
            IF (DBG_IOSTAT .NE. 0) DBG_LOC_INC = 1
         END IF
         CALL UPS_LOAD_INT_LIST_FILE(DBG_LOC_ELEM_FILE, DBG_LOC_ELEMS,
     1        256, DBG_LOC_NELEM, DBG_IOSTAT)
         IF (DBG_LOC_NELEM .GT. 0) THEN
            WRITE(*,*) 'UEL local diag whitelist loaded: ',
     1                 DBG_LOC_NELEM
            WRITE(*,*) 'UEL local diag outfile: ',
     1                 DBG_LOC_OUTFILE
         END IF
         DBG_LOC_INIT = 1
      END IF
      DBG_LOC_ACTIVE = .FALSE.
      IF (DBG_LOC_NELEM .GT. 0) THEN
         IF (KSTEP .EQ. DBG_LOC_STEP .AND. KINC .EQ. DBG_LOC_INC) THEN
            DO I = 1, DBG_LOC_NELEM
               IF (JELEM .EQ. DBG_LOC_ELEMS(I)) THEN
                  DBG_LOC_ACTIVE = .TRUE.
               END IF
            END DO
         END IF
      END IF

      IF (NNODE .NE. NNODEL) THEN
         WRITE(*,*) 'UEL_TWOPHASE_UPS: unexpected NNODE = ', NNODE
      ENDIF

      IF (NDOFEL .NE. NNODEL*NDOFN) THEN
         WRITE(*,*) 'UEL_TWOPHASE_UPS: unexpected NDOFEL = ', NDOFEL
      ENDIF

C ================================================================
C 1. Initialize outputs
C ================================================================
C All residual and tangent containers are explicitly zeroed before
C any Gauss-point contribution is accumulated. This makes the code
C easier to debug and avoids hidden carry-over from previous calls.
      CALL UPS_ZERO_RHS(RHS, MLVARX, NRHS)
      CALL UPS_ZERO_MAT(AMATRX, NDOFEL, NDOFEL)

      CALL UPS_ZERO_VEC(RE,16)
      CALL UPS_ZERO_MAT(KE,16,16)

      CALL UPS_ZERO_VEC(RU,8)
      CALL UPS_ZERO_VEC(RP,4)
      CALL UPS_ZERO_VEC(RS,4)

      CALL UPS_ZERO_MAT(KUU,8,8)
      CALL UPS_ZERO_MAT(KUP,8,4)
      CALL UPS_ZERO_MAT(KUS,8,4)
      CALL UPS_ZERO_MAT(KPU,4,8)
      CALL UPS_ZERO_MAT(KPP,4,4)
      CALL UPS_ZERO_MAT(KPS,4,4)
      CALL UPS_ZERO_MAT(KSU,4,8)
      CALL UPS_ZERO_MAT(KSP,4,4)
      CALL UPS_ZERO_MAT(KSS,4,4)
      CALL UPS_WP10I3_ZERO_KSS_AUDIT()
      CALL UPS_ZERO_VEC(DBG_GP_PW,4)
      CALL UPS_ZERO_VEC(DBG_GP_SN,4)
      CALL UPS_ZERO_VEC(DBG_GP_SW,4)
      CALL UPS_ZERO_VEC(DBG_GP_PC,4)
      CALL UPS_ZERO_VEC(DBG_GP_PEQ,4)
      CALL UPS_ZERO_VEC(DBG_GP_KABS,4)
      CALL UPS_ZERO_VEC(DBG_GP_PHI,4)
      CALL UPS_ZERO_VEC(DBG_GP_PW_OLD,4)
      CALL UPS_ZERO_VEC(DBG_GP_SN_OLD,4)
      CALL UPS_ZERO_VEC(DBG_GP_EPSV_OLD,4)
      CALL UPS_ZERO_VEC(DBG_GP_SE_RAW,4)
      CALL UPS_ZERO_VEC(DBG_GP_SE_CLAMP,4)
      CALL UPS_ZERO_VEC(DBG_GP_DS,4)
      CALL UPS_ZERO_VEC(DBG_GP_CHI,4)
      CALL UPS_ZERO_VEC(DBG_GP_DCHI_DSN,4)
      CALL UPS_ZERO_VEC(DBG_GP_KRW,4)
      CALL UPS_ZERO_VEC(DBG_GP_KRN,4)
      CALL UPS_ZERO_VEC(DBG_GP_DSE_DSN,4)
      CALL UPS_ZERO_VEC(DBG_GP_DKRW_DSN,4)
      CALL UPS_ZERO_VEC(DBG_GP_DKRN_DSN,4)
      CALL UPS_ZERO_VEC(DBG_GP_DPEQ_DPW,4)
      CALL UPS_ZERO_VEC(DBG_GP_DPEQ_DSN,4)
      CALL UPS_ZERO_VEC(DBG_GP_SIGMA_MEFF,4)
      DBG_FRONT_PNEWDT_FACTOR = ONE

      CALL UPS_BUILD_INDEX(IU, IP, IS)

C ================================================================
C 2. Unpack DOFs
C ================================================================
C Abaqus passes the element DOFs in node-major order:
C   [ux1, uy1, pw1, sn1, ux2, uy2, pw2, sn2, ...]
C Internally we split them into field blocks:
C   DE -> displacement block
C   PE -> wetting-phase pressure block
C   SE -> non-wetting saturation block
      CALL UPS_UNPACK_DOF(U, DE, PE, SE)
      CALL GET_ENVIRONMENT_VARIABLE('DBG_MECH_PROBE_TAG', DBG_PROBE_TAG)
      DBG_R1B_PROBE = (DBG_PROBE_TAG(1:3) .EQ. 'r1b')

       IF (DEBUG_UEL .NE. 0 .AND. JELEM .EQ. 1) THEN
          IF (.NOT. DBG_FILE_OPEN) THEN
             CALL UPS_BUILD_DBG_PATH(DBG_PATH)
             OPEN(98,FILE=DBG_PATH,STATUS='REPLACE',IOSTAT=DBG_IOSTAT)
             IF (DBG_IOSTAT .EQ. 0) THEN
                DBG_FILE_OPEN = .TRUE.
                DBG_MECH_FILE = .TRUE.
                WRITE(98,*) '=== DBG_MECH PROBE START ==='
                WRITE(98,*) 'JELEM=', JELEM, ' KSTEP=', KSTEP,
     1                     ' KINC=', KINC
                WRITE(98,*) 'NPROPS=', NPROPS, ' NJPROP=', NJPROP
             ELSE
                DBG_FILE_OPEN = .FALSE.
                DBG_MECH_FILE = .FALSE.
                WRITE(*,*) 'UEL_TWOPHASE_UPS: dbg open failed, IOSTAT=',
     1                    DBG_IOSTAT
             END IF
          END IF
       END IF

      IF (DBG_MECH_FILE) THEN
         WRITE(*,*) '=== DBG_MECH: AFTER UPS_UNPACK_DOF ==='
         WRITE(98,*) '=== DBG_MECH: AFTER UPS_UNPACK_DOF ==='
         WRITE(*,*) 'DE(1:8) = ', DE(1), DE(2), DE(3), DE(4),
     1              DE(5), DE(6), DE(7), DE(8)
         WRITE(98,*) 'DE(1:8) = ', DE(1), DE(2), DE(3), DE(4),
     1              DE(5), DE(6), DE(7), DE(8)
         WRITE(*,*) 'PE(1:4) = ', PE(1), PE(2), PE(3), PE(4)
         WRITE(98,*) 'PE(1:4) = ', PE(1), PE(2), PE(3), PE(4)
         WRITE(*,*) 'SE(1:4) = ', SE(1), SE(2), SE(3), SE(4)
         WRITE(98,*) 'SE(1:4) = ', SE(1), SE(2), SE(3), SE(4)
      END IF

C ================================================================
C 3. Gauss loop
C ================================================================
C Every Gauss point follows the same evaluation chain:
C   shape/Jacobian -> kinematics -> closure -> update -> constitutive
C   -> residual/tangent contribution -> state-variable writeback.
C
C This is the core flow that later versions should preserve even when
C the placeholder physics is replaced by the real weak form.
      DO I = 1, 4
         CP165_MAIN_GP_LOOP_HIT(I) = 0
         CP165_RP_ENTER_HIT(I) = 0
         CP165_RP_EXIT_HIT(I) = 0
         CP165_RS_ENTER_HIT(I) = 0
         CP165_RS_EXIT_HIT(I) = 0
         CP165_RU_ENTER_HIT(I) = 0
         CP165_RU_EXIT_HIT(I) = 0
         CP165_SVARS_WRITE_HIT(I) = 0
         CP165_CSV_WRITE_HIT(I) = 0
         CP165_RP_DUMMY_HIT(I) = 0
         CP165_RS_DUMMY_HIT(I) = 0
         CP165_RU_DUMMY_HIT(I) = 0
      END DO

      DO IGP = 1, NGAUSS
         CP165_MAIN_GP_LOOP_HIT(IGP) = 1
         CP165_RP_ENTER_CUR = 0
         CP165_RP_EXIT_CUR = 0
         CP165_RS_ENTER_CUR = 0
         CP165_RS_EXIT_CUR = 0
         CP165_RU_ENTER_CUR = 0
         CP165_RU_EXIT_CUR = 0
         CP165_RP_DUMMY_CUR = 0
         CP165_RS_DUMMY_CUR = 0
         CP165_RU_DUMMY_CUR = 0

C ---- 3.1 gauss coordinates and weight
C The first-stage skeleton uses a standard 2x2 Gauss rule.
C If future versions change the integration strategy, this is the
C wrapper that should be replaced first.
         CALL UPS_GAUSS_Q4(IGP, XI, ETA, WT)

C ---- 3.2 read old state variables
C The SVARS array stores the last converged state for each Gauss point.
C We read the current Gauss-point block here and update only that block.
         CALL UPS_SVARS_READ(SVARS, NSVARS, IGP, NSVARGP, SV_GP_OLD)
         CALL UPS_CAPREF_COMMITTED_SELECT(SV_GP_OLD(13),
     1      SV_GP_OLD(14), SV_GP_OLD(5), SV_GP_OLD(1),
     2      CAP_REF_USE, CAP_REF_VALID_OUT,
     3      CAP_REF_FALLBACK_FLAG)
         CALL UPS_CP170_SVARS_RECON_AUDIT(KSTEP, KINC, JELEM, IGP,
     1      NSVARGP, SV_GP_OLD)
         SIGEFF_OLD_GP(1) = SV_GP_OLD(10)
         SIGEFF_OLD_GP(2) = SV_GP_OLD(11)
         SIGEFF_OLD_GP(3) = SV_GP_OLD(12)

C ---- 3.3 shape functions and Jacobian
C This block converts the parent-space Q4 interpolation into global
C coordinates and provides the derivatives needed by all field updates.
          CALL UPS_SHAPE_Q4(XI, ETA, N, DNXI, DNETA)
          CALL UPS_JACOBIAN_Q4(COORDS, MCRD, NNODEL, DNXI, DNETA,
     1                        JMAT, INVJ, DETJ, DNX, DNY)

          IF (DETJ .LE. EPS) THEN
            WRITE(*,*) 'UEL_TWOPHASE_UPS: bad DETJ at element ',
     1                 JELEM, ' gp=', IGP, ' DETJ=', DETJ
             DETJ = EPS
          ENDIF

         X_GP = 0.0D0
         Y_GP = 0.0D0
         DO I = 1, NNODEL
            IF (MCRD .GE. 1) X_GP = X_GP + N(I) * COORDS(1, I)
            IF (MCRD .GE. 2) Y_GP = Y_GP + N(I) * COORDS(2, I)
         END DO

         DBG_SVARS_SANITIZE_ACTIVE = .FALSE.

C ---- 3.4 kinematics
C Here the three fields are interpolated/derived independently:
C   - displacement -> strain and volumetric strain
C   - pw           -> pressure and pressure gradient
C   - Sn           -> saturation and saturation gradient
          CALL UPS_KINEM_U(DE, DNX, DNY, BU, EPS_GP, EPSV_GP)
          CALL UPS_KINEM_PW(PE, N, DNX, DNY, PW_GP, GPW)
          IF (DBG_LOC_ACTIVE) THEN
             DBG_GP_PW_OLD(IGP)   = PW_OLD_EFF
             DBG_GP_SN_OLD(IGP)   = SN_OLD_EFF
             DBG_GP_EPSV_OLD(IGP) = EPSV_OLD_EFF
          END IF

          IF (DBG_MECH_FILE .AND. IGP .EQ. 1) THEN
             WRITE(*,*) '=== DBG_MECH: GEOMETRY / BU ==='
             WRITE(98,*) '=== DBG_MECH: GEOMETRY / BU ==='
             WRITE(*,*) 'IGP   = ', IGP
             WRITE(98,*) 'IGP   = ', IGP
             WRITE(*,*) 'detJ  = ', DETJ
             WRITE(98,*) 'detJ  = ', DETJ
             WRITE(*,*) 'dNdx  = ', DNX(1), DNX(2), DNX(3), DNX(4)
             WRITE(98,*) 'dNdx  = ', DNX(1), DNX(2), DNX(3), DNX(4)
             WRITE(*,*) 'dNdy  = ', DNY(1), DNY(2), DNY(3), DNY(4)
             WRITE(98,*) 'dNdy  = ', DNY(1), DNY(2), DNY(3), DNY(4)
             WRITE(*,*) 'Bu(1,:) = ', BU(1,1), BU(1,2), BU(1,3),
     1                    BU(1,4), BU(1,5), BU(1,6), BU(1,7), BU(1,8)
             WRITE(98,*) 'Bu(1,:) = ', BU(1,1), BU(1,2), BU(1,3),
     1                    BU(1,4), BU(1,5), BU(1,6), BU(1,7), BU(1,8)
             WRITE(*,*) 'Bu(2,:) = ', BU(2,1), BU(2,2), BU(2,3),
     1                    BU(2,4), BU(2,5), BU(2,6), BU(2,7), BU(2,8)
             WRITE(98,*) 'Bu(2,:) = ', BU(2,1), BU(2,2), BU(2,3),
     1                    BU(2,4), BU(2,5), BU(2,6), BU(2,7), BU(2,8)
             WRITE(*,*) 'Bu(3,:) = ', BU(3,1), BU(3,2), BU(3,3),
     1                    BU(3,4), BU(3,5), BU(3,6), BU(3,7), BU(3,8)
             WRITE(98,*) 'Bu(3,:) = ', BU(3,1), BU(3,2), BU(3,3),
     1                    BU(3,4), BU(3,5), BU(3,6), BU(3,7), BU(3,8)
          END IF

C Optional active-zone bootstrap for the saturation field.
C This is a debug-only patch-test hook. It is enabled only when the
C deck explicitly carries the extra PROPS(15) slot and a positive
C seed value is provided. Real physics decks should omit PROPS(15)
C entirely so the bootstrap stays inactive. The patch is applied once
C per element / Gauss point during the first increment only so it can
C seed the initial Newton state without repeatedly hard-pinning later
C cutback attempts.
         SN_PATCH = 0.0D0
         IF (DEBUG_UEL .NE. 0 .AND. NPROPS .GE. 15
     1       .AND. KSTEP .EQ. 1 .AND. KINC .EQ. 1) THEN
            SN_PATCH = PROPS(15)
         END IF
         IF (SN_PATCH .GT. 0.0D0) THEN
            WRITE(*,*) 'ERROR cp189A1 forbids SAVE-based Sn patch'
            STOP
         END IF

          CALL UPS_KINEM_SN(SE, N, DNX, DNY, SN_GP, GSN,
     1         DSN_GP_DSN, SN_KIN_BRANCH_ID,
     2         SN_KIN_BRANCH_DISTANCE, SN_KIN_SWITCH_FLAG)

          IF (DBG_MECH_FILE .AND. IGP .EQ. 1) THEN
             WRITE(*,*) '=== DBG_MECH: STRAIN ==='
             WRITE(98,*) '=== DBG_MECH: STRAIN ==='
             WRITE(*,*) 'eps_xx   = ', EPS_GP(1)
             WRITE(98,*) 'eps_xx   = ', EPS_GP(1)
             WRITE(*,*) 'eps_yy   = ', EPS_GP(2)
             WRITE(98,*) 'eps_yy   = ', EPS_GP(2)
             WRITE(*,*) 'gamma_xy = ', EPS_GP(3)
             WRITE(98,*) 'gamma_xy = ', EPS_GP(3)
             WRITE(*,*) 'eps_v    = ', EPSV_GP
             WRITE(98,*) 'eps_v    = ', EPSV_GP
          END IF

C ------------------------------------------------------------
C Saturation kinematics debug:
C print the nodal Sn field that feeds the Gauss-point interpolation.
         IF (DEBUG_UEL .EQ. 1 .AND. JELEM .EQ. 1 .AND. IGP .EQ. 1
     1      .AND. (KINC .EQ. 1 .OR. KINC .EQ. 5 .OR. KINC .EQ. 10)) THEN
            WRITE(*,*) '--- UEL_TWOPHASE_UPS Sn KINEMATICS ---'
            WRITE(*,*) 'SE(1:4)   = ', SE(1), SE(2), SE(3), SE(4)
            WRITE(*,*) 'SN_GP(raw)= ', SN_GP
            WRITE(*,*) 'GSN       = ', GSN(1), GSN(2)
         END IF

C ---- effective old state used by the time-difference terms
         PW_OLD_EFF   = SV_GP_OLD(1)
         SN_OLD_EFF   = SV_GP_OLD(2)
         EPSV_OLD_EFF = SV_GP_OLD(6)

C ---- bootstrap hold step: freeze the old state only in the very
C first Step-0 increment so the active-zone seed can settle before
C the second step changes the loading pattern.
         IF (BOOT_HOLD .EQ. 1) THEN
            PW_OLD_EFF   = PW_GP
            SN_OLD_EFF   = SN_GP
            EPSV_OLD_EFF = EPSV_GP
         END IF

         Y_SPAN_ANCHOR = DBG_P_ANCHOR_H
         IF (DABS(Y_SPAN_ANCHOR) .LT. 1.0D-12) Y_SPAN_ANCHOR = 1.0D3
         PW_ANCHOR_REF = DBG_P_ANCHOR_PBOTTOM +
     1        (DBG_P_ANCHOR_PTOP - DBG_P_ANCHOR_PBOTTOM) *
     2        (Y_GP / Y_SPAN_ANCHOR)
         SN_ANCHOR_REF = DBG_S_ANCHOR_SNREF

         IF (DEBUG_UEL .EQ. 1 .AND. JELEM .EQ. 1 .AND. IGP .EQ. 1
     1      .AND. (KINC .EQ. 1 .OR. KINC .EQ. 5 .OR. KINC .EQ. 10)) THEN
            WRITE(*,*) '--- UEL_TWOPHASE_UPS BOOT STRAT ---'
            WRITE(*,*) 'BOOT_HOLD   = ', BOOT_HOLD
            WRITE(*,*) 'PW_OLD_EFF  = ', PW_OLD_EFF
            WRITE(*,*) 'SN_OLD_EFF  = ', SN_OLD_EFF
            WRITE(*,*) 'EPSV_OLD_EFF= ', EPSV_OLD_EFF
         END IF

C ---- diagnostic guard: keep the closure fed by finite, bounded inputs
         IF (DBG_GUARD_NONFINITE .GT. 0.5D0) THEN
            PW_BAD = (PW_GP .NE. PW_GP) .OR.
     1               (DABS(PW_GP) .GT. 1.0D100)
            SN_BAD = (SN_GP .NE. SN_GP) .OR.
     1               (DABS(SN_GP) .GT. 1.0D100)
            SN_CLAMPED = .FALSE.
            IF (PW_BAD) THEN
               PW_GUARD = PW_OLD_EFF
               IF (PW_GUARD .NE. PW_GUARD) PW_GUARD = 0.0D0
               PW_GP = PW_GUARD
               GPW(1) = 0.0D0
               GPW(2) = 0.0D0
            END IF
            IF (SN_BAD) THEN
               SN_GUARD = DBG_SN_SEED
               IF (SN_GUARD .NE. SN_GUARD) SN_GUARD = 0.1D0
               SN_GP = SN_GUARD
               GSN(1) = 0.0D0
               GSN(2) = 0.0D0
            END IF
            IF (DBG_SN_BOUNDS_ON .GT. 0.5D0) THEN
               SN_GUARD = SN_GP
               IF (SN_GUARD .LT. DBG_SN_MIN) THEN
                  SN_GUARD = DBG_SN_MIN
                  SN_CLAMPED = .TRUE.
               END IF
               IF (SN_GUARD .GT. DBG_SN_MAX) THEN
                  SN_GUARD = DBG_SN_MAX
                  SN_CLAMPED = .TRUE.
               END IF
               IF (SN_CLAMPED) THEN
                  SN_GP = SN_GUARD
                  GSN(1) = 0.0D0
                  GSN(2) = 0.0D0
               END IF
            END IF
         END IF

C ---- 3.5 two-phase closure (placeholder first-stage)
C This is currently a placeholder closure law.
C It is the intended insertion point for the first real two-phase
C material relations. In the final version this block should carry:
C   - capillary pressure pc(Sn)
C   - relative permeabilities krw(Sn), krn(Sn)
C   - equivalent pore pressure peq(pw,Sn)
C   - analytical derivatives with respect to the state variables
C
C For the current two-phase development step we now use a modified
C Brooks-Corey / Corey closure with explicit analytical derivatives.
C The closure parameters are passed through PROPS so they remain easy
C to edit from the input deck without touching the UEL source.
         IF (STRICT_MECH_COMPRESS .GT. 0.5D0 .AND. KSTEP .GE. 2) THEN
            SW_GP     = 1.0D0 - SN_GP
            PC_GP     = 0.0D0
            KRW_GP    = 0.0D0
            KRN_GP    = 0.0D0
            PEQ_GP    = 0.0D0
            DPC_DSN   = 0.0D0
            D2PC_DSN2 = 0.0D0
            PC_SECOND_BRANCH_ID = -1
            PC_SECOND_BRANCH_DISTANCE = 0.0D0
            PC_SECOND_SWITCH_FLAG = 0
            DKRW_DSN  = 0.0D0
            DKRN_DSN  = 0.0D0
            DPEQ_DPW  = 0.0D0
            DPEQ_DSN  = 0.0D0
            IF (DBG_LOC_ACTIVE) THEN
               DBG_GP_SE_RAW(IGP)   = SN_GP
               DBG_GP_SE_CLAMP(IGP) = SN_GP
               DBG_GP_DS(IGP)       = 1.0D0 - PROPS(8) - PROPS(9)
               DBG_GP_CHI(IGP)      = 1.0D0 - SN_GP
               DBG_GP_DCHI_DSN(IGP) = 0.0D0
               DBG_GP_DSE_DSN(IGP)  = 0.0D0
               DBG_GP_KRW(IGP)      = KRW_GP
               DBG_GP_KRN(IGP)      = KRN_GP
               DBG_GP_DKRW_DSN(IGP) = DKRW_DSN
               DBG_GP_DKRN_DSN(IGP) = DKRN_DSN
               DBG_GP_DPEQ_DPW(IGP) = DPEQ_DPW
               DBG_GP_DPEQ_DSN(IGP) = DPEQ_DSN
            END IF
         ELSE
            CALL UPS_TWOPHASE_CLOSURE(PW_GP, SN_GP, PROPS,
     1           SW_GP, PC_GP, KRW_GP, KRN_GP, PEQ_GP,
     2           DPC_DSN, DKRW_DSN, DKRN_DSN,
     3           DPEQ_DPW, DPEQ_DSN, DBG_MECH_FILE,
     4           DBG_GP_SE_RAW(IGP), DBG_GP_SE_CLAMP(IGP),
     5           DBG_GP_DS(IGP), DBG_GP_CHI(IGP),
     6           DBG_GP_DCHI_DSN(IGP), DBG_GP_DSE_DSN(IGP))
            CALL UPS_PC_SECOND_DERIVATIVE(SN_GP, PROPS,
     1           D2PC_DSN2, PC_SECOND_BRANCH_ID,
     2           PC_SECOND_BRANCH_DISTANCE, PC_SECOND_SWITCH_FLAG)
         END IF
         IF (DBG_LOC_ACTIVE) THEN
            DBG_GP_KRW(IGP)      = KRW_GP
            DBG_GP_KRN(IGP)      = KRN_GP
            DBG_GP_DKRW_DSN(IGP) = DKRW_DSN
            DBG_GP_DKRN_DSN(IGP) = DKRN_DSN
            DBG_GP_DPEQ_DPW(IGP) = DPEQ_DPW
            DBG_GP_DPEQ_DSN(IGP) = DPEQ_DSN
         END IF

C ------------------------------------------------------------
C Temporary debug print:
C print only for element 1 / Gauss point 1 and only when the external
C debug switch is enabled. Restrict the output to a few early / sample
C increments so the log stays readable.
         IF (DEBUG_UEL .EQ. 1 .AND. JELEM .EQ. 1 .AND. IGP .EQ. 1
     1      .AND. (KINC .EQ. 1 .OR. KINC .EQ. 5 .OR. KINC .EQ. 10)) THEN
            WRITE(*,*) '--- UEL_TWOPHASE_UPS DEBUG: JELEM=1, IGP=1 ---'
            WRITE(*,*) 'PW_GP     = ', PW_GP
            WRITE(*,*) 'SN_GP     = ', SN_GP
            WRITE(*,*) 'SW_GP     = ', SW_GP
            WRITE(*,*) 'PC_GP     = ', PC_GP
            WRITE(*,*) 'KRW_GP    = ', KRW_GP
            WRITE(*,*) 'KRN_GP    = ', KRN_GP
            WRITE(*,*) 'PEQ_GP    = ', PEQ_GP
            WRITE(*,*) 'DPC_DSN   = ', DPC_DSN
            WRITE(*,*) 'DKRW_DSN  = ', DKRW_DSN
            WRITE(*,*) 'DKRN_DSN  = ', DKRN_DSN
            WRITE(*,*) 'DPEQ_DPW  = ', DPEQ_DPW
            WRITE(*,*) 'DPEQ_DSN  = ', DPEQ_DSN
            WRITE(*,*) 'DTIME     = ', DTIME
         END IF

C ---- 3.6 reservoir update (placeholder first-stage)
C This hook keeps the future porosity / permeability / compressibility
C evolution localised in one subroutine, instead of scattering those
C relations across the UEL main loop.
C
C In the first skeleton this routine returns constant material values.
C Later it is the right place to insert:
C   - porosity update rules
C   - permeability evolution laws
C   - compressibility dependence on stress or damage
C   - any additional material-state couplings
C ---- 3.7 constitutive law (mechanics backbone)
C The mechanics block is intentionally separated from the flow block.
C At this stage we only compute the linear-elastic effective stress
C response of the skeleton. The pore-pressure coupling is deliberately
C kept out of this subroutine so the mechanical backbone can be
C validated independently before coupling terms are reintroduced.
          CALL UPS_MECH_CONSTITUTIVE(EPS_GP, PROPS,
     1        SIGEFF_GP, DTAN)

C ---- 3.7a reservoir update (route 2A stage-1 value update)
C The permeability update is now allowed to see the effective stress.
C WP10-I1 retains the value update and adds its branchwise stress
C derivative for the KPU/KSU permeability chain only.
         IF (STRICT_MECH_COMPRESS .GT. 0.5D0 .AND. KSTEP .GE. 2) THEN
            PHI_GP     = 0.0D0
            KABS_GP    = 0.0D0
            CF_GP      = 0.0D0
            DK_DSIGE   = 0.0D0
            DK_DCF     = 0.0D0
            DCF_DSIGE  = 0.0D0
         ELSE
            CALL UPS_RESERVOIR_UPDATE(EPSV_GP, PEQ_GP, SIGEFF_GP, PROPS,
     1           PHI_GP, KABS_GP, CF_GP,
     2           DK_DSIGE, DK_DCF, DCF_DSIGE)
         END IF
         CALL UPS_KABS_SIGMA_TO_U(DK_DSIGE, DTAN, BU, DK_DU)

         SIGMA_M_EFF = 0.5D0 * (SIGEFF_GP(1) + SIGEFF_GP(2))
         IF (DBG_LOC_ACTIVE) DBG_GP_SIGMA_MEFF(IGP) = SIGMA_M_EFF

C cp188A1 sparse checkpoints reuse current physical values without changing
C the accepted-state writer or any residual, tangent, or SVARS path.
         CP188A1_CHK_PW(IGP) = PW_GP
         CP188A1_CHK_SN(IGP) = SN_GP
         CP188A1_CHK_PC(IGP) = PC_GP
         CP188A1_CHK_PEQ(IGP) = PEQ_GP
         CP188A1_CHK_KABS(IGP) = KABS_GP
         CP188A1_CHK_EPSV(IGP) = EPSV_GP
         CP188A1_CHK_SIGEFF(1,IGP) = SIGEFF_GP(1)
         CP188A1_CHK_SIGEFF(2,IGP) = SIGEFF_GP(2)
         CP188A1_CHK_SIGEFF(3,IGP) = SIGEFF_GP(3)

C cp171A2 no-restart continuous allow-cutback audit: record the U/DU -> PE/SE ->
C GP reconstruction state in the STEP3 KINC23-32 window only.
         CALL UPS_CP168_AUDIT_ROW(KSTEP, KINC, JELEM, IGP,
     1      NDOFEL, MLVARX, NRHS, U, DU, DE, PE, SE,
     2      N, DNX, DNY, PW_GP, SN_GP, GPW, GSN,
     3      SV_GP_OLD, PC_GP, PEQ_GP, KABS_GP, EPSV_GP,
     4      SIGEFF_GP, KRW_GP, KRN_GP, PROPS(5), PROPS(6),
     5      PROPS(7))
         CALL UPS_CP174A_OUTPUT_ROW(KSTEP, KINC, JELEM, IGP,
     1      TIME(2), X_GP, Y_GP, PW_GP, SN_GP, PC_GP,
     2      PEQ_GP, KABS_GP, EPSV_GP, SIGEFF_GP)

C ---- mobility continuity diagnostic:
C Smooth only the relative permeability entering the flow blocks.
C The mechanical PEQ path remains raw so this isolates the flux layer.
         KRW_FLOW = KRW_GP
         KRN_FLOW = KRN_GP
         DKRW_DSN_FLOW = DKRW_DSN
         DKRN_DSN_FLOW = DKRN_DSN
         IF (DBG_MOB_CONT_REG .GT. 0.5D0 .AND.
     1       KSTEP .GE. 3 .AND.
     2       DBLE(KINC) .GE. DBG_MOB_CONT_MIN_KINC) THEN
            CALL UPS_TWOPHASE_CLOSURE(PW_OLD_EFF, SN_OLD_EFF,
     1           PROPS, SW_MOB_OLD, PC_MOB_OLD, KRW_MOB_OLD,
     2           KRN_MOB_OLD, PEQ_MOB_OLD, DPC_DSN_MOB_OLD,
     3           DKRW_DSN_MOB_OLD, DKRN_DSN_MOB_OLD,
     4           DPEQ_DPW_MOB_OLD, DPEQ_DSN_MOB_OLD, .FALSE.,
     5           MOB_SE_RAW_OLD, MOB_SE_CLAMP_OLD, MOB_DS_OLD,
     6           MOB_CHI_OLD, MOB_DCHI_OLD, MOB_DSE_OLD)
            KRW_FLOW = KRW_MOB_OLD + DBG_MOB_CONT_BETA *
     1         (KRW_GP - KRW_MOB_OLD)
            KRN_FLOW = KRN_MOB_OLD + DBG_MOB_CONT_BETA *
     1         (KRN_GP - KRN_MOB_OLD)
            DKRW_DSN_FLOW = DBG_MOB_CONT_BETA * DKRW_DSN
            DKRN_DSN_FLOW = DBG_MOB_CONT_BETA * DKRN_DSN
         END IF

C ---- front-CFL diagnostic step control:
C Suggest a smaller Abaqus increment before the front flux/gradient
C overshoots far enough to force a late cutback.  This does not change
C residuals or tangents; it only returns a PNEWDT ratio.
         IF (DBG_FRONT_PNEWDT_REG .GT. 0.5D0 .AND.
     1       KSTEP .GE. 3 .AND.
     2       DBLE(KINC) .GE. DBG_FRONT_PNEWDT_MIN_KINC) THEN
            PNEWDT_GPC(1) = DPC_DSN * GSN(1)
            PNEWDT_GPC(2) = DPC_DSN * GSN(2)
            PNEWDT_GTOT(1) = GPW(1) + PNEWDT_GPC(1)
            PNEWDT_GTOT(2) = GPW(2) + PNEWDT_GPC(2)
            PNEWDT_GTOT_NORM = DSQRT(PNEWDT_GTOT(1)
     1         * PNEWDT_GTOT(1) + PNEWDT_GTOT(2)
     2         * PNEWDT_GTOT(2))
            PNEWDT_LAMN = 0.0D0
            IF (DABS(PROPS(7)) .GT. 1.0D-30)
     1         PNEWDT_LAMN = PROPS(6) * KABS_GP * KRN_GP / PROPS(7)
            PNEWDT_QN(1) = -PNEWDT_LAMN * PNEWDT_GTOT(1)
            PNEWDT_QN(2) = -PNEWDT_LAMN * PNEWDT_GTOT(2)
            PNEWDT_QN_NORM = DSQRT(PNEWDT_QN(1)*PNEWDT_QN(1)
     1         + PNEWDT_QN(2)*PNEWDT_QN(2))
            DBG_FRONT_PNEWDT_METRIC = 0.0D0
            DBG_FRONT_PNEWDT_TMP =
     1         PNEWDT_GTOT_NORM / DBG_FRONT_PNEWDT_GTOT_TOL
            IF (DBG_FRONT_PNEWDT_TMP .GT. DBG_FRONT_PNEWDT_METRIC)
     1         DBG_FRONT_PNEWDT_METRIC = DBG_FRONT_PNEWDT_TMP
            DBG_FRONT_PNEWDT_TMP =
     1         PNEWDT_QN_NORM / DBG_FRONT_PNEWDT_QN_TOL
            IF (DBG_FRONT_PNEWDT_TMP .GT. DBG_FRONT_PNEWDT_METRIC)
     1         DBG_FRONT_PNEWDT_METRIC = DBG_FRONT_PNEWDT_TMP
            IF (DBG_FRONT_PNEWDT_METRIC .GT. ONE) THEN
               DBG_FRONT_PNEWDT_SUGG = DBG_FRONT_PNEWDT_TARGET
     1            / DBG_FRONT_PNEWDT_METRIC
               IF (DBG_FRONT_PNEWDT_SUGG .LT. DBG_FRONT_PNEWDT_MIN)
     1            DBG_FRONT_PNEWDT_SUGG = DBG_FRONT_PNEWDT_MIN
               IF (DBG_FRONT_PNEWDT_MIN_DTIME .GT. 0.0D0 .AND.
     1             DTIME .GT. 0.0D0) THEN
                  DBG_FRONT_PNEWDT_TMP =
     1               DBG_FRONT_PNEWDT_MIN_DTIME / DTIME
                  IF (DBG_FRONT_PNEWDT_SUGG .LT.
     1                DBG_FRONT_PNEWDT_TMP)
     2                DBG_FRONT_PNEWDT_SUGG = DBG_FRONT_PNEWDT_TMP
               END IF
               IF (DBG_FRONT_PNEWDT_SUGG .GT. ONE)
     1            DBG_FRONT_PNEWDT_SUGG = ONE
               IF (DBG_FRONT_PNEWDT_SUGG .LT.
     1             DBG_FRONT_PNEWDT_FACTOR)
     2             DBG_FRONT_PNEWDT_FACTOR = DBG_FRONT_PNEWDT_SUGG
            END IF
         END IF

C ---- compression-step pure-mechanics diagnostic:
C Strip pore-pressure-equivalent coupling out of the mechanical
C residual so that RU/KUU can be tested as a stand-alone mechanics core.
         IF (MECH_ONLY_COMPRESS .GT. 0.5D0 .AND. KSTEP .GE. 2) THEN
            PEQ_GP    = 0.0D0
            DPEQ_DPW  = 0.0D0
            DPEQ_DSN  = 0.0D0
         END IF

         IF (DBG_LOC_ACTIVE) THEN
            DBG_GP_PW(IGP)   = PW_GP
            DBG_GP_SN(IGP)   = SN_GP
            DBG_GP_SW(IGP)   = SW_GP
            DBG_GP_PC(IGP)   = PC_GP
            DBG_GP_PEQ(IGP)  = PEQ_GP
            DBG_GP_KABS(IGP) = KABS_GP
            DBG_GP_PHI(IGP)  = PHI_GP
         END IF

          IF (DBG_MECH_FILE .AND. IGP .EQ. 1) THEN
             WRITE(*,*) '=== DBG_MECH: CONSTITUTIVE / UPDATE ==='
             WRITE(98,*) '=== DBG_MECH: CONSTITUTIVE / UPDATE ==='
             WRITE(*,*) 'sig_xx   = ', SIGEFF_GP(1)
             WRITE(98,*) 'sig_xx   = ', SIGEFF_GP(1)
             WRITE(*,*) 'sig_yy   = ', SIGEFF_GP(2)
             WRITE(98,*) 'sig_yy   = ', SIGEFF_GP(2)
             WRITE(*,*) 'sig_xy   = ', SIGEFF_GP(3)
             WRITE(98,*) 'sig_xy   = ', SIGEFF_GP(3)
             WRITE(*,*) 'sig_m    = ', SIGMA_M_EFF
             WRITE(98,*) 'sig_m    = ', SIGMA_M_EFF
             WRITE(*,*) 'D11      = ', DTAN(1,1)
             WRITE(98,*) 'D11      = ', DTAN(1,1)
             WRITE(*,*) 'D12      = ', DTAN(1,2)
             WRITE(98,*) 'D12      = ', DTAN(1,2)
             WRITE(*,*) 'D33      = ', DTAN(3,3)
             WRITE(98,*) 'D33      = ', DTAN(3,3)
             WRITE(*,*) 'KABS_GP  = ', KABS_GP
             WRITE(98,*) 'KABS_GP  = ', KABS_GP
          END IF

C ---- 3.8 assemble block residual/tangent contributions
C Here the displacement block is now assembled from the real weak form:
C   RU  <- internal force vector based on sigma'
C   KUU <- consistent small-strain plane-strain tangent
C
C The pore-pressure block is now assembled from a minimal storage plus
C Darcy-diffusion form, and it now carries the first saturation and
C volumetric-strain couplings through KPS and KPU so the pressure and
C saturation blocks stay consistent.
C The saturation block is now extended to include the first transport
C coupling terms and the first volumetric-strain coupling through KSU,
C while the strongest nonlinear saturation tangent is still kept under
C conservative control.
          CP157_RAW_PC_OK = 1
          CP157_RAW_PW_OK = 1
          CP157_RAW_SN_OK = 1
          CP157_RAW_PEQ_OK = 1
          CP157_RAW_KABS_OK = 1
          CP157_RAW_EPSV_OK = 1
          CP157_RAW_SIG_OK = 1
          IF (PC_GP .NE. PC_GP .OR. DABS(PC_GP) .GT. 1.0D100)
     1        CP157_RAW_PC_OK = 0
          IF (PW_GP .NE. PW_GP .OR. DABS(PW_GP) .GT. 1.0D100)
     1        CP157_RAW_PW_OK = 0
          IF (SN_GP .NE. SN_GP .OR. DABS(SN_GP) .GT. 1.0D100)
     1        CP157_RAW_SN_OK = 0
          IF (PEQ_GP .NE. PEQ_GP .OR. DABS(PEQ_GP) .GT. 1.0D100)
     1        CP157_RAW_PEQ_OK = 0
          IF (KABS_GP .NE. KABS_GP .OR.
     1        DABS(KABS_GP) .GT. 1.0D100) CP157_RAW_KABS_OK = 0
          IF (EPSV_GP .NE. EPSV_GP .OR.
     1        DABS(EPSV_GP) .GT. 1.0D100) CP157_RAW_EPSV_OK = 0
          IF (SIGEFF_GP(1) .NE. SIGEFF_GP(1) .OR.
     1        DABS(SIGEFF_GP(1)) .GT. 1.0D100)
     2        CP157_RAW_SIG_OK = 0
          IF (SIGEFF_GP(2) .NE. SIGEFF_GP(2) .OR.
     1        DABS(SIGEFF_GP(2)) .GT. 1.0D100)
     2        CP157_RAW_SIG_OK = 0
          IF (SIGEFF_GP(3) .NE. SIGEFF_GP(3) .OR.
     1        DABS(SIGEFF_GP(3)) .GT. 1.0D100)
     2        CP157_RAW_SIG_OK = 0
          CP157_RAW_ALL_OK = 0
          IF (CP157_RAW_PC_OK .EQ. 1 .AND.
     1        CP157_RAW_PW_OK .EQ. 1 .AND.
     2        CP157_RAW_SN_OK .EQ. 1 .AND.
     3        CP157_RAW_PEQ_OK .EQ. 1 .AND.
     4        CP157_RAW_KABS_OK .EQ. 1 .AND.
     5        CP157_RAW_EPSV_OK .EQ. 1 .AND.
     6        CP157_RAW_SIG_OK .EQ. 1) CP157_RAW_ALL_OK = 1

          CP157_OLD_OUT_OK = 1
          IF (SV_GP_OLD(33) .NE. SV_GP_OLD(33) .OR.
     1        DABS(SV_GP_OLD(33)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(34) .NE. SV_GP_OLD(34) .OR.
     1        DABS(SV_GP_OLD(34)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(35) .NE. SV_GP_OLD(35) .OR.
     1        DABS(SV_GP_OLD(35)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(36) .NE. SV_GP_OLD(36) .OR.
     1        DABS(SV_GP_OLD(36)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(37) .NE. SV_GP_OLD(37) .OR.
     1        DABS(SV_GP_OLD(37)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(38) .NE. SV_GP_OLD(38) .OR.
     1        DABS(SV_GP_OLD(38)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(39) .NE. SV_GP_OLD(39) .OR.
     1        DABS(SV_GP_OLD(39)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(40) .NE. SV_GP_OLD(40) .OR.
     1        DABS(SV_GP_OLD(40)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(41) .NE. SV_GP_OLD(41) .OR.
     1        DABS(SV_GP_OLD(41)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(43) .NE. SV_GP_OLD(43) .OR.
     1        DABS(SV_GP_OLD(43)) .GT. 1.0D100)
     2        CP157_OLD_OUT_OK = 0
          IF (SV_GP_OLD(43) .LT. 0.5D0) CP157_OLD_OUT_OK = 0

          CP162_COMMITTED_OK = 1
          IF (SV_GP_OLD(1) .NE. SV_GP_OLD(1) .OR.
     1        DABS(SV_GP_OLD(1)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(2) .NE. SV_GP_OLD(2) .OR.
     1        DABS(SV_GP_OLD(2)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(4) .NE. SV_GP_OLD(4) .OR.
     1        DABS(SV_GP_OLD(4)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(5) .NE. SV_GP_OLD(5) .OR.
     1        DABS(SV_GP_OLD(5)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(6) .NE. SV_GP_OLD(6) .OR.
     1        DABS(SV_GP_OLD(6)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(8) .NE. SV_GP_OLD(8) .OR.
     1        DABS(SV_GP_OLD(8)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(10) .NE. SV_GP_OLD(10) .OR.
     1        DABS(SV_GP_OLD(10)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(11) .NE. SV_GP_OLD(11) .OR.
     1        DABS(SV_GP_OLD(11)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0
          IF (SV_GP_OLD(12) .NE. SV_GP_OLD(12) .OR.
     1        DABS(SV_GP_OLD(12)) .GT. 1.0D100)
     2        CP162_COMMITTED_OK = 0

          CP157_OUT_SOURCE = 0
          CP157_OUT_PW_VAL = 0.0D0
          CP157_OUT_SN_VAL = 0.0D0
          CP157_OUT_PC_VAL = 0.0D0
          CP157_OUT_PEQ_VAL = 0.0D0
          CP157_OUT_KABS_VAL = 0.0D0
          CP157_OUT_EPSV_VAL = 0.0D0
          CP157_OUT_SIGXX_VAL = 0.0D0
          CP157_OUT_SIGYY_VAL = 0.0D0
          CP157_OUT_SIGXY_VAL = 0.0D0
          CP162_UPDATE_HIT = 0
          CP162_UPDATE_MODE = 0
          CP162_OUT_TIME_SLOT = SV_GP_OLD(44)
          CP162_OUT_KINC_SLOT = SV_GP_OLD(45)
          IF (KSTEP .GE. 3 .AND.
     1        CP157_RAW_ALL_OK .EQ. 1) THEN
             CP157_OUT_SOURCE = 1
             CP162_UPDATE_HIT = 1
             CP162_UPDATE_MODE = 1
             CP157_OUT_PW_VAL = PW_GP
             CP157_OUT_SN_VAL = SN_GP
             CP157_OUT_PC_VAL = PC_GP
             CP157_OUT_PEQ_VAL = PEQ_GP
             CP157_OUT_KABS_VAL = KABS_GP
             CP157_OUT_EPSV_VAL = EPSV_GP
             CP157_OUT_SIGXX_VAL = SIGEFF_GP(1)
             CP157_OUT_SIGYY_VAL = SIGEFF_GP(2)
             CP157_OUT_SIGXY_VAL = SIGEFF_GP(3)
          ELSE IF (KSTEP .GE. 3 .AND.
     1             CP162_COMMITTED_OK .EQ. 1) THEN
             CP157_OUT_SOURCE = 3
             CP162_UPDATE_HIT = 1
             CP162_UPDATE_MODE = 3
             CP157_OUT_PW_VAL = SV_GP_OLD(1)
             CP157_OUT_SN_VAL = SV_GP_OLD(2)
             CP157_OUT_PC_VAL = SV_GP_OLD(4)
             CP157_OUT_PEQ_VAL = SV_GP_OLD(5)
             CP157_OUT_KABS_VAL = SV_GP_OLD(8)
             CP157_OUT_EPSV_VAL = SV_GP_OLD(6)
             CP157_OUT_SIGXX_VAL = SV_GP_OLD(10)
             CP157_OUT_SIGYY_VAL = SV_GP_OLD(11)
             CP157_OUT_SIGXY_VAL = SV_GP_OLD(12)
          ELSE IF (((KSTEP .EQ. 3 .AND. KINC .GT. 25) .OR.
     1              KSTEP .GE. 4) .AND.
     2              CP157_OLD_OUT_OK .EQ. 1) THEN
             CP157_OUT_SOURCE = 2
             CP162_UPDATE_HIT = 0
             CP162_UPDATE_MODE = 2
             CP157_OUT_PW_VAL = SV_GP_OLD(33)
             CP157_OUT_SN_VAL = SV_GP_OLD(34)
             CP157_OUT_PC_VAL = SV_GP_OLD(35)
             CP157_OUT_PEQ_VAL = SV_GP_OLD(36)
             CP157_OUT_KABS_VAL = SV_GP_OLD(37)
             CP157_OUT_EPSV_VAL = SV_GP_OLD(38)
             CP157_OUT_SIGXX_VAL = SV_GP_OLD(39)
             CP157_OUT_SIGYY_VAL = SV_GP_OLD(40)
             CP157_OUT_SIGXY_VAL = SV_GP_OLD(41)
          END IF

          CP157_OUT_PW_OK = 0
          CP157_OUT_SN_OK = 0
          CP157_OUT_PC_OK = 0
          CP157_OUT_PEQ_OK = 0
          CP157_OUT_KABS_OK = 0
          CP157_OUT_EPSV_OK = 0
          CP157_OUT_SIG_OK = 0
          CP157_OUT_VALID_OK = 0
          IF (CP157_OUT_SOURCE .GT. 0) THEN
             CP157_OUT_PW_OK = 1
             CP157_OUT_SN_OK = 1
             CP157_OUT_PC_OK = 1
             CP157_OUT_PEQ_OK = 1
             CP157_OUT_KABS_OK = 1
             CP157_OUT_EPSV_OK = 1
             CP157_OUT_SIG_OK = 1
             CP157_OUT_VALID_OK = 1
             IF (CP157_OUT_PW_VAL .NE. CP157_OUT_PW_VAL .OR.
     1           DABS(CP157_OUT_PW_VAL) .GT. 1.0D100)
     2           CP157_OUT_PW_OK = 0
             IF (CP157_OUT_SN_VAL .NE. CP157_OUT_SN_VAL .OR.
     1           DABS(CP157_OUT_SN_VAL) .GT. 1.0D100)
     2           CP157_OUT_SN_OK = 0
             IF (CP157_OUT_PC_VAL .NE. CP157_OUT_PC_VAL .OR.
     1           DABS(CP157_OUT_PC_VAL) .GT. 1.0D100)
     2           CP157_OUT_PC_OK = 0
             IF (CP157_OUT_PEQ_VAL .NE. CP157_OUT_PEQ_VAL .OR.
     1           DABS(CP157_OUT_PEQ_VAL) .GT. 1.0D100)
     2           CP157_OUT_PEQ_OK = 0
             IF (CP157_OUT_KABS_VAL .NE. CP157_OUT_KABS_VAL
     1           .OR. DABS(CP157_OUT_KABS_VAL) .GT. 1.0D100)
     2           CP157_OUT_KABS_OK = 0
             IF (CP157_OUT_EPSV_VAL .NE. CP157_OUT_EPSV_VAL
     1           .OR. DABS(CP157_OUT_EPSV_VAL) .GT. 1.0D100)
     2           CP157_OUT_EPSV_OK = 0
             IF (CP157_OUT_SIGXX_VAL .NE. CP157_OUT_SIGXX_VAL
     1           .OR. DABS(CP157_OUT_SIGXX_VAL) .GT. 1.0D100)
     2           CP157_OUT_SIG_OK = 0
             IF (CP157_OUT_SIGYY_VAL .NE. CP157_OUT_SIGYY_VAL
     1           .OR. DABS(CP157_OUT_SIGYY_VAL) .GT. 1.0D100)
     2           CP157_OUT_SIG_OK = 0
             IF (CP157_OUT_SIGXY_VAL .NE. CP157_OUT_SIGXY_VAL
     1           .OR. DABS(CP157_OUT_SIGXY_VAL) .GT. 1.0D100)
     2           CP157_OUT_SIG_OK = 0
             IF (CP157_OUT_SOURCE .EQ. 2) CP157_OUT_VALID_OK = 0
          END IF

          IF (.FALSE. .AND. KSTEP .EQ. 3 .AND. KINC .GE. 1 .AND.
     1        KINC .LE. 400 .AND. JELEM .GE. 10287 .AND.
     2        JELEM .LE. 10291 .AND. IGP .GE. 1 .AND.
     3        IGP .LE. 4) THEN
             CP153A_IK = KINC
             CP153A_IE = JELEM - 10286
             CP153A_IG = IGP
             IF (CP153A_IK .GE. 1 .AND. CP153A_IK .LE. 144
     1           .AND. CP153A_IE .GE. 1 .AND.
     2           CP153A_IE .LE. 5 .AND. CP153A_IG .GE. 1
     3           .AND. CP153A_IG .LE. 4) THEN
                IF (CP153A_WRITTEN(CP153A_IK, CP153A_IE,
     1              CP153A_IG) .EQ. 0) THEN
                   IF (.NOT. CP153A_OPEN) THEN
                      CP153A_FILE =
     1 'C:\abq_runs\ac128wo_cp156A2_svars192'//
     2 '_compileAndInputPatch\outputs\cp156A2'//
     3 '_sv192_integer_rows_dedup.csv'
                      OPEN(UNIT=CP153A_UNIT,
     1                   FILE=CP153A_FILE(1:
     2                   LEN_TRIM(CP153A_FILE)),
     3                   STATUS='UNKNOWN', POSITION='APPEND',
     4                   ACTION='WRITE', IOSTAT=CP153A_IOS)
                      WRITE(*,*) 'CP153A_OPEN_IOSTAT', CP153A_IOS
                      IF (CP153A_IOS .EQ. 0) THEN
                         CP153A_OPEN = .TRUE.
                         WRITE(CP153A_UNIT,'(A)',
     1                      IOSTAT=CP153A_WRITE_IOS)
     2                      'kstep,kinc,elem,gp,const_flag'
                         WRITE(*,*) 'CP153A_HEADER_IOSTAT',
     1                      CP153A_WRITE_IOS
                         CALL FLUSH(CP153A_UNIT)
                      END IF
                   END IF
                   IF (CP153A_OPEN) THEN
                      WRITE(CP153A_UNIT,9149,
     1                   IOSTAT=CP153A_WRITE_IOS)
     2                   KSTEP, KINC, JELEM, IGP, 1
                      IF (CP153A_WRITE_IOS .EQ. 0) THEN
                         CP153A_ROW_COUNT = CP153A_ROW_COUNT + 1
                         CP153A_WRITTEN(CP153A_IK, CP153A_IE,
     1                      CP153A_IG) = 1
                      END IF
                      IF (CP153A_ROW_COUNT .LE. 5 .OR.
     1                    CP153A_WRITE_IOS .NE. 0) THEN
                         WRITE(*,*) 'CP153A_ROW_IOSTAT',
     1                      CP153A_ROW_COUNT, CP153A_WRITE_IOS
                      END IF
                      CALL FLUSH(CP153A_UNIT)
                   END IF
                END IF
             END IF
          END IF

          RP_PW_USE_OK = 0
          RP_GPW_OK = 0
          RP_KABS_USE_OK = 0
          RP_LAMW_USE_OK = 0
          RP_FINAL_OK = 0
          RS_SN_USE_OK = 0
          RS_GSN_OK = 0
          RS_KRN_USE_OK = 0
          RS_LAMN_USE_OK = 0
          RS_FINAL_OK = 0
          RU_PEQ_USE_OK = 0
          RU_SIGEFF_OK = 0
          RU_EPSV_OK = 0
          RU_FINAL_OK = 0
          CP163_UPDATE_HIT = 0
          CP163_SOURCE_CANDIDATE_ID = 0
          CP163_OUT_VALID_CANDIDATE = 0
          CP164_RP_RES_TERM_OK = 0
          CP164_RP_PRESS_GRAD_TERM_OK = 0
          CP164_RP_MOBILITY_FLUX_TERM_OK = 0
          CP164_RS_RES_TERM_OK = 0
          CP164_RS_SAT_FLUX_TERM_OK = 0
          CP164_RU_SIG_TERM_OK = 0
          CP164_RU_PEQ_TERM_OK = 0
          CP164_PEQ_FORCE_TERM_OK = 0
          CP164_KABS_PERM_TERM_OK = 0
          CP164_CANDIDATE_SOURCE_ID = 0
          CP163_LAMW_CAND = 0.0D0
          CP163_LAMN_CAND = 0.0D0

          IF (EPSV_GP .EQ. EPSV_GP .AND.
     1        DABS(EPSV_GP) .LE. 1.0D100) RU_EPSV_OK = 1

          IF (STRICT_MECH_COMPRESS .GT. 0.5D0 .AND. KSTEP .GE. 2) THEN
             CALL UPS_ASSEMBLE_RU_KU(WT, DETJ, BU,
     1           SIGEFF_GP, SIGEFF_OLD_GP, DTAN,
     2           0.0D0, PW_GP, SN_GP, PC_GP,
     3           0.0D0, PW_OLD_EFF, SN_OLD_EFF, SV_GP_OLD(4),
     4           CAP_REF_USE, CAP_REF_VALID_OUT, 0.0D0, 0.0D0,
     5           GPW, GSN, KABS_GP, KRW_GP, KRN_GP, DPC_DSN,
     6           X_GP, Y_GP, N, PROPS,
     7           JELEM, KSTEP, KINC, IGP, DEBUG_UEL,
     8           RU, KUU, KUP, KUS,
     9           RU_PEQ_USE_OK, RU_SIGEFF_OK, RU_FINAL_OK,
     1           CP164_RU_SIG_TERM_OK, CP164_RU_PEQ_TERM_OK,
     2           CP164_PEQ_FORCE_TERM_OK,
     3           CP165_RU_ENTER_CUR, CP165_RU_EXIT_CUR,
     4           CP165_RU_DUMMY_CUR)
            CALL UPS_ZERO_VEC(RP,4)
            CALL UPS_ZERO_VEC(RS,4)
            CALL UPS_ZERO_MAT(KUP,8,4)
            CALL UPS_ZERO_MAT(KUS,8,4)
            CALL UPS_ZERO_MAT(KPU,4,8)
            CALL UPS_ZERO_MAT(KPP,4,4)
            CALL UPS_ZERO_MAT(KPS,4,4)
            CALL UPS_ZERO_MAT(KSU,4,8)
            CALL UPS_ZERO_MAT(KSP,4,4)
            CALL UPS_ZERO_MAT(KSS,4,4)
          ELSE
             IF (PW_GP .EQ. PW_GP .AND.
     1           DABS(PW_GP) .LE. 1.0D100) RP_PW_USE_OK = 1
             IF (GPW(1) .EQ. GPW(1) .AND.
     1           DABS(GPW(1)) .LE. 1.0D100 .AND.
     2           GPW(2) .EQ. GPW(2) .AND.
     3           DABS(GPW(2)) .LE. 1.0D100) RP_GPW_OK = 1
             IF (KABS_GP .EQ. KABS_GP .AND.
     1           DABS(KABS_GP) .LE. 1.0D100 .AND.
     2           KABS_GP .GT. 0.0D0) RP_KABS_USE_OK = 1
             IF (RP_KABS_USE_OK .EQ. 1 .AND.
     1           KRW_FLOW .EQ. KRW_FLOW .AND.
     2           DABS(KRW_FLOW) .LE. 1.0D100 .AND.
     3           PROPS(5) .EQ. PROPS(5) .AND.
     4           DABS(PROPS(5)) .GT. 0.0D0 .AND.
     5           DABS(PROPS(5)) .LE. 1.0D100) THEN
                CP163_LAMW_CAND = KABS_GP * KRW_FLOW / PROPS(5)
                IF (CP163_LAMW_CAND .EQ. CP163_LAMW_CAND .AND.
     1              DABS(CP163_LAMW_CAND) .LE. 1.0D100)
     2              RP_LAMW_USE_OK = 1
             END IF
             IF (RP_PW_USE_OK .EQ. 1 .AND. RP_GPW_OK .EQ. 1
     1           .AND. RP_KABS_USE_OK .EQ. 1 .AND.
     2           RP_LAMW_USE_OK .EQ. 1) RP_FINAL_OK = 1

             IF (SN_GP .EQ. SN_GP .AND.
     1           DABS(SN_GP) .LE. 1.0D100) RS_SN_USE_OK = 1
             IF (GSN(1) .EQ. GSN(1) .AND.
     1           DABS(GSN(1)) .LE. 1.0D100 .AND.
     2           GSN(2) .EQ. GSN(2) .AND.
     3           DABS(GSN(2)) .LE. 1.0D100) RS_GSN_OK = 1
             IF (KRN_FLOW .EQ. KRN_FLOW .AND.
     1           DABS(KRN_FLOW) .LE. 1.0D100) RS_KRN_USE_OK = 1
             IF (KABS_GP .EQ. KABS_GP .AND.
     1           DABS(KABS_GP) .LE. 1.0D100 .AND.
     2           KABS_GP .GT. 0.0D0 .AND.
     3           RS_KRN_USE_OK .EQ. 1 .AND.
     4           PROPS(6) .EQ. PROPS(6) .AND.
     5           DABS(PROPS(6)) .LE. 1.0D100 .AND.
     6           PROPS(7) .EQ. PROPS(7) .AND.
     7           DABS(PROPS(7)) .GT. 0.0D0 .AND.
     8           DABS(PROPS(7)) .LE. 1.0D100) THEN
                CP163_LAMN_CAND =
     1             PROPS(6) * KABS_GP * KRN_FLOW / PROPS(7)
                IF (CP163_LAMN_CAND .EQ. CP163_LAMN_CAND .AND.
     1              DABS(CP163_LAMN_CAND) .LE. 1.0D100)
     2              RS_LAMN_USE_OK = 1
             END IF
             IF (RS_SN_USE_OK .EQ. 1 .AND. RS_GSN_OK .EQ. 1
     1           .AND. RS_KRN_USE_OK .EQ. 1 .AND.
     2           RS_LAMN_USE_OK .EQ. 1) RS_FINAL_OK = 1

             CALL UPS_ASSEMBLE_RU_KU(WT, DETJ, BU,
     1           SIGEFF_GP, SIGEFF_OLD_GP, DTAN,
     2           PEQ_GP, PW_GP, SN_GP, PC_GP,
     3           SV_GP_OLD(5), PW_OLD_EFF, SN_OLD_EFF, SV_GP_OLD(4),
     4           CAP_REF_USE, CAP_REF_VALID_OUT, DPEQ_DPW, DPEQ_DSN,
     5           GPW, GSN, KABS_GP, KRW_GP, KRN_GP, DPC_DSN,
     6           X_GP, Y_GP, N, PROPS,
     7           JELEM, KSTEP, KINC, IGP, DEBUG_UEL,
     8           RU, KUU, KUP, KUS,
     9           RU_PEQ_USE_OK, RU_SIGEFF_OK, RU_FINAL_OK,
     1           CP164_RU_SIG_TERM_OK, CP164_RU_PEQ_TERM_OK,
     2           CP164_PEQ_FORCE_TERM_OK,
     3           CP165_RU_ENTER_CUR, CP165_RU_EXIT_CUR,
     4           CP165_RU_DUMMY_CUR)
      CALL UPS_ASSEMBLE_RP_KP(WT, DETJ, DTIME,
     1           JELEM, KSTEP, KINC,
     2           N, DNX, DNY, BU,
     3           PW_GP, PW_OLD_EFF, GPW, PW_ANCHOR_REF,
     4           EPSV_GP, EPSV_OLD_EFF,
     5           KABS_GP, DK_DU, KRW_FLOW, DKRW_DSN_FLOW, PROPS,
     6           RP, KPU, KPP, KPS,
     7           CP164_RP_RES_TERM_OK,
     8           CP164_RP_PRESS_GRAD_TERM_OK,
     9           CP164_RP_MOBILITY_FLUX_TERM_OK,
     1           CP164_KABS_PERM_TERM_OK,
     2           CP165_RP_ENTER_CUR, CP165_RP_EXIT_CUR,
     3           CP165_RP_DUMMY_CUR)
         CALL UPS_ASSEMBLE_RS_KS(WT, DETJ, DTIME,
     1           JELEM, KSTEP, KINC,
     2           N, DNX, DNY, BU,
     3           GPW, SN_ANCHOR_REF,
     4           SN_GP, SN_OLD_EFF, GSN, DSN_GP_DSN,
     5           EPSV_GP, EPSV_OLD_EFF,
     6           PHI_GP, KABS_GP, DK_DU, KRN_FLOW,
     7           DPC_DSN, D2PC_DSN2, DKRN_DSN_FLOW, PROPS,
     8           RS, KSU, KSP, KSS,
     9           CP164_RS_RES_TERM_OK,
     1           CP164_RS_SAT_FLUX_TERM_OK,
     2           CP164_KABS_PERM_TERM_OK,
     3           CP165_RS_ENTER_CUR, CP165_RS_EXIT_CUR,
     4           CP165_RS_DUMMY_CUR)
          END IF

         CALL UPS_CP179B2_MECHANISM_AUDIT_ROW(KSTEP, KINC, JELEM, IGP,
     1      TIME(2), DTIME, X_GP, Y_GP, WT, DETJ,
     2      N, DNX, DNY, BU,
     3      PW_GP, PW_OLD_EFF, SN_GP, SN_OLD_EFF,
     4      PC_GP, PEQ_GP, SV_GP_OLD(5), EPSV_GP, EPSV_OLD_EFF,
     5      PHI_GP, KABS_GP, KRW_FLOW, KRN_FLOW,
     6      DPC_DSN, DKRW_DSN_FLOW, DKRN_DSN_FLOW,
     7      GPW, GSN, SIGEFF_GP, RP, RS, RU, PROPS)

         CALL UPS_CP184C_PRESSURE_TANGENT_AUDIT(KSTEP, KINC,
     1      JELEM, IGP, TIME(2), DTIME, X_GP, Y_GP, WT, DETJ,
     2      N, DNX, DNY, BU, PW_GP, PW_OLD_EFF, SN_GP, SN_OLD_EFF,
     3      PC_GP, PEQ_GP, EPSV_GP, EPSV_OLD_EFF, PHI_GP,
     4      KABS_GP, KRW_FLOW, DKRW_DSN_FLOW, GPW, GSN,
     5      PW_ANCHOR_REF, RP, KPU, KPP, KPS, PROPS)

          CP165_RP_ENTER_HIT(IGP) = CP165_RP_ENTER_CUR
          CP165_RP_EXIT_HIT(IGP) = CP165_RP_EXIT_CUR
          CP165_RS_ENTER_HIT(IGP) = CP165_RS_ENTER_CUR
          CP165_RS_EXIT_HIT(IGP) = CP165_RS_EXIT_CUR
          CP165_RU_ENTER_HIT(IGP) = CP165_RU_ENTER_CUR
          CP165_RU_EXIT_HIT(IGP) = CP165_RU_EXIT_CUR
          CP165_RP_DUMMY_HIT(IGP) = CP165_RP_DUMMY_CUR
          CP165_RS_DUMMY_HIT(IGP) = CP165_RS_DUMMY_CUR
          CP165_RU_DUMMY_HIT(IGP) = CP165_RU_DUMMY_CUR

          IF (CP164_RP_RES_TERM_OK .EQ. 1 .AND.
     1        CP164_RP_PRESS_GRAD_TERM_OK .EQ. 1 .AND.
     2        CP164_RP_MOBILITY_FLUX_TERM_OK .EQ. 1 .AND.
     3        CP164_KABS_PERM_TERM_OK .EQ. 1)
     4        CP164_CANDIDATE_SOURCE_ID =
     5        CP164_CANDIDATE_SOURCE_ID + 1
          IF (CP164_RS_RES_TERM_OK .EQ. 1 .AND.
     1        CP164_RS_SAT_FLUX_TERM_OK .EQ. 1 .AND.
     2        CP164_KABS_PERM_TERM_OK .EQ. 1)
     3        CP164_CANDIDATE_SOURCE_ID =
     4        CP164_CANDIDATE_SOURCE_ID + 2
          IF (CP164_RU_SIG_TERM_OK .EQ. 1 .AND.
     1        CP164_RU_PEQ_TERM_OK .EQ. 1 .AND.
     2        CP164_PEQ_FORCE_TERM_OK .EQ. 1)
     3        CP164_CANDIDATE_SOURCE_ID =
     4        CP164_CANDIDATE_SOURCE_ID + 4

          IF (RU_FINAL_OK .EQ. 1 .AND. RU_EPSV_OK .NE. 1)
     1       RU_FINAL_OK = 0
          IF (RP_FINAL_OK .EQ. 1)
     1       CP163_SOURCE_CANDIDATE_ID =
     2       CP163_SOURCE_CANDIDATE_ID + 1
          IF (RS_FINAL_OK .EQ. 1)
     1       CP163_SOURCE_CANDIDATE_ID =
     2       CP163_SOURCE_CANDIDATE_ID + 2
          IF (RU_FINAL_OK .EQ. 1)
     1       CP163_SOURCE_CANDIDATE_ID =
     2       CP163_SOURCE_CANDIDATE_ID + 4
          IF (CP163_SOURCE_CANDIDATE_ID .GT. 0)
     1       CP163_UPDATE_HIT = 1
         IF (RP_FINAL_OK .EQ. 1 .AND. RS_FINAL_OK .EQ. 1 .AND.
     1        RU_FINAL_OK .EQ. 1) CP163_OUT_VALID_CANDIDATE = 1

C         cp167 local-term audit output is intentionally disabled in
C         cp168; this case only writes restart-state reconstruction flags.

C ---- 3.8a debug check on the main blocks before scatter
          IF (DEBUG_UEL .EQ. 1 .AND. JELEM .EQ. 1 .AND.
     1      (KINC .EQ. 1 .OR. KINC .EQ. 5 .OR. KINC .EQ. 10)) THEN
            CALL UPS_PRINT_BLOCK_STATS('KUU', KUU, 8, 8, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            CALL UPS_PRINT_BLOCK_STATS('KPP', KPP, 4, 4, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            CALL UPS_PRINT_BLOCK_STATS('KSS', KSS, 4, 4, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            WRITE(*,*) 'KUU(1,1)=', KUU(1,1)
            WRITE(*,*) 'KPP(1,1)=', KPP(1,1)
            WRITE(*,*) 'KSS(1,1)=', KSS(1,1)
         END IF

C ---- 3.8b debug check on coupling blocks before scatter
         IF (DEBUG_UEL .EQ. 1 .AND. JELEM .EQ. 1 .AND.
     1      (KINC .EQ. 1 .OR. KINC .EQ. 5 .OR. KINC .EQ. 10)) THEN
            CALL UPS_PRINT_BLOCK_STATS('KUP', KUP, 8, 4, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            CALL UPS_PRINT_BLOCK_STATS('KUS', KUS, 8, 4, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            CALL UPS_PRINT_BLOCK_STATS('KPU', KPU, 4, 8, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            CALL UPS_PRINT_BLOCK_STATS('KPS', KPS, 4, 4, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            CALL UPS_PRINT_BLOCK_STATS('KSU', KSU, 4, 8, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            CALL UPS_PRINT_BLOCK_STATS('KSP', KSP, 4, 4, 1.0D-20,
     1                                 JELEM, KSTEP, KINC)
            WRITE(*,*) 'KUP(1,1)=', KUP(1,1)
            WRITE(*,*) 'KUS(1,1)=', KUS(1,1)
            WRITE(*,*) 'KPU(1,1)=', KPU(1,1)
            WRITE(*,*) 'KPS(1,1)=', KPS(1,1)
            WRITE(*,*) 'KSU(1,1)=', KSU(1,1)
            WRITE(*,*) 'KSP(1,1)=', KSP(1,1)
            WRITE(*,*) 'DPEQ_DPW = ', DPEQ_DPW
            WRITE(*,*) 'DPEQ_DSN = ', DPEQ_DSN
            WRITE(*,*) 'DKRW_DSN = ', DKRW_DSN
            WRITE(*,*) 'ALPHA_BIOT = ', PROPS(3)
            WRITE(*,*) 'BETA_PHI   = ', PROPS(14)
            WRITE(*,*) 'SN_GP    = ', SN_GP
            WRITE(*,*) 'EPSV_GP  = ', EPSV_GP
            WRITE(*,*) 'EPSV_OLD = ', SV_GP_OLD(6)
            WRITE(*,*) 'GPW      = ', GPW(1), GPW(2)
            WRITE(*,*) 'ALPHA_BIOT = ', PROPS(3)
            WRITE(*,*) 'BETA_PHI   = ', PROPS(14)
         END IF

C ---- 3.8c Jacobian / block consistency check on Step 1
         IF (DEBUG_UEL .NE. 0 .AND. JELEM .EQ. 1 .AND. IGP .EQ. 1
     1       .AND. KSTEP .EQ. 2 .AND. KINC .EQ. 1) THEN
            CALL UPS_JACOBIAN_CHECK_GAUSS(WT, DETJ, DTIME,
     1           JELEM, KSTEP, KINC, IGP,
     2           N, DNX, DNY, BU, DE, PE, SE,
     3           PW_OLD_EFF, SN_OLD_EFF, EPSV_OLD_EFF, PROPS)
         END IF

C ---- compression-step pure mechanics diagnostic:
C If enabled, strip all flow / saturation contributions and keep only
C the displacement block so we can isolate the mechanical path.
         IF (MECH_ONLY_COMPRESS .GT. 0.5D0 .AND. KSTEP .GE. 2) THEN
            CALL UPS_ZERO_VEC(RP,4)
            CALL UPS_ZERO_VEC(RS,4)
            CALL UPS_ZERO_MAT(KUP,8,4)
            CALL UPS_ZERO_MAT(KUS,8,4)
            CALL UPS_ZERO_MAT(KPU,4,8)
            CALL UPS_ZERO_MAT(KPP,4,4)
            CALL UPS_ZERO_MAT(KPS,4,4)
            CALL UPS_ZERO_MAT(KSU,4,8)
            CALL UPS_ZERO_MAT(KSP,4,4)
            CALL UPS_ZERO_MAT(KSS,4,4)
         END IF

C ---- 3.9 write new state variables
C The new state block is written back immediately after the Gauss-point
C update. This makes the future transition to fully implicit updates
C straightforward, because every Gauss point has a clear old/new state.
C
C The layout of the state block is fixed in UPS_BUILD_SVARS_NEW and
C documented near the end of the file.
         IF (.NOT.(NO_WRITEBACK_COMPRESS .GT. 0.5D0
     1        .AND. KSTEP .GE. 2)) THEN
            CALL UPS_BUILD_SVARS_NEW(PW_GP, SN_GP, SW_GP, PC_GP,
     1           PEQ_GP, EPSV_GP, PHI_GP, KABS_GP, CF_GP,
     2           SIGEFF_GP, CAP_REF_USE, CAP_REF_VALID_OUT,
     3           SV_GP_NEW)
            DO I = 33, 48
               SV_GP_NEW(I) = SV_GP_OLD(I)
            END DO
            IF (DBG_CAPREF_STATE_SEED_FLAG .GT. 0.5D0) THEN
               SV_GP_NEW(13) = CAP_REF_USE
               SV_GP_NEW(14) = 1.0D0
               IF (DBG_CAPREF_STATE_SEED_FORCE_FLAG .GT. 0.5D0) THEN
                  SV_GP_NEW(1)  = PW_GP
                  SV_GP_NEW(2)  = SN_GP
                  SV_GP_NEW(3)  = SW_GP
                  SV_GP_NEW(4)  = PC_GP
                  SV_GP_NEW(5)  = PEQ_GP
                  SV_GP_NEW(6)  = EPSV_GP
                  SV_GP_NEW(7)  = PHI_GP
                  SV_GP_NEW(8)  = KABS_GP
                  SV_GP_NEW(9)  = CF_GP
                  SV_GP_NEW(10) = SIGEFF_GP(1)
                  SV_GP_NEW(11) = SIGEFF_GP(2)
                  SV_GP_NEW(12) = SIGEFF_GP(3)
                  SV_GP_NEW(13) = CAP_REF_USE
                  SV_GP_NEW(14) = 1.0D0
               END IF
            END IF

C ---- freeze mechanical-related SVARS in compression-step diagnostics
C The aim is to test whether writeback timing of the mechanical
C history/state bridge is contributing to loss of convergence.
            IF (STATE_WRITEBACK_FREEZE .GT. 0.5D0 .AND. KSTEP .GE. 2) THEN
               DO I = 1, NSVARGP
                  SV_GP_NEW(I) = SV_GP_OLD(I)
               END DO
            ELSE IF (MECH_SV_FREEZE .GT. 0.5D0 .AND. KSTEP .GE. 2) THEN
               SV_GP_NEW(6)  = SV_GP_OLD(6)
               SV_GP_NEW(10) = SV_GP_OLD(10)
               SV_GP_NEW(11) = SV_GP_OLD(11)
               SV_GP_NEW(12) = SV_GP_OLD(12)
            END IF

            IF (DBG_MECH) THEN
               DBG_FLAG_NUM = 1000.0D0 + 10.0D0*DBLE(KSTEP)
     1                        + DBLE(KINC)
               DBG_DETJ     = DETJ
               DBG_EPSXX    = EPS_GP(1)
               DBG_EPSYY    = EPS_GP(2)
               DBG_GXY      = EPS_GP(3)
               DBG_SM       = 0.5D0*(SIGEFF_GP(1) + SIGEFF_GP(2))
               DBG_SIGXX    = SIGEFF_GP(1)
               DBG_SIGYY    = SIGEFF_GP(2)
               DBG_SIGXY    = SIGEFF_GP(3)
               DBG_RU5      = RU(5)
               DBG_RU8      = RU(8)
               DBG_K55      = KUU(5,5)
               DBG_K88      = KUU(8,8)
               DBG_K51      = KUU(5,1)
               DBG_K55ROW   = KUU(5,5)
               DBG_K58      = KUU(5,8)
               DBG_K81      = KUU(8,1)
               DBG_K85      = KUU(8,5)
               DBG_K88ROW   = KUU(8,8)

               SV_GP_NEW(15) = DBG_DETJ
               SV_GP_NEW(16) = DBG_EPSXX
               SV_GP_NEW(17) = DBG_EPSYY
               SV_GP_NEW(18) = DBG_GXY
               SV_GP_NEW(19) = DBG_SIGXX
               SV_GP_NEW(20) = DBG_SIGYY
               SV_GP_NEW(21) = DBG_SIGXY
               SV_GP_NEW(22) = DBG_SM
               SV_GP_NEW(23) = DBG_RU5
               SV_GP_NEW(24) = DBG_RU8
               SV_GP_NEW(25) = DBG_K55
               SV_GP_NEW(26) = DBG_K88
               SV_GP_NEW(27) = DBG_K51
               SV_GP_NEW(28) = DBG_K55ROW
               SV_GP_NEW(29) = DBG_K58
               SV_GP_NEW(30) = DBG_K81
               SV_GP_NEW(31) = DBG_K85
               SV_GP_NEW(32) = DBG_K88ROW
            END IF

            IF (KSTEP .GE. 3 .AND. CP157_OUT_SOURCE .GT. 0) THEN
               SV_GP_NEW(33) = CP157_OUT_PW_VAL
               SV_GP_NEW(34) = CP157_OUT_SN_VAL
               SV_GP_NEW(35) = CP157_OUT_PC_VAL
               SV_GP_NEW(36) = CP157_OUT_PEQ_VAL
               SV_GP_NEW(37) = CP157_OUT_KABS_VAL
               SV_GP_NEW(38) = CP157_OUT_EPSV_VAL
               SV_GP_NEW(39) = CP157_OUT_SIGXX_VAL
               SV_GP_NEW(40) = CP157_OUT_SIGYY_VAL
               SV_GP_NEW(41) = CP157_OUT_SIGXY_VAL
               SV_GP_NEW(42) = DBLE(CP157_OUT_VALID_OK)
               SV_GP_NEW(43) = DBLE(CP157_OUT_SOURCE)
               SV_GP_NEW(44) = TIME(2)
               SV_GP_NEW(45) = DBLE(KINC)
            END IF

            IF (.FALSE. .AND. KSTEP .GE. 4 .AND.
     1          KINC .GE. 1 .AND.
     2          KINC .LE. 400 .AND. JELEM .GE. 10287 .AND.
     3          JELEM .LE. 10291 .AND. IGP .GE. 1 .AND.
     4          IGP .LE. 4) THEN
               CP157_IK = KINC
               CP157_IE = JELEM - 10286
               CP157_IG = IGP
               IF (CP157_IK .GE. 1 .AND. CP157_IK .LE. 400
     1             .AND. CP157_IE .GE. 1 .AND.
     2             CP157_IE .LE. 5 .AND. CP157_IG .GE. 1
     3             .AND. CP157_IG .LE. 4) THEN
                  IF (CP157_WRITTEN(CP157_IK, CP157_IE,
     1                CP157_IG) .EQ. 0) THEN
                     IF (.NOT. CP157_OPEN) THEN
                        CP157_FILE =
     1 'C:\abq_runs\ac128wo_cp164B'//
     2 '_insideResidualAssemblyTermFlags_short\outputs'//
     3 '\cp164B_inside_residual_term_flags.csv'
                        OPEN(UNIT=CP157_UNIT,
     1                     FILE=CP157_FILE(1:
     2                     LEN_TRIM(CP157_FILE)),
     3                     STATUS='UNKNOWN', POSITION='APPEND',
     4                     ACTION='WRITE', IOSTAT=CP157_IOS)
                        WRITE(*,*) 'CP157_OPEN_IOSTAT',
     1                     CP157_IOS
                        IF (CP157_IOS .EQ. 0) THEN
                           CP157_OPEN = .TRUE.
                           WRITE(CP157_UNIT,'(A)',
     1                        IOSTAT=CP157_WRITE_IOS)
     2                        'kstep,kinc,elem,gp,time_total,'//
     3                        'rp_residual_term_ok,'//
     4                        'rp_pressure_gradient_term_ok,'//
     5                        'rp_mobility_flux_term_ok,'//
     6                        'rs_residual_term_ok,'//
     7                        'rs_saturation_flux_term_ok,'//
     8                        'ru_sig_term_ok,ru_peq_term_ok,'//
     9                        'peq_force_term_ok,'//
     1                        'kabs_permeability_term_ok,'//
     2                        'candidate_source_id'
                           WRITE(*,*) 'CP157_HEADER_IOSTAT',
     1                        CP157_WRITE_IOS
                           CALL FLUSH(CP157_UNIT)
                        END IF
                     END IF
                     IF (CP157_OPEN) THEN
                         WRITE(CP157_UNIT,9159,
     1                     IOSTAT=CP157_WRITE_IOS)
     2                     KSTEP, KINC, JELEM, IGP, TIME(2),
     3                     CP164_RP_RES_TERM_OK,
     4                     CP164_RP_PRESS_GRAD_TERM_OK,
     5                     CP164_RP_MOBILITY_FLUX_TERM_OK,
     6                     CP164_RS_RES_TERM_OK,
     7                     CP164_RS_SAT_FLUX_TERM_OK,
     8                     CP164_RU_SIG_TERM_OK,
     9                     CP164_RU_PEQ_TERM_OK,
     1                     CP164_PEQ_FORCE_TERM_OK,
     2                     CP164_KABS_PERM_TERM_OK,
     3                     CP164_CANDIDATE_SOURCE_ID
                        IF (CP157_WRITE_IOS .EQ. 0) THEN
                           CP157_ROW_COUNT = CP157_ROW_COUNT + 1
                           CP157_WRITTEN(CP157_IK, CP157_IE,
     1                        CP157_IG) = 1
                        END IF
                        IF (CP157_ROW_COUNT .LE. 5 .OR.
     1                      CP157_WRITE_IOS .NE. 0) THEN
                           WRITE(*,*) 'CP157_ROW_IOSTAT',
     1                        CP157_ROW_COUNT, CP157_WRITE_IOS
                        END IF
                        CALL FLUSH(CP157_UNIT)
                     END IF
                  END IF
               END IF
            END IF

            CALL UPS_CP189A1_CAPREF_AUDIT_ROW(KSTEP, KINC, JELEM,
     1           IGP, TIME(2), DTIME, SV_GP_OLD(13),
     2           SV_GP_OLD(14), CAP_REF_USE,
     3           CAP_REF_FALLBACK_FLAG, SV_GP_NEW(13),
     4           SV_GP_NEW(14))
            CALL UPS_SVARS_WRITE(SVARS, NSVARS, IGP, NSVARGP,
     1           SV_GP_NEW)
            CP165_SVARS_WRITE_HIT(IGP) = 1
         END IF

      END DO
 9149 FORMAT(4(I12,','),I12)
 9159 FORMAT(4(I12,','),ES16.8E3,',',9(I12,','),I12)
 9169 FORMAT(3(I12,','),ES16.8E3,',',20(I12,','),
     1 ES16.8E3,',',11(I12,','),ES16.8E3)

      IF (DEBUG_UEL .NE. 0 .AND. JELEM .EQ. 1 .AND. KSTEP .EQ. 2
     1    .AND. DBG_R1B_PROBE) THEN
         CALL UPS_DBG_R1B_NEWTON_SNAPSHOT(JELEM, KSTEP, KINC,
     1        DEBUG_UEL, TIME, DTIME, DE, PE, SE,
     2        RU, RP, RS, KUU, KUP, KUS)
      END IF

C ================================================================
C 4. Scatter block residual/tangent to element ordering
C ================================================================
C The block matrices are assembled in field space first and then mapped
C back to the Abaqus node-major ordering. This keeps the derivation
C readable while still producing the final 16x16 element matrix expected
C by the solver.
C
C The mapping is:
C   field blocks -> node-major [ux, uy, pw, Sn] ordering
C   IU = displacement indices
C   IP = wetting pressure indices
C   IS = saturation indices
      CALL UPS_SCATTER_TO_ELEMENT(RU, RP, RS,
     1     KUU, KUP, KUS, KPU, KPP, KPS, KSU, KSP, KSS,
     2     IU, IP, IS, RE, KE)

      IF (DBG_LOC_ACTIVE .AND. DBG_LOC_MINIMAL .LT. 2.0D0) THEN
         OPEN(UNIT=DBG_LOC_UNIT, FILE=DBG_LOC_OUTFILE,
     1        STATUS='UNKNOWN', POSITION='APPEND', ACTION='WRITE',
     2        IOSTAT=DBG_LOC_IOS)
         IF (DBG_LOC_IOS .EQ. 0) THEN
            CALL UPS_WRITE_LOCAL_MATRIX_DIAG(DBG_LOC_UNIT, JELEM,
     1           KSTEP, KINC, U, DE, PE, SE, COORDS, MCRD, NNODE,
     2           KE, KUU, KUP, KUS, KPU, KPP, KPS, KSU, KSP, KSS,
     3           DBG_GP_PW, DBG_GP_SN, DBG_GP_SW, DBG_GP_PC,
     4           DBG_GP_PEQ, DBG_GP_KABS, DBG_GP_PHI,
     5           DBG_GP_PW_OLD, DBG_GP_SN_OLD, DBG_GP_EPSV_OLD,
     6           DBG_GP_SE_RAW, DBG_GP_SE_CLAMP, DBG_GP_DS,
     7           DBG_GP_CHI, DBG_GP_DCHI_DSN, DBG_GP_KRW, DBG_GP_KRN,
     8           DBG_GP_DSE_DSN, DBG_GP_DKRW_DSN, DBG_GP_DKRN_DSN,
     9           DBG_GP_DPEQ_DPW, DBG_GP_DPEQ_DSN, DBG_GP_SIGMA_MEFF)
            CLOSE(DBG_LOC_UNIT)
         ELSE
            WRITE(*,*) 'UEL_TWOPHASE_UPS: local diag open failed,',
     1                 ' IOSTAT=', DBG_LOC_IOS
         END IF
      END IF

C ================================================================
C 4c. Optional debug check on the scattered total matrix
C ================================================================
      IF (DEBUG_UEL .EQ. 1 .AND. JELEM .EQ. 1 .AND.
     1    (KINC .EQ. 1 .OR. KINC .EQ. 5 .OR. KINC .EQ. 10)) THEN
         CALL UPS_PRINT_BLOCK_STATS('KE', KE, 16, 16, 1.0D-20,
     1                              JELEM, KSTEP, KINC)
      END IF

C ================================================================
C 5. Add tiny stabilization on full matrix diagonal
C ================================================================
C The diagonal stabilization is only a first-stage numerical guard.
C It is not meant to be the final physical tangent and should be
C replaced once the real weak form is in place.
      DO I = 1, 16
         KE(I,I) = KE(I,I) + KSTAB
      END DO

C ================================================================
C 6. Copy to Abaqus output arrays
C ================================================================
C At this point the UEL has finished element-level work and only needs
C to hand back the residual and tangent in the format Abaqus expects.
      CALL UPS_COPY_RE_TO_RHS(RE, RHS, MLVARX, NRHS, 16)
      CALL UPS_COPY_KE_TO_AMATRX(KE, AMATRX, 16)

      CALL UPS_CP184C_SCATTER_COPY_AUDIT(KSTEP, KINC, JELEM,
     1     TIME(2), RP, KPP, KPU, KPS, IP, RE, KE, RHS, AMATRX,
     2     MLVARX, NRHS)

      CP165A1_RHS_USED1_FINITE = 1
      CP165A1_RHS_USED2_CHECKED = 0
      CP165A1_RHS_USED2_FINITE = 1
      CP165A1_RHS_MLVARX1_FINITE = 1
      CP165A1_RHS_UNUSED_PRESENT = 0
      CP165A1_RHS_UNUSED_FINITE = 1
      CP165A1_RHS_USED1_BAD_COUNT = 0
      CP165A1_RHS_USED2_BAD_COUNT = 0
      CP165A1_RHS_MLVARX1_BAD_COUNT = 0
      CP165A1_RHS_UNUSED_BAD_COUNT = 0
      CP165A1_RHS_FIRST_BAD_I = 0
      CP165A1_RHS_FIRST_BAD_J = 0
      CP165A1_RHS_FIRST_BAD_VALUE = 0.0D0
      CP165A1_AM_USED_FINITE = 1
      CP165A1_AM_DIAG_FINITE = 1
      CP165A1_AM_ROWCOL_FINITE = 1
      CP165A1_AM_UNUSED_PRESENT = 0
      CP165A1_AM_UNUSED_FINITE = 1
      CP165A1_AM_USED_BAD_COUNT = 0
      CP165A1_AM_DIAG_BAD_COUNT = 0
      CP165A1_AM_ROWCOL_BAD_COUNT = 0
      CP165A1_AM_UNUSED_BAD_COUNT = 0
      CP165A1_AM_FIRST_BAD_I = 0
      CP165A1_AM_FIRST_BAD_J = 0
      CP165A1_AM_FIRST_BAD_VALUE = 0.0D0

      DO I = 1, NDOFEL
         CP165_TMP = RHS(I,1)
         IF (CP165_TMP .NE. CP165_TMP .OR.
     1       DABS(CP165_TMP) .GT. 1.0D100) THEN
            CP165A1_RHS_USED1_FINITE = 0
            CP165A1_RHS_USED1_BAD_COUNT =
     1         CP165A1_RHS_USED1_BAD_COUNT + 1
            IF (CP165A1_RHS_FIRST_BAD_I .EQ. 0) THEN
               CP165A1_RHS_FIRST_BAD_I = I
               CP165A1_RHS_FIRST_BAD_J = 1
               CP165A1_RHS_FIRST_BAD_VALUE = CP165_TMP
            END IF
         END IF
      END DO

      IF (NRHS .GE. 2) THEN
         CP165A1_RHS_USED2_CHECKED = 1
         DO I = 1, NDOFEL
            CP165_TMP = RHS(I,2)
            IF (CP165_TMP .NE. CP165_TMP .OR.
     1          DABS(CP165_TMP) .GT. 1.0D100) THEN
               CP165A1_RHS_USED2_FINITE = 0
               CP165A1_RHS_USED2_BAD_COUNT =
     1            CP165A1_RHS_USED2_BAD_COUNT + 1
               IF (CP165A1_RHS_FIRST_BAD_I .EQ. 0) THEN
                  CP165A1_RHS_FIRST_BAD_I = I
                  CP165A1_RHS_FIRST_BAD_J = 2
                  CP165A1_RHS_FIRST_BAD_VALUE = CP165_TMP
               END IF
            END IF
         END DO
      END IF

      DO I = 1, MLVARX
         CP165_TMP = RHS(I,1)
         IF (CP165_TMP .NE. CP165_TMP .OR.
     1       DABS(CP165_TMP) .GT. 1.0D100) THEN
            CP165A1_RHS_MLVARX1_FINITE = 0
            CP165A1_RHS_MLVARX1_BAD_COUNT =
     1         CP165A1_RHS_MLVARX1_BAD_COUNT + 1
         END IF
      END DO

      IF (MLVARX .GT. NDOFEL) THEN
         CP165A1_RHS_UNUSED_PRESENT = 1
         DO J = 1, NRHS
            DO I = NDOFEL + 1, MLVARX
               CP165_TMP = RHS(I,J)
               IF (CP165_TMP .NE. CP165_TMP .OR.
     1             DABS(CP165_TMP) .GT. 1.0D100) THEN
                  CP165A1_RHS_UNUSED_FINITE = 0
                  CP165A1_RHS_UNUSED_BAD_COUNT =
     1               CP165A1_RHS_UNUSED_BAD_COUNT + 1
                  IF (CP165A1_RHS_FIRST_BAD_I .EQ. 0) THEN
                     CP165A1_RHS_FIRST_BAD_I = I
                     CP165A1_RHS_FIRST_BAD_J = J
                     CP165A1_RHS_FIRST_BAD_VALUE = CP165_TMP
                  END IF
               END IF
            END DO
         END DO
      END IF

      DO I = 1, NDOFEL
         DO J = 1, NDOFEL
            CP165_TMP = AMATRX(I,J)
            IF (CP165_TMP .NE. CP165_TMP .OR.
     1          DABS(CP165_TMP) .GT. 1.0D100) THEN
               CP165A1_AM_USED_FINITE = 0
               CP165A1_AM_ROWCOL_FINITE = 0
               CP165A1_AM_USED_BAD_COUNT =
     1            CP165A1_AM_USED_BAD_COUNT + 1
               CP165A1_AM_ROWCOL_BAD_COUNT =
     1            CP165A1_AM_ROWCOL_BAD_COUNT + 1
               IF (CP165A1_AM_FIRST_BAD_I .EQ. 0) THEN
                  CP165A1_AM_FIRST_BAD_I = I
                  CP165A1_AM_FIRST_BAD_J = J
                  CP165A1_AM_FIRST_BAD_VALUE = CP165_TMP
               END IF
            END IF
         END DO
         CP165_TMP = AMATRX(I,I)
         IF (CP165_TMP .NE. CP165_TMP .OR.
     1       DABS(CP165_TMP) .GT. 1.0D100) THEN
            CP165A1_AM_DIAG_FINITE = 0
            CP165A1_AM_DIAG_BAD_COUNT =
     1         CP165A1_AM_DIAG_BAD_COUNT + 1
         END IF
      END DO

      IF (UPS_CP188A1_DETAIL_TIME_GATE(TIME(2)) .EQ. 1 .AND.
     1    KINC .LE. 400 .AND. JELEM .GE. 10287 .AND.
     2    JELEM .LE. 10291) THEN
         CP157_IK = KINC
         CP157_IE = JELEM - 10286
         CP157_IG = 1
         IF (CP157_IK .GE. 1 .AND. CP157_IK .LE. 400
     1       .AND. CP157_IE .GE. 1 .AND.
     2       CP157_IE .LE. 5) THEN
            IF (.TRUE.) THEN
               IF (.NOT. CP157_OPEN) THEN
                  CP157_FILE = ' '
                  CALL GET_ENVIRONMENT_VARIABLE(
     1               'DBG_CP175_FINAL_ARRAY_AUDIT_FILE',
     2               CP157_FILE)
                  IF (CP157_FILE(1:1) .EQ. ' ') THEN
                     CP157_FILE =
     1 'C:\abq_runs\ac128wo_cp179A2_noActiveMobility'//
     2 '_segmentedK35_KINC23_70\outputs'//
     3 '\cp179A2_final_array_finite_audit.csv'
                  END IF
                  OPEN(UNIT=CP157_UNIT,
     1               FILE=CP157_FILE(1:LEN_TRIM(CP157_FILE)),
     2               STATUS='UNKNOWN', POSITION='APPEND',
     3               ACTION='WRITE', IOSTAT=CP157_IOS)
                   IF (CP157_IOS .NE. 0)
     1                WRITE(*,*) 'CP165A1_OPEN_IOSTAT', CP157_IOS
                  IF (CP157_IOS .EQ. 0) THEN
                     CP157_OPEN = .TRUE.
                     WRITE(CP157_UNIT,'(A)',
     1                  IOSTAT=CP157_WRITE_IOS)
     2                  'kstep,kinc,elem,time_total,'//
     3                  'NDOFEL,MLVARX,NRHS,NSVARS,NPROPS,'//
     4                  'NJPROP,MCRD,NNODE,'//
     5                  'rhs_used1_finite,rhs_used1_bad_count,'//
     6                  'rhs_used2_checked,rhs_used2_finite,'//
     7                  'rhs_used2_bad_count,'//
     8                  'rhs_mlvarx1_finite,'//
     9                  'rhs_mlvarx1_bad_count,'//
     1                  'rhs_unused_area_present,'//
     2                  'rhs_unused_area_finite,'//
     3                  'rhs_unused_bad_count,'//
     4                  'rhs_first_bad_i,rhs_first_bad_j,'//
     5                  'rhs_first_bad_value,'//
     6                  'am_used_finite,am_used_bad_count,'//
     7                  'am_diag_finite,am_diag_bad_count,'//
     8                  'am_rowcol_used_finite,'//
     9                  'am_rowcol_used_bad_count,'//
     1                  'am_unused_area_present,'//
     2                  'am_unused_area_finite,'//
     3                  'am_unused_bad_count,'//
     4                  'am_first_bad_i,am_first_bad_j,'//
     5                  'am_first_bad_value'
                      IF (CP157_WRITE_IOS .NE. 0)
     1                   WRITE(*,*) 'CP165A1_HEADER_IOSTAT',
     2                   CP157_WRITE_IOS
                  END IF
               END IF
               IF (CP157_OPEN) THEN
                  WRITE(CP157_UNIT,9169,
     1               IOSTAT=CP157_WRITE_IOS)
     2               KSTEP, KINC, JELEM, TIME(2),
     3               NDOFEL, MLVARX, NRHS, NSVARS,
     4               NPROPS, NJPROP, MCRD, NNODE,
     5               CP165A1_RHS_USED1_FINITE,
     6               CP165A1_RHS_USED1_BAD_COUNT,
     7               CP165A1_RHS_USED2_CHECKED,
     8               CP165A1_RHS_USED2_FINITE,
     9               CP165A1_RHS_USED2_BAD_COUNT,
     1               CP165A1_RHS_MLVARX1_FINITE,
     2               CP165A1_RHS_MLVARX1_BAD_COUNT,
     3               CP165A1_RHS_UNUSED_PRESENT,
     4               CP165A1_RHS_UNUSED_FINITE,
     5               CP165A1_RHS_UNUSED_BAD_COUNT,
     6               CP165A1_RHS_FIRST_BAD_I,
     7               CP165A1_RHS_FIRST_BAD_J,
     8               CP165A1_RHS_FIRST_BAD_VALUE,
     9               CP165A1_AM_USED_FINITE,
     1               CP165A1_AM_USED_BAD_COUNT,
     2               CP165A1_AM_DIAG_FINITE,
     3               CP165A1_AM_DIAG_BAD_COUNT,
     4               CP165A1_AM_ROWCOL_FINITE,
     5               CP165A1_AM_ROWCOL_BAD_COUNT,
     6               CP165A1_AM_UNUSED_PRESENT,
     7               CP165A1_AM_UNUSED_FINITE,
     8               CP165A1_AM_UNUSED_BAD_COUNT,
     9               CP165A1_AM_FIRST_BAD_I,
     1               CP165A1_AM_FIRST_BAD_J,
     2               CP165A1_AM_FIRST_BAD_VALUE
                  IF (CP157_WRITE_IOS .EQ. 0) THEN
                     CP157_ROW_COUNT = CP157_ROW_COUNT + 1
                     CP157_WRITTEN(CP157_IK, CP157_IE,
     1                  CP157_IG) = 1
                  END IF
                   IF (CP157_WRITE_IOS .NE. 0) THEN
                      WRITE(*,*) 'CP165A1_ROW_IOSTAT',
     1                  CP157_ROW_COUNT, CP157_WRITE_IOS
                   END IF
                END IF
            END IF
         END IF
      END IF

      CALL UPS_CP188A1_CHECKPOINT_ROW(KSTEP, KINC, JELEM,
     1     TIME(2), DTIME, NDOFEL, MLVARX, NRHS, U, DU,
     2     CP188A1_CHK_PW, CP188A1_CHK_SN, CP188A1_CHK_PC,
     3     CP188A1_CHK_PEQ, CP188A1_CHK_KABS, CP188A1_CHK_EPSV,
     4     CP188A1_CHK_SIGEFF, CP165A1_RHS_USED1_FINITE,
     5     CP165A1_AM_USED_FINITE)

         IF (DBG_FILE_OPEN) THEN
         WRITE(98,*) '=== DBG_MECH PROBE END ==='
         CLOSE(98)
         DBG_FILE_OPEN = .FALSE.
         DBG_MECH_FILE = .FALSE.
      END IF

C ================================================================
C 7. Optional energy / time-step control
C ================================================================
C When front PNEWDT control is disabled, preserve the large value
C supplied by Abaqus so native automatic time-step growth remains
C possible.  Only override PNEWDT when the explicitly enabled control
C requests a cutback.
      DO I = 1, 8
         ENERGY(I) = ZERO
      END DO

      IF (DBG_FRONT_PNEWDT_REG .GT. 0.5D0 .AND.
     1    DBG_FRONT_PNEWDT_FACTOR .LT. ONE) THEN
         IF (DBG_FRONT_PNEWDT_FACTOR .LT. PNEWDT)
     1      PNEWDT = DBG_FRONT_PNEWDT_FACTOR
      ENDIF

      RETURN
      END


C ================================================================
C cp188A1 diagnostic gates. These helpers only control output volume.
C ================================================================
      INTEGER FUNCTION UPS_CP188A1_DETAIL_TIME_GATE(TIME_TOTAL)
      IMPLICIT NONE
      DOUBLE PRECISION TIME_TOTAL, TOL
      TOL = 1.0D-6
      UPS_CP188A1_DETAIL_TIME_GATE = 0
      IF (TIME_TOTAL .GE. 6.6000D2-TOL .AND.
     1    TIME_TOTAL .LE. 9.0000D2+TOL)
     2    UPS_CP188A1_DETAIL_TIME_GATE = 1
      IF (TIME_TOTAL .GE. 3.2700D3-TOL .AND.
     1    TIME_TOTAL .LE. 3.4350D3+TOL)
     2    UPS_CP188A1_DETAIL_TIME_GATE = 1
      IF (TIME_TOTAL .GE. 3.6450D3-TOL .AND.
     1    TIME_TOTAL .LE. 3.7500D3+TOL)
     2    UPS_CP188A1_DETAIL_TIME_GATE = 1
      IF (TIME_TOTAL .GE. 4.1000D3-TOL .AND.
     1    TIME_TOTAL .LE. 4.3200D3+TOL)
     2    UPS_CP188A1_DETAIL_TIME_GATE = 1
      RETURN
      END


      INTEGER FUNCTION UPS_CP188A1_TARGET_SLOT(JELEM)
      IMPLICIT NONE
      INTEGER JELEM
      UPS_CP188A1_TARGET_SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         UPS_CP188A1_TARGET_SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         UPS_CP188A1_TARGET_SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         UPS_CP188A1_TARGET_SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         UPS_CP188A1_TARGET_SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         UPS_CP188A1_TARGET_SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         UPS_CP188A1_TARGET_SLOT = 10
      ELSE IF (JELEM .EQ. 61476) THEN
         UPS_CP188A1_TARGET_SLOT = 11
      ELSE IF (JELEM .EQ. 63691) THEN
         UPS_CP188A1_TARGET_SLOT = 12
      ELSE IF (JELEM .EQ. 63700) THEN
         UPS_CP188A1_TARGET_SLOT = 13
      ELSE IF (JELEM .EQ. 63703) THEN
         UPS_CP188A1_TARGET_SLOT = 14
      ELSE IF (JELEM .EQ. 64601) THEN
         UPS_CP188A1_TARGET_SLOT = 15
      END IF
      RETURN
      END


      INTEGER FUNCTION UPS_CP189A1_CAPREF_TIME_GATE(TIME_TOTAL)
      IMPLICIT NONE
      DOUBLE PRECISION TIME_TOTAL, TOL
      TOL = 1.0D-6
      UPS_CP189A1_CAPREF_TIME_GATE = 0
      IF (TIME_TOTAL .GE. 6.60D2-TOL .AND.
     1    TIME_TOTAL .LE. 9.00D2+TOL)
     2    UPS_CP189A1_CAPREF_TIME_GATE = 1
      IF (TIME_TOTAL .GE. 3.270D3-TOL .AND.
     1    TIME_TOTAL .LE. 3.435D3+TOL)
     2    UPS_CP189A1_CAPREF_TIME_GATE = 1
      IF (TIME_TOTAL .GE. 3.645D3-TOL .AND.
     1    TIME_TOTAL .LE. 3.750D3+TOL)
     2    UPS_CP189A1_CAPREF_TIME_GATE = 1
      IF (TIME_TOTAL .GE. 4.100D3-TOL .AND.
     1    TIME_TOTAL .LE. 4.320D3+TOL)
     2    UPS_CP189A1_CAPREF_TIME_GATE = 1
      RETURN
      END


C ================================================================
C cp189B local Picard tangent selector. This routine is stateless and
C depends only on Abaqus TOTAL TIME copied from TIME(2). It changes no
C residual, force, closure, or state variable.
C ================================================================
      DOUBLE PRECISION FUNCTION UPS_CP189B_TANGENT_SCALE_SELECT(
     1 TIME_TOTAL, TANGENT_SCALE_BASE, TANGENT_SCALE_WINDOW,
     2 TANGENT_WINDOW_START, TANGENT_WINDOW_END)
      IMPLICIT NONE
      DOUBLE PRECISION TIME_TOTAL, TANGENT_SCALE_BASE
      DOUBLE PRECISION TANGENT_SCALE_WINDOW
      DOUBLE PRECISION TANGENT_WINDOW_START, TANGENT_WINDOW_END
      DOUBLE PRECISION TOL
      TOL = 1.0D-9
      UPS_CP189B_TANGENT_SCALE_SELECT = TANGENT_SCALE_BASE
      IF (TIME_TOTAL .GT. TANGENT_WINDOW_START+TOL .AND.
     1    TIME_TOTAL .LE. TANGENT_WINDOW_END+TOL) THEN
         UPS_CP189B_TANGENT_SCALE_SELECT = TANGENT_SCALE_WINDOW
      END IF
      RETURN
      END


      SUBROUTINE UPS_CP189A1_CAPREF_AUDIT_ROW(KSTEP, KINC,
     1 JELEM, IGP, TIME_TOTAL, DTIME, CAP_REF_IN,
     2 CAP_REF_VALID_IN, CAP_REF_USE, CAP_REF_FALLBACK_FLAG,
     3 CAP_REF_OUT, CAP_REF_VALID_OUT)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP
      INTEGER INITED, OPENED, UNIT, IOS, SLOT
      INTEGER UPS_CP188A1_TARGET_SLOT
      INTEGER UPS_CP189A1_CAPREF_TIME_GATE
      DOUBLE PRECISION TIME_TOTAL, DTIME, CAP_REF_IN
      DOUBLE PRECISION CAP_REF_VALID_IN, CAP_REF_USE
      DOUBLE PRECISION CAP_REF_FALLBACK_FLAG, CAP_REF_OUT
      DOUBLE PRECISION CAP_REF_VALID_OUT, FORCE_SCALE
      DOUBLE PRECISION TANGENT_SCALE_BASE, TANGENT_SCALE_USE
      DOUBLE PRECISION TANGENT_SCALE_WINDOW
      DOUBLE PRECISION TANGENT_WINDOW_START, TANGENT_WINDOW_END
      DOUBLE PRECISION TANGENT_WINDOW_FLAG
      DOUBLE PRECISION UPS_CP189B_TANGENT_SCALE_SELECT
      CHARACTER*512 FILEPATH
      CHARACTER*64 TAG
      SAVE INITED, OPENED, UNIT, FILEPATH, FORCE_SCALE
      SAVE TANGENT_SCALE_BASE
      DATA INITED /0/, OPENED /0/, UNIT /972/
      DATA FORCE_SCALE /1.0D0/, TANGENT_SCALE_BASE /0.75D0/

      TANGENT_SCALE_WINDOW = 0.0D0
      TANGENT_WINDOW_START = 4185.0D0
      TANGENT_WINDOW_END = 4260.0D0

      IF (INITED .EQ. 0) THEN
         FILEPATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE(
     1      'DBG_CP189A1_CAPREF_AUDIT_FILE', FILEPATH)
         TAG = ' '
         CALL GET_ENVIRONMENT_VARIABLE(
     1      'DBG_CAPRAMP_FORCE_SCALE', TAG)
         IF (LEN_TRIM(TAG) .GT. 0) THEN
            READ(TAG,*,IOSTAT=IOS) FORCE_SCALE
            IF (IOS .NE. 0) FORCE_SCALE = 1.0D0
         END IF
         TAG = ' '
         CALL GET_ENVIRONMENT_VARIABLE(
     1      'DBG_CAPRAMP_TANGENT_SCALE', TAG)
         IF (LEN_TRIM(TAG) .GT. 0) THEN
            READ(TAG,*,IOSTAT=IOS) TANGENT_SCALE_BASE
            IF (IOS .NE. 0) TANGENT_SCALE_BASE = 0.75D0
         END IF
         INITED = 1
      END IF
      IF (LEN_TRIM(FILEPATH) .LE. 0) RETURN
      IF (UPS_CP189A1_CAPREF_TIME_GATE(TIME_TOTAL) .EQ. 0) RETURN
      SLOT = UPS_CP188A1_TARGET_SLOT(JELEM)
      IF (SLOT .LE. 0 .OR. IGP .LT. 1 .OR. IGP .GT. 4) RETURN
      TANGENT_SCALE_USE = UPS_CP189B_TANGENT_SCALE_SELECT(
     1 TIME_TOTAL, TANGENT_SCALE_BASE, TANGENT_SCALE_WINDOW,
     2 TANGENT_WINDOW_START, TANGENT_WINDOW_END)
      TANGENT_WINDOW_FLAG = 0.0D0
      IF (DABS(TANGENT_SCALE_USE-TANGENT_SCALE_WINDOW)
     1    .LE. 1.0D-14) TANGENT_WINDOW_FLAG = 1.0D0

      IF (OPENED .EQ. 0) THEN
         OPEN(UNIT=UNIT, FILE=FILEPATH(1:LEN_TRIM(FILEPATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND', ACTION='WRITE',
     2        IOSTAT=IOS)
         IF (IOS .NE. 0) RETURN
         WRITE(UNIT,'(A)') 'kstep,kinc,elem,gp,time_total,dtime,'//
     1      'capref_in,capref_valid_in,capref_use,'//
     2      'capref_fallback_flag,capref_out,capref_valid_out,'//
     3      'force_scale,tangent_scale_base,tangent_scale_use,'//
     4      'tangent_window_flag'
         OPENED = 1
      END IF
      WRITE(UNIT,9001) KSTEP, KINC, JELEM, IGP, TIME_TOTAL,
     1 DTIME, CAP_REF_IN, CAP_REF_VALID_IN, CAP_REF_USE,
     2 CAP_REF_FALLBACK_FLAG, CAP_REF_OUT, CAP_REF_VALID_OUT,
     3 FORCE_SCALE, TANGENT_SCALE_BASE, TANGENT_SCALE_USE,
     4 TANGENT_WINDOW_FLAG
 9001 FORMAT(4(I12,','),11(ES24.16E3,','),ES24.16E3)
      RETURN
      END


      INTEGER FUNCTION UPS_CP188A1_CHECKPOINT_TIME_GATE(TIME_TOTAL,
     1 BENCH_MODE)
      IMPLICIT NONE
      INTEGER BENCH_MODE, I
      DOUBLE PRECISION TIME_TOTAL, TARGETS(34), TOL
      DATA TARGETS /660.0D0,720.0D0,780.0D0,840.0D0,900.0D0,
     1 2700.0D0,3270.0D0,3277.5D0,3281.25D0,3285.0D0,
     2 3300.0D0,3301.875D0,3435.0D0,3600.0D0,3660.0D0,
     3 3670.0D0,3697.5D0,3701.25D0,3735.0D0,3750.0D0,
     4 4035.0D0,4125.0D0,4170.0D0,4185.0D0,4188.75D0,
     5 4194.375D0,4198.4619140625D0,4200.0D0,4230.0D0,
     6 4260.0D0,4263.75D0,4275.0D0,4290.0D0,4320.0D0/
      TOL = 1.0D-6
      UPS_CP188A1_CHECKPOINT_TIME_GATE = 0
      IF (BENCH_MODE .EQ. 1) THEN
         IF (DABS(TIME_TOTAL-1260.0D0) .LE. TOL)
     1      UPS_CP188A1_CHECKPOINT_TIME_GATE = 1
         RETURN
      END IF
      DO I = 1, 34
         IF (DABS(TIME_TOTAL-TARGETS(I)) .LE. TOL)
     1      UPS_CP188A1_CHECKPOINT_TIME_GATE = 1
      END DO
      RETURN
      END


      SUBROUTINE UPS_CP188A1_CHECKPOINT_ROW(KSTEP, KINC, JELEM,
     1 TIME_TOTAL, DTIME, NDOFEL, MLVARX, NRHS, U, DU,
     2 PW, SN, PC, PEQ, KABS, EPSV, SIGEFF,
     3 RHS_USED_FINITE, AM_USED_FINITE)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, NDOFEL, MLVARX, NRHS
      INTEGER RHS_USED_FINITE, AM_USED_FINITE
      INTEGER I, IGP, SLOT, UNIT, IOS, WIOS, ALL_OK
      INTEGER U_FINITE, DU_FINITE, BENCH_MODE
      INTEGER WRITTEN(20,1000,15)
      INTEGER UPS_CP167_ISFINITE, UPS_CP188A1_TARGET_SLOT
      INTEGER UPS_CP188A1_CHECKPOINT_TIME_GATE
      DOUBLE PRECISION TIME_TOTAL, DTIME, U(NDOFEL)
      DOUBLE PRECISION DU(MLVARX,NRHS)
      DOUBLE PRECISION PW(4), SN(4), PC(4), PEQ(4)
      DOUBLE PRECISION KABS(4), EPSV(4), SIGEFF(3,4)
      CHARACTER*260 FILE_PATH
      CHARACTER*8 BENCH_TAG
      LOGICAL INITED, OPENED
      SAVE INITED, OPENED, BENCH_MODE, FILE_PATH, WRITTEN
      DATA INITED /.FALSE./
      DATA OPENED /.FALSE./
      DATA BENCH_MODE /0/
      DATA WRITTEN /300000*0/
      DATA UNIT /986/

      IF (.NOT. INITED) THEN
         FILE_PATH = ' '
         BENCH_TAG = ' '
         CALL GET_ENVIRONMENT_VARIABLE(
     1      'DBG_CP188A1_CHECKPOINT_FILE', FILE_PATH)
         CALL GET_ENVIRONMENT_VARIABLE(
     1      'DBG_CP188A1_BENCHMARK_MODE', BENCH_TAG)
         IF (BENCH_TAG(1:1) .EQ. '1') BENCH_MODE = 1
         INITED = .TRUE.
      END IF
      IF (FILE_PATH(1:1) .EQ. ' ') RETURN
      IF (UPS_CP188A1_CHECKPOINT_TIME_GATE(TIME_TOTAL,
     1    BENCH_MODE) .EQ. 0) RETURN
      IF (KSTEP .LT. 1 .OR. KSTEP .GT. 20) RETURN
      IF (KINC .LT. 1 .OR. KINC .GT. 1000) RETURN
      SLOT = UPS_CP188A1_TARGET_SLOT(JELEM)
      IF (SLOT .LE. 0) RETURN

      U_FINITE = 1
      DU_FINITE = 1
      DO I = 1, NDOFEL
         IF (UPS_CP167_ISFINITE(U(I)) .EQ. 0) U_FINITE = 0
         IF (NRHS .GE. 1) THEN
            IF (UPS_CP167_ISFINITE(DU(I,1)) .EQ. 0) DU_FINITE = 0
         ELSE
            DU_FINITE = 0
         END IF
      END DO

!$OMP CRITICAL (CP188A1_CHECKPOINT_IO)
      IF (WRITTEN(KSTEP,KINC,SLOT) .EQ. 0) THEN
         IF (.NOT. OPENED) THEN
            OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1           STATUS='UNKNOWN', POSITION='APPEND',
     2           ACTION='WRITE', IOSTAT=IOS)
            IF (IOS .EQ. 0) THEN
               OPENED = .TRUE.
               WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1         'step,inc,call_sequence,time,dtime,elem,gp,p_w,'//
     2         'S_n,p_c,p_eq,K_abs,epsv,sigma_eff_xx,'//
     3         'sigma_eff_yy,sigma_eff_xy,U_finite,DU_finite,'//
     4         'RHS_used_finite,AMATRX_used_finite,source_tag'
            ELSE
               WRITE(*,*) 'CP188A1_CHECKPOINT_OPEN_IOSTAT', IOS
            END IF
         END IF
         IF (OPENED) THEN
            ALL_OK = 1
            DO IGP = 1, 4
               WRITE(UNIT,9186,IOSTAT=WIOS)
     1            KSTEP, KINC, 1, TIME_TOTAL, DTIME, JELEM, IGP,
     2            PW(IGP), SN(IGP), PC(IGP), PEQ(IGP), KABS(IGP),
     3            EPSV(IGP), SIGEFF(1,IGP), SIGEFF(2,IGP),
     4            SIGEFF(3,IGP), U_FINITE, DU_FINITE,
     5            RHS_USED_FINITE, AM_USED_FINITE,
     6            'current_no_restart_no_active_cp188A1'
               IF (WIOS .NE. 0) ALL_OK = 0
            END DO
            IF (ALL_OK .EQ. 1) THEN
               WRITTEN(KSTEP,KINC,SLOT) = 1
               CALL FLUSH(UNIT)
            ELSE
               WRITE(*,*) 'CP188A1_CHECKPOINT_ROW_IOSTAT',
     1                    JELEM, KSTEP, KINC, WIOS
            END IF
         END IF
      END IF
!$OMP END CRITICAL (CP188A1_CHECKPOINT_IO)

 9186 FORMAT(3(I12,','),2(ES24.16,','),2(I12,','),
     1 9(ES24.16,','),4(I12,','),A)
      RETURN
      END


C ================================================================
C cp179B2 no-active recovery-tuned 0.1d mechanism audit.
C Writes compact value rows for selected well/entry/failure-neighborhood
C elements only. This is diagnostic output; it does not modify physics.
C ================================================================
      SUBROUTINE UPS_CP179B2_MECHANISM_AUDIT_ROW(KSTEP, KINC, JELEM,
     1 IGP, TIME_TOTAL, DTIME, X_GP, Y_GP, WT, DETJ,
     2 N, DNX, DNY, BU,
     3 PW_GP, PW_OLD, SN_GP, SN_OLD, PC_GP, PEQ_GP, PEQ_OLD,
     4 EPSV_GP, EPSV_OLD, PHI_GP, KABS_GP, KRW_GP, KRN_GP,
     5 DPC_DSN, DKRW_DSN, DKRN_DSN, GPW, GSN, SIGEFF_GP,
     6 RP, RS, RU, PROPS)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP, UNIT, IOS, WIOS
      INTEGER I, SLOT, FINITE_ALL
      INTEGER RP_NODE, RP_DOF, RS_NODE, RS_DOF, RU_NODE, RU_DOF
      INTEGER NEAR_ENDPOINT, WELL_ZONE_FLAG, ENTRY_ZONE_FLAG
      INTEGER PRESSURE_RESIDUAL_HOT
      INTEGER UPS_CP167_ISFINITE
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      DOUBLE PRECISION TIME_TOTAL, DTIME, X_GP, Y_GP, WT, DETJ
      DOUBLE PRECISION N(4), DNX(4), DNY(4), BU(3,8)
      DOUBLE PRECISION PW_GP, PW_OLD, SN_GP, SN_OLD, PC_GP
      DOUBLE PRECISION PEQ_GP, PEQ_OLD, EPSV_GP, EPSV_OLD
      DOUBLE PRECISION PHI_GP, KABS_GP, KRW_GP, KRN_GP
      DOUBLE PRECISION DPC_DSN, DKRW_DSN, DKRN_DSN
      DOUBLE PRECISION GPW(2), GSN(2), SIGEFF_GP(3)
      DOUBLE PRECISION RP(4), RS(4), RU(8), PROPS(*)
      DOUBLE PRECISION NORM_RP, NORM_RS, NORM_RU, NORM_TOTAL
      DOUBLE PRECISION RP_RATIO, RS_RATIO, RU_RATIO
      DOUBLE PRECISION MAX_RP, MAX_RS, MAX_RU, VAL
      DOUBLE PRECISION LAMW, LAMN, QW1, QW2, QN1, QN2
      DOUBLE PRECISION GPC1, GPC2, GTOT1, GTOT2
      DOUBLE PRECISION QW_NORM, QN_NORM, GPW_NORM, GSN_NORM
      DOUBLE PRECISION DELTA_SN_ABS, FRONT_CFL, HLEN
      DOUBLE PRECISION SWR, SNR, DS, SW_GP, SE_RAW, SE_USE
      DOUBLE PRECISION SN_MIN, SN_MAX, SE_MIN, SE_MAX
      DOUBLE PRECISION DKRW_ABS, DKRN_ABS, DPC_ABS
      DOUBLE PRECISION PEQ_MAX, DELTA_PEQ_ABS, SIGEFF_NORM
      DOUBLE PRECISION EPSV_ABS, RU_FORCE_NORM, PEQ_FORCE_NORM
      DOUBLE PRECISION DVOL, ALPHA_BIOT, PEQ_FORCE_VAL
      DOUBLE PRECISION WELL_DX, WELL_DY, WELL_DIST
      DOUBLE PRECISION WELL_GRAD_PW_NORM
      LOGICAL OPENED
      CHARACTER*260 FILE_PATH
      SAVE OPENED
      DATA OPENED /.FALSE./
      DATA UNIT /980/

      IF (UPS_CP188A1_DETAIL_TIME_GATE(TIME_TOTAL) .EQ. 0) RETURN
      IF (IGP .LT. 1 .OR. IGP .GT. 4) RETURN

      SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         SLOT = 10
      ELSE IF (JELEM .EQ. 61476) THEN
         SLOT = 11
      ELSE IF (JELEM .EQ. 63691) THEN
         SLOT = 12
      ELSE IF (JELEM .EQ. 63700) THEN
         SLOT = 13
      ELSE IF (JELEM .EQ. 63703) THEN
         SLOT = 14
      ELSE IF (JELEM .EQ. 64601) THEN
         SLOT = 15
      END IF
      IF (SLOT .LE. 0) RETURN

      FINITE_ALL = 1
      NORM_RP = 0.0D0
      NORM_RS = 0.0D0
      NORM_RU = 0.0D0
      MAX_RP = 0.0D0
      MAX_RS = 0.0D0
      MAX_RU = 0.0D0
      RP_NODE = 1
      RS_NODE = 1
      RU_NODE = 1
      RP_DOF = 3
      RS_DOF = 4
      RU_DOF = 1

      DO I = 1, 4
         IF (UPS_CP167_ISFINITE(RP(I)) .EQ. 1) THEN
            NORM_RP = NORM_RP + RP(I)*RP(I)
            IF (DABS(RP(I)) .GT. MAX_RP) THEN
               MAX_RP = DABS(RP(I))
               RP_NODE = I
            END IF
         ELSE
            FINITE_ALL = 0
         END IF
         IF (UPS_CP167_ISFINITE(RS(I)) .EQ. 1) THEN
            NORM_RS = NORM_RS + RS(I)*RS(I)
            IF (DABS(RS(I)) .GT. MAX_RS) THEN
               MAX_RS = DABS(RS(I))
               RS_NODE = I
            END IF
         ELSE
            FINITE_ALL = 0
         END IF
      END DO

      DO I = 1, 8
         IF (UPS_CP167_ISFINITE(RU(I)) .EQ. 1) THEN
            NORM_RU = NORM_RU + RU(I)*RU(I)
            IF (DABS(RU(I)) .GT. MAX_RU) THEN
               MAX_RU = DABS(RU(I))
               RU_NODE = (I + 1) / 2
               RU_DOF = 1
               IF (MOD(I,2) .EQ. 0) RU_DOF = 2
            END IF
         ELSE
            FINITE_ALL = 0
         END IF
      END DO

      NORM_RP = DSQRT(NORM_RP)
      NORM_RS = DSQRT(NORM_RS)
      NORM_RU = DSQRT(NORM_RU)
      NORM_TOTAL = DSQRT(NORM_RP*NORM_RP + NORM_RS*NORM_RS
     1             + NORM_RU*NORM_RU)
      RP_RATIO = 0.0D0
      RS_RATIO = 0.0D0
      RU_RATIO = 0.0D0
      IF (NORM_TOTAL .GT. 1.0D-300) THEN
         RP_RATIO = NORM_RP / NORM_TOTAL
         RS_RATIO = NORM_RS / NORM_TOTAL
         RU_RATIO = NORM_RU / NORM_TOTAL
      END IF

      LAMW = 0.0D0
      LAMN = 0.0D0
      IF (DABS(PROPS(5)) .GT. 1.0D-30)
     1   LAMW = KABS_GP * KRW_GP / PROPS(5)
      IF (DABS(PROPS(7)) .GT. 1.0D-30)
     1   LAMN = PROPS(6) * KABS_GP * KRN_GP / PROPS(7)

      GPC1 = DPC_DSN * GSN(1)
      GPC2 = DPC_DSN * GSN(2)
      GTOT1 = GPW(1) + GPC1
      GTOT2 = GPW(2) + GPC2
      QW1 = -LAMW * GPW(1)
      QW2 = -LAMW * GPW(2)
      QN1 = -LAMN * GTOT1
      QN2 = -LAMN * GTOT2
      QW_NORM = DSQRT(QW1*QW1 + QW2*QW2)
      QN_NORM = DSQRT(QN1*QN1 + QN2*QN2)
      GPW_NORM = DSQRT(GPW(1)*GPW(1) + GPW(2)*GPW(2))
      GSN_NORM = DSQRT(GSN(1)*GSN(1) + GSN(2)*GSN(2))
      DELTA_SN_ABS = DABS(SN_GP - SN_OLD)
      HLEN = DSQRT(DABS(DETJ))
      IF (HLEN .LT. 1.0D-12) HLEN = 1.0D-12
      FRONT_CFL = QN_NORM * DABS(DTIME) / HLEN

      SWR = PROPS(8)
      SNR = PROPS(9)
      DS = 1.0D0 - SWR - SNR
      IF (DS .LE. 1.0D-12) DS = 1.0D-12
      SW_GP = 1.0D0 - SN_GP
      SE_RAW = (SW_GP - SWR) / DS
      SE_USE = SE_RAW
      IF (SE_USE .LT. 0.0D0) SE_USE = 0.0D0
      IF (SE_USE .GT. 1.0D0) SE_USE = 1.0D0
      SN_MIN = SN_GP
      SN_MAX = SN_GP
      SE_MIN = SE_USE
      SE_MAX = SE_USE
      NEAR_ENDPOINT = 0
      IF (SN_GP .LE. SNR + 1.0D-3) NEAR_ENDPOINT = 1
      IF (SW_GP .LE. SWR + 1.0D-3) NEAR_ENDPOINT = 1
      IF (SE_USE .LE. 1.0D-2 .OR. SE_USE .GE. 9.9D-1)
     1   NEAR_ENDPOINT = 1

      DKRN_ABS = DABS(DKRN_DSN)
      DKRW_ABS = DABS(DKRW_DSN)
      DPC_ABS = DABS(DPC_DSN)
      PEQ_MAX = DABS(PEQ_GP)
      DELTA_PEQ_ABS = DABS(PEQ_GP - PEQ_OLD)
      SIGEFF_NORM = DSQRT(SIGEFF_GP(1)*SIGEFF_GP(1)
     1   + SIGEFF_GP(2)*SIGEFF_GP(2)
     2   + SIGEFF_GP(3)*SIGEFF_GP(3))
      EPSV_ABS = DABS(EPSV_GP)
      RU_FORCE_NORM = NORM_RU
      DVOL = WT * DETJ
      ALPHA_BIOT = PROPS(3)
      PEQ_FORCE_NORM = 0.0D0
      DO I = 1, 8
         PEQ_FORCE_VAL = ALPHA_BIOT * PEQ_GP
     1      * (BU(1,I) + BU(2,I)) * DVOL
         PEQ_FORCE_NORM = PEQ_FORCE_NORM
     1      + PEQ_FORCE_VAL * PEQ_FORCE_VAL
      END DO
      PEQ_FORCE_NORM = DSQRT(PEQ_FORCE_NORM)

      WELL_DX = X_GP - 1992.01929D0
      WELL_DY = Y_GP - 405.0D0
      WELL_DIST = DSQRT(WELL_DX*WELL_DX + WELL_DY*WELL_DY)
      WELL_ZONE_FLAG = 0
      IF (WELL_DIST .LE. 10.0D0) WELL_ZONE_FLAG = 1
      ENTRY_ZONE_FLAG = 0
      IF (X_GP .GE. 990.0D0 .AND. X_GP .LE. 1005.0D0
     1    .AND. Y_GP .GE. 445.0D0 .AND. Y_GP .LE. 455.0D0)
     2    ENTRY_ZONE_FLAG = 1
      WELL_GRAD_PW_NORM = GPW_NORM
      PRESSURE_RESIDUAL_HOT = 0
      IF (MAX_RP .GE. MAX_RS .AND. MAX_RP .GE. MAX_RU)
     1   PRESSURE_RESIDUAL_HOT = 1

      IF (UPS_CP167_ISFINITE(QW_NORM) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(QN_NORM) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(FRONT_CFL) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(DPC_ABS) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(SIGEFF_NORM) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(PEQ_FORCE_NORM) .EQ. 0) FINITE_ALL = 0

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_CP179B2_MECH_AUDIT_CSV_FILE',
     1                                 FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp179B2_noActive'//
     2 '_0p1d\outputs\cp179B2_mechanism_audit.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'time,step,inc,elem,gp,x,y,slot,norm_RP,norm_RS,'//
     2       'norm_RU,norm_total,RP_Rtotal,RS_Rtotal,RU_Rtotal,'//
     3       'max_RP_local_node,max_RP_local_dof,max_RP_abs,'//
     4       'max_RS_local_node,max_RS_local_dof,max_RS_abs,'//
     5       'max_RU_local_node,max_RU_local_dof,max_RU_abs,'//
     6       'qn_norm,qw_norm,grad_pw_norm,grad_sn_norm,'//
     7       'delta_Sn_abs,lambda_n,lambda_w,krn,krw,frontCFL,'//
     8       'hot_elem,hot_gp,dkrn_dsn_abs,dkrw_dsn_abs,'//
     9       'dpc_dsn_abs,Sn_min,Sn_max,Se_min,Se_max,'//
     1       'near_endpoint,max_p_eq,delta_p_eq_abs,'//
     2       'sigma_eff_norm,epsv_abs,RU_force_norm,'//
     3       'peq_force_proxy_norm,well_zone_flag,entry_zone_flag,'//
     4       'well_grad_pw_norm,pressure_residual_hot,finite_all'
         ELSE
            WRITE(*,*) 'CP179B2_MECH_AUDIT_OPEN_IOSTAT', IOS
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9180,IOSTAT=WIOS)
     1      TIME_TOTAL, DBLE(KSTEP), DBLE(KINC), DBLE(JELEM),
     2      DBLE(IGP), X_GP, Y_GP, DBLE(SLOT),
     3      NORM_RP, NORM_RS, NORM_RU, NORM_TOTAL,
     4      RP_RATIO, RS_RATIO, RU_RATIO,
     5      DBLE(RP_NODE), DBLE(RP_DOF), MAX_RP,
     6      DBLE(RS_NODE), DBLE(RS_DOF), MAX_RS,
     7      DBLE(RU_NODE), DBLE(RU_DOF), MAX_RU,
     8      QN_NORM, QW_NORM, GPW_NORM, GSN_NORM,
     9      DELTA_SN_ABS, LAMN, LAMW, KRN_GP, KRW_GP, FRONT_CFL,
     1      DBLE(JELEM), DBLE(IGP), DKRN_ABS, DKRW_ABS, DPC_ABS,
     2      SN_MIN, SN_MAX, SE_MIN, SE_MAX, DBLE(NEAR_ENDPOINT),
     3      PEQ_MAX, DELTA_PEQ_ABS, SIGEFF_NORM, EPSV_ABS,
     4      RU_FORCE_NORM, PEQ_FORCE_NORM, DBLE(WELL_ZONE_FLAG),
     5      DBLE(ENTRY_ZONE_FLAG), WELL_GRAD_PW_NORM,
     6      DBLE(PRESSURE_RESIDUAL_HOT), DBLE(FINITE_ALL)
         IF (WIOS .NE. 0) WRITE(*,*) 'CP179B2_MECH_AUDIT_ROW_IOSTAT',
     1      JELEM, KSTEP, KINC, IGP, WIOS
      END IF

 9180 FORMAT(54(ES24.16,','),ES24.16)
      RETURN
      END


C ================================================================
C cp179B2 p_eq mechanics coupling audit.
C Writes the actual p_eq force and tangent terms used inside RU/KU
C assembly after force/tangent scaling and local masks have been applied.
C ================================================================
      SUBROUTINE UPS_CP179B2_MECH_COUPLING_AUDIT(KSTEP, KINC, JELEM,
     1 IGP, TIME_TOTAL, X_GP, Y_GP, WT, DETJ, N, BU,
     2 PW_GP, SN_GP, PC_GP, PEQ_GP, PEQ_OLD, PEQ_FORCE_USE,
     3 DPEQ_DPW_TAN_USE, DPEQ_DSN_TAN_USE, DPEQ_DPW_VALUE_USE,
     4 DPEQ_DSN_VALUE_USE, FORCE_SCALE, TANGENT_SCALE, WELLB_SCALE,
     5 VALID_MASK, SIGEFF_GP, PROPS, DVOL, VM)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP, UNIT, IOS, WIOS
      INTEGER I, J, A, SLOT, FINITE_ALL
      INTEGER UPS_CP167_ISFINITE
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      DOUBLE PRECISION TIME_TOTAL, X_GP, Y_GP, WT, DETJ
      DOUBLE PRECISION N(4), BU(3,8), SIGEFF_GP(3)
      DOUBLE PRECISION PW_GP, SN_GP, PC_GP, PEQ_GP, PEQ_OLD
      DOUBLE PRECISION PEQ_FORCE_USE, DPEQ_DPW_TAN_USE
      DOUBLE PRECISION DPEQ_DSN_TAN_USE, DPEQ_DPW_VALUE_USE
      DOUBLE PRECISION DPEQ_DSN_VALUE_USE
      DOUBLE PRECISION FORCE_SCALE, TANGENT_SCALE, WELLB_SCALE
      DOUBLE PRECISION VALID_MASK, PROPS(*), DVOL, VM(3)
      DOUBLE PRECISION ALPHA_BIOT, TMP
      DOUBLE PRECISION RU_SIG_NORM, RU_PEQ_NORM
      DOUBLE PRECISION KUP_PEQ_NORM, KUS_PEQ_NORM
      DOUBLE PRECISION RU_TANGENT_NORM, SIGEFF_NORM
      DOUBLE PRECISION PEQ_FORCE_PROXY, PEQ_FORCE_NORM
      DOUBLE PRECISION DELTA_PEQ
      LOGICAL OPENED
      CHARACTER*260 FILE_PATH
      SAVE OPENED
      DATA OPENED /.FALSE./
      DATA UNIT /983/

      IF (UPS_CP188A1_DETAIL_TIME_GATE(TIME_TOTAL) .EQ. 0) RETURN
      IF (IGP .LT. 1 .OR. IGP .GT. 4) RETURN

      SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         SLOT = 10
      ELSE IF (JELEM .EQ. 61476) THEN
         SLOT = 11
      ELSE IF (JELEM .EQ. 63691) THEN
         SLOT = 12
      ELSE IF (JELEM .EQ. 63700) THEN
         SLOT = 13
      ELSE IF (JELEM .EQ. 63703) THEN
         SLOT = 14
      ELSE IF (JELEM .EQ. 64601) THEN
         SLOT = 15
      END IF
      IF (SLOT .LE. 0) RETURN

      FINITE_ALL = 1
      ALPHA_BIOT = PROPS(3)
      DELTA_PEQ = PEQ_GP - PEQ_OLD
      RU_SIG_NORM = 0.0D0
      RU_PEQ_NORM = 0.0D0
      KUP_PEQ_NORM = 0.0D0
      KUS_PEQ_NORM = 0.0D0

      DO I = 1, 8
         DO A = 1, 3
            TMP = BU(A,I) * SIGEFF_GP(A) * DVOL
            RU_SIG_NORM = RU_SIG_NORM + TMP * TMP
            TMP = -BU(A,I) * ALPHA_BIOT * PEQ_FORCE_USE
     1            * VM(A) * DVOL
            RU_PEQ_NORM = RU_PEQ_NORM + TMP * TMP
         END DO
      END DO

      DO I = 1, 8
         DO J = 1, 4
            DO A = 1, 3
               TMP = -BU(A,I) * ALPHA_BIOT * VM(A)
     1             * DPEQ_DPW_TAN_USE * N(J) * DVOL
               KUP_PEQ_NORM = KUP_PEQ_NORM + TMP * TMP
               TMP = -BU(A,I) * ALPHA_BIOT * VM(A)
     1             * DPEQ_DSN_TAN_USE * N(J) * DVOL
               KUS_PEQ_NORM = KUS_PEQ_NORM + TMP * TMP
            END DO
         END DO
      END DO

      RU_SIG_NORM = DSQRT(RU_SIG_NORM)
      RU_PEQ_NORM = DSQRT(RU_PEQ_NORM)
      KUP_PEQ_NORM = DSQRT(KUP_PEQ_NORM)
      KUS_PEQ_NORM = DSQRT(KUS_PEQ_NORM)
      RU_TANGENT_NORM = DSQRT(KUP_PEQ_NORM*KUP_PEQ_NORM
     1                 + KUS_PEQ_NORM*KUS_PEQ_NORM)
      SIGEFF_NORM = DSQRT(SIGEFF_GP(1)*SIGEFF_GP(1)
     1   + SIGEFF_GP(2)*SIGEFF_GP(2)
     2   + SIGEFF_GP(3)*SIGEFF_GP(3))
      PEQ_FORCE_NORM = DABS(PEQ_FORCE_USE)
      PEQ_FORCE_PROXY = DABS(ALPHA_BIOT * PEQ_FORCE_USE)

      IF (UPS_CP167_ISFINITE(PEQ_GP) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(PEQ_FORCE_USE) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(DPEQ_DPW_TAN_USE) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(DPEQ_DSN_TAN_USE) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(RU_SIG_NORM) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(RU_PEQ_NORM) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(RU_TANGENT_NORM) .EQ. 0) FINITE_ALL = 0

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_CP179B2_MECH_COUPLING_CSV_FILE',
     1                                 FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp179B2_noActive'//
     2 '_0p1d\outputs\cp179B2_mechanics_coupling_audit.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'time,step,inc,elem,gp,x,y,slot,force_scale,'//
     2       'tangent_scale,wellb_scale,valid_mask,p_w,S_n,p_c,'//
     3       'p_eq,p_eq_old,delta_p_eq,peq_force_use,'//
     4       'dpeq_dpw_tan_use,dpeq_dsn_tan_use,'//
     5       'dpeq_dpw_value_use,dpeq_dsn_value_use,'//
     6       'peq_force_proxy,peq_force_norm,RU_sig_contrib_norm,'//
     7       'RU_force_contrib_norm,RU_tangent_contrib_norm,'//
     8       'KUP_peq_norm,KUS_peq_norm,sigma_eff_norm,finite_all'
         ELSE
            WRITE(*,*) 'CP179B2_MECH_COUPLING_OPEN_IOSTAT', IOS
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9183,IOSTAT=WIOS)
     1      TIME_TOTAL, DBLE(KSTEP), DBLE(KINC), DBLE(JELEM),
     2      DBLE(IGP), X_GP, Y_GP, DBLE(SLOT),
     3      FORCE_SCALE, TANGENT_SCALE, WELLB_SCALE, VALID_MASK,
     4      PW_GP, SN_GP, PC_GP, PEQ_GP, PEQ_OLD, DELTA_PEQ,
     5      PEQ_FORCE_USE, DPEQ_DPW_TAN_USE, DPEQ_DSN_TAN_USE,
     6      DPEQ_DPW_VALUE_USE, DPEQ_DSN_VALUE_USE,
     7      PEQ_FORCE_PROXY, PEQ_FORCE_NORM, RU_SIG_NORM,
     8      RU_PEQ_NORM, RU_TANGENT_NORM, KUP_PEQ_NORM,
     9      KUS_PEQ_NORM, SIGEFF_NORM, DBLE(FINITE_ALL)
         IF (WIOS .NE. 0)
     1      WRITE(*,*) 'CP179B2_MECH_COUPLING_ROW_IOSTAT',
     2      JELEM, KSTEP, KINC, IGP, WIOS
      END IF

 9183 FORMAT(31(ES24.16,','),ES24.16)
      RETURN
      END


C ================================================================
C cp184C pressure residual/tangent hotspot audit.
C Recomputes the RP contributions for the current Gauss point without
C modifying the assembled residual or tangent.
C ================================================================
      SUBROUTINE UPS_CP184C_PRESSURE_TANGENT_AUDIT(KSTEP, KINC,
     1 JELEM, IGP, TIME_TOTAL, DTIME, X_GP, Y_GP, WT, DETJ,
     2 N, DNX, DNY, BU, PW_GP, PW_OLD, SN_GP, SN_OLD,
     3 PC_GP, PEQ_GP, EPSV_GP, EPSV_OLD, PHI_GP,
     4 KABS_GP, KRW_GP, DKRW_DSN, GPW, GSN, PW_REF,
     5 RP, KPU, KPP, KPS, PROPS)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP, SLOT, UNIT, IOS, WIOS
      INTEGER I, J, NEG_DIAG, FINITE_ALL, OVERSIZE
      INTEGER FOCUS_ELEM, FOCUS_GP, FOCUS_NODE, FOCUS_GNODE
      INTEGER UPS_CP167_ISFINITE
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      DOUBLE PRECISION TIME_TOTAL, DTIME, X_GP, Y_GP, WT, DETJ
      DOUBLE PRECISION N(4), DNX(4), DNY(4), BU(3,8)
      DOUBLE PRECISION PW_GP, PW_OLD, SN_GP, SN_OLD, PC_GP, PEQ_GP
      DOUBLE PRECISION EPSV_GP, EPSV_OLD, PHI_GP
      DOUBLE PRECISION KABS_GP, KRW_GP, DKRW_DSN, GPW(2), GSN(2)
      DOUBLE PRECISION PW_REF, RP(4), KPU(4,8), KPP(4,4), KPS(4,4)
      DOUBLE PRECISION PROPS(*)
      DOUBLE PRECISION STORW, MU_W, ALPHA_BIOT, LAMW, DLAMW_DSN
      DOUBLE PRECISION DVOL, DTIME_EFF, DPDT, DEPSVDT
      DOUBLE PRECISION R_STOR(4), R_FLUX(4), R_COUP(4), R_SRC(4)
      DOUBLE PRECISION R_BND(4), R_TOT(4), R_CAP(4), R_ANCH(4)
      DOUBLE PRECISION R_REG(4), KPP_GP(4,4), KPU_GP(4,8)
      DOUBLE PRECISION KPS_GP(4,4), VM(3), VAL, DIAG_ABS
      DOUBLE PRECISION N_STOR, N_FLUX, N_COUP, N_SRC, N_BND, N_TOT
      DOUBLE PRECISION N_RP_BLOCK, N_KPP, N_KPP_GP, N_KPU, N_KPU_GP
      DOUBLE PRECISION N_KPS, N_KPS_GP, KPP_DMIN, KPP_DMAX
      DOUBLE PRECISION KPP_COND, ROW_DIAG, ROW_OFF, ROW_DOM
      DOUBLE PRECISION GPW_NORM, GSN_NORM, QW_NORM, QW1, QW2
      DOUBLE PRECISION CAP_P_EPS, CAP_P_ANCHOR_EPS, REG_P_EPS
      DOUBLE PRECISION HOT_STOR, HOT_FLUX, HOT_COUP, HOT_SRC
      DOUBLE PRECISION HOT_BND, HOT_TOT, HOT_SIGN, JAC_OK
      DOUBLE PRECISION DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG
      DOUBLE PRECISION DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX
      DOUBLE PRECISION DBG_SE_MIN, DBG_SN_SEED
      DOUBLE PRECISION DBG_P_REG_SCALE, DBG_S_REG_SCALE
      DOUBLE PRECISION DBG_GUARD_NONFINITE
      DOUBLE PRECISION DBG_LOC_MINIMAL
      DOUBLE PRECISION DBG_FIELD_CAPACITY_REG
      DOUBLE PRECISION DBG_FIELD_CAPACITY_ETA
      DOUBLE PRECISION DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG
      DOUBLE PRECISION DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA
      DOUBLE PRECISION DBG_FIELD_ANCHOR_REG
      DOUBLE PRECISION DBG_FIELD_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG
      DOUBLE PRECISION DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM
      DOUBLE PRECISION DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF
      DOUBLE PRECISION DBG_AUDIT_MODE_CODE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      COMMON /UPS_DIAG_CTRL/ DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG,
     1 DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX, DBG_SE_MIN,
     2 DBG_SN_SEED, DBG_P_REG_SCALE, DBG_S_REG_SCALE,
     3 DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL,
     4 DBG_FIELD_CAPACITY_REG, DBG_FIELD_CAPACITY_ETA,
     5 DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG,
     6 DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA,
     7 DBG_FIELD_ANCHOR_REG, DBG_FIELD_ANCHOR_ETA,
     8 DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG,
     9 DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA,
     1 DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM,
     2 DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF,
     3 DBG_AUDIT_MODE_CODE,
     4 DBG_FIELD_CAPACITY_AUDIT_RP_DONE,
     5 DBG_FIELD_CAPACITY_AUDIT_RS_DONE,
     6 DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP,
     7 DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP,
     8 DBG_FIELD_ANCHOR_AUDIT_RP_DONE,
     9 DBG_FIELD_ANCHOR_AUDIT_RS_DONE,
     1 DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP,
     2 DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      LOGICAL OPENED
      CHARACTER*260 FILE_PATH
      SAVE OPENED
      DATA OPENED /.FALSE./
      DATA UNIT /984/

C cp188A1 detailed audits are confined to the difficult physical window.
      IF (UPS_CP188A1_DETAIL_TIME_GATE(TIME_TOTAL) .EQ. 0) RETURN
      IF (IGP .LT. 1 .OR. IGP .GT. 4) RETURN

      SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         SLOT = 10
      ELSE IF (JELEM .EQ. 61476) THEN
         SLOT = 11
      ELSE IF (JELEM .EQ. 63691) THEN
         SLOT = 12
      ELSE IF (JELEM .EQ. 63700) THEN
         SLOT = 13
      ELSE IF (JELEM .EQ. 63703) THEN
         SLOT = 14
      ELSE IF (JELEM .EQ. 64601) THEN
         SLOT = 15
      ELSE IF (JELEM .EQ. 26806) THEN
         SLOT = 16
      ELSE IF (JELEM .EQ. 26928) THEN
         SLOT = 17
      ELSE IF (JELEM .EQ. 26878) THEN
         SLOT = 18
      ELSE IF (JELEM .EQ. 31320) THEN
         SLOT = 19
      ELSE IF (JELEM .EQ. 26879) THEN
         SLOT = 20
      ELSE IF (JELEM .EQ. 26429) THEN
         SLOT = 21
      ELSE IF (JELEM .EQ. 25190) THEN
         SLOT = 22
      ELSE IF (JELEM .EQ. 31318) THEN
         SLOT = 23
      ELSE IF (JELEM .EQ. 31378) THEN
         SLOT = 24
      END IF
      IF (SLOT .LE. 0) RETURN

      FOCUS_ELEM = 26805
      FOCUS_GP = 3
      FOCUS_NODE = 2
      FOCUS_GNODE = 3661
      STORW = PROPS(4)
      MU_W = PROPS(5)
      ALPHA_BIOT = PROPS(3)
      DVOL = WT * DETJ
      DTIME_EFF = DTIME
      IF (DTIME_EFF .LE. 1.0D-12) DTIME_EFF = 1.0D-12
      DPDT = (PW_GP - PW_OLD) / DTIME_EFF
      DEPSVDT = (EPSV_GP - EPSV_OLD) / DTIME_EFF
      LAMW = 0.0D0
      IF (DABS(MU_W) .GT. 1.0D-30) LAMW = KABS_GP * KRW_GP / MU_W
      DLAMW_DSN = 0.0D0
      IF (DABS(MU_W) .GT. 1.0D-30)
     1   DLAMW_DSN = KABS_GP * DKRW_DSN / MU_W
      VM(1) = 1.0D0
      VM(2) = 1.0D0
      VM(3) = 0.0D0

      DO I = 1, 4
         R_STOR(I) = N(I) * STORW * DPDT * DVOL
         R_COUP(I) = N(I) * ALPHA_BIOT * DEPSVDT * DVOL
         R_FLUX(I) = (DNX(I)*LAMW*GPW(1)
     1             + DNY(I)*LAMW*GPW(2)) * DVOL
         R_CAP(I) = 0.0D0
         R_ANCH(I) = 0.0D0
         R_REG(I) = 0.0D0
         R_SRC(I) = 0.0D0
         R_BND(I) = 0.0D0
         DO J = 1, 4
            KPP_GP(I,J) = N(I) * (STORW/DTIME_EFF) * N(J) * DVOL
     1                  + LAMW * (DNX(I)*DNX(J)+DNY(I)*DNY(J))
     2                  * DVOL
            KPS_GP(I,J) = (DNX(I) * DLAMW_DSN * N(J) * GPW(1)
     1                  + DNY(I) * DLAMW_DSN * N(J) * GPW(2))
     2                  * DVOL
         END DO
         DO J = 1, 8
            KPU_GP(I,J) = 0.0D0
            KPU_GP(I,J) = N(I) * (ALPHA_BIOT/DTIME_EFF)
     1                  * (VM(1)*BU(1,J)+VM(2)*BU(2,J)
     2                  + VM(3)*BU(3,J)) * DVOL
         END DO
      END DO

      IF (DBG_P_CAPACITY_REG .GT. 0.5D0 .AND. DTIME .GT. 0.0D0) THEN
         CAP_P_EPS = DBG_P_CAPACITY_ETA * STORW / DTIME
         DO I = 1, 4
            R_CAP(I) = N(I) * CAP_P_EPS * (PW_GP - PW_OLD) * DVOL
            DO J = 1, 4
               KPP_GP(I,J) = KPP_GP(I,J)
     1                    + N(I) * CAP_P_EPS * N(J) * DVOL
            END DO
         END DO
      END IF
      IF (DBG_P_ANCHOR_REG .GT. 0.5D0 .AND. DTIME .GT. 0.0D0) THEN
         CAP_P_ANCHOR_EPS = DBG_P_ANCHOR_ETA * STORW / DTIME
         DO I = 1, 4
            R_ANCH(I) = N(I) * CAP_P_ANCHOR_EPS
     1                * (PW_GP - PW_REF) * DVOL
            DO J = 1, 4
               KPP_GP(I,J) = KPP_GP(I,J)
     1                    + N(I) * CAP_P_ANCHOR_EPS * N(J) * DVOL
            END DO
         END DO
      END IF
      IF (DBG_REG_P_DIAG .GT. 0.5D0) THEN
         REG_P_EPS = DBG_P_REG_SCALE * STORW / DTIME_EFF
         DO I = 1, 4
            R_REG(I) = REG_P_EPS * (PW_GP - PW_OLD) * DVOL
            KPP_GP(I,I) = KPP_GP(I,I) + REG_P_EPS * DVOL
         END DO
      END IF

      N_STOR = 0.0D0
      N_FLUX = 0.0D0
      N_COUP = 0.0D0
      N_SRC = 0.0D0
      N_BND = 0.0D0
      N_TOT = 0.0D0
      N_RP_BLOCK = 0.0D0
      DO I = 1, 4
         R_SRC(I) = R_CAP(I) + R_ANCH(I) + R_REG(I)
         R_TOT(I) = R_STOR(I) + R_FLUX(I) + R_COUP(I)
     1            + R_SRC(I) + R_BND(I)
         N_STOR = N_STOR + R_STOR(I)*R_STOR(I)
         N_FLUX = N_FLUX + R_FLUX(I)*R_FLUX(I)
         N_COUP = N_COUP + R_COUP(I)*R_COUP(I)
         N_SRC = N_SRC + R_SRC(I)*R_SRC(I)
         N_BND = N_BND + R_BND(I)*R_BND(I)
         N_TOT = N_TOT + R_TOT(I)*R_TOT(I)
         N_RP_BLOCK = N_RP_BLOCK + RP(I)*RP(I)
      END DO
      N_STOR = DSQRT(N_STOR)
      N_FLUX = DSQRT(N_FLUX)
      N_COUP = DSQRT(N_COUP)
      N_SRC = DSQRT(N_SRC)
      N_BND = DSQRT(N_BND)
      N_TOT = DSQRT(N_TOT)
      N_RP_BLOCK = DSQRT(N_RP_BLOCK)

      N_KPP = 0.0D0
      N_KPP_GP = 0.0D0
      N_KPU = 0.0D0
      N_KPU_GP = 0.0D0
      N_KPS = 0.0D0
      N_KPS_GP = 0.0D0
      KPP_DMIN = 1.0D300
      KPP_DMAX = 0.0D0
      NEG_DIAG = 0
      DO I = 1, 4
         DIAG_ABS = DABS(KPP(I,I))
         IF (DIAG_ABS .LT. KPP_DMIN) KPP_DMIN = DIAG_ABS
         IF (DIAG_ABS .GT. KPP_DMAX) KPP_DMAX = DIAG_ABS
         IF (KPP(I,I) .LT. 0.0D0) NEG_DIAG = NEG_DIAG + 1
         DO J = 1, 4
            N_KPP = N_KPP + KPP(I,J)*KPP(I,J)
            N_KPP_GP = N_KPP_GP + KPP_GP(I,J)*KPP_GP(I,J)
            N_KPS = N_KPS + KPS(I,J)*KPS(I,J)
            N_KPS_GP = N_KPS_GP + KPS_GP(I,J)*KPS_GP(I,J)
         END DO
         DO J = 1, 8
            N_KPU = N_KPU + KPU(I,J)*KPU(I,J)
            N_KPU_GP = N_KPU_GP + KPU_GP(I,J)*KPU_GP(I,J)
         END DO
      END DO
      N_KPP = DSQRT(N_KPP)
      N_KPP_GP = DSQRT(N_KPP_GP)
      N_KPU = DSQRT(N_KPU)
      N_KPU_GP = DSQRT(N_KPU_GP)
      N_KPS = DSQRT(N_KPS)
      N_KPS_GP = DSQRT(N_KPS_GP)
      IF (KPP_DMIN .LT. 1.0D-300) THEN
         KPP_COND = 1.0D300
      ELSE
         KPP_COND = KPP_DMAX / KPP_DMIN
      END IF

      ROW_DIAG = DABS(KPP(FOCUS_NODE,FOCUS_NODE))
      ROW_OFF = 0.0D0
      DO J = 1, 4
         IF (J .NE. FOCUS_NODE) ROW_OFF = ROW_OFF
     1      + DABS(KPP(FOCUS_NODE,J))
      END DO
      ROW_DOM = ROW_DIAG / (ROW_OFF + 1.0D-300)

      GPW_NORM = DSQRT(GPW(1)*GPW(1)+GPW(2)*GPW(2))
      GSN_NORM = DSQRT(GSN(1)*GSN(1)+GSN(2)*GSN(2))
      QW1 = -LAMW * GPW(1)
      QW2 = -LAMW * GPW(2)
      QW_NORM = DSQRT(QW1*QW1 + QW2*QW2)
      HOT_STOR = R_STOR(FOCUS_NODE)
      HOT_FLUX = R_FLUX(FOCUS_NODE)
      HOT_COUP = R_COUP(FOCUS_NODE)
      HOT_SRC = R_SRC(FOCUS_NODE)
      HOT_BND = R_BND(FOCUS_NODE)
      HOT_TOT = R_TOT(FOCUS_NODE)
      HOT_SIGN = 0.0D0
      IF (HOT_TOT .GT. 0.0D0) HOT_SIGN = 1.0D0
      IF (HOT_TOT .LT. 0.0D0) HOT_SIGN = -1.0D0
      JAC_OK = 0.0D0
      IF (UPS_CP167_ISFINITE(DETJ) .EQ. 1 .AND.
     1    UPS_CP167_ISFINITE(DVOL) .EQ. 1 .AND.
     2    DABS(DETJ) .GT. 1.0D-30) JAC_OK = 1.0D0

      FINITE_ALL = 1
      OVERSIZE = 0
      DO I = 1, 4
         IF (UPS_CP167_ISFINITE(R_TOT(I)) .EQ. 0) FINITE_ALL = 0
         IF (DABS(R_TOT(I)) .GT. 1.0D100) OVERSIZE = 1
      END DO
      IF (UPS_CP167_ISFINITE(N_KPP) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(N_KPU) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(N_KPS) .EQ. 0) FINITE_ALL = 0
      IF (DABS(N_KPP) .GT. 1.0D100) OVERSIZE = 1
      IF (DABS(N_KPU) .GT. 1.0D100) OVERSIZE = 1
      IF (DABS(N_KPS) .GT. 1.0D100) OVERSIZE = 1

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE(
     1      'DBG_CP184C_PRESSURE_TANGENT_AUDIT_FILE', FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp184C_pressureTangentIsolation_'//
     2 'recoveryStage\outputs\cp184C_pressure_tangent_audit.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'time,step,inc,elem,gp,x,y,slot,focus_elem,'//
     2       'focus_gp,focus_local_node,expected_global_node,dtime,'//
     3       'dvol,detj,finite_all,oversize_gt1e100,p_w,p_w_old,'//
     4       'delta_p_w,S_n,S_n_old,delta_Sn,p_c,p_eq,epsv,'//
     5       'epsv_old,phi,K_abs,krw,dkrw_dsn,storw,mu_w,alpha,'//
     6       'grad_pw_x,grad_pw_y,grad_pw_norm,grad_sn_norm,'//
     7       'lambda_w,qw_norm,RP_storage_norm,RP_flux_norm,'//
     8       'RP_source_norm,RP_boundary_norm,RP_coupling_mech_norm,'//
     9       'RP_total_norm,RP_block_norm,hot_storage,hot_flux,'//
     1       'hot_source,hot_boundary,hot_coupling,hot_total,'//
     2       'hot_total_sign,KPP_norm,KPP_gp_norm,KPP_diag_min,'//
     3       'KPP_diag_max,KPP_negative_diag_count,'//
     4       'KPP_condition_proxy,KPU_norm,KPU_gp_norm,KPS_norm,'//
     5       'KPS_gp_norm,KPP_row2_diag,KPP_row2_abs_offdiag,'//
     6       'KPP_row2_diag_dominance_proxy,local_N2,local_dNdx2,'//
     7       'local_dNdy2,jacobian_ok'
         ELSE
            WRITE(*,*) 'CP184C_PRESSURE_TANGENT_OPEN_IOSTAT', IOS
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9184,IOSTAT=WIOS)
     1      TIME_TOTAL, DBLE(KSTEP), DBLE(KINC), DBLE(JELEM),
     2      DBLE(IGP), X_GP, Y_GP, DBLE(SLOT), DBLE(FOCUS_ELEM),
     3      DBLE(FOCUS_GP), DBLE(FOCUS_NODE), DBLE(FOCUS_GNODE),
     4      DTIME, DVOL, DETJ, DBLE(FINITE_ALL), DBLE(OVERSIZE),
     5      PW_GP, PW_OLD, PW_GP-PW_OLD, SN_GP, SN_OLD,
     6      SN_GP-SN_OLD, PC_GP, PEQ_GP, EPSV_GP, EPSV_OLD,
     7      PHI_GP, KABS_GP, KRW_GP, DKRW_DSN, STORW, MU_W,
     8      ALPHA_BIOT, GPW(1), GPW(2), GPW_NORM, GSN_NORM,
     9      LAMW, QW_NORM, N_STOR, N_FLUX, N_SRC, N_BND,
     1      N_COUP, N_TOT, N_RP_BLOCK, HOT_STOR, HOT_FLUX,
     2      HOT_SRC, HOT_BND, HOT_COUP, HOT_TOT, HOT_SIGN,
     3      N_KPP, N_KPP_GP, KPP_DMIN, KPP_DMAX, DBLE(NEG_DIAG),
     4      KPP_COND, N_KPU, N_KPU_GP, N_KPS, N_KPS_GP,
     5      ROW_DIAG, ROW_OFF, ROW_DOM, N(FOCUS_NODE),
     6      DNX(FOCUS_NODE), DNY(FOCUS_NODE), JAC_OK
         IF (WIOS .NE. 0)
     1      WRITE(*,*) 'CP184C_PRESSURE_TANGENT_ROW_IOSTAT',
     2      JELEM, KSTEP, KINC, IGP, WIOS
      END IF

 9184 FORMAT(80(ES24.16,','))
      RETURN
      END


C ================================================================
C cp184C scatter/copy audit for the focused pressure row.
C ================================================================
      SUBROUTINE UPS_CP184C_SCATTER_COPY_AUDIT(KSTEP, KINC, JELEM,
     1 TIME_TOTAL, RP, KPP, KPU, KPS, IP, RE, KE, RHS, AMATRX,
     2 MLVARX, NRHS)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, MLVARX, NRHS, UNIT, IOS, WIOS
      INTEGER IP(4), I, J, LOCAL_NODE, EDOF, FINITE_ALL
      INTEGER UPS_CP167_ISFINITE
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      DOUBLE PRECISION TIME_TOTAL, RP(4), KPP(4,4), KPU(4,8), KPS(4,4)
      DOUBLE PRECISION RE(16), KE(16,16), RHS(MLVARX,NRHS)
      DOUBLE PRECISION AMATRX(16,16), ROW_KE_NORM, ROW_AM_NORM
      DOUBLE PRECISION RP_VAL, RE_VAL, RHS_VAL, KPP_ROW_NORM
      DOUBLE PRECISION KPP_DIAG, KE_DIAG, AM_DIAG
      LOGICAL OPENED
      CHARACTER*260 FILE_PATH
      SAVE OPENED
      DATA OPENED /.FALSE./
      DATA UNIT /985/

C Keep the scatter/copy audit aligned with the same total-time window.
      IF (UPS_CP188A1_DETAIL_TIME_GATE(TIME_TOTAL) .EQ. 0) RETURN
      IF (JELEM .NE. 26805) RETURN
      LOCAL_NODE = 2
      EDOF = IP(LOCAL_NODE)
      ROW_KE_NORM = 0.0D0
      ROW_AM_NORM = 0.0D0
      KPP_ROW_NORM = 0.0D0
      DO J = 1, 16
         ROW_KE_NORM = ROW_KE_NORM + KE(EDOF,J)*KE(EDOF,J)
         ROW_AM_NORM = ROW_AM_NORM + AMATRX(EDOF,J)*AMATRX(EDOF,J)
      END DO
      DO J = 1, 4
         KPP_ROW_NORM = KPP_ROW_NORM
     1      + KPP(LOCAL_NODE,J)*KPP(LOCAL_NODE,J)
      END DO
      ROW_KE_NORM = DSQRT(ROW_KE_NORM)
      ROW_AM_NORM = DSQRT(ROW_AM_NORM)
      KPP_ROW_NORM = DSQRT(KPP_ROW_NORM)
      RP_VAL = RP(LOCAL_NODE)
      RE_VAL = RE(EDOF)
      RHS_VAL = RHS(EDOF,1)
      KPP_DIAG = KPP(LOCAL_NODE,LOCAL_NODE)
      KE_DIAG = KE(EDOF,EDOF)
      AM_DIAG = AMATRX(EDOF,EDOF)
      FINITE_ALL = 1
      IF (UPS_CP167_ISFINITE(RP_VAL) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(RE_VAL) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(RHS_VAL) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(ROW_KE_NORM) .EQ. 0) FINITE_ALL = 0
      IF (UPS_CP167_ISFINITE(ROW_AM_NORM) .EQ. 0) FINITE_ALL = 0

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE(
     1      'DBG_CP184C_SCATTER_COPY_AUDIT_FILE', FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp184C_pressureTangentIsolation_'//
     2 'recoveryStage\outputs\cp184C_scatter_copy_audit.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'time,step,inc,elem,local_node,expected_global_node,'//
     2       'element_pressure_dof,RP_local,RE_scattered,'//
     3       'RHS_copied,KPP_row_norm,KPP_diag,KE_row_norm,'//
     4       'KE_diag,AMATRX_row_norm,AMATRX_diag,finite_all'
         ELSE
            WRITE(*,*) 'CP184C_SCATTER_COPY_OPEN_IOSTAT', IOS
         END IF
      END IF
      IF (OPENED) THEN
         WRITE(UNIT,9185,IOSTAT=WIOS)
     1      TIME_TOTAL, DBLE(KSTEP), DBLE(KINC), DBLE(JELEM),
     2      DBLE(LOCAL_NODE), 3661.0D0, DBLE(EDOF),
     3      RP_VAL, RE_VAL, RHS_VAL, KPP_ROW_NORM, KPP_DIAG,
     4      ROW_KE_NORM, KE_DIAG, ROW_AM_NORM, AM_DIAG,
     5      DBLE(FINITE_ALL)
         IF (WIOS .NE. 0)
     1      WRITE(*,*) 'CP184C_SCATTER_COPY_ROW_IOSTAT',
     2      JELEM, KSTEP, KINC, WIOS
      END IF

 9185 FORMAT(20(ES24.16,','))
      RETURN
      END


C ================================================================
C cp167 local RP/RS/RU term audit.
C Writes only integer flags and bad-index metadata.  No physical field
C values are emitted.
C ================================================================
      SUBROUTINE UPS_CP167_AUDIT_ROW(KSTEP, KINC, JELEM, IGP,
     1 PW_GP, PW_OLD, SN_GP, SN_OLD, PC_GP, PEQ_GP,
     2 EPSV_GP, EPSV_OLD, PHI_GP, KABS_GP, KRW_GP, KRN_GP,
     3 DKRW_DSN, DKRN_DSN, DPC_DSN, DPEQ_DPW, DPEQ_DSN,
     4 GPW, GSN, DTIME, STORW, MU_W, RHON, MU_N, SIGEFF_GP,
     5 RP, KPU, KPP, KPS, RS, KSU, KSP, KSS,
     6 RU, KUU, KUP, KUS)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP, SLOT, UNIT, IOS, WIOS
      INTEGER I, J, WRITTEN(500,10,4)
      INTEGER RS_BAD, RP_BAD, RU_BAD
      INTEGER RS_I, RS_J, RP_I, RP_J, RU_I, RU_J
      INTEGER FIRST_BLOCK, FIRST_TERM, FIRST_I, FIRST_J
      INTEGER PW_OK, PWOLD_OK, SN_OK, SNOLD_OK, PC_OK, PEQ_OK
      INTEGER EPSV_OK, EPSVOLD_OK, SIGEFF_OK, PHI_OK, KABS_OK
      INTEGER KRW_OK, KRN_OK, DKRW_OK, DKRN_OK, DPC_OK
      INTEGER DPEQPW_OK, DPEQSN_OK, GPW_OK, GSN_OK, DT_OK
      INTEGER STORW_OK, MUW_OK, RHON_OK, MUN_OK, VISC_OK, DEN_OK
      INTEGER LAMW_OK, LAMN_OK, QW_OK, QN_OK
      INTEGER RS_ACC_OK, RS_CAP_OK, RS_FLUX_OK, RS_MOB_OK
      INTEGER RS_GRAD_OK, RS_QN_OK, RS_TAN_SN_OK, RS_TAN_PW_OK
      INTEGER RS_DEN_OK
      INTEGER RP_ACC_OK, RP_FLUX_OK, RP_GPW_OK, RP_LAMW_OK
      INTEGER RP_KABS_OK, RP_TAN_PW_OK, RP_TAN_SN_OK, RP_DEN_OK
      INTEGER RU_SIG_OK, RU_PEQ_OK, RU_PEQFORCE_OK, RU_SIGEFF_OK
      INTEGER RU_EPSV_OK, RU_TAN_OK, RU_DEN_OK
      INTEGER UPS_CP167_ISFINITE
      DOUBLE PRECISION PW_GP, PW_OLD, SN_GP, SN_OLD, PC_GP
      DOUBLE PRECISION PEQ_GP, EPSV_GP, EPSV_OLD, PHI_GP
      DOUBLE PRECISION KABS_GP, KRW_GP, KRN_GP, DKRW_DSN
      DOUBLE PRECISION DKRN_DSN, DPC_DSN, DPEQ_DPW, DPEQ_DSN
      DOUBLE PRECISION GPW(2), GSN(2), DTIME, STORW, MU_W
      DOUBLE PRECISION RHON, MU_N, SIGEFF_GP(3)
      DOUBLE PRECISION RP(4), KPU(4,8), KPP(4,4), KPS(4,4)
      DOUBLE PRECISION RS(4), KSU(4,8), KSP(4,4), KSS(4,4)
      DOUBLE PRECISION RU(8), KUU(8,8), KUP(8,4), KUS(8,4)
      DOUBLE PRECISION LAMW, LAMN, QW1, QW2, QN1, QN2
      DOUBLE PRECISION GPC1, GPC2, GTOT1, GTOT2, VAL
      LOGICAL OPENED
      CHARACTER*220 FILE_PATH
      SAVE OPENED, WRITTEN
      DATA OPENED /.FALSE./
      DATA WRITTEN /20000*0/
      DATA UNIT /967/

      IF (KSTEP .LT. 4) RETURN
      IF (KINC .LT. 1 .OR. KINC .GT. 500) RETURN
      IF (IGP .LT. 1 .OR. IGP .GT. 4) RETURN

      SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         SLOT = 10
      END IF
      IF (SLOT .LE. 0) RETURN
      IF (WRITTEN(KINC,SLOT,IGP) .NE. 0) RETURN

      PW_OK = UPS_CP167_ISFINITE(PW_GP)
      PWOLD_OK = UPS_CP167_ISFINITE(PW_OLD)
      SN_OK = UPS_CP167_ISFINITE(SN_GP)
      SNOLD_OK = UPS_CP167_ISFINITE(SN_OLD)
      PC_OK = UPS_CP167_ISFINITE(PC_GP)
      PEQ_OK = UPS_CP167_ISFINITE(PEQ_GP)
      EPSV_OK = UPS_CP167_ISFINITE(EPSV_GP)
      EPSVOLD_OK = UPS_CP167_ISFINITE(EPSV_OLD)
      PHI_OK = UPS_CP167_ISFINITE(PHI_GP)
      KABS_OK = UPS_CP167_ISFINITE(KABS_GP)
      KRW_OK = UPS_CP167_ISFINITE(KRW_GP)
      KRN_OK = UPS_CP167_ISFINITE(KRN_GP)
      DKRW_OK = UPS_CP167_ISFINITE(DKRW_DSN)
      DKRN_OK = UPS_CP167_ISFINITE(DKRN_DSN)
      DPC_OK = UPS_CP167_ISFINITE(DPC_DSN)
      DPEQPW_OK = UPS_CP167_ISFINITE(DPEQ_DPW)
      DPEQSN_OK = UPS_CP167_ISFINITE(DPEQ_DSN)
      DT_OK = UPS_CP167_ISFINITE(DTIME)
      IF (DT_OK .EQ. 1 .AND. DTIME .LE. 0.0D0) DT_OK = 0
      STORW_OK = UPS_CP167_ISFINITE(STORW)
      MUW_OK = UPS_CP167_ISFINITE(MU_W)
      MUN_OK = UPS_CP167_ISFINITE(MU_N)
      RHON_OK = UPS_CP167_ISFINITE(RHON)
      IF (MUW_OK .EQ. 1 .AND. DABS(MU_W) .LE. 1.0D-30)
     1   MUW_OK = 0
      IF (MUN_OK .EQ. 1 .AND. DABS(MU_N) .LE. 1.0D-30)
     1   MUN_OK = 0
      VISC_OK = 0
      IF (MUW_OK .EQ. 1 .AND. MUN_OK .EQ. 1) VISC_OK = 1
      DEN_OK = 0
      IF (DT_OK .EQ. 1 .AND. VISC_OK .EQ. 1 .AND.
     1    PHI_OK .EQ. 1 .AND. STORW_OK .EQ. 1) DEN_OK = 1

      GPW_OK = 0
      IF (UPS_CP167_ISFINITE(GPW(1)) .EQ. 1 .AND.
     1    UPS_CP167_ISFINITE(GPW(2)) .EQ. 1) GPW_OK = 1
      GSN_OK = 0
      IF (UPS_CP167_ISFINITE(GSN(1)) .EQ. 1 .AND.
     1    UPS_CP167_ISFINITE(GSN(2)) .EQ. 1) GSN_OK = 1

      SIGEFF_OK = 0
      IF (UPS_CP167_ISFINITE(SIGEFF_GP(1)) .EQ. 1 .AND.
     1    UPS_CP167_ISFINITE(SIGEFF_GP(2)) .EQ. 1 .AND.
     2    UPS_CP167_ISFINITE(SIGEFF_GP(3)) .EQ. 1)
     3    SIGEFF_OK = 1

      LAMW_OK = 0
      LAMW = 0.0D0
      IF (KABS_OK .EQ. 1 .AND. KRW_OK .EQ. 1 .AND.
     1    MUW_OK .EQ. 1) THEN
         LAMW = KABS_GP * KRW_GP / MU_W
         LAMW_OK = UPS_CP167_ISFINITE(LAMW)
      END IF
      LAMN_OK = 0
      LAMN = 0.0D0
      IF (RHON_OK .EQ. 1 .AND. KABS_OK .EQ. 1 .AND.
     1    KRN_OK .EQ. 1 .AND. MUN_OK .EQ. 1) THEN
         LAMN = RHON * KABS_GP * KRN_GP / MU_N
         LAMN_OK = UPS_CP167_ISFINITE(LAMN)
      END IF

      QW_OK = 0
      QW1 = 0.0D0
      QW2 = 0.0D0
      IF (LAMW_OK .EQ. 1 .AND. GPW_OK .EQ. 1) THEN
         QW1 = -LAMW * GPW(1)
         QW2 = -LAMW * GPW(2)
         IF (UPS_CP167_ISFINITE(QW1) .EQ. 1 .AND.
     1       UPS_CP167_ISFINITE(QW2) .EQ. 1) QW_OK = 1
      END IF
      QN_OK = 0
      QN1 = 0.0D0
      QN2 = 0.0D0
      IF (LAMN_OK .EQ. 1 .AND. GPW_OK .EQ. 1 .AND.
     1    GSN_OK .EQ. 1 .AND. DPC_OK .EQ. 1) THEN
         GPC1 = DPC_DSN * GSN(1)
         GPC2 = DPC_DSN * GSN(2)
         GTOT1 = GPW(1) + GPC1
         GTOT2 = GPW(2) + GPC2
         QN1 = -LAMN * GTOT1
         QN2 = -LAMN * GTOT2
         IF (UPS_CP167_ISFINITE(QN1) .EQ. 1 .AND.
     1       UPS_CP167_ISFINITE(QN2) .EQ. 1) QN_OK = 1
      END IF

      RS_ACC_OK = 0
      IF (SN_OK .EQ. 1 .AND. SNOLD_OK .EQ. 1 .AND.
     1    PHI_OK .EQ. 1 .AND. RHON_OK .EQ. 1 .AND.
     2    DT_OK .EQ. 1) RS_ACC_OK = 1
      RS_CAP_OK = 0
      IF (DPC_OK .EQ. 1 .AND. GSN_OK .EQ. 1) RS_CAP_OK = 1
      RS_FLUX_OK = QN_OK
      RS_MOB_OK = LAMN_OK
      RS_GRAD_OK = GSN_OK
      RS_QN_OK = QN_OK
      RS_TAN_SN_OK = 0
      IF (LAMN_OK .EQ. 1 .AND. DPC_OK .EQ. 1 .AND.
     1    DKRN_OK .EQ. 1 .AND. GSN_OK .EQ. 1)
     2    RS_TAN_SN_OK = 1
      RS_TAN_PW_OK = 0
      IF (LAMN_OK .EQ. 1 .AND. GPW_OK .EQ. 1)
     1    RS_TAN_PW_OK = 1
      RS_DEN_OK = 0
      IF (DT_OK .EQ. 1 .AND. PHI_OK .EQ. 1 .AND.
     1    MUN_OK .EQ. 1) RS_DEN_OK = 1

      RP_ACC_OK = 0
      IF (PW_OK .EQ. 1 .AND. PWOLD_OK .EQ. 1 .AND.
     1    STORW_OK .EQ. 1 .AND. DT_OK .EQ. 1)
     2    RP_ACC_OK = 1
      RP_FLUX_OK = QW_OK
      RP_GPW_OK = GPW_OK
      RP_LAMW_OK = LAMW_OK
      RP_KABS_OK = KABS_OK
      RP_TAN_PW_OK = 0
      IF (LAMW_OK .EQ. 1 .AND. DT_OK .EQ. 1)
     1    RP_TAN_PW_OK = 1
      RP_TAN_SN_OK = 0
      IF (KABS_OK .EQ. 1 .AND. DKRW_OK .EQ. 1 .AND.
     1    MUW_OK .EQ. 1 .AND. GPW_OK .EQ. 1)
     2    RP_TAN_SN_OK = 1
      RP_DEN_OK = 0
      IF (DT_OK .EQ. 1 .AND. MUW_OK .EQ. 1 .AND.
     1    STORW_OK .EQ. 1) RP_DEN_OK = 1

      RU_SIG_OK = SIGEFF_OK
      RU_PEQ_OK = PEQ_OK
      RU_PEQFORCE_OK = PEQ_OK
      RU_SIGEFF_OK = SIGEFF_OK
      RU_EPSV_OK = EPSV_OK
      RU_TAN_OK = 0
      IF (DPEQPW_OK .EQ. 1 .AND. DPEQSN_OK .EQ. 1)
     1   RU_TAN_OK = 1
      RU_DEN_OK = DT_OK

      RS_BAD = 0
      RP_BAD = 0
      RU_BAD = 0
      RS_I = 0
      RS_J = 0
      RP_I = 0
      RP_J = 0
      RU_I = 0
      RU_J = 0

      DO I = 1, 4
         VAL = RS(I)
         IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
            RS_BAD = RS_BAD + 1
            IF (RS_I .EQ. 0) THEN
               RS_I = I
               RS_J = 0
            END IF
         END IF
      END DO
      DO I = 1, 4
         DO J = 1, 8
            VAL = KSU(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RS_BAD = RS_BAD + 1
               IF (RS_I .EQ. 0) THEN
                  RS_I = I
                  RS_J = J
               END IF
            END IF
         END DO
      END DO
      DO I = 1, 4
         DO J = 1, 4
            VAL = KSP(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RS_BAD = RS_BAD + 1
               IF (RS_I .EQ. 0) THEN
                  RS_I = I
                  RS_J = J
               END IF
            END IF
            VAL = KSS(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RS_BAD = RS_BAD + 1
               IF (RS_I .EQ. 0) THEN
                  RS_I = I
                  RS_J = J
               END IF
            END IF
         END DO
      END DO

      DO I = 1, 4
         VAL = RP(I)
         IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
            RP_BAD = RP_BAD + 1
            IF (RP_I .EQ. 0) THEN
               RP_I = I
               RP_J = 0
            END IF
         END IF
      END DO
      DO I = 1, 4
         DO J = 1, 8
            VAL = KPU(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RP_BAD = RP_BAD + 1
               IF (RP_I .EQ. 0) THEN
                  RP_I = I
                  RP_J = J
               END IF
            END IF
         END DO
      END DO
      DO I = 1, 4
         DO J = 1, 4
            VAL = KPP(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RP_BAD = RP_BAD + 1
               IF (RP_I .EQ. 0) THEN
                  RP_I = I
                  RP_J = J
               END IF
            END IF
            VAL = KPS(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RP_BAD = RP_BAD + 1
               IF (RP_I .EQ. 0) THEN
                  RP_I = I
                  RP_J = J
               END IF
            END IF
         END DO
      END DO

      DO I = 1, 8
         VAL = RU(I)
         IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
            RU_BAD = RU_BAD + 1
            IF (RU_I .EQ. 0) THEN
               RU_I = I
               RU_J = 0
            END IF
         END IF
      END DO
      DO I = 1, 8
         DO J = 1, 8
            VAL = KUU(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RU_BAD = RU_BAD + 1
               IF (RU_I .EQ. 0) THEN
                  RU_I = I
                  RU_J = J
               END IF
            END IF
         END DO
      END DO
      DO I = 1, 8
         DO J = 1, 4
            VAL = KUP(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RU_BAD = RU_BAD + 1
               IF (RU_I .EQ. 0) THEN
                  RU_I = I
                  RU_J = J
               END IF
            END IF
            VAL = KUS(I,J)
            IF (UPS_CP167_ISFINITE(VAL) .EQ. 0) THEN
               RU_BAD = RU_BAD + 1
               IF (RU_I .EQ. 0) THEN
                  RU_I = I
                  RU_J = J
               END IF
            END IF
         END DO
      END DO

      FIRST_BLOCK = 0
      FIRST_TERM = 0
      FIRST_I = 0
      FIRST_J = 0
      IF (RS_ACC_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 1
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_CAP_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 2
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_FLUX_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 3
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_MOB_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 4
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_GRAD_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 6
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_QN_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 7
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_TAN_SN_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 8
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_TAN_PW_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 9
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RS_DEN_OK .EQ. 0) THEN
         FIRST_BLOCK = 1
         FIRST_TERM = 10
         FIRST_I = RS_I
         FIRST_J = RS_J
      ELSE IF (RP_ACC_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 1
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RP_FLUX_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 2
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RP_GPW_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 3
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RP_LAMW_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 4
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RP_KABS_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 5
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RP_TAN_PW_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 6
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RP_TAN_SN_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 7
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RP_DEN_OK .EQ. 0) THEN
         FIRST_BLOCK = 2
         FIRST_TERM = 8
         FIRST_I = RP_I
         FIRST_J = RP_J
      ELSE IF (RU_SIG_OK .EQ. 0) THEN
         FIRST_BLOCK = 3
         FIRST_TERM = 1
         FIRST_I = RU_I
         FIRST_J = RU_J
      ELSE IF (RU_PEQ_OK .EQ. 0) THEN
         FIRST_BLOCK = 3
         FIRST_TERM = 2
         FIRST_I = RU_I
         FIRST_J = RU_J
      ELSE IF (RU_PEQFORCE_OK .EQ. 0) THEN
         FIRST_BLOCK = 3
         FIRST_TERM = 3
         FIRST_I = RU_I
         FIRST_J = RU_J
      ELSE IF (RU_SIGEFF_OK .EQ. 0) THEN
         FIRST_BLOCK = 3
         FIRST_TERM = 4
         FIRST_I = RU_I
         FIRST_J = RU_J
      ELSE IF (RU_EPSV_OK .EQ. 0) THEN
         FIRST_BLOCK = 3
         FIRST_TERM = 5
         FIRST_I = RU_I
         FIRST_J = RU_J
      ELSE IF (RU_TAN_OK .EQ. 0) THEN
         FIRST_BLOCK = 3
         FIRST_TERM = 6
         FIRST_I = RU_I
         FIRST_J = RU_J
      ELSE IF (RU_DEN_OK .EQ. 0) THEN
         FIRST_BLOCK = 3
         FIRST_TERM = 7
         FIRST_I = RU_I
         FIRST_J = RU_J
      END IF

      IF (.NOT. OPENED) THEN
         FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp167_localAssemblyTermAudit_short'//
     2 '\outputs\cp167_local_assembly_term_audit.csv'
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         WRITE(*,*) 'CP167_OPEN_IOSTAT', IOS
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'kstep,kinc,elem,slot,gp,'//
     2       'rs_local_bad_count,rp_local_bad_count,'//
     3       'ru_local_bad_count,first_bad_block_id,'//
     4       'first_bad_term_id,first_bad_i,first_bad_j,'//
     5       'rs_acc_ok,rs_cap_ok,rs_flux_ok,rs_mob_ok,'//
     6       'rs_grad_ok,rs_qn_ok,rs_tangent_sn_ok,'//
     7       'rs_tangent_pw_ok,rs_den_ok,rp_acc_ok,'//
     8       'rp_flux_ok,rp_gpw_ok,rp_lamw_ok,rp_kabs_ok,'//
     9       'rp_tangent_pw_ok,rp_tangent_sn_ok,rp_den_ok,'//
     1       'ru_sig_ok,ru_peq_ok,ru_peqforce_ok,ru_sigeff_ok,'//
     2       'ru_epsv_ok,ru_tangent_ok,ru_den_ok,'//
     3       'pw_ok,pw_old_ok,sn_ok,sn_old_ok,pc_ok,peq_ok,'//
     4       'epsv_ok,epsv_old_ok,sigeff_ok,porosity_ok,'//
     5       'kabs_ok,krw_ok,krn_ok,lamw_ok,lamn_ok,'//
     6       'gpw_ok,gsn_ok,qw_ok,qn_ok,dpc_dsn_ok,'//
     7       'dkrw_dsn_ok,dkrn_dsn_ok,dpeq_dpw_ok,'//
     8       'dpeq_dsn_ok,dt_ok,storw_ok,viscosity_ok,'//
     9       'den_ok,rs_first_bad_i,rs_first_bad_j,'//
     1       'rp_first_bad_i,rp_first_bad_j,'//
     2       'ru_first_bad_i,ru_first_bad_j'
            WRITE(*,*) 'CP167_HEADER_IOSTAT', WIOS
            CALL FLUSH(UNIT)
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9877,IOSTAT=WIOS)
     1      KSTEP, KINC, JELEM, SLOT, IGP,
     2      RS_BAD, RP_BAD, RU_BAD, FIRST_BLOCK, FIRST_TERM,
     3      FIRST_I, FIRST_J,
     4      RS_ACC_OK, RS_CAP_OK, RS_FLUX_OK, RS_MOB_OK,
     5      RS_GRAD_OK, RS_QN_OK, RS_TAN_SN_OK, RS_TAN_PW_OK,
     6      RS_DEN_OK, RP_ACC_OK, RP_FLUX_OK, RP_GPW_OK,
     7      RP_LAMW_OK, RP_KABS_OK, RP_TAN_PW_OK,
     8      RP_TAN_SN_OK, RP_DEN_OK, RU_SIG_OK, RU_PEQ_OK,
     9      RU_PEQFORCE_OK, RU_SIGEFF_OK, RU_EPSV_OK,
     1      RU_TAN_OK, RU_DEN_OK, PW_OK, PWOLD_OK, SN_OK,
     2      SNOLD_OK, PC_OK, PEQ_OK, EPSV_OK, EPSVOLD_OK,
     3      SIGEFF_OK, PHI_OK, KABS_OK, KRW_OK, KRN_OK,
     4      LAMW_OK, LAMN_OK, GPW_OK, GSN_OK, QW_OK, QN_OK,
     5      DPC_OK, DKRW_OK, DKRN_OK, DPEQPW_OK, DPEQSN_OK,
     6      DT_OK, STORW_OK, VISC_OK, DEN_OK,
     7      RS_I, RS_J, RP_I, RP_J, RU_I, RU_J
         IF (WIOS .EQ. 0) WRITTEN(KINC,SLOT,IGP) = 1
         IF (WIOS .NE. 0) WRITE(*,*) 'CP167_ROW_IOSTAT',
     1      JELEM, KINC, IGP, WIOS
         CALL FLUSH(UNIT)
      END IF

9877  FORMAT(69(I12,','),I12)
      RETURN
      END

      INTEGER FUNCTION UPS_CP167_ISFINITE(X)
      IMPLICIT NONE
      DOUBLE PRECISION X
      IF (X .EQ. X .AND. DABS(X) .LE. 1.0D100) THEN
         UPS_CP167_ISFINITE = 1
      ELSE
         UPS_CP167_ISFINITE = 0
      END IF
      RETURN
      END


C ================================================================
C cp179B2 no-active recovery-tuned 0.1d current-GP output probe.
C This writes raw UEL-call rows only. Post-processing keeps the last
C row per step/inc/elem/gp so cutback retries do not produce duplicate
C formal probe keys.
C ================================================================
      SUBROUTINE UPS_CP174A_OUTPUT_ROW(KSTEP, KINC, JELEM, IGP,
     1 TIME_TOTAL, X_GP, Y_GP, PW_GP, SN_GP, PC_GP, PEQ_GP,
     2 KABS_GP, EPSV_GP, SIGEFF_GP)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP, UNIT, IOS, WIOS
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      DOUBLE PRECISION TIME_TOTAL, X_GP, Y_GP, PW_GP, SN_GP
      DOUBLE PRECISION PC_GP, PEQ_GP, KABS_GP, EPSV_GP
      DOUBLE PRECISION SIGEFF_GP(3)
      CHARACTER*240 FILE_PATH
      LOGICAL OPENED
      PARAMETER (UNIT=974)
      SAVE OPENED
      DATA OPENED /.FALSE./

      IF (UPS_CP188A1_DETAIL_TIME_GATE(TIME_TOTAL) .EQ. 0) RETURN
      IF (KINC .LT. 1 .OR. KINC .GT. 1000) RETURN
      IF (IGP .LT. 1 .OR. IGP .GT. 4) RETURN
      IF (.NOT.((JELEM .GE. 10287 .AND. JELEM .LE. 10291)
     1     .OR. JELEM .EQ. 61476 .OR. JELEM .EQ. 63691
     2     .OR. JELEM .EQ. 63700 .OR. JELEM .EQ. 63703
     3     .OR. JELEM .EQ. 64601)) RETURN

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_CP179B2_REAL_OUTPUT_CSV_FILE',
     1                                 FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            CALL GET_ENVIRONMENT_VARIABLE('DBG_CP179A2_REAL_OUTPUT_CSV_FILE',
     1                                    FILE_PATH)
         END IF
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            CALL GET_ENVIRONMENT_VARIABLE('DBG_CP179A1_REAL_OUTPUT_CSV_FILE',
     1                                    FILE_PATH)
         END IF
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            CALL GET_ENVIRONMENT_VARIABLE('DBG_CP179A_REAL_OUTPUT_CSV_FILE',
     1                                    FILE_PATH)
         END IF
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            CALL GET_ENVIRONMENT_VARIABLE('DBG_CP174A_OUTPUT_CSV_FILE',
     1                                    FILE_PATH)
         END IF
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp179B2_noActive'//
     2 '_0p1d\outputs'//
     3 '\cp179B2_real_output_current_state.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'time,step,inc,elem,gp,x,y,p_w,S_n,p_c,p_eq,'//
     2       'K_abs,epsv,sigma_eff_xx,sigma_eff_yy,'//
     3       'sigma_eff_xy,source_tag'
         ELSE
            WRITE(*,*) 'CP174A_OUTPUT_OPEN_IOSTAT', IOS
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9174,IOSTAT=WIOS)
     1      TIME_TOTAL, KSTEP, KINC, JELEM, IGP,
     2      X_GP, Y_GP, PW_GP, SN_GP, PC_GP, PEQ_GP,
     3      KABS_GP, EPSV_GP, SIGEFF_GP(1), SIGEFF_GP(2),
     4      SIGEFF_GP(3),
     5      'current_no_restart_no_active_cp188A1'
         IF (WIOS .NE. 0) WRITE(*,*) 'CP174A_OUTPUT_ROW_IOSTAT',
     1      JELEM, KINC, IGP, WIOS
      END IF

 9174 FORMAT(ES24.16,',',4(I12,','),11(ES24.16,','),A)
      RETURN
      END


C ================================================================
C cp168 restart state reconstruction audit.
C Writes only flags, bad counts, masks, source ids, and non-finite
C cp171A2 reuses this primary-state reconstruction audit for the
C no-restart continuous allow-cutback STEP3 KINC23+ window. It deliberately
C avoids physical field values and records only finite/value classes.
C ================================================================
      SUBROUTINE UPS_CP168_AUDIT_ROW(KSTEP, KINC, JELEM, IGP,
     1 NDOFEL, MLVARX, NRHS, U, DU, DE, PE, SE,
     2 N, DNX, DNY, PW_GP, SN_GP, GPW, GSN,
     3 SV_GP_OLD, PC_GP, PEQ_GP, KABS_GP, EPSV_GP,
     4 SIGEFF_GP, KRW_GP, KRN_GP, MU_W, RHON, MU_N)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP, NDOFEL, MLVARX, NRHS
      INTEGER SLOT, UNIT, IOS, WIOS, I, K, WRITTEN(500,10,4)
      INTEGER U_ALL_OK, DU1_ALL_OK, U_U_OK, U_PW_OK, U_SN_OK
      INTEGER DU_U_OK, DU_PW_OK, DU_SN_OK
      INTEGER U_BAD_COUNT, DU_BAD_COUNT, U_FIRST_I, DU_FIRST_I
      INTEGER U_FIRST_CLASS, DU_FIRST_CLASS
      INTEGER U_PW_BAD_MASK, U_SN_BAD_MASK
      INTEGER DU_PW_BAD_MASK, DU_SN_BAD_MASK
      INTEGER DE_OK, PE_OK, SE_OK, PE_FROM_U_OK, SE_FROM_U_OK
      INTEGER PE_BAD_MASK, SE_BAD_MASK
      INTEGER N_OK, N_SUM_OK, DNX_OK, DNY_OK, PWGP_OK, SNGP_OK
      INTEGER GPW_OK, GSN_OK, INTERP_INPUT_OK, INTERP_BAD_SOURCE
      INTEGER SV_CORE_BAD_COUNT, SV_CORE_BAD_MASK
      INTEGER SV_OUT_BAD_COUNT, SV_OUT_BAD_MASK, SV_OUT_VALID_OK
      INTEGER SV1_OK, SV2_OK, SV4_OK, SV5_OK, SV6_OK, SV8_OK
      INTEGER SV10_OK, SV11_OK, SV12_OK, SV13_OK
      INTEGER PC_OK, PEQ_OK, KABS_OK, EPSV_OK, SIGEFF_OK
      INTEGER KRW_OK, KRN_OK, LAMW_OK, LAMN_OK, DERIVED_ALL_OK
      INTEGER FIRST_BAD_LAYER_ID, SOURCE_ID
      INTEGER PW_NODE1_OK, PW_NODE2_OK, PW_NODE3_OK, PW_NODE4_OK
      INTEGER SN_NODE1_OK, SN_NODE2_OK, SN_NODE3_OK, SN_NODE4_OK
      INTEGER UEL_OK, TMP_OK, UPS_CP168_ISFINITE
      INTEGER UPS_CP168_BADCLASS
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      DOUBLE PRECISION U(NDOFEL), DU(MLVARX,NRHS)
      DOUBLE PRECISION DE(8), PE(4), SE(4), N(4), DNX(4), DNY(4)
      DOUBLE PRECISION PW_GP, SN_GP, GPW(2), GSN(2)
      DOUBLE PRECISION SV_GP_OLD(48), PC_GP, PEQ_GP, KABS_GP
      DOUBLE PRECISION EPSV_GP, SIGEFF_GP(3), KRW_GP, KRN_GP
      DOUBLE PRECISION MU_W, RHON, MU_N, LAMW, LAMN
      DOUBLE PRECISION SUMN, VAL
      DOUBLE PRECISION UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME
      DOUBLE PRECISION UPS_CUR_PERIOD
      COMMON /UPS_TIME_CTRL/ UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME,
     1 UPS_CUR_PERIOD
      LOGICAL OPENED
      CHARACTER*240 FILE_PATH
      SAVE OPENED, WRITTEN
      DATA OPENED /.FALSE./
      DATA WRITTEN /20000*0/
      DATA UNIT /968/

      IF (UPS_CP188A1_DETAIL_TIME_GATE(UPS_CUR_TOTAL_TIME)
     1    .EQ. 0) RETURN
      IF (KINC .LT. 1 .OR. KINC .GT. 500) RETURN
      IF (IGP .LT. 1 .OR. IGP .GT. 4) RETURN

      SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         SLOT = 10
      END IF
      IF (SLOT .LE. 0) RETURN
C cp171A2 intentionally keeps duplicate KINC rows so cutback attempts
C are visible in the CSV audit.

      U_ALL_OK = 1
      DU1_ALL_OK = 1
      U_U_OK = 1
      U_PW_OK = 1
      U_SN_OK = 1
      DU_U_OK = 1
      DU_PW_OK = 1
      DU_SN_OK = 1
      U_BAD_COUNT = 0
      DU_BAD_COUNT = 0
      U_FIRST_I = 0
      DU_FIRST_I = 0
      U_FIRST_CLASS = 0
      DU_FIRST_CLASS = 0
      U_PW_BAD_MASK = 0
      U_SN_BAD_MASK = 0
      DU_PW_BAD_MASK = 0
      DU_SN_BAD_MASK = 0
      PW_NODE1_OK = 1
      PW_NODE2_OK = 1
      PW_NODE3_OK = 1
      PW_NODE4_OK = 1
      SN_NODE1_OK = 1
      SN_NODE2_OK = 1
      SN_NODE3_OK = 1
      SN_NODE4_OK = 1

      DO I = 1, NDOFEL
         IF (UPS_CP168_ISFINITE(U(I)) .EQ. 0) THEN
            U_ALL_OK = 0
            U_BAD_COUNT = U_BAD_COUNT + 1
            IF (U_FIRST_I .EQ. 0) THEN
               U_FIRST_I = I
               U_FIRST_CLASS = UPS_CP168_BADCLASS(U(I))
            END IF
            K = MOD(I-1,4) + 1
            IF (K .LE. 2) U_U_OK = 0
            IF (K .EQ. 3) THEN
               U_PW_OK = 0
               U_PW_BAD_MASK = U_PW_BAD_MASK + 2**((I-1)/4)
            END IF
            IF (K .EQ. 4) THEN
               U_SN_OK = 0
               U_SN_BAD_MASK = U_SN_BAD_MASK + 2**((I-1)/4)
            END IF
         END IF
      END DO

      IF (NRHS .GE. 1) THEN
         DO I = 1, NDOFEL
            IF (UPS_CP168_ISFINITE(DU(I,1)) .EQ. 0) THEN
               DU1_ALL_OK = 0
               DU_BAD_COUNT = DU_BAD_COUNT + 1
               IF (DU_FIRST_I .EQ. 0) THEN
                  DU_FIRST_I = I
                  DU_FIRST_CLASS = UPS_CP168_BADCLASS(DU(I,1))
               END IF
               K = MOD(I-1,4) + 1
               IF (K .LE. 2) DU_U_OK = 0
               IF (K .EQ. 3) THEN
                  DU_PW_OK = 0
                  DU_PW_BAD_MASK = DU_PW_BAD_MASK + 2**((I-1)/4)
               END IF
               IF (K .EQ. 4) THEN
                  DU_SN_OK = 0
                  DU_SN_BAD_MASK = DU_SN_BAD_MASK + 2**((I-1)/4)
               END IF
            END IF
         END DO
      ELSE
         DU1_ALL_OK = 0
      END IF

      DE_OK = 1
      DO I = 1, 8
         IF (UPS_CP168_ISFINITE(DE(I)) .EQ. 0) DE_OK = 0
      END DO
      PE_OK = 1
      SE_OK = 1
      PE_BAD_MASK = 0
      SE_BAD_MASK = 0
      PE_FROM_U_OK = 1
      SE_FROM_U_OK = 1
      DO I = 1, 4
         IF (UPS_CP168_ISFINITE(PE(I)) .EQ. 0) THEN
            PE_OK = 0
            PE_BAD_MASK = PE_BAD_MASK + 2**(I-1)
         END IF
         IF (UPS_CP168_ISFINITE(SE(I)) .EQ. 0) THEN
            SE_OK = 0
            SE_BAD_MASK = SE_BAD_MASK + 2**(I-1)
         END IF
         K = 4*(I-1)
         IF (K+3 .LE. NDOFEL) THEN
            IF (UPS_CP168_BADCLASS(PE(I)) .NE.
     1          UPS_CP168_BADCLASS(U(K+3))) PE_FROM_U_OK = 0
            IF (UPS_CP168_ISFINITE(PE(I)) .EQ. 1 .AND.
     1          PE(I) .NE. U(K+3)) PE_FROM_U_OK = 0
         END IF
         IF (K+4 .LE. NDOFEL) THEN
            IF (UPS_CP168_BADCLASS(SE(I)) .NE.
     1          UPS_CP168_BADCLASS(U(K+4))) SE_FROM_U_OK = 0
            IF (UPS_CP168_ISFINITE(SE(I)) .EQ. 1 .AND.
     1          SE(I) .NE. U(K+4)) SE_FROM_U_OK = 0
         END IF
      END DO

      IF (UPS_CP168_ISFINITE(PE(1)) .EQ. 0) PW_NODE1_OK = 0
      IF (UPS_CP168_ISFINITE(PE(2)) .EQ. 0) PW_NODE2_OK = 0
      IF (UPS_CP168_ISFINITE(PE(3)) .EQ. 0) PW_NODE3_OK = 0
      IF (UPS_CP168_ISFINITE(PE(4)) .EQ. 0) PW_NODE4_OK = 0
      IF (UPS_CP168_ISFINITE(SE(1)) .EQ. 0) SN_NODE1_OK = 0
      IF (UPS_CP168_ISFINITE(SE(2)) .EQ. 0) SN_NODE2_OK = 0
      IF (UPS_CP168_ISFINITE(SE(3)) .EQ. 0) SN_NODE3_OK = 0
      IF (UPS_CP168_ISFINITE(SE(4)) .EQ. 0) SN_NODE4_OK = 0

      N_OK = 1
      DNX_OK = 1
      DNY_OK = 1
      SUMN = 0.0D0
      DO I = 1, 4
         IF (UPS_CP168_ISFINITE(N(I)) .EQ. 0) N_OK = 0
         IF (UPS_CP168_ISFINITE(DNX(I)) .EQ. 0) DNX_OK = 0
         IF (UPS_CP168_ISFINITE(DNY(I)) .EQ. 0) DNY_OK = 0
         SUMN = SUMN + N(I)
      END DO
      N_SUM_OK = 0
      IF (UPS_CP168_ISFINITE(SUMN) .EQ. 1 .AND.
     1    DABS(SUMN - 1.0D0) .LE. 1.0D-8) N_SUM_OK = 1
      PWGP_OK = UPS_CP168_ISFINITE(PW_GP)
      SNGP_OK = UPS_CP168_ISFINITE(SN_GP)
      GPW_OK = 0
      IF (UPS_CP168_ISFINITE(GPW(1)) .EQ. 1 .AND.
     1    UPS_CP168_ISFINITE(GPW(2)) .EQ. 1) GPW_OK = 1
      GSN_OK = 0
      IF (UPS_CP168_ISFINITE(GSN(1)) .EQ. 1 .AND.
     1    UPS_CP168_ISFINITE(GSN(2)) .EQ. 1) GSN_OK = 1
      INTERP_INPUT_OK = 0
      IF (N_OK .EQ. 1 .AND. N_SUM_OK .EQ. 1 .AND.
     1    DNX_OK .EQ. 1 .AND. DNY_OK .EQ. 1 .AND.
     2    PE_OK .EQ. 1 .AND. SE_OK .EQ. 1) INTERP_INPUT_OK = 1
      INTERP_BAD_SOURCE = 0
      IF (N_OK .EQ. 0 .OR. N_SUM_OK .EQ. 0) THEN
         INTERP_BAD_SOURCE = 1
      ELSE IF (PE_OK .EQ. 0) THEN
         INTERP_BAD_SOURCE = 2
      ELSE IF (SE_OK .EQ. 0) THEN
         INTERP_BAD_SOURCE = 3
      ELSE IF (DNX_OK .EQ. 0 .OR. DNY_OK .EQ. 0) THEN
         INTERP_BAD_SOURCE = 4
      ELSE IF (PWGP_OK .EQ. 0 .OR. SNGP_OK .EQ. 0 .OR.
     1         GPW_OK .EQ. 0 .OR. GSN_OK .EQ. 0) THEN
         INTERP_BAD_SOURCE = 5
      END IF

      SV1_OK = UPS_CP168_ISFINITE(SV_GP_OLD(1))
      SV2_OK = UPS_CP168_ISFINITE(SV_GP_OLD(2))
      SV4_OK = UPS_CP168_ISFINITE(SV_GP_OLD(4))
      SV5_OK = UPS_CP168_ISFINITE(SV_GP_OLD(5))
      SV6_OK = UPS_CP168_ISFINITE(SV_GP_OLD(6))
      SV8_OK = UPS_CP168_ISFINITE(SV_GP_OLD(8))
      SV10_OK = UPS_CP168_ISFINITE(SV_GP_OLD(10))
      SV11_OK = UPS_CP168_ISFINITE(SV_GP_OLD(11))
      SV12_OK = UPS_CP168_ISFINITE(SV_GP_OLD(12))
      SV13_OK = UPS_CP168_ISFINITE(SV_GP_OLD(13))
      SV_CORE_BAD_COUNT = 0
      SV_CORE_BAD_MASK = 0
      IF (SV1_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 1
      END IF
      IF (SV2_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 2
      END IF
      IF (SV4_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 4
      END IF
      IF (SV5_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 8
      END IF
      IF (SV6_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 16
      END IF
      IF (SV8_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 32
      END IF
      IF (SV10_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 64
      END IF
      IF (SV11_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 128
      END IF
      IF (SV12_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 256
      END IF
      IF (SV13_OK .EQ. 0) THEN
         SV_CORE_BAD_COUNT = SV_CORE_BAD_COUNT + 1
         SV_CORE_BAD_MASK = SV_CORE_BAD_MASK + 512
      END IF

      SV_OUT_BAD_COUNT = 0
      SV_OUT_BAD_MASK = 0
      DO I = 33, 48
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(I)) .EQ. 0) THEN
            SV_OUT_BAD_COUNT = SV_OUT_BAD_COUNT + 1
            SV_OUT_BAD_MASK = SV_OUT_BAD_MASK + 2**(I-33)
         END IF
      END DO
      SV_OUT_VALID_OK = 0
      IF (UPS_CP168_ISFINITE(SV_GP_OLD(42)) .EQ. 1 .AND.
     1    SV_GP_OLD(42) .GE. 0.5D0) SV_OUT_VALID_OK = 1

      PC_OK = UPS_CP168_ISFINITE(PC_GP)
      PEQ_OK = UPS_CP168_ISFINITE(PEQ_GP)
      KABS_OK = UPS_CP168_ISFINITE(KABS_GP)
      EPSV_OK = UPS_CP168_ISFINITE(EPSV_GP)
      SIGEFF_OK = 0
      IF (UPS_CP168_ISFINITE(SIGEFF_GP(1)) .EQ. 1 .AND.
     1    UPS_CP168_ISFINITE(SIGEFF_GP(2)) .EQ. 1 .AND.
     2    UPS_CP168_ISFINITE(SIGEFF_GP(3)) .EQ. 1)
     3    SIGEFF_OK = 1
      KRW_OK = UPS_CP168_ISFINITE(KRW_GP)
      KRN_OK = UPS_CP168_ISFINITE(KRN_GP)
      LAMW_OK = 0
      IF (KABS_OK .EQ. 1 .AND. KRW_OK .EQ. 1 .AND.
     1    UPS_CP168_ISFINITE(MU_W) .EQ. 1 .AND.
     2    DABS(MU_W) .GT. 1.0D-30) THEN
         LAMW = KABS_GP * KRW_GP / MU_W
         LAMW_OK = UPS_CP168_ISFINITE(LAMW)
      END IF
      LAMN_OK = 0
      IF (UPS_CP168_ISFINITE(RHON) .EQ. 1 .AND.
     1    KABS_OK .EQ. 1 .AND. KRN_OK .EQ. 1 .AND.
     2    UPS_CP168_ISFINITE(MU_N) .EQ. 1 .AND.
     3    DABS(MU_N) .GT. 1.0D-30) THEN
         LAMN = RHON * KABS_GP * KRN_GP / MU_N
         LAMN_OK = UPS_CP168_ISFINITE(LAMN)
      END IF
      DERIVED_ALL_OK = 0
      IF (PC_OK .EQ. 1 .AND. PEQ_OK .EQ. 1 .AND.
     1    KABS_OK .EQ. 1 .AND. EPSV_OK .EQ. 1 .AND.
     2    SIGEFF_OK .EQ. 1 .AND. KRW_OK .EQ. 1 .AND.
     3    KRN_OK .EQ. 1 .AND. LAMW_OK .EQ. 1 .AND.
     4    LAMN_OK .EQ. 1) DERIVED_ALL_OK = 1

      FIRST_BAD_LAYER_ID = 0
      SOURCE_ID = 0
      IF (U_ALL_OK .EQ. 0 .OR. DU1_ALL_OK .EQ. 0) THEN
         FIRST_BAD_LAYER_ID = 1
         SOURCE_ID = 1
      ELSE IF (DE_OK .EQ. 0 .OR. PE_OK .EQ. 0 .OR.
     1         SE_OK .EQ. 0 .OR. PE_FROM_U_OK .EQ. 0 .OR.
     2         SE_FROM_U_OK .EQ. 0) THEN
         FIRST_BAD_LAYER_ID = 2
         SOURCE_ID = 2
      ELSE IF (INTERP_INPUT_OK .EQ. 0 .OR. PWGP_OK .EQ. 0 .OR.
     1         SNGP_OK .EQ. 0 .OR. GPW_OK .EQ. 0 .OR.
     2         GSN_OK .EQ. 0) THEN
         FIRST_BAD_LAYER_ID = 3
         SOURCE_ID = 3
      ELSE IF (SV_CORE_BAD_COUNT .GT. 0) THEN
         FIRST_BAD_LAYER_ID = 4
         SOURCE_ID = 4
      ELSE IF (DERIVED_ALL_OK .EQ. 0) THEN
         FIRST_BAD_LAYER_ID = 5
         SOURCE_ID = 5
      END IF

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_CP168_GP_RECON_CSV_FILE',
     1                                 FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp179A2_noActiveMobility'//
     2 '_segmentedK35_KINC23_70\outputs'//
     3 '\cp179A2_gp_reconstruction_audit.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .NE. 0) WRITE(*,*) 'CP168_OPEN_IOSTAT', IOS
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'kstep,kinc,elem,slot,gp,source_id,'//
     2       'first_bad_layer_id,u_all_finite,du1_all_finite,'//
     3       'u_u_finite,u_pw_finite,u_sn_finite,'//
     4       'du_u_finite,du_pw_finite,du_sn_finite,'//
     5       'u_bad_count,du_bad_count,u_first_bad_i,'//
     6       'u_first_bad_value_class,du_first_bad_i,'//
     7       'du_first_bad_value_class,u_pw_bad_node_mask,'//
     8       'u_sn_bad_node_mask,du_pw_bad_node_mask,'//
     9       'du_sn_bad_node_mask,pw_node1_ok,pw_node2_ok,'//
     1       'pw_node3_ok,pw_node4_ok,sn_node1_ok,sn_node2_ok,'//
     2       'sn_node3_ok,sn_node4_ok,de_finite,pe_finite,'//
     3       'se_finite,pe_from_u_ok,se_from_u_ok,'//
     4       'pe_bad_node_mask,se_bad_node_mask,n_finite,'//
     5       'n_sum_ok,dnx_finite,dny_finite,pw_gp_finite,'//
     6       'sn_gp_finite,gpw_finite,gsn_finite,'//
     7       'interp_input_ok,interp_bad_source_id,'//
     8       'sv_core_bad_count,sv_core_bad_mask,'//
     9       'sv_out_bad_count,sv_out_bad_mask,sv_out_valid_ok,'//
     1       'sv1_ok,sv2_ok,sv4_ok,sv5_ok,sv6_ok,sv8_ok,'//
     2       'sv10_ok,sv11_ok,sv12_ok,sv13_ok,pc_ok,peq_ok,'//
     3       'kabs_ok,epsv_ok,sigeff_ok,krw_ok,krn_ok,'//
     4       'lamw_ok,lamn_ok,derived_all_ok'
            IF (WIOS .NE. 0) WRITE(*,*) 'CP168_HEADER_IOSTAT', WIOS
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9888,IOSTAT=WIOS)
     1      KSTEP, KINC, JELEM, SLOT, IGP, SOURCE_ID,
     2      FIRST_BAD_LAYER_ID, U_ALL_OK, DU1_ALL_OK,
     3      U_U_OK, U_PW_OK, U_SN_OK, DU_U_OK, DU_PW_OK,
     4      DU_SN_OK, U_BAD_COUNT, DU_BAD_COUNT, U_FIRST_I,
     5      U_FIRST_CLASS, DU_FIRST_I, DU_FIRST_CLASS,
     6      U_PW_BAD_MASK, U_SN_BAD_MASK, DU_PW_BAD_MASK,
     7      DU_SN_BAD_MASK, PW_NODE1_OK, PW_NODE2_OK,
     8      PW_NODE3_OK, PW_NODE4_OK, SN_NODE1_OK, SN_NODE2_OK,
     9      SN_NODE3_OK, SN_NODE4_OK, DE_OK, PE_OK, SE_OK,
     1      PE_FROM_U_OK, SE_FROM_U_OK, PE_BAD_MASK, SE_BAD_MASK,
     2      N_OK, N_SUM_OK, DNX_OK, DNY_OK, PWGP_OK, SNGP_OK,
     3      GPW_OK, GSN_OK, INTERP_INPUT_OK, INTERP_BAD_SOURCE,
     4      SV_CORE_BAD_COUNT, SV_CORE_BAD_MASK, SV_OUT_BAD_COUNT,
     5      SV_OUT_BAD_MASK, SV_OUT_VALID_OK, SV1_OK, SV2_OK,
     6      SV4_OK, SV5_OK, SV6_OK, SV8_OK, SV10_OK, SV11_OK,
     7      SV12_OK, SV13_OK, PC_OK, PEQ_OK, KABS_OK, EPSV_OK,
     8      SIGEFF_OK, KRW_OK, KRN_OK, LAMW_OK, LAMN_OK,
     9      DERIVED_ALL_OK
C cp171A2 does not mark written; repeated cutback attempts are retained.
         IF (WIOS .NE. 0) WRITE(*,*) 'CP168_ROW_IOSTAT',
     1      JELEM, KINC, IGP, WIOS
      END IF

9888  FORMAT(120(I12,:,','))
      RETURN
      END

C ================================================================
C cp169 primary DOF restart audit.
C This subroutine runs at UEL entry before local unpack/interpolation.
C It records only U/DU finite flags and DOF-class masks for selected
C probe/control elements.
C ================================================================
      SUBROUTINE UPS_CP169_UENTRY_AUDIT(KSTEP, KINC, JELEM, NDOFEL,
     1 MLVARX, NRHS, U, DU)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, NDOFEL, MLVARX, NRHS
      INTEGER REGION_ID, SLOT, I, K, NODE, IOS, WIOS
      INTEGER CASE_ID, BC_FLAG, UNIT
      INTEGER U_ALL_OK, DU_ALL_OK, U_BAD_COUNT, DU_BAD_COUNT
      INTEGER U_U_BAD_MASK, U_PW_BAD_MASK, U_SN_BAD_MASK
      INTEGER DU_U_BAD_MASK, DU_PW_BAD_MASK, DU_SN_BAD_MASK
      INTEGER FIRST_U_I, FIRST_DU_I, FIRST_U_CLASS, FIRST_DU_CLASS
      INTEGER UPS_CP168_ISFINITE, UPS_CP168_BADCLASS
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      INTEGER WRITTEN(20,600,10)
      DOUBLE PRECISION U(NDOFEL), DU(MLVARX,NRHS)
      DOUBLE PRECISION FIRST_U_VALUE, FIRST_DU_VALUE
      DOUBLE PRECISION UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME
      DOUBLE PRECISION UPS_CUR_PERIOD
      COMMON /UPS_TIME_CTRL/ UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME,
     1 UPS_CUR_PERIOD
      CHARACTER*240 FILE_PATH
      CHARACTER*32 CASE_TAG
      LOGICAL OPENED
      PARAMETER (UNIT=969)
      SAVE OPENED, WRITTEN
      DATA OPENED /.FALSE./
      DATA WRITTEN /120000*0/

      IF (UPS_CP188A1_DETAIL_TIME_GATE(UPS_CUR_TOTAL_TIME)
     1    .EQ. 0) RETURN
      IF (KSTEP .LT. 1 .OR. KSTEP .GT. 20) RETURN
      IF (KINC .LT. 1 .OR. KINC .GT. 600) RETURN

      REGION_ID = 0
      SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         REGION_ID = 1
         SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         REGION_ID = 2
         SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         REGION_ID = 2
         SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         REGION_ID = 2
         SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         REGION_ID = 2
         SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         REGION_ID = 2
         SLOT = 10
      END IF
      IF (SLOT .LE. 0) RETURN
C cp171A2 intentionally keeps duplicate KINC rows so cutback attempts
C are visible in the CSV audit.

      CASE_ID = 0
      CASE_TAG = ' '
      CALL GET_ENVIRONMENT_VARIABLE('DBG_CP169_CASE_ID', CASE_TAG)
      IF (CASE_TAG(1:1) .NE. ' ') THEN
         READ(CASE_TAG,*,IOSTAT=IOS) CASE_ID
         IF (IOS .NE. 0) CASE_ID = 0
      END IF

      U_ALL_OK = 1
      DU_ALL_OK = 1
      U_BAD_COUNT = 0
      DU_BAD_COUNT = 0
      U_U_BAD_MASK = 0
      U_PW_BAD_MASK = 0
      U_SN_BAD_MASK = 0
      DU_U_BAD_MASK = 0
      DU_PW_BAD_MASK = 0
      DU_SN_BAD_MASK = 0
      FIRST_U_I = 0
      FIRST_DU_I = 0
      FIRST_U_CLASS = 0
      FIRST_DU_CLASS = 0
      FIRST_U_VALUE = 0.0D0
      FIRST_DU_VALUE = 0.0D0
      BC_FLAG = 0

      DO I = 1, NDOFEL
         IF (UPS_CP168_ISFINITE(U(I)) .EQ. 0) THEN
            U_ALL_OK = 0
            U_BAD_COUNT = U_BAD_COUNT + 1
            IF (FIRST_U_I .EQ. 0) THEN
               FIRST_U_I = I
               FIRST_U_CLASS = UPS_CP168_BADCLASS(U(I))
               FIRST_U_VALUE = U(I)
            END IF
            K = MOD(I-1,4) + 1
            NODE = (I-1)/4
            IF (K .LE. 2) U_U_BAD_MASK = U_U_BAD_MASK + 2**NODE
            IF (K .EQ. 3) U_PW_BAD_MASK = U_PW_BAD_MASK + 2**NODE
            IF (K .EQ. 4) U_SN_BAD_MASK = U_SN_BAD_MASK + 2**NODE
         END IF
      END DO

      IF (NRHS .GE. 1) THEN
         DO I = 1, NDOFEL
            IF (UPS_CP168_ISFINITE(DU(I,1)) .EQ. 0) THEN
               DU_ALL_OK = 0
               DU_BAD_COUNT = DU_BAD_COUNT + 1
               IF (FIRST_DU_I .EQ. 0) THEN
                  FIRST_DU_I = I
                  FIRST_DU_CLASS = UPS_CP168_BADCLASS(DU(I,1))
                  FIRST_DU_VALUE = DU(I,1)
               END IF
               K = MOD(I-1,4) + 1
               NODE = (I-1)/4
               IF (K .LE. 2)
     1            DU_U_BAD_MASK = DU_U_BAD_MASK + 2**NODE
               IF (K .EQ. 3)
     1            DU_PW_BAD_MASK = DU_PW_BAD_MASK + 2**NODE
               IF (K .EQ. 4)
     1            DU_SN_BAD_MASK = DU_SN_BAD_MASK + 2**NODE
            END IF
         END DO
      ELSE
         DU_ALL_OK = 0
      END IF

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_CP169_UENTRY_CSV_FILE',
     1                                 FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp169_restartPrimaryDOF_Audit'//
     2 '\outputs\cp169_uentry_audit.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'case_id,kstep,kinc,elem,region_id,'//
     2       'u_all_finite,du_all_finite,u_bad_count,'//
     3       'du_bad_count,u_u_bad_mask,u_pw_bad_mask,'//
     4       'u_sn_bad_mask,du_u_bad_mask,du_pw_bad_mask,'//
     5       'du_sn_bad_mask,first_bad_u_i,first_bad_u_class,'//
     6       'first_bad_u_value,first_bad_du_i,'//
     7       'first_bad_du_class,first_bad_du_value,'//
     8       'bc_flag,ndofel,mlvarx,nrhs'
         ELSE
            WRITE(*,*) 'CP169_OPEN_IOSTAT', IOS
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9169,IOSTAT=WIOS)
     1      CASE_ID, KSTEP, KINC, JELEM, REGION_ID,
     2      U_ALL_OK, DU_ALL_OK, U_BAD_COUNT, DU_BAD_COUNT,
     3      U_U_BAD_MASK, U_PW_BAD_MASK, U_SN_BAD_MASK,
     4      DU_U_BAD_MASK, DU_PW_BAD_MASK, DU_SN_BAD_MASK,
     5      FIRST_U_I, FIRST_U_CLASS, FIRST_U_VALUE,
     6      FIRST_DU_I, FIRST_DU_CLASS, FIRST_DU_VALUE,
     7      BC_FLAG, NDOFEL, MLVARX, NRHS
C cp171A2 does not mark written; repeated cutback attempts are retained.
         IF (WIOS .NE. 0) WRITE(*,*) 'CP169_ROW_IOSTAT',
     1      JELEM, KSTEP, KINC, WIOS
      END IF

9169  FORMAT(I12,16(',',I12),',',ES24.16,2(',',I12),',',
     1 ES24.16,4(',',I12))
      RETURN
      END

C ================================================================
C cp170 SVARS reconstruction proof audit.
C This runs immediately after UPS_SVARS_READ. It does not modify
C SVARS or any local state. The goal is to decide whether committed
C physical state can be reconstructed without trusting Abaqus U/DU
C after restart.
C ================================================================
      SUBROUTINE UPS_CP170_SVARS_RECON_AUDIT(KSTEP, KINC, JELEM,
     1 IGP, NSVARGP, SV_GP_OLD)
      IMPLICIT NONE
      INTEGER KSTEP, KINC, JELEM, IGP, NSVARGP
      INTEGER REGION_ID, SLOT, IOS, WIOS, CASE_ID, UNIT
      INTEGER CORE_OK, PW_OK, SN_OK, PC_OK, PEQ_OK, EPSV_OK
      INTEGER KABS_OK, SIG_OK, OUT_OK, OUT_VALID_OK
      INTEGER OUT_SOURCE_OK, OUT_TIME_OK, OUT_KINC_OK
      INTEGER OUT_VALID_GT0, OUT_SOURCE_GT0
      INTEGER PRIMARY_RECON_OK, MECH_RECON_OK, BUNDLE_RECON_OK
      INTEGER U_RECON_OK, FIRST_BAD_CORE_SLOT, FIRST_BAD_OUT_SLOT
      INTEGER WRITTEN(20,600,10,4)
      INTEGER UPS_CP168_ISFINITE
      INTEGER UPS_CP188A1_DETAIL_TIME_GATE
      DOUBLE PRECISION SV_GP_OLD(NSVARGP)
      DOUBLE PRECISION UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME
      DOUBLE PRECISION UPS_CUR_PERIOD
      COMMON /UPS_TIME_CTRL/ UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME,
     1 UPS_CUR_PERIOD
      CHARACTER*240 FILE_PATH
      CHARACTER*32 CASE_TAG
      LOGICAL OPENED
      PARAMETER (UNIT=970)
      SAVE OPENED, WRITTEN
      DATA OPENED /.FALSE./
      DATA WRITTEN /480000*0/

      IF (UPS_CP188A1_DETAIL_TIME_GATE(UPS_CUR_TOTAL_TIME)
     1    .EQ. 0) RETURN
      IF (KSTEP .LT. 1 .OR. KSTEP .GT. 20) RETURN
      IF (KINC .LT. 1 .OR. KINC .GT. 600) RETURN
      IF (IGP .LT. 1 .OR. IGP .GT. 4) RETURN

      REGION_ID = 0
      SLOT = 0
      IF (JELEM .GE. 10287 .AND. JELEM .LE. 10291) THEN
         REGION_ID = 1
         SLOT = JELEM - 10286
      ELSE IF (JELEM .EQ. 23490) THEN
         REGION_ID = 2
         SLOT = 6
      ELSE IF (JELEM .EQ. 26805) THEN
         REGION_ID = 2
         SLOT = 7
      ELSE IF (JELEM .EQ. 32962) THEN
         REGION_ID = 2
         SLOT = 8
      ELSE IF (JELEM .EQ. 78333) THEN
         REGION_ID = 2
         SLOT = 9
      ELSE IF (JELEM .EQ. 80223) THEN
         REGION_ID = 2
         SLOT = 10
      END IF
      IF (SLOT .LE. 0) RETURN
      IF (WRITTEN(KSTEP,KINC,SLOT,IGP) .NE. 0) RETURN

      CASE_ID = 0
      CASE_TAG = ' '
      CALL GET_ENVIRONMENT_VARIABLE('DBG_CP170_CASE_ID', CASE_TAG)
      IF (CASE_TAG(1:1) .NE. ' ') THEN
         READ(CASE_TAG,*,IOSTAT=IOS) CASE_ID
         IF (IOS .NE. 0) CASE_ID = 0
      END IF

      CORE_OK = 1
      PW_OK = 0
      SN_OK = 0
      PC_OK = 0
      PEQ_OK = 0
      EPSV_OK = 0
      KABS_OK = 0
      SIG_OK = 0
      OUT_OK = 1
      OUT_VALID_OK = 0
      OUT_SOURCE_OK = 0
      OUT_TIME_OK = 0
      OUT_KINC_OK = 0
      OUT_VALID_GT0 = 0
      OUT_SOURCE_GT0 = 0
      PRIMARY_RECON_OK = 0
      MECH_RECON_OK = 0
      BUNDLE_RECON_OK = 0
      U_RECON_OK = 0
      FIRST_BAD_CORE_SLOT = 0
      FIRST_BAD_OUT_SLOT = 0

      IF (NSVARGP .GE. 1) PW_OK = UPS_CP168_ISFINITE(SV_GP_OLD(1))
      IF (NSVARGP .GE. 2) SN_OK = UPS_CP168_ISFINITE(SV_GP_OLD(2))
      IF (NSVARGP .GE. 4) PC_OK = UPS_CP168_ISFINITE(SV_GP_OLD(4))
      IF (NSVARGP .GE. 5) PEQ_OK = UPS_CP168_ISFINITE(SV_GP_OLD(5))
      IF (NSVARGP .GE. 6) EPSV_OK = UPS_CP168_ISFINITE(SV_GP_OLD(6))
      IF (NSVARGP .GE. 8) KABS_OK = UPS_CP168_ISFINITE(SV_GP_OLD(8))
      IF (NSVARGP .GE. 12) THEN
         SIG_OK = UPS_CP168_ISFINITE(SV_GP_OLD(10))
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(11)) .EQ. 0) SIG_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(12)) .EQ. 0) SIG_OK = 0
      END IF

      IF (PW_OK .EQ. 0) THEN
         CORE_OK = 0
         IF (FIRST_BAD_CORE_SLOT .EQ. 0) FIRST_BAD_CORE_SLOT = 1
      END IF
      IF (SN_OK .EQ. 0) THEN
         CORE_OK = 0
         IF (FIRST_BAD_CORE_SLOT .EQ. 0) FIRST_BAD_CORE_SLOT = 2
      END IF
      IF (PC_OK .EQ. 0) THEN
         CORE_OK = 0
         IF (FIRST_BAD_CORE_SLOT .EQ. 0) FIRST_BAD_CORE_SLOT = 4
      END IF
      IF (PEQ_OK .EQ. 0) THEN
         CORE_OK = 0
         IF (FIRST_BAD_CORE_SLOT .EQ. 0) FIRST_BAD_CORE_SLOT = 5
      END IF
      IF (EPSV_OK .EQ. 0) THEN
         CORE_OK = 0
         IF (FIRST_BAD_CORE_SLOT .EQ. 0) FIRST_BAD_CORE_SLOT = 6
      END IF
      IF (KABS_OK .EQ. 0) THEN
         CORE_OK = 0
         IF (FIRST_BAD_CORE_SLOT .EQ. 0) FIRST_BAD_CORE_SLOT = 8
      END IF
      IF (SIG_OK .EQ. 0) THEN
         CORE_OK = 0
         IF (FIRST_BAD_CORE_SLOT .EQ. 0) FIRST_BAD_CORE_SLOT = 10
      END IF

      IF (NSVARGP .GE. 45) THEN
         OUT_VALID_OK = UPS_CP168_ISFINITE(SV_GP_OLD(42))
         OUT_SOURCE_OK = UPS_CP168_ISFINITE(SV_GP_OLD(43))
         OUT_TIME_OK = UPS_CP168_ISFINITE(SV_GP_OLD(44))
         OUT_KINC_OK = UPS_CP168_ISFINITE(SV_GP_OLD(45))
         IF (OUT_VALID_OK .EQ. 1 .AND. SV_GP_OLD(42) .GE. 0.5D0)
     1      OUT_VALID_GT0 = 1
         IF (OUT_SOURCE_OK .EQ. 1 .AND. SV_GP_OLD(43) .GT. 0.5D0)
     1      OUT_SOURCE_GT0 = 1
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(33)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(34)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(35)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(36)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(37)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(38)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(39)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(40)) .EQ. 0) OUT_OK = 0
         IF (UPS_CP168_ISFINITE(SV_GP_OLD(41)) .EQ. 0) OUT_OK = 0
         IF (OUT_VALID_OK .EQ. 0) OUT_OK = 0
         IF (OUT_SOURCE_OK .EQ. 0) OUT_OK = 0
         IF (OUT_TIME_OK .EQ. 0) OUT_OK = 0
         IF (OUT_KINC_OK .EQ. 0) OUT_OK = 0
         IF (OUT_OK .EQ. 0) THEN
            IF (UPS_CP168_ISFINITE(SV_GP_OLD(33)) .EQ. 0)
     1         FIRST_BAD_OUT_SLOT = 33
            IF (FIRST_BAD_OUT_SLOT .EQ. 0 .AND.
     1          UPS_CP168_ISFINITE(SV_GP_OLD(34)) .EQ. 0)
     2         FIRST_BAD_OUT_SLOT = 34
            IF (FIRST_BAD_OUT_SLOT .EQ. 0 .AND.
     1          UPS_CP168_ISFINITE(SV_GP_OLD(42)) .EQ. 0)
     2         FIRST_BAD_OUT_SLOT = 42
         END IF
      ELSE
         OUT_OK = 0
         FIRST_BAD_OUT_SLOT = 33
      END IF

      IF (PW_OK .EQ. 1 .AND. SN_OK .EQ. 1)
     1   PRIMARY_RECON_OK = 1
      IF (PEQ_OK .EQ. 1 .AND. EPSV_OK .EQ. 1 .AND.
     1    KABS_OK .EQ. 1 .AND. SIG_OK .EQ. 1)
     2   MECH_RECON_OK = 1
      IF (PRIMARY_RECON_OK .EQ. 1 .AND. MECH_RECON_OK .EQ. 1)
     1   BUNDLE_RECON_OK = 1

      IF (.NOT. OPENED) THEN
         FILE_PATH = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_CP170_SVARS_CSV_FILE',
     1                                 FILE_PATH)
         IF (FILE_PATH(1:1) .EQ. ' ') THEN
            FILE_PATH =
     1 'C:\abq_runs\ac128wo_cp170_restartPrimaryDOFMechanism'//
     2 '\outputs\cp170_svars_reconstruct_audit.csv'
         END IF
         OPEN(UNIT=UNIT, FILE=FILE_PATH(1:LEN_TRIM(FILE_PATH)),
     1        STATUS='UNKNOWN', POSITION='APPEND',
     2        ACTION='WRITE', IOSTAT=IOS)
         IF (IOS .EQ. 0) THEN
            OPENED = .TRUE.
            WRITE(UNIT,'(A)',IOSTAT=WIOS)
     1       'case_id,kstep,kinc,elem,gp,region_id,'//
     2       'core_committed_all_finite,pw_old_ok,sn_old_ok,'//
     3       'pc_old_ok,peq_old_ok,epsv_old_ok,kabs_old_ok,'//
     4       'sig_old_ok,out_mirror_all_finite,out_valid_slot_ok,'//
     5       'out_source_slot_ok,out_time_slot_ok,out_kinc_slot_ok,'//
     6       'out_valid_gt0,out_source_gt0,'//
     7       'svars_primary_reconstruct_ok,'//
     8       'svars_mech_reconstruct_ok,'//
     9       'svars_bundle_reconstruct_ok,u_reconstruct_ok,'//
     1       'first_bad_core_slot,first_bad_out_slot,nsvargp'
         ELSE
            WRITE(*,*) 'CP170_SVARS_OPEN_IOSTAT', IOS
         END IF
      END IF

      IF (OPENED) THEN
         WRITE(UNIT,9170,IOSTAT=WIOS)
     1      CASE_ID, KSTEP, KINC, JELEM, IGP, REGION_ID,
     2      CORE_OK, PW_OK, SN_OK, PC_OK, PEQ_OK, EPSV_OK,
     3      KABS_OK, SIG_OK, OUT_OK, OUT_VALID_OK, OUT_SOURCE_OK,
     4      OUT_TIME_OK, OUT_KINC_OK, OUT_VALID_GT0, OUT_SOURCE_GT0,
     5      PRIMARY_RECON_OK, MECH_RECON_OK, BUNDLE_RECON_OK,
     6      U_RECON_OK, FIRST_BAD_CORE_SLOT, FIRST_BAD_OUT_SLOT,
     7      NSVARGP
         IF (WIOS .EQ. 0) WRITTEN(KSTEP,KINC,SLOT,IGP) = 1
         IF (WIOS .NE. 0) WRITE(*,*) 'CP170_SVARS_ROW_IOSTAT',
     1      JELEM, KSTEP, KINC, IGP, WIOS
      END IF

9170  FORMAT(28(I12,:,','))
      RETURN
      END

      INTEGER FUNCTION UPS_CP168_ISFINITE(X)
      IMPLICIT NONE
      DOUBLE PRECISION X
      IF (X .EQ. X .AND. DABS(X) .LE. 1.0D100) THEN
         UPS_CP168_ISFINITE = 1
      ELSE
         UPS_CP168_ISFINITE = 0
      END IF
      RETURN
      END

      INTEGER FUNCTION UPS_CP168_BADCLASS(X)
      IMPLICIT NONE
      DOUBLE PRECISION X
      IF (X .NE. X) THEN
         UPS_CP168_BADCLASS = 1
      ELSE IF (DABS(X) .GT. 1.0D100) THEN
         UPS_CP168_BADCLASS = 2
      ELSE
         UPS_CP168_BADCLASS = 0
      END IF
      RETURN
      END


C ================================================================
C Helper: row-wise L1 norms of a dense matrix
C ================================================================
      SUBROUTINE UPS_ROW_L1NORMS(A, NROW, NCOL, RNORM)
      IMPLICIT NONE
      INTEGER NROW, NCOL, I, J
      DOUBLE PRECISION A(NROW,NCOL), RNORM(NROW), SUMABS

      DO I = 1, NROW
         SUMABS = 0.0D0
         DO J = 1, NCOL
            SUMABS = SUMABS + DABS(A(I,J))
         END DO
         RNORM(I) = SUMABS
      END DO

      RETURN
      END


C ================================================================
C Helper: write local matrix diagnostics for selected elements
C ================================================================
      SUBROUTINE UPS_WRITE_LOCAL_MATRIX_DIAG(IUNIT, JELEM, KSTEP,
     1 KINC, U, DE, PE, SE, COORDS, MCRD, NNODE, KE, KUU, KUP, KUS,
     2 KPU, KPP, KPS, KSU, KSP, KSS, GP_PW, GP_SN, GP_SW, GP_PC,
     3 GP_PEQ, GP_KABS, GP_PHI, GP_PW_OLD, GP_SN_OLD, GP_EPSV_OLD,
     4 GP_SE_RAW, GP_SE_CLAMP, GP_DS, GP_CHI, GP_DCHI_DSN, GP_KRW,
     5 GP_KRN, GP_DSE_DSN, GP_DKRW_DSN, GP_DKRN_DSN, GP_DPEQ_DPW,
     6 GP_DPEQ_DSN, GP_SIGMA_MEFF)

      IMPLICIT NONE
      INTEGER IUNIT, JELEM, KSTEP, KINC, MCRD, NNODE, I, J, NODE
      CHARACTER*2 FIELD
      DOUBLE PRECISION U(16), DE(8), PE(4), SE(4)
      DOUBLE PRECISION COORDS(MCRD,NNODE), KE(16,16)
      DOUBLE PRECISION KUU(8,8), KUP(8,4), KUS(8,4)
      DOUBLE PRECISION KPU(4,8), KPP(4,4), KPS(4,4)
      DOUBLE PRECISION KSU(4,8), KSP(4,4), KSS(4,4)
      DOUBLE PRECISION GP_PW(4), GP_SN(4), GP_SW(4), GP_PC(4)
      DOUBLE PRECISION GP_PEQ(4), GP_KABS(4), GP_PHI(4)
      DOUBLE PRECISION GP_PW_OLD(4), GP_SN_OLD(4), GP_EPSV_OLD(4)
      DOUBLE PRECISION GP_SE_RAW(4), GP_SE_CLAMP(4), GP_DS(4)
      DOUBLE PRECISION GP_CHI(4), GP_DCHI_DSN(4), GP_KRW(4), GP_KRN(4)
      DOUBLE PRECISION GP_DSE_DSN(4), GP_DKRW_DSN(4), GP_DKRN_DSN(4)
      DOUBLE PRECISION GP_DPEQ_DPW(4), GP_DPEQ_DSN(4), GP_SIGMA_MEFF(4)
      DOUBLE PRECISION ROW_NORM(16)
      DOUBLE PRECISION AMAX, FNORM
      DOUBLE PRECISION DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG
      DOUBLE PRECISION DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX
      DOUBLE PRECISION DBG_SE_MIN, DBG_SN_SEED
      DOUBLE PRECISION DBG_P_REG_SCALE, DBG_S_REG_SCALE
      DOUBLE PRECISION DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL
      DOUBLE PRECISION DBG_FIELD_CAPACITY_REG
      DOUBLE PRECISION DBG_FIELD_CAPACITY_ETA
      DOUBLE PRECISION DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG
      DOUBLE PRECISION DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA
      DOUBLE PRECISION DBG_FIELD_ANCHOR_REG
      DOUBLE PRECISION DBG_FIELD_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG
      DOUBLE PRECISION DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM
      DOUBLE PRECISION DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF
      DOUBLE PRECISION DBG_AUDIT_MODE_CODE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      COMMON /UPS_DIAG_CTRL/ DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG,
     1 DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX, DBG_SE_MIN,
     2 DBG_SN_SEED, DBG_P_REG_SCALE, DBG_S_REG_SCALE,
     3 DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL,
     4 DBG_FIELD_CAPACITY_REG, DBG_FIELD_CAPACITY_ETA,
     5 DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG,
     6 DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA,
     7 DBG_FIELD_ANCHOR_REG, DBG_FIELD_ANCHOR_ETA,
     8 DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG,
     9 DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA,
     1 DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM,
     2 DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF,
     3 DBG_AUDIT_MODE_CODE,
     4 DBG_FIELD_CAPACITY_AUDIT_RP_DONE,
     5 DBG_FIELD_CAPACITY_AUDIT_RS_DONE,
     6 DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP,
     7 DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP,
     8 DBG_FIELD_ANCHOR_AUDIT_RP_DONE,
     9 DBG_FIELD_ANCHOR_AUDIT_RS_DONE,
     1 DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP,
     2 DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP

      WRITE(IUNIT,*) '==============================================='
      WRITE(IUNIT,*) 'LOCAL MATRIX DIAG'
      WRITE(IUNIT,*) 'JELEM = ', JELEM, ' KSTEP = ', KSTEP,
     1                ' KINC = ', KINC
      WRITE(IUNIT,*) 'ENTRY U(1:16) [node-major ux, uy, pw, sn]'
      WRITE(IUNIT,*) 'U = ', U(1), U(2), U(3), U(4), U(5), U(6),
     1               U(7), U(8), U(9), U(10), U(11), U(12), U(13),
     2               U(14), U(15), U(16)

      IF (DBG_LOC_MINIMAL .GT. 0.5D0) THEN
         WRITE(IUNIT,*) 'PW/SN BY GP (MINIMAL TRACE ONLY)'
         DO I = 1, 4
            WRITE(IUNIT,*) I, GP_PW(I), GP_SN(I)
         END DO
         RETURN
      END IF

      WRITE(IUNIT,*) 'ENTRY DE(1:8) = ', DE(1), DE(2), DE(3), DE(4),
     1               DE(5), DE(6), DE(7), DE(8)
      WRITE(IUNIT,*) 'ENTRY PE(1:4) = ', PE(1), PE(2), PE(3), PE(4)
      WRITE(IUNIT,*) 'ENTRY SE(1:4) = ', SE(1), SE(2), SE(3), SE(4)
      WRITE(IUNIT,*) 'LOCAL NODE ORDER = 1..4 (global node ids are in',
     1               ' the whitelist manifest)'
      WRITE(IUNIT,*) 'ROW ORDER = node-major [U1, U2, PW, SN]'
      WRITE(IUNIT,*) 'LOCAL NODE COORDS (node#, x, y)'
      DO I = 1, NNODE
         WRITE(IUNIT,*) I, COORDS(1,I), COORDS(2,I)
      END DO

      WRITE(IUNIT,*) 'GP STATE SUMMARY (IGP, PW, SN, SW, PC, PEQ,',
     1               ' KABS, PHI)'
      DO I = 1, 4
         WRITE(IUNIT,*) I, GP_PW(I), GP_SN(I), GP_SW(I), GP_PC(I),
     1                   GP_PEQ(I), GP_KABS(I), GP_PHI(I)
         WRITE(IUNIT,*) '  OLD PW/SN/EPSV = ', GP_PW_OLD(I),
     1                   GP_SN_OLD(I), GP_EPSV_OLD(I)
         WRITE(IUNIT,*) '  RAW/CLAMP/DS/CHI = ', GP_SE_RAW(I),
     1                   GP_SE_CLAMP(I), GP_DS(I), GP_CHI(I)
         WRITE(IUNIT,*) '  DSE/DCHI = ', GP_DSE_DSN(I), GP_DCHI_DSN(I)
         WRITE(IUNIT,*) '  KRW/KRN = ', GP_KRW(I), GP_KRN(I)
         WRITE(IUNIT,*) '  DKRW/DKRN = ', GP_DKRW_DSN(I),
     1                   GP_DKRN_DSN(I)
         WRITE(IUNIT,*) '  DPEQ_DPW/DPEQ_DSN = ', GP_DPEQ_DPW(I),
     1                   GP_DPEQ_DSN(I)
         WRITE(IUNIT,*) '  SIGMA_MEFF = ', GP_SIGMA_MEFF(I)
      END DO

      CALL UPS_ROW_L1NORMS(KE, 16, 16, ROW_NORM)
      WRITE(IUNIT,*) 'KE ROW L1 NORMS (row, node, field, norm)'
      DO I = 1, 16
         NODE = (I-1)/4 + 1
         J = MOD(I-1,4) + 1
         FIELD = '??'
         IF (J .EQ. 1) FIELD = 'U1'
         IF (J .EQ. 2) FIELD = 'U2'
         IF (J .EQ. 3) FIELD = 'PW'
         IF (J .EQ. 4) FIELD = 'SN'
         WRITE(IUNIT,*) I, NODE, FIELD, ROW_NORM(I)
      END DO

      WRITE(IUNIT,*) 'BLOCK STATS (MAXABS, FNORM)'
      CALL UPS_MAT_MAXABS(KUU, 8, 8, AMAX)
      CALL UPS_MAT_FROBNORM(KUU, 8, 8, FNORM)
      WRITE(IUNIT,*) 'KUU ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KUP, 8, 4, AMAX)
      CALL UPS_MAT_FROBNORM(KUP, 8, 4, FNORM)
      WRITE(IUNIT,*) 'KUP ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KUS, 8, 4, AMAX)
      CALL UPS_MAT_FROBNORM(KUS, 8, 4, FNORM)
      WRITE(IUNIT,*) 'KUS ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KPU, 4, 8, AMAX)
      CALL UPS_MAT_FROBNORM(KPU, 4, 8, FNORM)
      WRITE(IUNIT,*) 'KPU ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KPP, 4, 4, AMAX)
      CALL UPS_MAT_FROBNORM(KPP, 4, 4, FNORM)
      WRITE(IUNIT,*) 'KPP ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KPS, 4, 4, AMAX)
      CALL UPS_MAT_FROBNORM(KPS, 4, 4, FNORM)
      WRITE(IUNIT,*) 'KPS ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KSU, 4, 8, AMAX)
      CALL UPS_MAT_FROBNORM(KSU, 4, 8, FNORM)
      WRITE(IUNIT,*) 'KSU ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KSP, 4, 4, AMAX)
      CALL UPS_MAT_FROBNORM(KSP, 4, 4, FNORM)
      WRITE(IUNIT,*) 'KSP ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KSS, 4, 4, AMAX)
      CALL UPS_MAT_FROBNORM(KSS, 4, 4, FNORM)
      WRITE(IUNIT,*) 'KSS ', AMAX, FNORM
      CALL UPS_MAT_MAXABS(KE, 16, 16, AMAX)
      CALL UPS_MAT_FROBNORM(KE, 16, 16, FNORM)
      WRITE(IUNIT,*) 'KE  ', AMAX, FNORM
      WRITE(IUNIT,*) '==============================================='

      RETURN
      END


C ================================================================
C Helper: load integer whitelist from a text file
C ================================================================
      SUBROUTINE UPS_LOAD_INT_LIST_FILE(FPATH, LIST, MAXLIST, NLIST,
     1 IOS)
      IMPLICIT NONE
      CHARACTER*(*) FPATH
      INTEGER LIST(MAXLIST), MAXLIST, NLIST, IOS
      INTEGER UNIT, VAL, IOS2
      CHARACTER*512 LINE
      LOGICAL EXISTS

      NLIST = 0
      IOS = 0
      IF (LEN_TRIM(FPATH) .LE. 0) RETURN

      INQUIRE(FILE=FPATH, EXIST=EXISTS)
      IF (.NOT. EXISTS) THEN
         IOS = 1
         RETURN
      END IF

      UNIT = 95
      OPEN(UNIT=UNIT, FILE=FPATH, STATUS='OLD', ACTION='READ',
     1     IOSTAT=IOS)
      IF (IOS .NE. 0) RETURN

      DO
         READ(UNIT,'(A)',IOSTAT=IOS2) LINE
         IF (IOS2 .NE. 0) EXIT
         IF (LEN_TRIM(LINE) .LE. 0) CYCLE
         READ(LINE,*,IOSTAT=IOS2) VAL
         IF (IOS2 .NE. 0) CYCLE
         IF (NLIST .LT. MAXLIST) THEN
            NLIST = NLIST + 1
            LIST(NLIST) = VAL
         END IF
      END DO

      CLOSE(UNIT)
      IOS = 0
      RETURN
      END


C ================================================================
C r1b Newton snapshot at element level
C ================================================================
      SUBROUTINE UPS_DBG_R1B_NEWTON_SNAPSHOT(JELEM, KSTEP, KINC,
     1     DEBUG_UEL, TIME, DTIME, DE, PE, SE,
     2     RU, RP, RS, KUU, KUP, KUS)
      IMPLICIT NONE
      INTEGER JELEM, KSTEP, KINC, DEBUG_UEL
      INTEGER IUDBG, IOS
      DOUBLE PRECISION TIME(2), DTIME
      DOUBLE PRECISION DE(8), PE(4), SE(4)
      DOUBLE PRECISION RU(8), RP(4), RS(4), KUU(8,8), KUP(8,4), KUS(8,4)
      DOUBLE PRECISION RELOC(16), KELOC(16,16), RHSLOC(16)
      DOUBLE PRECISION UF, RF, KFF, DUN, DF, DUMX
      DOUBLE PRECISION DUMECH(8), DP_MECH(4), DS_MECH(4)
      DOUBLE PRECISION DE_PREV(8), PE_PREV(4), SE_PREV(4)
      DOUBLE PRECISION DUF, DPU, DSP, BF
      DOUBLE PRECISION RE8, KE88, RHS8, AM88, DURE, DURHS
      DOUBLE PRECISION B_UEL, B_U, B_P, B_S, B_REM
      DOUBLE PRECISION RF8_SIG_GP, RF8_PEQ_GP, RF8_TOT_GP
      DOUBLE PRECISION DBG_SUM_RF8_SIG, DBG_SUM_RF8_PEQ
      DOUBLE PRECISION DBG_SUM_RF8_TOT
      INTEGER J, A
      LOGICAL SNAP_INIT
      CHARACTER*256 FDBG

      SAVE DE_PREV, PE_PREV, SE_PREV, SNAP_INIT
      SAVE DBG_SUM_RF8_SIG, DBG_SUM_RF8_PEQ, DBG_SUM_RF8_TOT
      DATA SNAP_INIT /.FALSE./
      DATA DBG_SUM_RF8_SIG /0.0D0/
      DATA DBG_SUM_RF8_PEQ /0.0D0/
      DATA DBG_SUM_RF8_TOT /0.0D0/

      IF (DEBUG_UEL .EQ. 0) RETURN
      IF (JELEM .NE. 1) RETURN
      IF (KSTEP .NE. 2) RETURN

      IUDBG = 97
      FDBG = 'C:/Users/Ldd/AppData/Local/Temp/dbg_r1b_newton.txt'

      OPEN(UNIT=IUDBG, FILE=FDBG, STATUS='UNKNOWN',
     1     POSITION='APPEND', ACTION='WRITE', IOSTAT=IOS)
      IF (IOS .NE. 0) RETURN

      UF = DE(8)
      RF = RU(8)
      KFF = KUU(8,8)

      IF (.NOT. SNAP_INIT) THEN
         DO J = 1, 8
            DE_PREV(J) = DE(J)
         END DO
         DO A = 1, 4
            PE_PREV(A) = PE(A)
            SE_PREV(A) = SE(A)
         END DO
         SNAP_INIT = .TRUE.
      END IF

      DUMECH(1) = DE(1) - DE_PREV(1)
      DUMECH(2) = DE(2) - DE_PREV(2)
      DUMECH(3) = DE(3) - DE_PREV(3)
      DUMECH(4) = DE(4) - DE_PREV(4)
      DUMECH(5) = DE(5) - DE_PREV(5)
      DUMECH(6) = DE(6) - DE_PREV(6)
      DUMECH(7) = DE(7) - DE_PREV(7)
      DUMECH(8) = DE(8) - DE_PREV(8)
      DO A = 1, 4
         DP_MECH(A) = PE(A) - PE_PREV(A)
         DS_MECH(A) = SE(A) - SE_PREV(A)
      END DO

      DF = KUU(8,8) * DUMECH(8)
      DPU = 0.0D0
      DSP = 0.0D0
      DO A = 1, 4
         DPU = DPU + KUP(8,A) * DP_MECH(A)
         DSP = DSP + KUS(8,A) * DS_MECH(A)
      END DO

      DUMX = 0.0D0
      DO J = 1, 7
         DUMX = DUMX + KUU(8,J) * DUMECH(J)
      END DO

      IF (DABS(KFF) .GT. 1.0D-20) THEN
         DUN = -(RF + DUMX + DPU + DSP) / KFF
      ELSE
         DUN = 0.0D0
      END IF
      BF = RF + DF + DUMX + DPU + DSP

      CALL UPS_ZERO_VEC(RELOC,16)
      CALL UPS_ZERO_MAT(KELOC,16,16)
      DO J = 1, 8
         RELOC(J) = RU(J)
      END DO
      RELOC(9)  = RU(1)
      RELOC(10) = RU(2)
      RELOC(11) = RU(3)
      RELOC(12) = RU(4)
      RELOC(13) = RS(1)
      RELOC(14) = RS(2)
      RELOC(15) = RS(3)
      RELOC(16) = RS(4)

      DO J = 1, 8
         KELOC(8,J) = KUU(8,J)
         KELOC(J,8) = KUU(J,8)
      END DO
      DO A = 1, 4
         KELOC(8,8+A) = KUP(8,A)
         KELOC(8,12+A) = KUS(8,A)
      END DO

      RE8 = RELOC(8)
      KE88 = KELOC(8,8)
      RHS8 = -RE8
      AM88 = KE88
      IF (DABS(KE88) .GT. 1.0D-20) THEN
         DURE = -RE8 / KE88
         DURHS = RHS8 / AM88
      ELSE
         DURE = 0.0D0
         DURHS = 0.0D0
      END IF

      B_UEL = RF - KFF * UF
      B_U = 0.0D0
      DO J = 1, 7
         B_U = B_U + KUU(8,J) * DE(J)
      END DO
      B_P = 0.0D0
      DO A = 1, 4
         B_P = B_P + KUP(8,A) * PE(A)
      END DO
      B_S = 0.0D0
      DO A = 1, 4
         B_S = B_S + KUS(8,A) * SE(A)
      END DO
      B_REM = B_UEL - (B_U + B_P + B_S)

      WRITE(IUDBG,*) '=== DBG_R1B_NEWTON ==='
      WRITE(IUDBG,*) 'JELEM = ', JELEM, ' KSTEP = ', KSTEP,
     1     ' KINC = ', KINC
      WRITE(IUDBG,*) 'TIME  = ', TIME(1), TIME(2), ' DTIME = ', DTIME
      WRITE(IUDBG,*) 'u_f   = ', UF
      WRITE(IUDBG,*) 'du_f_eff = ', DUMECH(8)
      WRITE(IUDBG,*) 'R_f   = ', RF
      WRITE(IUDBG,*) 'K_ff  = ', KFF
      WRITE(IUDBG,*) '-B_f/K_ff = ', DUN
      WRITE(IUDBG,*) 'D_f   = ', DF
      WRITE(IUDBG,*) 'D_u   = ', DUMX
      WRITE(IUDBG,*) 'D_p   = ', DPU
      WRITE(IUDBG,*) 'D_s   = ', DSP
      WRITE(IUDBG,*) 'B_f   = ', BF
      WRITE(IUDBG,*) 'du_pred  = ', DUN
      WRITE(IUDBG,*) 'RE(8) = ', RE8
      WRITE(IUDBG,*) 'KE(8,8) = ', KE88
      WRITE(IUDBG,*) 'RHS(8) = ', RHS8
      WRITE(IUDBG,*) 'AM88   = ', AM88
      WRITE(IUDBG,*) '-RE/KE = ', DURE
      WRITE(IUDBG,*) 'RHS/AM = ', DURHS
      WRITE(IUDBG,*) 'DU_mech = ', DUMECH(1), DUMECH(2), DUMECH(3),
     1     DUMECH(4), DUMECH(5), DUMECH(6), DUMECH(7), DUMECH(8)
      WRITE(IUDBG,*) 'DP_mech = ', DP_MECH(1), DP_MECH(2),
     1     DP_MECH(3), DP_MECH(4)
      WRITE(IUDBG,*) 'DS_mech = ', DS_MECH(1), DS_MECH(2),
     1     DS_MECH(3), DS_MECH(4)
      WRITE(IUDBG,*) 'KUU row8 = ', KUU(8,1), KUU(8,2), KUU(8,3),
     1     KUU(8,4), KUU(8,5), KUU(8,6), KUU(8,7), KUU(8,8)
      WRITE(IUDBG,*) 'KUP row8 = ', KUP(8,1), KUP(8,2), KUP(8,3),
     1     KUP(8,4)
      WRITE(IUDBG,*) 'KUS row8 = ', KUS(8,1), KUS(8,2), KUS(8,3),
     1     KUS(8,4)
      WRITE(IUDBG,*) '=== DBG_R1B_BIAS ==='
      WRITE(IUDBG,*) 'B_UEL = ', B_UEL
      WRITE(IUDBG,*) 'B_U   = ', B_U
      WRITE(IUDBG,*) 'B_P   = ', B_P
      WRITE(IUDBG,*) 'B_S   = ', B_S
      WRITE(IUDBG,*) 'B_REM = ', B_REM
      WRITE(IUDBG,*) 'B_SUM = ', B_U + B_P + B_S
      DO J = 1, 8
         DE_PREV(J) = DE(J)
      END DO
      DO A = 1, 4
         PE_PREV(A) = PE(A)
         SE_PREV(A) = SE(A)
      END DO
      WRITE(IUDBG,*) ' '
      CALL FLUSH(IUDBG)
      CLOSE(IUDBG)

      RETURN
      END


C ================================================================
C Evaluate one Gauss point state and block residual/tangent values
C ================================================================
      SUBROUTINE UPS_EVAL_GAUSS_BLOCKS(WT, DETJ, DTIME,
     1 JELEM, KSTEP, KINC,
     2 N, DNX, DNY, BU, DE, PE, SE,
     3 PW_OLD, SN_OLD, EPSV_OLD, PROPS,
     4 RU, RP, RS,
     5 KUU, KUP, KUS, KPU, KPP, KPS, KSU, KSP, KSS)

      IMPLICIT NONE
      INTEGER I, J, A, B, JELEM, KSTEP, KINC
      DOUBLE PRECISION WT, DETJ, DTIME
      DOUBLE PRECISION N(4), DNX(4), DNY(4), BU(3,8)
      DOUBLE PRECISION DE(8), PE(4), SE(4)
      DOUBLE PRECISION PW_OLD, SN_OLD, EPSV_OLD, PROPS(*)
      DOUBLE PRECISION RU(8), RP(4), RS(4)
      DOUBLE PRECISION KUU(8,8), KUP(8,4), KUS(8,4)
      DOUBLE PRECISION KPU(4,8), KPP(4,4), KPS(4,4)
      DOUBLE PRECISION KSU(4,8), KSP(4,4), KSS(4,4)
      DOUBLE PRECISION EPS_GP(3), EPSV_GP
      DOUBLE PRECISION PW_GP, GPW(2), SN_GP, GSN(2)
      DOUBLE PRECISION SW_GP, PC_GP, KRW_GP, KRN_GP, PEQ_GP
      DOUBLE PRECISION SE_RAW, SE_CLAMP, DS, CHI, DCHI_DSN, DSE_DSN
      DOUBLE PRECISION PHI_GP, KABS_GP, CF_GP
      DOUBLE PRECISION SIGEFF_GP(3), DTAN(3,3)
      DOUBLE PRECISION DPC_DSN, D2PC_DSN2, DKRW_DSN, DKRN_DSN
      DOUBLE PRECISION KRW_FLOW, KRN_FLOW
      DOUBLE PRECISION DKRW_DSN_FLOW, DKRN_DSN_FLOW
      DOUBLE PRECISION SW_MOB_OLD, PC_MOB_OLD, KRW_MOB_OLD
      DOUBLE PRECISION KRN_MOB_OLD, PEQ_MOB_OLD
      DOUBLE PRECISION DPC_DSN_MOB_OLD, DKRW_DSN_MOB_OLD
      DOUBLE PRECISION DKRN_DSN_MOB_OLD, DPEQ_DPW_MOB_OLD
      DOUBLE PRECISION DPEQ_DSN_MOB_OLD
      DOUBLE PRECISION MOB_SE_RAW_OLD, MOB_SE_CLAMP_OLD
      DOUBLE PRECISION MOB_DS_OLD, MOB_CHI_OLD
      DOUBLE PRECISION MOB_DCHI_OLD, MOB_DSE_OLD
      DOUBLE PRECISION DPEQ_DPW, DPEQ_DSN
      DOUBLE PRECISION PC_SECOND_BRANCH_DISTANCE
      DOUBLE PRECISION DSN_GP_DSN, SN_KIN_BRANCH_DISTANCE
      DOUBLE PRECISION DK_DSIGE, DK_DCF, DCF_DSIGE
      DOUBLE PRECISION DK_DU(8)
      DOUBLE PRECISION PW_ANCHOR_REF, SN_ANCHOR_REF, Y_SPAN_ANCHOR
      DOUBLE PRECISION SV_DUMMY(12)
      DOUBLE PRECISION DBG_RU8_CXX, DBG_RU8_CYY, DBG_RU8_CXY
      DOUBLE PRECISION DBG_RU8_CTOT, DBG_K88_GP
      DOUBLE PRECISION DBG_SUM_RU8_CXX, DBG_SUM_RU8_CYY, DBG_SUM_RU8_CXY
      DOUBLE PRECISION DBG_SUM_RU8_CTOT, DBG_SUM_K88_GP
      CHARACTER*32 DBG_PROBE_TAG
      LOGICAL DBG_S2_DETAIL
      LOGICAL DBG_MECH_FILE
      INTEGER DBG_GP_COUNT
      INTEGER RU_PEQ_USE_OK, RU_SIGEFF_OK, RU_FINAL_OK
      INTEGER CP164_RP_RES_TERM_OK
      INTEGER CP164_RP_PRESS_GRAD_TERM_OK
      INTEGER CP164_RP_MOBILITY_FLUX_TERM_OK
      INTEGER CP164_RS_RES_TERM_OK
      INTEGER CP164_RS_SAT_FLUX_TERM_OK
      INTEGER CP164_RU_SIG_TERM_OK
      INTEGER CP164_RU_PEQ_TERM_OK
      INTEGER CP164_PEQ_FORCE_TERM_OK
      INTEGER CP164_KABS_PERM_TERM_OK
      INTEGER CP165_RP_ENTER_TMP, CP165_RP_EXIT_TMP
      INTEGER CP165_RS_ENTER_TMP, CP165_RS_EXIT_TMP
      INTEGER CP165_RU_ENTER_TMP, CP165_RU_EXIT_TMP
      INTEGER CP165_RP_DUMMY_TMP, CP165_RS_DUMMY_TMP
      INTEGER CP165_RU_DUMMY_TMP
      INTEGER PC_SECOND_BRANCH_ID, PC_SECOND_SWITCH_FLAG
      INTEGER SN_KIN_BRANCH_ID, SN_KIN_SWITCH_FLAG
      SAVE DBG_GP_COUNT
      DATA DBG_GP_COUNT /0/

      CALL UPS_ZERO_VEC(RU,8)
      CALL UPS_ZERO_VEC(RP,4)
      CALL UPS_ZERO_VEC(RS,4)
      CALL UPS_ZERO_MAT(KUU,8,8)
      CALL UPS_ZERO_MAT(KUP,8,4)
      CALL UPS_ZERO_MAT(KUS,8,4)
      CALL UPS_ZERO_MAT(KPU,4,8)
      CALL UPS_ZERO_MAT(KPP,4,4)
      CALL UPS_ZERO_MAT(KPS,4,4)
      CALL UPS_ZERO_MAT(KSU,4,8)
      CALL UPS_ZERO_MAT(KSP,4,4)
      CALL UPS_ZERO_MAT(KSS,4,4)
      CALL UPS_WP10I3_ZERO_KSS_AUDIT()

      CALL UPS_KINEM_U(DE, DNX, DNY, BU, EPS_GP, EPSV_GP)
      CALL UPS_KINEM_PW(PE, N, DNX, DNY, PW_GP, GPW)
      CALL UPS_KINEM_SN(SE, N, DNX, DNY, SN_GP, GSN,
     1     DSN_GP_DSN, SN_KIN_BRANCH_ID,
     2     SN_KIN_BRANCH_DISTANCE, SN_KIN_SWITCH_FLAG)

      DBG_MECH_FILE = .FALSE.
      CALL UPS_TWOPHASE_CLOSURE(PW_GP, SN_GP, PROPS,
     1     SW_GP, PC_GP, KRW_GP, KRN_GP, PEQ_GP,
     2     DPC_DSN, DKRW_DSN, DKRN_DSN,
     3     DPEQ_DPW, DPEQ_DSN, DBG_MECH_FILE,
     4     SE_RAW, SE_CLAMP, DS, CHI, DCHI_DSN, DSE_DSN)
      CALL UPS_PC_SECOND_DERIVATIVE(SN_GP, PROPS,
     1     D2PC_DSN2, PC_SECOND_BRANCH_ID,
     2     PC_SECOND_BRANCH_DISTANCE, PC_SECOND_SWITCH_FLAG)
      CALL GET_ENVIRONMENT_VARIABLE('DBG_MECH_PROBE_TAG', DBG_PROBE_TAG)
      DBG_S2_DETAIL = (DBG_PROBE_TAG(1:2) .EQ. 'S2')
      DBG_MECH_FILE = (JELEM .EQ. 1 .AND. KSTEP .EQ. 2 .AND.
     1                 KINC .EQ. 1)

      SV_DUMMY(1)  = PW_OLD
      SV_DUMMY(2)  = SN_OLD
      SV_DUMMY(3)  = 0.0D0
      SV_DUMMY(4)  = 0.0D0
      SV_DUMMY(5)  = 0.0D0
      SV_DUMMY(6)  = EPSV_OLD
      SV_DUMMY(7)  = 0.0D0
      SV_DUMMY(8)  = 0.0D0
      SV_DUMMY(9)  = 0.0D0
      SV_DUMMY(10) = 0.0D0
      SV_DUMMY(11) = 0.0D0
      SV_DUMMY(12) = 0.0D0

      CALL UPS_MECH_CONSTITUTIVE(EPS_GP, PROPS,
     1     SIGEFF_GP, DTAN)

      CALL UPS_RESERVOIR_UPDATE(EPSV_GP, PEQ_GP, SIGEFF_GP, PROPS,
     1     PHI_GP, KABS_GP, CF_GP, DK_DSIGE, DK_DCF, DCF_DSIGE)
      CALL UPS_KABS_SIGMA_TO_U(DK_DSIGE, DTAN, BU, DK_DU)

      CP164_RP_RES_TERM_OK = 0
      CP164_RP_PRESS_GRAD_TERM_OK = 0
      CP164_RP_MOBILITY_FLUX_TERM_OK = 0
      CP164_RS_RES_TERM_OK = 0
      CP164_RS_SAT_FLUX_TERM_OK = 0
      CP164_RU_SIG_TERM_OK = 0
      CP164_RU_PEQ_TERM_OK = 0
      CP164_PEQ_FORCE_TERM_OK = 0
      CP164_KABS_PERM_TERM_OK = 0
      CP165_RP_ENTER_TMP = 0
      CP165_RP_EXIT_TMP = 0
      CP165_RS_ENTER_TMP = 0
      CP165_RS_EXIT_TMP = 0
      CP165_RU_ENTER_TMP = 0
      CP165_RU_EXIT_TMP = 0
      CP165_RP_DUMMY_TMP = 0
      CP165_RS_DUMMY_TMP = 0
      CP165_RU_DUMMY_TMP = 0

      CALL UPS_ASSEMBLE_RU_KU(WT, DETJ, BU,
     1     SIGEFF_GP, SIGEFF_GP, DTAN,
     2     PEQ_GP, PW_GP, SN_GP, PC_GP,
     3     PEQ_GP, PW_GP, SN_GP, PC_GP, PEQ_GP-PW_GP, 1.0D0,
     4     DPEQ_DPW, DPEQ_DSN,
     5     GPW, GSN, KABS_GP, KRW_GP, KRN_GP, DPC_DSN,
     6     0.0D0, 0.0D0, N, PROPS,
     7     JELEM, KSTEP, KINC, DBG_GP_COUNT, 1,
     8     RU, KUU, KUP, KUS,
     9     RU_PEQ_USE_OK, RU_SIGEFF_OK, RU_FINAL_OK,
     1     CP164_RU_SIG_TERM_OK, CP164_RU_PEQ_TERM_OK,
     2     CP164_PEQ_FORCE_TERM_OK,
     3     CP165_RU_ENTER_TMP, CP165_RU_EXIT_TMP,
     4     CP165_RU_DUMMY_TMP)
      CALL UPS_ASSEMBLE_RP_KP(WT, DETJ, DTIME,
     1     JELEM, KSTEP, KINC,
     2     N, DNX, DNY, BU,
     3     PW_GP, PW_OLD, GPW, PW_ANCHOR_REF,
     4     EPSV_GP, EPSV_OLD,
     5     KABS_GP, DK_DU, KRW_GP, DKRW_DSN, PROPS,
     6     RP, KPU, KPP, KPS,
     7     CP164_RP_RES_TERM_OK,
     8     CP164_RP_PRESS_GRAD_TERM_OK,
     9     CP164_RP_MOBILITY_FLUX_TERM_OK,
     1     CP164_KABS_PERM_TERM_OK,
     2     CP165_RP_ENTER_TMP, CP165_RP_EXIT_TMP,
     3     CP165_RP_DUMMY_TMP)
      CALL UPS_ASSEMBLE_RS_KS(WT, DETJ, DTIME,
     1     JELEM, KSTEP, KINC,
     2     N, DNX, DNY, BU,
     3     GPW, SN_ANCHOR_REF,
     4     SN_GP, SN_OLD, GSN, DSN_GP_DSN,
     5     EPSV_GP, EPSV_OLD,
     6     PHI_GP, KABS_GP, DK_DU, KRN_GP,
     7     DPC_DSN, D2PC_DSN2, DKRN_DSN, PROPS,
     8     RS, KSU, KSP, KSS,
     9     CP164_RS_RES_TERM_OK,
     1     CP164_RS_SAT_FLUX_TERM_OK,
     2     CP164_KABS_PERM_TERM_OK,
     3     CP165_RS_ENTER_TMP, CP165_RS_EXIT_TMP,
     4     CP165_RS_DUMMY_TMP)

C ---- r1b Newton diagnostic on the fully assembled mechanical block.
C This is enabled only when the harness sets DBG_NEWTON_DIAG=1.
      RETURN
      END


C ================================================================
C Jacobian / block consistency check at one Gauss point
C ================================================================
      SUBROUTINE UPS_JACOBIAN_CHECK_GAUSS(WT, DETJ, DTIME,
     1 JELEM, KSTEP, KINC, IGP,
     2 N, DNX, DNY, BU, DE, PE, SE,
     3 PW_OLD, SN_OLD, EPSV_OLD, PROPS)

      IMPLICIT NONE
      INTEGER I, J, JELEM, KSTEP, KINC, IGP
      DOUBLE PRECISION WT, DETJ, DTIME
      DOUBLE PRECISION N(4), DNX(4), DNY(4), BU(3,8)
      DOUBLE PRECISION DE(8), PE(4), SE(4)
      DOUBLE PRECISION PW_OLD, SN_OLD, EPSV_OLD, PROPS(*)
      RETURN
      END


C ================================================================
C Helper: maximum absolute value of a dense matrix block
C ================================================================
C This utility is used by the block-level debug checks to quickly tell
C whether a block is truly zero or just small but nonzero.
      SUBROUTINE UPS_MAT_MAXABS(A, NROW, NCOL, AMAX)
      IMPLICIT NONE
      INTEGER NROW, NCOL, I, J
      DOUBLE PRECISION A(NROW,NCOL), AMAX, TMP

      AMAX = 0.0D0
      DO I = 1, NROW
         DO J = 1, NCOL
            TMP = DABS(A(I,J))
            IF (TMP .GT. AMAX) AMAX = TMP
         END DO
      END DO

      RETURN
      END


C ================================================================
C Helper: Frobenius norm of a dense matrix block
C ================================================================
C The Frobenius norm is a compact one-number summary of the overall
C block magnitude and is useful for comparing coupling strengths.
      SUBROUTINE UPS_MAT_FROBNORM(A, NROW, NCOL, FNORM)
      IMPLICIT NONE
      INTEGER NROW, NCOL, I, J
      DOUBLE PRECISION A(NROW,NCOL), FNORM, SUMSQ

      SUMSQ = 0.0D0
      DO I = 1, NROW
         DO J = 1, NCOL
            SUMSQ = SUMSQ + A(I,J)*A(I,J)
         END DO
      END DO

      FNORM = DSQRT(SUMSQ)

      RETURN
      END


C ================================================================
C Helper: near-zero test for a dense matrix block
C ================================================================
C ISZERO = 1 means the block is numerically close to zero according to
C the supplied tolerance; ISZERO = 0 means at least one entry exceeds
C the tolerance.
      SUBROUTINE UPS_MAT_IS_ZERO(A, NROW, NCOL, TOL, ISZERO)
      IMPLICIT NONE
      INTEGER NROW, NCOL, I, J, ISZERO
      DOUBLE PRECISION A(NROW,NCOL), TOL

      ISZERO = 1
      DO I = 1, NROW
         DO J = 1, NCOL
            IF (DABS(A(I,J)) .GT. TOL) THEN
               ISZERO = 0
               RETURN
            END IF
         END DO
      END DO

      RETURN
      END


C ================================================================
C Helper: print standardized statistics for a matrix block
C ================================================================
C The routine prints the block name, the active element/increment, the
C max-abs value, the Frobenius norm and the near-zero flag. This keeps
C debug output consistent across all blocks.
      SUBROUTINE UPS_PRINT_BLOCK_STATS(BNAME, A, NROW, NCOL, TOL,
     1 JELEM, KSTEP, KINC)
      IMPLICIT NONE
      CHARACTER*(*) BNAME
      INTEGER NROW, NCOL, JELEM, KSTEP, KINC, ISZERO
      DOUBLE PRECISION A(NROW,NCOL), TOL, AMAX, FNORM

      CALL UPS_MAT_MAXABS(A, NROW, NCOL, AMAX)
      CALL UPS_MAT_FROBNORM(A, NROW, NCOL, FNORM)
      CALL UPS_MAT_IS_ZERO(A, NROW, NCOL, TOL, ISZERO)

      WRITE(*,*) '---------------------------------------------'
      WRITE(*,*) 'BLOCK = ', BNAME
      WRITE(*,*) 'JELEM = ', JELEM, ' KSTEP = ', KSTEP, ' KINC = ', KINC
      WRITE(*,*) 'MAXABS = ', AMAX
      WRITE(*,*) 'FNORM  = ', FNORM
      WRITE(*,*) 'ISZERO = ', ISZERO
      WRITE(*,*) '---------------------------------------------'

      RETURN
      END


C ================================================================
C Helper: build block index maps
C ================================================================
C This mapping is one of the most important design decisions in the
C skeleton. It converts the field-block view used in the formulation
C into the node-major ordering used by Abaqus.
C
C Keep this routine small and explicit so the node/block mapping can be
C audited quickly during future debugging or refactoring.
      SUBROUTINE UPS_BUILD_INDEX(IU, IP, IS)
      IMPLICIT NONE
      INTEGER IU(8), IP(4), IS(4)

      IU(1)=1
      IU(2)=2
      IU(3)=5
      IU(4)=6
      IU(5)=9
      IU(6)=10
      IU(7)=13
      IU(8)=14

      IP(1)=3
      IP(2)=7
      IP(3)=11
      IP(4)=15

      IS(1)=4
      IS(2)=8
      IS(3)=12
      IS(4)=16

      RETURN
      END


C ================================================================
C Helper: zero vector
C ================================================================
C Small utility routines keep the main UEL body compact and make the
C later transition to larger helper libraries easier.
C
C These helpers are intentionally trivial, but keeping them separate
C makes the main routine much easier to read.
      SUBROUTINE UPS_ZERO_VEC(X, N)
      IMPLICIT NONE
      INTEGER N, I
      DOUBLE PRECISION X(N)

      DO I = 1, N
         X(I) = 0.0D0
      END DO

      RETURN
      END


C ================================================================
C Helper: zero matrix
C ================================================================
C The explicit loops make the initialization behaviour obvious and
C avoid any hidden assumptions about compiler-specific array utilities.
      SUBROUTINE UPS_ZERO_MAT(A, NROW, NCOL)
      IMPLICIT NONE
      INTEGER NROW, NCOL, I, J
      DOUBLE PRECISION A(NROW,NCOL)

      DO I = 1, NROW
         DO J = 1, NCOL
            A(I,J) = 0.0D0
         END DO
      END DO

      RETURN
      END


C ================================================================
C Helper: zero RHS
C ================================================================
C RHS is initialized separately because Abaqus passes it as a 2D array
C with the leading dimension MLVARX, not as a flat 1D vector.
C
C The copy routines later in the file mirror this storage layout.
      SUBROUTINE UPS_ZERO_RHS(RHS, MLVARX, NRHS)
      IMPLICIT NONE
      INTEGER MLVARX, NRHS, I, J
      DOUBLE PRECISION RHS(MLVARX,NRHS)

      DO I = 1, MLVARX
         DO J = 1, NRHS
            RHS(I,J) = 0.0D0
         END DO
      END DO

      RETURN
      END


C ================================================================
C Unpack local DOFs
C U = [ux1 uy1 pw1 sn1 ux2 uy2 pw2 sn2 ...]
C ================================================================
C This routine is the bridge between the solver ordering and the
C formulation ordering. It is intentionally simple and explicit so
C future reviewers can immediately see the DOF mapping.
C
C If the local DOF ordering changes in a later version, this is one of
C the first routines that must be updated.
      SUBROUTINE UPS_UNPACK_DOF(U, DE, PE, SE)
      IMPLICIT NONE
      INTEGER I, K
      DOUBLE PRECISION U(16), DE(8), PE(4), SE(4)

      DO I = 1, 4
         K = 4*(I-1)
         DE(2*I-1) = U(K+1)
         DE(2*I  ) = U(K+2)
         PE(I)     = U(K+3)
         SE(I)     = U(K+4)
      END DO

      RETURN
      END


C ================================================================
C 2x2 Gauss points for Q4
C ================================================================
C The Gauss-point locations are hard-coded for the first skeleton.
C Later versions can replace this with a more general quadrature rule
C if higher-order integration is ever needed.
C
C The current choice is the standard 2x2 rule for a bilinear quad.
      SUBROUTINE UPS_GAUSS_Q4(IGP, XI, ETA, WT)
      IMPLICIT NONE
      INTEGER IGP
      DOUBLE PRECISION XI, ETA, WT
      DOUBLE PRECISION A
      PARAMETER (A=0.5773502691896258D0)

      WT = 1.0D0

      IF (IGP .EQ. 1) THEN
         XI  = -A
         ETA = -A
      ELSEIF (IGP .EQ. 2) THEN
         XI  =  A
         ETA = -A
      ELSEIF (IGP .EQ. 3) THEN
         XI  =  A
         ETA =  A
      ELSE
         XI  = -A
         ETA =  A
      ENDIF

      RETURN
      END


C ================================================================
C Shape functions for Q4
C ================================================================
C Standard bilinear Q4 interpolation in the parent element space.
C The derivatives returned here are with respect to xi and eta only.
C
C This routine should remain purely geometric and never carry any
C material-state logic.
      SUBROUTINE UPS_SHAPE_Q4(XI, ETA, N, DNXI, DNETA)
      IMPLICIT NONE
      DOUBLE PRECISION XI, ETA, N(4), DNXI(4), DNETA(4)

      N(1) = 0.25D0*(1.0D0-XI )*(1.0D0-ETA)
      N(2) = 0.25D0*(1.0D0+XI )*(1.0D0-ETA)
      N(3) = 0.25D0*(1.0D0+XI )*(1.0D0+ETA)
      N(4) = 0.25D0*(1.0D0-XI )*(1.0D0+ETA)

      DNXI(1)  = -0.25D0*(1.0D0-ETA)
      DNXI(2)  =  0.25D0*(1.0D0-ETA)
      DNXI(3)  =  0.25D0*(1.0D0+ETA)
      DNXI(4)  = -0.25D0*(1.0D0+ETA)

      DNETA(1) = -0.25D0*(1.0D0-XI)
      DNETA(2) = -0.25D0*(1.0D0+XI)
      DNETA(3) =  0.25D0*(1.0D0+XI)
      DNETA(4) =  0.25D0*(1.0D0-XI)

      RETURN
      END


C ================================================================
C Jacobian and dN/dx, dN/dy
C ================================================================
C This routine maps the parent-domain derivatives to the physical
C coordinates of the current element. Every later field calculation
C depends on these global derivatives.
C
C In the final UEL, this is the routine that guards against badly
C distorted elements via DETJ checks.
      SUBROUTINE UPS_JACOBIAN_Q4(COORDS, MCRD, NNODE, DNXI, DNETA,
     1                           JMAT, INVJ, DETJ, DNX, DNY)
      IMPLICIT NONE
      INTEGER MCRD, NNODE, I
      DOUBLE PRECISION COORDS(MCRD,NNODE), DNXI(4), DNETA(4)
      DOUBLE PRECISION JMAT(2,2), INVJ(2,2), DETJ, DNX(4), DNY(4)

      JMAT(1,1) = 0.0D0
      JMAT(1,2) = 0.0D0
      JMAT(2,1) = 0.0D0
      JMAT(2,2) = 0.0D0

      DO I = 1, 4
         JMAT(1,1) = JMAT(1,1) + DNXI(I )*COORDS(1,I)
         JMAT(1,2) = JMAT(1,2) + DNXI(I )*COORDS(2,I)
         JMAT(2,1) = JMAT(2,1) + DNETA(I)*COORDS(1,I)
         JMAT(2,2) = JMAT(2,2) + DNETA(I)*COORDS(2,I)
      END DO

      DETJ = JMAT(1,1)*JMAT(2,2) - JMAT(1,2)*JMAT(2,1)

      IF (DABS(DETJ) .LT. 1.0D-20) DETJ = 1.0D-20

      INVJ(1,1) =  JMAT(2,2)/DETJ
      INVJ(1,2) = -JMAT(1,2)/DETJ
      INVJ(2,1) = -JMAT(2,1)/DETJ
      INVJ(2,2) =  JMAT(1,1)/DETJ

      DO I = 1, 4
         DNX(I) = INVJ(1,1)*DNXI(I) + INVJ(1,2)*DNETA(I)
         DNY(I) = INVJ(2,1)*DNXI(I) + INVJ(2,2)*DNETA(I)
      END DO

      RETURN
      END


C ================================================================
C Kinematics for displacement
C ================================================================
C Build the displacement-strain operator and evaluate the engineering
C strain vector at the current Gauss point.
C
C The current implementation is linear and small-strain; the comment
C is left here so later upgrades can replace it with a finite-strain
C variant if needed.
      SUBROUTINE UPS_KINEM_U(DE, DNX, DNY, BU, EPS_GP, EPSV_GP)
      IMPLICIT NONE
      INTEGER I
      DOUBLE PRECISION DE(8), DNX(4), DNY(4)
      DOUBLE PRECISION BU(3,8), EPS_GP(3), EPSV_GP

      CALL UPS_ZERO_MAT(BU,3,8)

      DO I = 1, 4
         BU(1,2*I-1) = DNX(I)
         BU(2,2*I  ) = DNY(I)
         BU(3,2*I-1) = DNY(I)
         BU(3,2*I  ) = DNX(I)
      END DO

      EPS_GP(1) = 0.0D0
      EPS_GP(2) = 0.0D0
      EPS_GP(3) = 0.0D0

      DO I = 1, 8
         EPS_GP(1) = EPS_GP(1) + BU(1,I)*DE(I)
         EPS_GP(2) = EPS_GP(2) + BU(2,I)*DE(I)
         EPS_GP(3) = EPS_GP(3) + BU(3,I)*DE(I)
      END DO

      EPSV_GP = EPS_GP(1) + EPS_GP(2)

      RETURN
      END


C ================================================================
C Kinematics for pw
C ================================================================
C Interpolate the wetting-phase pressure field and compute its spatial
C gradient. The gradient is needed by Darcy-type transport terms.
C
C This routine deliberately does not apply any constitutive law; it
C only performs interpolation and differentiation.
      SUBROUTINE UPS_KINEM_PW(PE, N, DNX, DNY, PW_GP, GPW)
      IMPLICIT NONE
      INTEGER I
      DOUBLE PRECISION PE(4), N(4), DNX(4), DNY(4)
      DOUBLE PRECISION PW_GP, GPW(2)

      PW_GP = 0.0D0
      GPW(1)= 0.0D0
      GPW(2)= 0.0D0

      DO I = 1, 4
         PW_GP  = PW_GP  + N(I)*PE(I)
         GPW(1) = GPW(1) + DNX(I)*PE(I)
         GPW(2) = GPW(2) + DNY(I)*PE(I)
      END DO

      RETURN
      END


C ================================================================
C Kinematics for Sn
C ================================================================
C Interpolate the non-wetting saturation field and compute its spatial
C gradient. The clamping here is only a first-stage safeguard and is
C not a substitute for a proper constitutive bound enforcement.
C
C The clamping is a numerical safeguard only. The real two-phase model
C should enforce admissible saturation through the constitutive update.
      SUBROUTINE UPS_KINEM_SN(SE, N, DNX, DNY, SN_GP, GSN,
     1 DSN_GP_DSN, BRANCH_ID, BRANCH_DISTANCE, SWITCH_FLAG)
      IMPLICIT NONE
      INTEGER I, BRANCH_ID, SWITCH_FLAG
      DOUBLE PRECISION SE(4), N(4), DNX(4), DNY(4)
      DOUBLE PRECISION SN_GP, GSN(2), DSN_GP_DSN
      DOUBLE PRECISION SN_GP_RAW, BRANCH_DISTANCE

      SN_GP = 0.0D0
      GSN(1)= 0.0D0
      GSN(2)= 0.0D0

      DO I = 1, 4
         SN_GP  = SN_GP  + N(I)*SE(I)
         GSN(1) = GSN(1) + DNX(I)*SE(I)
         GSN(2) = GSN(2) + DNY(I)*SE(I)
      END DO

      SN_GP_RAW = SN_GP
      DSN_GP_DSN = 1.0D0
      BRANCH_ID = 0
      SWITCH_FLAG = 0
      BRANCH_DISTANCE = DMIN1(DABS(SN_GP_RAW),
     1                               DABS(SN_GP_RAW-1.0D0))
      IF (SN_GP_RAW .EQ. 0.0D0 .OR.
     1    SN_GP_RAW .EQ. 1.0D0) SWITCH_FLAG = 1
      IF (SN_GP_RAW .LT. 0.0D0) THEN
         DSN_GP_DSN = 0.0D0
         BRANCH_ID = 1
         BRANCH_DISTANCE = DABS(SN_GP_RAW)
      END IF
      IF (SN_GP_RAW .GT. 1.0D0) THEN
         DSN_GP_DSN = 0.0D0
         BRANCH_ID = 2
         BRANCH_DISTANCE = DABS(SN_GP_RAW-1.0D0)
      END IF

      IF (SN_GP .LT. 0.0D0) SN_GP = 0.0D0
      IF (SN_GP .GT. 1.0D0) SN_GP = 1.0D0

      RETURN
      END


C ================================================================
C Two-phase closure: modified Brooks-Corey + Corey + peq weighting
C ================================================================
C This version keeps the algebra compact and the derivatives explicit.
C The effective saturation is clamped to avoid singular behaviour near
C the endpoints. When clamped, the derivative is frozen to zero so the
C tangent remains numerically stable.
      SUBROUTINE UPS_TWOPHASE_CLOSURE(PW_GP, SN_GP, PROPS,
     1 SW_GP, PC_GP, KRW_GP, KRN_GP, PEQ_GP,
     2 DPC_DSN, DKRW_DSN, DKRN_DSN,
     3 DPEQ_DPW, DPEQ_DSN, DBG_SRC_PRINT,
     4 SE_RAW_OUT, SE_CLAMP_OUT, DS_OUT, CHI_OUT,
     5 DCHI_DSN_OUT, DSE_DSN_OUT)

      IMPLICIT NONE
      DOUBLE PRECISION PW_GP, SN_GP, PROPS(*)
      DOUBLE PRECISION SW_GP, PC_GP, KRW_GP, KRN_GP, PEQ_GP
      DOUBLE PRECISION DPC_DSN, DKRW_DSN, DKRN_DSN
      DOUBLE PRECISION DPEQ_DPW, DPEQ_DSN
      DOUBLE PRECISION SE_RAW_OUT, SE_CLAMP_OUT, DS_OUT
      DOUBLE PRECISION CHI_OUT, DCHI_DSN_OUT, DSE_DSN_OUT
      LOGICAL DBG_SRC_PRINT
      DOUBLE PRECISION DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG
      DOUBLE PRECISION DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX
      DOUBLE PRECISION DBG_SE_MIN, DBG_SN_SEED
      DOUBLE PRECISION DBG_P_REG_SCALE, DBG_S_REG_SCALE
      DOUBLE PRECISION DBG_GUARD_NONFINITE
      DOUBLE PRECISION DBG_LOC_MINIMAL
      DOUBLE PRECISION DBG_FIELD_CAPACITY_REG
      DOUBLE PRECISION DBG_FIELD_CAPACITY_ETA
      DOUBLE PRECISION DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG
      DOUBLE PRECISION DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA
      DOUBLE PRECISION DBG_FIELD_ANCHOR_REG
      DOUBLE PRECISION DBG_FIELD_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG
      DOUBLE PRECISION DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM
      DOUBLE PRECISION DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF
      DOUBLE PRECISION DBG_AUDIT_MODE_CODE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      COMMON /UPS_DIAG_CTRL/ DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG,
     1 DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX, DBG_SE_MIN,
     2 DBG_SN_SEED, DBG_P_REG_SCALE, DBG_S_REG_SCALE,
     3 DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL,
     4 DBG_FIELD_CAPACITY_REG, DBG_FIELD_CAPACITY_ETA,
     5 DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG,
     6 DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA,
     7 DBG_FIELD_ANCHOR_REG, DBG_FIELD_ANCHOR_ETA,
     8 DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG,
     9 DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA,
     1 DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM,
     2 DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF,
     3 DBG_AUDIT_MODE_CODE,
     4 DBG_FIELD_CAPACITY_AUDIT_RP_DONE,
     5 DBG_FIELD_CAPACITY_AUDIT_RS_DONE,
     6 DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP,
     7 DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP,
     8 DBG_FIELD_ANCHOR_AUDIT_RP_DONE,
     9 DBG_FIELD_ANCHOR_AUDIT_RS_DONE,
     1 DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP,
     2 DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP

      DOUBLE PRECISION SWR, SNR, PB, LAMBDA_BC, NW, NN
      DOUBLE PRECISION DS, SE_RAW, SE, SE_EPS, SN_USE
      DOUBLE PRECISION DSE_DSN
      DOUBLE PRECISION CHI, DCHI_DSN
      DOUBLE PRECISION PEQ_FROM_PC
      DOUBLE PRECISION DBG_PC_SLOPE_CAP_REG
      DOUBLE PRECISION DBG_PC_SLOPE_CAP_MAX
      DOUBLE PRECISION DBG_PC_CAP_MAX
      CHARACTER*32 DBG_PC_SLOPE_CAP_REG_TAG
      CHARACTER*32 DBG_PC_SLOPE_CAP_MAX_TAG
      CHARACTER*32 DBG_PC_CAP_MAX_TAG
      INTEGER IOS_PC_SLOPE_CAP

C --- read closure parameters
      SWR       = PROPS(8)
      SNR       = PROPS(9)
      PB        = PROPS(10)
      LAMBDA_BC = PROPS(11)
      NW        = PROPS(12)
      NN        = PROPS(13)

C --- optional closure regularization for front diagnostics.  This is
C     disabled by default and is intended to isolate endpoint PC jumps.
      DBG_PC_SLOPE_CAP_REG = 0.0D0
      DBG_PC_SLOPE_CAP_MAX = 1.0D99
      DBG_PC_CAP_MAX = 1.0D99
      CALL GET_ENVIRONMENT_VARIABLE('DBG_PC_SLOPE_CAP_REG',
     1                              DBG_PC_SLOPE_CAP_REG_TAG)
      IF (LEN_TRIM(DBG_PC_SLOPE_CAP_REG_TAG) .GT. 0) THEN
         READ(DBG_PC_SLOPE_CAP_REG_TAG,*,IOSTAT=IOS_PC_SLOPE_CAP)
     1        DBG_PC_SLOPE_CAP_REG
         IF (IOS_PC_SLOPE_CAP .NE. 0) DBG_PC_SLOPE_CAP_REG = 0.0D0
      END IF
      CALL GET_ENVIRONMENT_VARIABLE('DBG_PC_SLOPE_CAP_MAX',
     1                              DBG_PC_SLOPE_CAP_MAX_TAG)
      IF (LEN_TRIM(DBG_PC_SLOPE_CAP_MAX_TAG) .GT. 0) THEN
         READ(DBG_PC_SLOPE_CAP_MAX_TAG,*,IOSTAT=IOS_PC_SLOPE_CAP)
     1        DBG_PC_SLOPE_CAP_MAX
         IF (IOS_PC_SLOPE_CAP .NE. 0) DBG_PC_SLOPE_CAP_MAX = 1.0D99
      END IF
      CALL GET_ENVIRONMENT_VARIABLE('DBG_PC_CAP_MAX',
     1                              DBG_PC_CAP_MAX_TAG)
      IF (LEN_TRIM(DBG_PC_CAP_MAX_TAG) .GT. 0) THEN
         READ(DBG_PC_CAP_MAX_TAG,*,IOSTAT=IOS_PC_SLOPE_CAP)
     1        DBG_PC_CAP_MAX
         IF (IOS_PC_SLOPE_CAP .NE. 0) DBG_PC_CAP_MAX = 1.0D99
      END IF
      IF (DBG_PC_SLOPE_CAP_MAX .LT. 0.0D0)
     1   DBG_PC_SLOPE_CAP_MAX = DABS(DBG_PC_SLOPE_CAP_MAX)
      IF (DBG_PC_CAP_MAX .LT. 0.0D0)
     1   DBG_PC_CAP_MAX = DABS(DBG_PC_CAP_MAX)

C --- numerical lower bound for effective saturation
      SE_EPS = DBG_SE_MIN
      SN_USE = SN_GP
      IF (SN_USE .NE. SN_USE) SN_USE = DBG_SN_SEED
      IF (DBG_SN_BOUNDS_ON .GT. 0.5D0) THEN
         IF (SN_USE .LT. DBG_SN_MIN) SN_USE = DBG_SN_MIN
         IF (SN_USE .GT. DBG_SN_MAX) SN_USE = DBG_SN_MAX
      END IF

C ============================================================
C 1. basic saturation quantities
C ============================================================
      SW_GP = 1.0D0 - SN_USE

      DS = 1.0D0 - SWR - SNR
      IF (DS .LE. 1.0D-12) DS = 1.0D-12

      SE_RAW = (SW_GP - SWR) / DS

C --- clamp Se and keep derivative consistent with clamping
      IF (SE_RAW .LE. SE_EPS) THEN
         SE      = SE_EPS
         DSE_DSN = 0.0D0
      ELSEIF (SE_RAW .GE. 1.0D0 - SE_EPS) THEN
         SE      = 1.0D0 - SE_EPS
         DSE_DSN = 0.0D0
      ELSE
         SE      = SE_RAW
         DSE_DSN = -1.0D0 / DS
      END IF
      SE_RAW_OUT   = SE_RAW
      SE_CLAMP_OUT = SE
      DS_OUT       = DS
      DSE_DSN_OUT  = DSE_DSN

C ============================================================
C 2. capillary pressure: modified Brooks-Corey
C    pc = pb * ( Se^(-1/lambda) - 1 )
C ============================================================
      PC_GP = PB * ( SE**(-1.0D0/LAMBDA_BC) - 1.0D0 )

      DPC_DSN = -(PB / LAMBDA_BC)
     1         * SE**(-1.0D0/LAMBDA_BC - 1.0D0)
     2         * DSE_DSN

      IF (DBG_PC_SLOPE_CAP_REG .GT. 0.5D0) THEN
         IF (PC_GP .GT. DBG_PC_CAP_MAX) PC_GP = DBG_PC_CAP_MAX
         IF (DPC_DSN .GT. DBG_PC_SLOPE_CAP_MAX)
     1      DPC_DSN = DBG_PC_SLOPE_CAP_MAX
         IF (DPC_DSN .LT. -DBG_PC_SLOPE_CAP_MAX)
     1      DPC_DSN = -DBG_PC_SLOPE_CAP_MAX
      END IF

C ============================================================
C 3. relative permeability: Corey type
C ============================================================
      KRW_GP = SE**NW
      KRN_GP = (1.0D0 - SE)**NN

      DKRW_DSN = NW * SE**(NW - 1.0D0) * DSE_DSN

      DKRN_DSN = -NN * (1.0D0 - SE)**(NN - 1.0D0) * DSE_DSN

C ============================================================
C 4. effective pore pressure
C    chi = 1 - Se
C    peq = pw + chi * pc
C ============================================================
      CHI      = 1.0D0 - SE
      DCHI_DSN = -DSE_DSN
      CHI_OUT      = CHI
      DCHI_DSN_OUT = DCHI_DSN

      PEQ_GP = PW_GP + CHI * PC_GP

      DPEQ_DPW = 1.0D0

      DPEQ_DSN = DCHI_DSN * PC_GP + CHI * DPC_DSN

      IF (DBG_SRC_PRINT) THEN
         PEQ_FROM_PC = PW_GP + CHI * PC_GP
         WRITE(*,*) '=== DBG_PEQ SOURCE ==='
         WRITE(*,*) 'PW_GP        = ', PW_GP
         WRITE(*,*) 'SN_GP        = ', SN_GP
         WRITE(*,*) 'SW_GP        = ', SW_GP
         WRITE(*,*) 'SE_RAW       = ', SE_RAW
         WRITE(*,*) 'SE_CLAMP     = ', SE
         WRITE(*,*) 'DS           = ', DS
         WRITE(*,*) 'CHI          = ', CHI
         WRITE(*,*) 'PC_GP        = ', PC_GP
         WRITE(*,*) 'PEQ_GP(raw)  = ', PEQ_GP
         WRITE(*,*) 'PEQ_FROM_PC  = ', PEQ_FROM_PC
         WRITE(*,*) 'DPEQ_DPW     = ', DPEQ_DPW
         WRITE(*,*) 'DPEQ_DSN     = ', DPEQ_DSN
         WRITE(*,*) 'DSE_DSN      = ', DSE_DSN
         WRITE(*,*) 'DCHI_DSN     = ', DCHI_DSN
         WRITE(*,*) 'DBG_GUARD_NONFINITE = ', DBG_GUARD_NONFINITE
         WRITE(*,*) 'DBG_SN_BOUNDS_ON    = ', DBG_SN_BOUNDS_ON
         WRITE(*,*) 'DBG_REG_P_DIAG      = ', DBG_REG_P_DIAG
         WRITE(*,*) 'DBG_REG_S_DIAG      = ', DBG_REG_S_DIAG
         WRITE(*,*) 'DBG_FIELD_CAPACITY_REG = ',
     1        DBG_FIELD_CAPACITY_REG
         WRITE(*,*) 'DBG_FIELD_CAPACITY_ETA = ',
     1        DBG_FIELD_CAPACITY_ETA
         WRITE(*,*) 'DBG_P_CAPACITY_REG     = ',
     1        DBG_P_CAPACITY_REG
         WRITE(*,*) 'DBG_P_CAPACITY_ETA     = ',
     1        DBG_P_CAPACITY_ETA
         WRITE(*,*) 'DBG_S_CAPACITY_REG     = ',
     1        DBG_S_CAPACITY_REG
         WRITE(*,*) 'DBG_S_CAPACITY_ETA     = ',
     1        DBG_S_CAPACITY_ETA
      END IF

      RETURN
      END


C ================================================================
C WP10-I3 derivative-only capillary second derivative.
C This mirrors the existing closure branch arithmetic without changing
C any closure value or first derivative returned to the UEL.
C ================================================================
      SUBROUTINE UPS_PC_SECOND_DERIVATIVE(SN_GP, PROPS,
     1 D2PC_DSN2, BRANCH_ID, BRANCH_DISTANCE, SWITCH_FLAG)
      IMPLICIT NONE
      INTEGER BRANCH_ID, SWITCH_FLAG
      DOUBLE PRECISION SN_GP, PROPS(*), D2PC_DSN2
      DOUBLE PRECISION BRANCH_DISTANCE
      DOUBLE PRECISION SWR, SNR, PB, LAMBDA_BC
      DOUBLE PRECISION DS, SE_RAW, SE, SE_EPS, SN_USE, DSE_DSN
      DOUBLE PRECISION DIST_LOW, DIST_HIGH
      DOUBLE PRECISION DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG
      DOUBLE PRECISION DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX
      DOUBLE PRECISION DBG_SE_MIN, DBG_SN_SEED
      DOUBLE PRECISION DBG_P_REG_SCALE, DBG_S_REG_SCALE
      DOUBLE PRECISION DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL
      DOUBLE PRECISION DBG_FIELD_CAPACITY_REG
      DOUBLE PRECISION DBG_FIELD_CAPACITY_ETA
      DOUBLE PRECISION DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG
      DOUBLE PRECISION DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA
      DOUBLE PRECISION DBG_FIELD_ANCHOR_REG
      DOUBLE PRECISION DBG_FIELD_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG
      DOUBLE PRECISION DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM
      DOUBLE PRECISION DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF
      DOUBLE PRECISION DBG_AUDIT_MODE_CODE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      COMMON /UPS_DIAG_CTRL/ DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG,
     1 DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX, DBG_SE_MIN,
     2 DBG_SN_SEED, DBG_P_REG_SCALE, DBG_S_REG_SCALE,
     3 DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL,
     4 DBG_FIELD_CAPACITY_REG, DBG_FIELD_CAPACITY_ETA,
     5 DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG,
     6 DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA,
     7 DBG_FIELD_ANCHOR_REG, DBG_FIELD_ANCHOR_ETA,
     8 DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG,
     9 DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA,
     1 DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM,
     2 DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF,
     3 DBG_AUDIT_MODE_CODE,
     4 DBG_FIELD_CAPACITY_AUDIT_RP_DONE,
     5 DBG_FIELD_CAPACITY_AUDIT_RS_DONE,
     6 DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP,
     7 DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP,
     8 DBG_FIELD_ANCHOR_AUDIT_RP_DONE,
     9 DBG_FIELD_ANCHOR_AUDIT_RS_DONE,
     1 DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP,
     2 DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP

      SWR = PROPS(8)
      SNR = PROPS(9)
      PB = PROPS(10)
      LAMBDA_BC = PROPS(11)
      SE_EPS = DBG_SE_MIN
      SN_USE = SN_GP
      IF (SN_USE .NE. SN_USE) SN_USE = DBG_SN_SEED
      IF (DBG_SN_BOUNDS_ON .GT. 0.5D0) THEN
         IF (SN_USE .LT. DBG_SN_MIN) SN_USE = DBG_SN_MIN
         IF (SN_USE .GT. DBG_SN_MAX) SN_USE = DBG_SN_MAX
      END IF

      DS = 1.0D0 - SWR - SNR
      IF (DS .LE. 1.0D-12) DS = 1.0D-12
      SE_RAW = (1.0D0-SN_USE-SWR) / DS
      DIST_LOW = DABS(SE_RAW-SE_EPS) * DS
      DIST_HIGH = DABS(SE_RAW-(1.0D0-SE_EPS)) * DS
      BRANCH_DISTANCE = DMIN1(DIST_LOW,DIST_HIGH)
      SWITCH_FLAG = 0

      IF (SE_RAW .LE. SE_EPS) THEN
         SE = SE_EPS
         DSE_DSN = 0.0D0
         D2PC_DSN2 = 0.0D0
         BRANCH_ID = 1
         IF (SE_RAW .EQ. SE_EPS) SWITCH_FLAG = 1
      ELSE IF (SE_RAW .GE. 1.0D0-SE_EPS) THEN
         SE = 1.0D0-SE_EPS
         DSE_DSN = 0.0D0
         D2PC_DSN2 = 0.0D0
         BRANCH_ID = 2
         IF (SE_RAW .EQ. 1.0D0-SE_EPS) SWITCH_FLAG = 1
      ELSE
         SE = SE_RAW
         DSE_DSN = -1.0D0 / DS
         D2PC_DSN2 = -(PB/LAMBDA_BC)
     1      * (-1.0D0/LAMBDA_BC-1.0D0)
     2      * SE**(-1.0D0/LAMBDA_BC-2.0D0)
     3      * DSE_DSN * DSE_DSN
         BRANCH_ID = 0
      END IF

      RETURN
      END


C ================================================================
C WP10-I3 exact branch derivative of the existing storage-use path.
C No persistent state is read or written.
C ================================================================
      SUBROUTINE UPS_EVAL_SN_RAW_USE_JET(SN_GP, SN_OLD,
     1 REG_ON, JUMP_TOL, BETA_MIN, SN_RAW_USE, RAW_BETA,
     2 DSN_RAW_USE_DSN, BRANCH_ID, BRANCH_DISTANCE, SWITCH_FLAG)
      IMPLICIT NONE
      INTEGER BRANCH_ID, SWITCH_FLAG
      DOUBLE PRECISION SN_GP, SN_OLD, REG_ON, JUMP_TOL, BETA_MIN
      DOUBLE PRECISION SN_RAW_USE, RAW_BETA, DSN_RAW_USE_DSN
      DOUBLE PRECISION BRANCH_DISTANCE
      DOUBLE PRECISION DELTA, ABS_DELTA, EPS_DEN, BETA_RATIO
      DOUBLE PRECISION DBETA_DSN, DIST_TOL, DIST_BETA

      EPS_DEN = 1.0D-30
      DELTA = SN_GP-SN_OLD
      ABS_DELTA = DABS(DELTA)
      RAW_BETA = 1.0D0
      DSN_RAW_USE_DSN = 1.0D0
      BRANCH_ID = 0
      BRANCH_DISTANCE = 1.0D99
      SWITCH_FLAG = 0

      IF (REG_ON .GT. 0.5D0) THEN
         DIST_TOL = DABS(ABS_DELTA-JUMP_TOL)
         BRANCH_DISTANCE = DIST_TOL
         BRANCH_ID = 1
         IF (ABS_DELTA .EQ. JUMP_TOL) SWITCH_FLAG = 1
         IF (ABS_DELTA .GT. JUMP_TOL) THEN
            BETA_RATIO = JUMP_TOL / (ABS_DELTA+EPS_DEN)
            RAW_BETA = BETA_RATIO
            IF (DELTA .GT. 0.0D0) THEN
               DBETA_DSN = -JUMP_TOL/(ABS_DELTA+EPS_DEN)**2
               BRANCH_ID = 2
            ELSE IF (DELTA .LT. 0.0D0) THEN
               DBETA_DSN = JUMP_TOL/(ABS_DELTA+EPS_DEN)**2
               BRANCH_ID = 3
            ELSE
               DBETA_DSN = 0.0D0
            END IF
            DSN_RAW_USE_DSN = RAW_BETA+DELTA*DBETA_DSN

            IF (BETA_MIN .GT. 0.0D0) THEN
               DIST_BETA = DABS(ABS_DELTA-JUMP_TOL/BETA_MIN)
               BRANCH_DISTANCE = DMIN1(DIST_TOL,DIST_BETA)
               IF (BETA_RATIO .EQ. BETA_MIN) SWITCH_FLAG = 2
            END IF
            IF (RAW_BETA .LT. BETA_MIN) THEN
               RAW_BETA = BETA_MIN
               DSN_RAW_USE_DSN = BETA_MIN
               IF (DELTA .GT. 0.0D0) THEN
                  BRANCH_ID = 4
               ELSE
                  BRANCH_ID = 5
               END IF
            END IF
            IF (RAW_BETA .GT. 1.0D0) THEN
               RAW_BETA = 1.0D0
               DSN_RAW_USE_DSN = 1.0D0
               BRANCH_ID = 6
            END IF
         END IF
      END IF

      SN_RAW_USE = SN_OLD+RAW_BETA*DELTA
      IF (SN_RAW_USE .EQ. 0.0D0 .OR.
     1    SN_RAW_USE .EQ. 1.0D0) SWITCH_FLAG = 3
      IF (SN_RAW_USE .LT. 0.0D0) THEN
         BRANCH_DISTANCE = DABS(SN_RAW_USE)
         SN_RAW_USE = 0.0D0
         DSN_RAW_USE_DSN = 0.0D0
         BRANCH_ID = 7
      END IF
      IF (SN_RAW_USE .GT. 1.0D0) THEN
         BRANCH_DISTANCE = DABS(SN_RAW_USE-1.0D0)
         SN_RAW_USE = 1.0D0
         DSN_RAW_USE_DSN = 0.0D0
         BRANCH_ID = 8
      END IF

      RETURN
      END


C ================================================================
C WP10-I3 nonphysical KSS term-audit storage.
C These arrays never enter residual, tangent, or SVARS evaluation.
C ================================================================
      SUBROUTINE UPS_WP10I3_ZERO_KSS_AUDIT()
      IMPLICIT NONE
      DOUBLE PRECISION WP10I3_KSS_STORAGE(4,4)
      DOUBLE PRECISION WP10I3_KSS_STRAIN(4,4)
      DOUBLE PRECISION WP10I3_KSS_MOBILITY(4,4)
      DOUBLE PRECISION WP10I3_KSS_PC_FIRST(4,4)
      DOUBLE PRECISION WP10I3_KSS_PC_SECOND(4,4)
      DOUBLE PRECISION WP10I3_KSS_CAPACITY(4,4)
      DOUBLE PRECISION WP10I3_KSS_ANCHOR(4,4)
      DOUBLE PRECISION WP10I3_KSS_DIAG(4,4)
      COMMON /WP10I3_KSS_AUDIT/ WP10I3_KSS_STORAGE,
     1 WP10I3_KSS_STRAIN, WP10I3_KSS_MOBILITY,
     2 WP10I3_KSS_PC_FIRST, WP10I3_KSS_PC_SECOND,
     3 WP10I3_KSS_CAPACITY, WP10I3_KSS_ANCHOR,
     4 WP10I3_KSS_DIAG
      CALL UPS_ZERO_MAT(WP10I3_KSS_STORAGE,4,4)
      CALL UPS_ZERO_MAT(WP10I3_KSS_STRAIN,4,4)
      CALL UPS_ZERO_MAT(WP10I3_KSS_MOBILITY,4,4)
      CALL UPS_ZERO_MAT(WP10I3_KSS_PC_FIRST,4,4)
      CALL UPS_ZERO_MAT(WP10I3_KSS_PC_SECOND,4,4)
      CALL UPS_ZERO_MAT(WP10I3_KSS_CAPACITY,4,4)
      CALL UPS_ZERO_MAT(WP10I3_KSS_ANCHOR,4,4)
      CALL UPS_ZERO_MAT(WP10I3_KSS_DIAG,4,4)
      RETURN
      END


      SUBROUTINE UPS_WP10I3_GET_KSS_AUDIT(KSTOR, KSTRAIN, KMOB,
     1 KPC1, KPC2, KCAP, KANCHOR, KDIAG)
      IMPLICIT NONE
      INTEGER I, J
      DOUBLE PRECISION KSTOR(4,4), KSTRAIN(4,4), KMOB(4,4)
      DOUBLE PRECISION KPC1(4,4), KPC2(4,4), KCAP(4,4)
      DOUBLE PRECISION KANCHOR(4,4), KDIAG(4,4)
      DOUBLE PRECISION WP10I3_KSS_STORAGE(4,4)
      DOUBLE PRECISION WP10I3_KSS_STRAIN(4,4)
      DOUBLE PRECISION WP10I3_KSS_MOBILITY(4,4)
      DOUBLE PRECISION WP10I3_KSS_PC_FIRST(4,4)
      DOUBLE PRECISION WP10I3_KSS_PC_SECOND(4,4)
      DOUBLE PRECISION WP10I3_KSS_CAPACITY(4,4)
      DOUBLE PRECISION WP10I3_KSS_ANCHOR(4,4)
      DOUBLE PRECISION WP10I3_KSS_DIAG(4,4)
      COMMON /WP10I3_KSS_AUDIT/ WP10I3_KSS_STORAGE,
     1 WP10I3_KSS_STRAIN, WP10I3_KSS_MOBILITY,
     2 WP10I3_KSS_PC_FIRST, WP10I3_KSS_PC_SECOND,
     3 WP10I3_KSS_CAPACITY, WP10I3_KSS_ANCHOR,
     4 WP10I3_KSS_DIAG
      DO I = 1, 4
         DO J = 1, 4
            KSTOR(I,J) = WP10I3_KSS_STORAGE(I,J)
            KSTRAIN(I,J) = WP10I3_KSS_STRAIN(I,J)
            KMOB(I,J) = WP10I3_KSS_MOBILITY(I,J)
            KPC1(I,J) = WP10I3_KSS_PC_FIRST(I,J)
            KPC2(I,J) = WP10I3_KSS_PC_SECOND(I,J)
            KCAP(I,J) = WP10I3_KSS_CAPACITY(I,J)
            KANCHOR(I,J) = WP10I3_KSS_ANCHOR(I,J)
            KDIAG(I,J) = WP10I3_KSS_DIAG(I,J)
         END DO
      END DO
      RETURN
      END


C ================================================================
C WP10-I1 stateless absolute-permeability value/derivative utility
C ================================================================
      SUBROUTINE UPS_KABS_VALUE_DERIVATIVE(SIGMA_M_EFF, K0_ABS,
     1 SIGMA0_EFF, A_SIGMA, SCALE_CB, KABS_MIN, KABS_MAX,
     2 KABS_GP, DK_DSIGE, KABS_BRANCH)

      IMPLICIT NONE
      INTEGER KABS_BRANCH
      DOUBLE PRECISION SIGMA_M_EFF, K0_ABS, SIGMA0_EFF, A_SIGMA
      DOUBLE PRECISION SCALE_CB, KABS_MIN, KABS_MAX
      DOUBLE PRECISION KABS_GP, DK_DSIGE, KABS_RAW

C --- Preserve the frozen value arithmetic and operation order.
      KABS_GP = K0_ABS
     1   * DEXP(A_SIGMA * (SIGMA_M_EFF - SIGMA0_EFF))
      KABS_GP = KABS_GP * SCALE_CB
      KABS_RAW = KABS_GP
      DK_DSIGE = A_SIGMA * KABS_RAW
      KABS_BRANCH = 0

      IF (KABS_RAW .LT. KABS_MIN) THEN
         KABS_GP = KABS_MIN
         DK_DSIGE = 0.0D0
         KABS_BRANCH = -1
      ELSE IF (KABS_RAW .GT. KABS_MAX) THEN
         KABS_GP = KABS_MAX
         DK_DSIGE = 0.0D0
         KABS_BRANCH = 1
      ELSE IF (KABS_RAW .EQ. KABS_MIN .OR.
     1         KABS_RAW .EQ. KABS_MAX) THEN
C        The value is continuous, but the exact switching derivative
C        is intentionally excluded from smooth finite-difference claims.
         DK_DSIGE = 0.0D0
         KABS_BRANCH = 2
      END IF

      RETURN
      END


C ================================================================
C WP10-I1 stateless mean-stress to displacement chain
C ================================================================
      SUBROUTINE UPS_KABS_SIGMA_TO_U(DK_DSIGE, DTAN, BU, DK_DU)

      IMPLICIT NONE
      INTEGER A, B, J
      DOUBLE PRECISION DK_DSIGE, DTAN(3,3), BU(3,8), DK_DU(8)
      DOUBLE PRECISION DSIGMA_M_DU

      DO J = 1, 8
         DSIGMA_M_DU = 0.0D0
         DO A = 1, 2
            DO B = 1, 3
               DSIGMA_M_DU = DSIGMA_M_DU
     1              + 0.5D0 * DTAN(A,B) * BU(B,J)
            END DO
         END DO
         DK_DU(J) = DK_DSIGE * DSIGMA_M_DU
      END DO

      RETURN
      END


C ================================================================
C Reservoir update (placeholder first-stage)
C ================================================================
C This subroutine is reserved for future porosity / permeability /
C compressibility evolution. The legacy constant branch is kept so the
C overall UEL can still be exercised safely when the extended route-2A
C property block is absent.
C Route 2A switches to a stress-sensitive KABS update when PROPS(16..22)
C are provided; CF_GP remains constant in this stage.
      SUBROUTINE UPS_RESERVOIR_UPDATE(EPSV_GP, PEQ_GP, SIGEFF_GP,
     1 PROPS, PHI_GP, KABS_GP, CF_GP, DK_DSIGE, DK_DCF, DCF_DSIGE)

      IMPLICIT NONE
      DOUBLE PRECISION EPSV_GP, PEQ_GP, SIGEFF_GP(3), PROPS(*)
      INTEGER UEL_NPROPS
      COMMON /UPS_ROUTE2A_CTRL/ UEL_NPROPS
      DOUBLE PRECISION PHI_GP, KABS_GP, CF_GP
      DOUBLE PRECISION DK_DSIGE, DK_DCF, DCF_DSIGE
      DOUBLE PRECISION K0_ABS, SIGMA0_EFF, A_SIGMA
      DOUBLE PRECISION CB0, A_CB, KABS_MIN, KABS_MAX
      DOUBLE PRECISION SIGMA_M_EFF
      DOUBLE PRECISION CB_GP, SCALE_CB
      INTEGER KABS_BRANCH

      PHI_GP     = 0.15D0
C     KABS_GP scan history for the mini baseline:
C     1.0D-12 -> 1.0D-18, with caseA/caseB still completed.
C     Legacy fallback remains at KABS_GP = 1.0D-15 when route 2A
C     properties are not supplied.
      CF_GP      = 1.0D-9
      DK_DSIGE   = 0.0D0
      DK_DCF     = 0.0D0
      DCF_DSIGE  = 0.0D0

      SIGMA_M_EFF = 0.5D0 * (SIGEFF_GP(1) + SIGEFF_GP(2))

      IF (UEL_NPROPS .GE. 22) THEN
         K0_ABS     = PROPS(16)
         SIGMA0_EFF = PROPS(17)
         A_SIGMA    = PROPS(18)
         CB0        = PROPS(19)
         A_CB       = PROPS(20)
         KABS_MIN   = PROPS(21)
         KABS_MAX   = PROPS(22)

C --- Route 2A stage-1: freeze Cb at the reference value
         CB_GP = CB0
         SCALE_CB = 1.0D0 + A_CB * (CB_GP - CB0)

C --- Abaqus sign convention: tension positive, compression negative
         CALL UPS_KABS_VALUE_DERIVATIVE(SIGMA_M_EFF, K0_ABS,
     1      SIGMA0_EFF, A_SIGMA, SCALE_CB, KABS_MIN, KABS_MAX,
     2      KABS_GP, DK_DSIGE, KABS_BRANCH)
      ELSE
         KABS_GP    = 1.0D-15
      END IF

      RETURN
      END


C ================================================================
C Linear elastic constitutive law (plane strain)
C effective stress only, mechanics backbone
C ================================================================
C This routine computes the small-strain isotropic plane-strain
C effective stress response of the skeleton. It does not apply any
C pore-pressure coupling here; that coupling is intentionally kept in
C the assembly stage so the mechanics backbone can be checked in
C isolation.
      SUBROUTINE UPS_MECH_CONSTITUTIVE(EPS_GP, PROPS,
     1 SIGEFF_GP, DTAN)

      IMPLICIT NONE
      INTEGER I, J
      DOUBLE PRECISION EPS_GP(3), SIGEFF_GP(3), DTAN(3,3)
      DOUBLE PRECISION PROPS(*)
      DOUBLE PRECISION E_MOD, NU_MOD, LAMBDA, GMOD

C --- read material parameters from PROPS
C PROPS(1) = E
C PROPS(2) = NU
      E_MOD  = PROPS(1)
      NU_MOD = PROPS(2)

C --- Lam? constants for plane strain
      LAMBDA = E_MOD*NU_MOD /
     1         ((1.0D0 + NU_MOD)*(1.0D0 - 2.0D0*NU_MOD))
      GMOD   = E_MOD /
     1         (2.0D0*(1.0D0 + NU_MOD))

      DO I = 1, 3
         DO J = 1, 3
            DTAN(I,J) = 0.0D0
         END DO
      END DO

      DTAN(1,1) = LAMBDA + 2.0D0*GMOD
      DTAN(1,2) = LAMBDA
      DTAN(2,1) = LAMBDA
      DTAN(2,2) = LAMBDA + 2.0D0*GMOD
      DTAN(3,3) = GMOD

C --- effective stress in the [exx, eyy, gxy] engineering strain basis
      SIGEFF_GP(1) = DTAN(1,1)*EPS_GP(1) + DTAN(1,2)*EPS_GP(2)
      SIGEFF_GP(2) = DTAN(2,1)*EPS_GP(1) + DTAN(2,2)*EPS_GP(2)
      SIGEFF_GP(3) = DTAN(3,3)*EPS_GP(3)

      RETURN
      END


