               OLDSTATE_SEEN_STEP(I,J) = -999999
               OLDSTATE_SEEN_INC(I,J) = -999999
            END DO
         END DO
         OLDSTATE_UNIQ_INIT_DONE = 1
      END IF
      IF (CAPRAMP_RING_INIT .EQ. 0) THEN
         CAPRAMP_RING_FILE = ' '
         CALL GET_ENVIRONMENT_VARIABLE('DBG_CAPRAMP_RING_ELEM_FILE',
     1        CAPRAMP_RING_FILE)
