     1         PEQ_RAMP_LAMBDA = 1.0D0
            IF (CAPRAMP_SN_JUMP_REG .GT. 0.5D0 .AND.
     1          KSTEP .GE. CAPRAMP_PROBE_TEST_KSTEP) THEN
               CAPRAMP_SN_JUMP_ABS = DABS(DELTA_SN)
               CAPRAMP_SN_JUMP_BETA = 1.0D0
               IF (CAPRAMP_SN_JUMP_ABS .GT.
     1             CAPRAMP_SN_JUMP_TOL) THEN
                  CAPRAMP_SN_JUMP_BETA =
     1               CAPRAMP_SN_JUMP_TOL
     2               / (CAPRAMP_SN_JUMP_ABS + 1.0D-30)
                  IF (CAPRAMP_SN_JUMP_BETA .LT.
     1                CAPRAMP_SN_JUMP_BETA_MIN)
     2                CAPRAMP_SN_JUMP_BETA =
     3                CAPRAMP_SN_JUMP_BETA_MIN
                  IF (CAPRAMP_SN_JUMP_BETA .GT. 1.0D0)
     1                CAPRAMP_SN_JUMP_BETA = 1.0D0
                  CAPRAMP_SN_JUMP_SN_MECH = SN_OLD
     1               + CAPRAMP_SN_JUMP_BETA * DELTA_SN
                  IF (CAPRAMP_SN_JUMP_SN_MECH .LT. 0.0D0)
     1                CAPRAMP_SN_JUMP_SN_MECH = 0.0D0
                  IF (CAPRAMP_SN_JUMP_SN_MECH .GT. 1.0D0)
     1                CAPRAMP_SN_JUMP_SN_MECH = 1.0D0
                  CALL UPS_TWOPHASE_CLOSURE(PW_GP,
     1               CAPRAMP_SN_JUMP_SN_MECH, PROPS,
     2               SW_MECH, PC_MECH, KRW_MECH, KRN_MECH,
     3               PEQ_MECH, DPC_DSN_MECH, DKRW_DSN_MECH,
     4               DKRN_DSN_MECH, DPEQ_DPW_MECH,
     5               DPEQ_DSN_MECH, .FALSE.,
     6               SE_RAW_MECH, SE_CLAMP_MECH, DS_MECH,
     7               CHI_MECH, DCHI_DSN_MECH, DSE_DSN_MECH)
                  PEQ_CAPREF = PEQ_MECH - PEQ_REF
                  DELTA_PEQ = PEQ_MECH - PEQ_OLD
                  DPEQ_DPW_USE = DPEQ_DPW_MECH
                  DPEQ_DSN_USE = CAPRAMP_SN_JUMP_BETA
     1                            * DPEQ_DSN_MECH
               END IF
            END IF
            PEQ_USE = PEQ_RAMP_LAMBDA * PEQ_CAPREF
            DPEQ_DPW_USE = PEQ_RAMP_LAMBDA * DPEQ_DPW_USE
            DPEQ_DSN_USE = PEQ_RAMP_LAMBDA * DPEQ_DSN_USE
            PEQ_FORCE_USE = CAPRAMP_FORCE_SIGN
     1                    * CAPRAMP_FORCE_SCALE * PEQ_USE
            DELTA_PEQ_FORCE_RAW = CAPRAMP_FORCE_SIGN
     1                    * CAPRAMP_FORCE_SCALE * DELTA_PEQ
C WP10-I2 M2a: differentiate the unchanged force value exactly.  The
C loading multiplier is already present in DPEQ_*_USE; FORCE_SCALE is
C the remaining value factor.  Do not apply the quasi-Newton tangent
C scale or the local-Picard tangent selector in this consistency path.
            DPEQ_DPW_TAN_USE = CAPRAMP_FORCE_SIGN
     1                    * CAPRAMP_FORCE_SCALE * DPEQ_DPW_USE
            DPEQ_DSN_TAN_USE = CAPRAMP_FORCE_SIGN
     1                    * CAPRAMP_FORCE_SCALE * DPEQ_DSN_USE
            CAPRAMP_WELLB_REG_SCALE = 1.0D0
            IF (CAPRAMP_WELLB_FORCE_REG .GT. 0.5D0 .AND.
     1          KSTEP .GE. CAPRAMP_PROBE_TEST_KSTEP) THEN
               CAPRAMP_WELLB_REG_DIST = DSQRT(
     1            (X_GP - CAPRAMP_WELLB_X)
     2            * (X_GP - CAPRAMP_WELLB_X)
     3            + (Y_GP - CAPRAMP_WELLB_Y)
     4            * (Y_GP - CAPRAMP_WELLB_Y))
               IF (CAPRAMP_WELLB_REG_DIST .LE.
     1             CAPRAMP_WELLB_REG_INNER) THEN
                  CAPRAMP_WELLB_REG_SCALE = CAPRAMP_WELLB_REG_MIN
               ELSE IF (CAPRAMP_WELLB_REG_DIST .LT.
     1                  CAPRAMP_WELLB_REG_RADIUS) THEN
                  CAPRAMP_WELLB_REG_FRAC =
     1               (CAPRAMP_WELLB_REG_DIST - CAPRAMP_WELLB_REG_INNER)
     2               / (CAPRAMP_WELLB_REG_RADIUS
     3               - CAPRAMP_WELLB_REG_INNER)
                  CAPRAMP_WELLB_REG_SCALE = CAPRAMP_WELLB_REG_MIN
     1               + (1.0D0 - CAPRAMP_WELLB_REG_MIN)
     2               * (3.0D0*CAPRAMP_WELLB_REG_FRAC
     3               * CAPRAMP_WELLB_REG_FRAC
     4               - 2.0D0*CAPRAMP_WELLB_REG_FRAC
     5               * CAPRAMP_WELLB_REG_FRAC
     6               * CAPRAMP_WELLB_REG_FRAC)
               END IF
               PEQ_FORCE_USE = CAPRAMP_WELLB_REG_SCALE
     1                         * PEQ_FORCE_USE
               DPEQ_DPW_TAN_USE = CAPRAMP_WELLB_REG_SCALE
     1                            * DPEQ_DPW_TAN_USE
               DPEQ_DSN_TAN_USE = CAPRAMP_WELLB_REG_SCALE
     1                            * DPEQ_DSN_TAN_USE
            END IF
            CAPRAMP_PC_FRONT_SCALE = 1.0D0
            IF (CAPRAMP_PC_FRONT_REG .GT. 0.5D0 .AND.
     1          KSTEP .GE. CAPRAMP_PROBE_TEST_KSTEP) THEN
               CAPRAMP_PC_FRONT_SN_SCALE = 1.0D0
               CAPRAMP_PC_FRONT_PC_SCALE = 1.0D0
               IF (SN_GP .GE. CAPRAMP_PC_FRONT_SN1) THEN
                  CAPRAMP_PC_FRONT_SN_SCALE = CAPRAMP_PC_FRONT_MIN
               ELSE IF (SN_GP .GT. CAPRAMP_PC_FRONT_SN0) THEN
                  CAPRAMP_PC_FRONT_FRAC =
     1               (SN_GP - CAPRAMP_PC_FRONT_SN0)
     2               / (CAPRAMP_PC_FRONT_SN1 - CAPRAMP_PC_FRONT_SN0)
                  CAPRAMP_PC_FRONT_SN_SCALE = 1.0D0
     1               - (1.0D0 - CAPRAMP_PC_FRONT_MIN)
     2               * (3.0D0*CAPRAMP_PC_FRONT_FRAC
     3               * CAPRAMP_PC_FRONT_FRAC
     4               - 2.0D0*CAPRAMP_PC_FRONT_FRAC
     5               * CAPRAMP_PC_FRONT_FRAC
     6               * CAPRAMP_PC_FRONT_FRAC)
               END IF
               IF (PC_GP .GE. CAPRAMP_PC_FRONT_PC1) THEN
                  CAPRAMP_PC_FRONT_PC_SCALE = CAPRAMP_PC_FRONT_MIN
               ELSE IF (PC_GP .GT. CAPRAMP_PC_FRONT_PC0) THEN
                  CAPRAMP_PC_FRONT_FRAC =
     1               (PC_GP - CAPRAMP_PC_FRONT_PC0)
     2               / (CAPRAMP_PC_FRONT_PC1 - CAPRAMP_PC_FRONT_PC0)
                  CAPRAMP_PC_FRONT_PC_SCALE = 1.0D0
     1               - (1.0D0 - CAPRAMP_PC_FRONT_MIN)
     2               * (3.0D0*CAPRAMP_PC_FRONT_FRAC
     3               * CAPRAMP_PC_FRONT_FRAC
     4               - 2.0D0*CAPRAMP_PC_FRONT_FRAC
     5               * CAPRAMP_PC_FRONT_FRAC
     6               * CAPRAMP_PC_FRONT_FRAC)
               END IF
               CAPRAMP_PC_FRONT_SCALE = CAPRAMP_PC_FRONT_SN_SCALE
               IF (CAPRAMP_PC_FRONT_PC_SCALE .LT.
     1             CAPRAMP_PC_FRONT_SCALE)
     2             CAPRAMP_PC_FRONT_SCALE = CAPRAMP_PC_FRONT_PC_SCALE
               PEQ_FORCE_USE = CAPRAMP_PC_FRONT_SCALE * PEQ_FORCE_USE
               DPEQ_DPW_TAN_USE = CAPRAMP_PC_FRONT_SCALE
     1                              * DPEQ_DPW_TAN_USE
               DPEQ_DSN_TAN_USE = CAPRAMP_PC_FRONT_SCALE
     1                              * DPEQ_DSN_TAN_USE
            END IF
            CAPRAMP_FRONT_FILTER_GATE = 0.0D0
            IF (KSTEP .GE. CAPRAMP_PROBE_TEST_KSTEP) THEN
               IF (CAPRAMP_FRONT_FILTER_MIN_KINC .LE. -999000
     1             .AND. CAPRAMP_FRONT_FILTER_MIN_TIME .LT.
     2             0.0D0) THEN
                  CAPRAMP_FRONT_FILTER_GATE = 1.0D0
               ELSE
                  IF (CAPRAMP_FRONT_FILTER_MIN_KINC .GT.
     1                -999000 .AND.
     2                KINC .GE. CAPRAMP_FRONT_FILTER_MIN_KINC)
     3                CAPRAMP_FRONT_FILTER_GATE = 1.0D0
                  IF (CAPRAMP_FRONT_FILTER_MIN_TIME .GE. 0.0D0
     1                .AND. UPS_CUR_STEP_TIME .GE.
     2                CAPRAMP_FRONT_FILTER_MIN_TIME)
     3                CAPRAMP_FRONT_FILTER_GATE = 1.0D0
               END IF
            END IF
            CAPRAMP_FRONT_RU_RATIO_PRE = 0.0D0
            IF (CAPRAMP_FRONT_RU_REG .GT. 0.5D0 .AND.
     1          CAPRAMP_FRONT_FILTER_GATE .GT. 0.5D0) THEN
               RU_PEQ_NORM = 0.0D0
               RU_SIG_NORM = 0.0D0
               DO I = 1, 8
                  TMP_RU = 0.0D0
                  TMP_KUU = 0.0D0
                  DO A = 1, 3
                     IF (A .LE. 2) THEN
                        TMP_RU = TMP_RU - BU(A,I) * ALPHA_BIOT
     1                       * PEQ_FORCE_USE * DVOL
                     END IF
                     TMP_KUU = TMP_KUU + BU(A,I) * SIGEFF_GP(A)
     1                    * DVOL
                  END DO
                  RU_PEQ_NORM = RU_PEQ_NORM + TMP_RU * TMP_RU
                  RU_SIG_NORM = RU_SIG_NORM + TMP_KUU * TMP_KUU
               END DO
               CAPRAMP_FRONT_RU_RATIO_PRE = DSQRT(RU_PEQ_NORM)
     1              / (DSQRT(RU_SIG_NORM) + 1.0D-30)
            END IF
            CAPRAMP_FRONT_JUMP_SCALE = 1.0D0
            IF (CAPRAMP_FRONT_JUMP_REG .GT. 0.5D0 .AND.
     1          CAPRAMP_FRONT_FILTER_GATE .GT. 0.5D0) THEN
               CAPRAMP_FRONT_JUMP_METRIC = 0.0D0
               CAPRAMP_FRONT_JUMP_TMP =
     1            DABS(DELTA_SN) / CAPRAMP_FRONT_JUMP_SN_TOL
               IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1             CAPRAMP_FRONT_JUMP_METRIC)
     2             CAPRAMP_FRONT_JUMP_METRIC =
     3             CAPRAMP_FRONT_JUMP_TMP
               CAPRAMP_FRONT_JUMP_TMP =
     1            DABS(DELTA_PC) / CAPRAMP_FRONT_JUMP_PC_TOL
               IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1             CAPRAMP_FRONT_JUMP_METRIC)
     2             CAPRAMP_FRONT_JUMP_METRIC =
     3             CAPRAMP_FRONT_JUMP_TMP
               CAPRAMP_FRONT_JUMP_TMP =
     1            DABS(PW_GP-PW_OLD) / CAPRAMP_FRONT_JUMP_DPW_TOL
               IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1             CAPRAMP_FRONT_JUMP_METRIC)
     2             CAPRAMP_FRONT_JUMP_METRIC =
     3             CAPRAMP_FRONT_JUMP_TMP
               CAPRAMP_FRONT_JUMP_TMP =
     1            DABS(DELTA_PEQ) / CAPRAMP_FRONT_JUMP_DPEQ_TOL
               IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1             CAPRAMP_FRONT_JUMP_METRIC)
     2             CAPRAMP_FRONT_JUMP_METRIC =
     3             CAPRAMP_FRONT_JUMP_TMP
               IF (CAPRAMP_FRONT_JUMP_GTOT_TOL .LT. 1.0D90 .OR.
     1             CAPRAMP_FRONT_JUMP_QN_TOL .LT. 1.0D90) THEN
                  GPC_AUD_VEC(1) = DPC_DSN * GSN(1)
                  GPC_AUD_VEC(2) = DPC_DSN * GSN(2)
                  GTOT_AUD_VEC(1) = GPW(1) + GPC_AUD_VEC(1)
                  GTOT_AUD_VEC(2) = GPW(2) + GPC_AUD_VEC(2)
                  GTOT_NORM_AUD = DSQRT(GTOT_AUD_VEC(1)
     1               * GTOT_AUD_VEC(1) + GTOT_AUD_VEC(2)
     2               * GTOT_AUD_VEC(2))
                  CAPRAMP_FRONT_JUMP_TMP =
     1               GTOT_NORM_AUD / CAPRAMP_FRONT_JUMP_GTOT_TOL
                  IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_JUMP_TMP
                  MU_N_AUD = PROPS(7)
                  RHON_AUD = PROPS(6)
                  LAMN_AUD = 0.0D0
                  IF (DABS(MU_N_AUD) .GT. 1.0D-30)
     1               LAMN_AUD = RHON_AUD * KABS_GP * KRN_GP
     2                          / MU_N_AUD
                  QN_AUD_VEC(1) = -LAMN_AUD * GTOT_AUD_VEC(1)
                  QN_AUD_VEC(2) = -LAMN_AUD * GTOT_AUD_VEC(2)
                  QN_NORM_AUD = DSQRT(QN_AUD_VEC(1)
     1               * QN_AUD_VEC(1) + QN_AUD_VEC(2)
     2               * QN_AUD_VEC(2))
                  CAPRAMP_FRONT_JUMP_TMP =
     1               QN_NORM_AUD / CAPRAMP_FRONT_JUMP_QN_TOL
                  IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_JUMP_TMP
               END IF
               CAPRAMP_FRONT_JUMP_ABS_TMP =
     1            DABS(DELTA_PEQ_FORCE_RAW)
     2            / CAPRAMP_FRONT_JUMP_PEQF_TOL
               CAPRAMP_FRONT_JUMP_TMP = CAPRAMP_FRONT_JUMP_ABS_TMP
               IF (CAPRAMP_FRONT_JUMP_PEQF_REL_TOL .GT. 0.0D0) THEN
                  CAPRAMP_FRONT_JUMP_REL_DEN = DABS(PEQ_FORCE_USE)
     1               + DABS(PEQ_FORCE_USE - DELTA_PEQ_FORCE_RAW)
     2               + 1.0D-30
                  CAPRAMP_FRONT_JUMP_TMP = DABS(DELTA_PEQ_FORCE_RAW)
     1               / CAPRAMP_FRONT_JUMP_REL_DEN
     2               / CAPRAMP_FRONT_JUMP_PEQF_REL_TOL
                  IF (CAPRAMP_FRONT_JUMP_ABS_TMP .LT.
     1                CAPRAMP_FRONT_JUMP_TMP)
     2                CAPRAMP_FRONT_JUMP_TMP =
     3                CAPRAMP_FRONT_JUMP_ABS_TMP
               END IF
               IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1             CAPRAMP_FRONT_JUMP_METRIC)
     2             CAPRAMP_FRONT_JUMP_METRIC =
     3             CAPRAMP_FRONT_JUMP_TMP
               IF (CAPRAMP_FRONT_RU_REG .GT. 0.5D0) THEN
                  CAPRAMP_FRONT_RU_TMP = CAPRAMP_FRONT_RU_RATIO_PRE
     1               / CAPRAMP_FRONT_RU_RATIO_TOL
                  IF (CAPRAMP_FRONT_RU_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_RU_TMP
               END IF
               IF (CAPRAMP_FRONT_JUMP_METRIC .GE.
     1             CAPRAMP_FRONT_JUMP_J1) THEN
                  CAPRAMP_FRONT_JUMP_SCALE =
     1               CAPRAMP_FRONT_JUMP_MIN
               ELSE IF (CAPRAMP_FRONT_JUMP_METRIC .GT.
     1                  CAPRAMP_FRONT_JUMP_J0) THEN
                  CAPRAMP_FRONT_JUMP_FRAC =
     1               (CAPRAMP_FRONT_JUMP_METRIC
     2               - CAPRAMP_FRONT_JUMP_J0)
     3               / (CAPRAMP_FRONT_JUMP_J1
     4               - CAPRAMP_FRONT_JUMP_J0)
                  CAPRAMP_FRONT_JUMP_SCALE = 1.0D0
     1               - (1.0D0 - CAPRAMP_FRONT_JUMP_MIN)
     2               * (3.0D0*CAPRAMP_FRONT_JUMP_FRAC
     3               * CAPRAMP_FRONT_JUMP_FRAC
     4               - 2.0D0*CAPRAMP_FRONT_JUMP_FRAC
     5               * CAPRAMP_FRONT_JUMP_FRAC
     6               * CAPRAMP_FRONT_JUMP_FRAC)
               END IF
               PEQ_FORCE_USE = CAPRAMP_FRONT_JUMP_SCALE
     1                         * PEQ_FORCE_USE
               DPEQ_DPW_TAN_USE = CAPRAMP_FRONT_JUMP_SCALE
     1                            * DPEQ_DPW_TAN_USE
               DPEQ_DSN_TAN_USE = CAPRAMP_FRONT_JUMP_SCALE
     1                            * DPEQ_DSN_TAN_USE
               CAPRAMP_PC_FRONT_SCALE = CAPRAMP_PC_FRONT_SCALE
     1                              * CAPRAMP_FRONT_JUMP_SCALE
            END IF
            IF (CAPRAMP_FRONT_TFILTER_REG .GT. 0.5D0 .AND.
     1          KSTEP .GE. CAPRAMP_PROBE_SEED_KSTEP) THEN
               CAPRAMP_FRONT_TFILTER_ACTIVE =
     1            CAPRAMP_FRONT_FILTER_GATE
               CAPRAMP_FRONT_TFILTER_TARGET = PEQ_FORCE_USE
               CAPRAMP_FRONT_TFILTER_NEW = CAPRAMP_FRONT_TFILTER_TARGET
               IF (KSTEP .GE. CAPRAMP_PROBE_TEST_KSTEP .AND.
     1             CAPRAMP_FRONT_FILTER_GATE .GT. 0.5D0) THEN
                  CAPRAMP_FRONT_TFILTER_OLD = 0.0D0
                  IF (PEQ_FILTER_INIT(JELEM,IGP) .EQ. 1)
     1               CAPRAMP_FRONT_TFILTER_OLD =
     2               PEQ_FILTER_EGP(JELEM,IGP)
                  CAPRAMP_FRONT_JUMP_METRIC = 0.0D0
                  CAPRAMP_FRONT_JUMP_TMP =
     1               DABS(DELTA_SN) / CAPRAMP_FRONT_JUMP_SN_TOL
                  IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_JUMP_TMP
                  CAPRAMP_FRONT_JUMP_TMP =
     1               DABS(DELTA_PC) / CAPRAMP_FRONT_JUMP_PC_TOL
                  IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_JUMP_TMP
                  CAPRAMP_FRONT_JUMP_TMP =
     1               DABS(PW_GP-PW_OLD) / CAPRAMP_FRONT_JUMP_DPW_TOL
                  IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_JUMP_TMP
                  CAPRAMP_FRONT_JUMP_TMP =
     1               DABS(DELTA_PEQ) / CAPRAMP_FRONT_JUMP_DPEQ_TOL
                  IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_JUMP_TMP
                  IF (CAPRAMP_FRONT_JUMP_GTOT_TOL .LT. 1.0D90 .OR.
     1                CAPRAMP_FRONT_JUMP_QN_TOL .LT. 1.0D90) THEN
                     GPC_AUD_VEC(1) = DPC_DSN * GSN(1)
                     GPC_AUD_VEC(2) = DPC_DSN * GSN(2)
                     GTOT_AUD_VEC(1) = GPW(1) + GPC_AUD_VEC(1)
                     GTOT_AUD_VEC(2) = GPW(2) + GPC_AUD_VEC(2)
                     GTOT_NORM_AUD = DSQRT(GTOT_AUD_VEC(1)
     1                  * GTOT_AUD_VEC(1) + GTOT_AUD_VEC(2)
     2                  * GTOT_AUD_VEC(2))
                     CAPRAMP_FRONT_JUMP_TMP =
     1                  GTOT_NORM_AUD / CAPRAMP_FRONT_JUMP_GTOT_TOL
                     IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                   CAPRAMP_FRONT_JUMP_METRIC)
     2                   CAPRAMP_FRONT_JUMP_METRIC =
     3                   CAPRAMP_FRONT_JUMP_TMP
                     MU_N_AUD = PROPS(7)
                     RHON_AUD = PROPS(6)
                     LAMN_AUD = 0.0D0
                     IF (DABS(MU_N_AUD) .GT. 1.0D-30)
     1                  LAMN_AUD = RHON_AUD * KABS_GP * KRN_GP
     2                             / MU_N_AUD
                     QN_AUD_VEC(1) = -LAMN_AUD * GTOT_AUD_VEC(1)
                     QN_AUD_VEC(2) = -LAMN_AUD * GTOT_AUD_VEC(2)
                     QN_NORM_AUD = DSQRT(QN_AUD_VEC(1)
     1                  * QN_AUD_VEC(1) + QN_AUD_VEC(2)
     2                  * QN_AUD_VEC(2))
                     CAPRAMP_FRONT_JUMP_TMP =
     1                  QN_NORM_AUD / CAPRAMP_FRONT_JUMP_QN_TOL
                     IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                   CAPRAMP_FRONT_JUMP_METRIC)
     2                   CAPRAMP_FRONT_JUMP_METRIC =
     3                   CAPRAMP_FRONT_JUMP_TMP
                  END IF
                  CAPRAMP_FRONT_JUMP_ABS_TMP =
     1               DABS(CAPRAMP_FRONT_TFILTER_TARGET
     2               - CAPRAMP_FRONT_TFILTER_OLD)
     3               / CAPRAMP_FRONT_JUMP_PEQF_TOL
                  CAPRAMP_FRONT_JUMP_TMP = CAPRAMP_FRONT_JUMP_ABS_TMP
                  IF (CAPRAMP_FRONT_JUMP_PEQF_REL_TOL .GT.
     1                0.0D0) THEN
                     CAPRAMP_FRONT_JUMP_REL_DEN =
     1                  DABS(CAPRAMP_FRONT_TFILTER_TARGET)
     2                  + DABS(CAPRAMP_FRONT_TFILTER_OLD)
     3                  + 1.0D-30
                     CAPRAMP_FRONT_JUMP_TMP =
     1                  DABS(CAPRAMP_FRONT_TFILTER_TARGET
     2                  - CAPRAMP_FRONT_TFILTER_OLD)
     3                  / CAPRAMP_FRONT_JUMP_REL_DEN
     4                  / CAPRAMP_FRONT_JUMP_PEQF_REL_TOL
                     IF (CAPRAMP_FRONT_JUMP_ABS_TMP .LT.
     1                   CAPRAMP_FRONT_JUMP_TMP)
     2                   CAPRAMP_FRONT_JUMP_TMP =
     3                   CAPRAMP_FRONT_JUMP_ABS_TMP
                  END IF
                  IF (CAPRAMP_FRONT_JUMP_TMP .GT.
     1                CAPRAMP_FRONT_JUMP_METRIC)
     2                CAPRAMP_FRONT_JUMP_METRIC =
     3                CAPRAMP_FRONT_JUMP_TMP
                  IF (CAPRAMP_FRONT_RU_REG .GT. 0.5D0) THEN
                     CAPRAMP_FRONT_RU_TMP =
     1                  CAPRAMP_FRONT_RU_RATIO_PRE
     2                  / CAPRAMP_FRONT_RU_RATIO_TOL
                     IF (CAPRAMP_FRONT_RU_TMP .GT.
     1                   CAPRAMP_FRONT_JUMP_METRIC)
     2                   CAPRAMP_FRONT_JUMP_METRIC =
     3                   CAPRAMP_FRONT_RU_TMP
                  END IF
                  CAPRAMP_FRONT_TFILTER_BETA = 1.0D0
                  IF (CAPRAMP_FRONT_JUMP_METRIC .GE.
     1                CAPRAMP_FRONT_JUMP_J1) THEN
                     CAPRAMP_FRONT_TFILTER_BETA =
     1                  CAPRAMP_FRONT_TFILTER_BETA_MIN
                  ELSE IF (CAPRAMP_FRONT_JUMP_METRIC .GT.
     1                     CAPRAMP_FRONT_JUMP_J0) THEN
                     CAPRAMP_FRONT_TFILTER_FRAC =
     1                  (CAPRAMP_FRONT_JUMP_METRIC
     2                  - CAPRAMP_FRONT_JUMP_J0)
     3                  / (CAPRAMP_FRONT_JUMP_J1
     4                  - CAPRAMP_FRONT_JUMP_J0)
                     CAPRAMP_FRONT_TFILTER_BETA = 1.0D0
     1                  - (1.0D0 - CAPRAMP_FRONT_TFILTER_BETA_MIN)
     2                  * (3.0D0*CAPRAMP_FRONT_TFILTER_FRAC
     3                  * CAPRAMP_FRONT_TFILTER_FRAC
     4                  - 2.0D0*CAPRAMP_FRONT_TFILTER_FRAC
     5                  * CAPRAMP_FRONT_TFILTER_FRAC
     6                  * CAPRAMP_FRONT_TFILTER_FRAC)
                  END IF
                  CAPRAMP_FRONT_TFILTER_NEW =
     1               CAPRAMP_FRONT_TFILTER_OLD
     2               + CAPRAMP_FRONT_TFILTER_BETA
     3               * (CAPRAMP_FRONT_TFILTER_TARGET
     4               - CAPRAMP_FRONT_TFILTER_OLD)
                  PEQ_FORCE_USE = CAPRAMP_FRONT_TFILTER_NEW
                  DPEQ_DPW_TAN_USE = CAPRAMP_FRONT_TFILTER_BETA
     1                              * DPEQ_DPW_TAN_USE
                  DPEQ_DSN_TAN_USE = CAPRAMP_FRONT_TFILTER_BETA
     1                              * DPEQ_DSN_TAN_USE
               END IF
               PEQ_FILTER_EGP(JELEM,IGP) = CAPRAMP_FRONT_TFILTER_NEW
               PEQ_FILTER_INIT(JELEM,IGP) = 1
            END IF
            CAPRAMP_VALID_MASK = 1.0D0
            IF (CAPRAMP_INVALID_MASK .GT. 0.5D0) THEN
               IF (DABS(CAP_REF_FLAG) .LT. 0.5D0 .OR.
     1             DABS(PW_OLD) .LT. 1.0D-20 .OR.
     2             DABS(PEQ_OLD) .LT. 1.0D-20 .OR.
     3             SIGEFF_OLD_NORM .LT. 1.0D-20) THEN
                  CAPRAMP_VALID_MASK = 0.0D0
               END IF
            END IF
            PEQ_FORCE_USE = CAPRAMP_VALID_MASK * PEQ_FORCE_USE
            DPEQ_DPW_TAN_USE = CAPRAMP_VALID_MASK * DPEQ_DPW_TAN_USE
            DPEQ_DSN_TAN_USE = CAPRAMP_VALID_MASK * DPEQ_DSN_TAN_USE
            VM(1) = 1.0D0
            VM(2) = 1.0D0
            VM(3) = 0.0D0
            SIGEFF_NORM = DSQRT(SIGEFF_GP(1)*SIGEFF_GP(1)
     1           + SIGEFF_GP(2)*SIGEFF_GP(2)
     2           + SIGEFF_GP(3)*SIGEFF_GP(3))
            IF (DBG_CAPRAMP_SIGEFF_BAD_AUDIT .AND.
     1          KSTEP .GE. 2 .AND.
     2          SIGEFF_OLD_NORM .LT. SIGEFF_BAD_TOL) THEN
               IF (OLDSTATE_SEEN_STEP(JELEM,IGP) .LT. 0) THEN
                  OLDSTATE_SEEN_STEP(JELEM,IGP) = KSTEP
                  OLDSTATE_SEEN_INC(JELEM,IGP) = KINC
                  IF (SIGEFF_BAD_AUDIT_COUNT .LT.
     1                SIGEFF_BAD_AUDIT_MAX_COUNT) THEN
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD JELEM IGP = ',
     1                          JELEM, IGP
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD KSTEP KINC = ',
     1                          KSTEP, KINC
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD X Y = ',
     1                          X_GP, Y_GP
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD SIGEFF_NORM = ',
     1                          SIGEFF_OLD_NORM
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD CUR_OLD_NORM = ',
     1                          SIGEFF_NORM, SIGEFF_OLD_NORM
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD OLD_SIGEFF = ',
     1                          SIGEFF_OLD(1), SIGEFF_OLD(2),
     2                          SIGEFF_OLD(3)
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD PW PEQ = ',
     1                          PW_GP, PEQ_GP
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD OLD PW PEQ = ',
     1                          PW_OLD, PEQ_OLD
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD CAPREF FLAG = ',
     1                          PEQ_REF, CAP_REF_FLAG
                     WRITE(*,*) 'CAPRAMP_SIGEFF_BAD UNIQUE_COUNT = ',
     1                          SIGEFF_BAD_AUDIT_COUNT + 1
                  END IF
                  SIGEFF_BAD_AUDIT_COUNT =
     1               SIGEFF_BAD_AUDIT_COUNT + 1
               END IF
            END IF
            OLDSTATE_BAD_ENTRY = (DABS(PW_OLD) .LT. 1.0D-20 .OR.
     1                           DABS(PEQ_REF) .LT. 1.0D-20 .OR.
     2                           SIGEFF_OLD_NORM .LT. 1.0D-20)
            IF (DBG_CAPRAMP_OLDSTATE_AUDIT .AND.
     1          KSTEP .GE. 2 .AND.
     2          OLDSTATE_BAD_ENTRY) THEN
               IF (OLDSTATE_STEP_LAST .NE. KSTEP .OR.
     1             OLDSTATE_STEP_INC_LAST .NE. KINC) THEN
                  IF (OLDSTATE_STEP_LAST .NE. -999999) THEN
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY STEP = ',
     1                          OLDSTATE_STEP_LAST
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY INC = ',
     1                          OLDSTATE_STEP_INC_LAST
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE TOTAL = ',
     1                          OLDSTATE_STEP_BAD_TOTAL
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE CAPREF_FLAG = ',
     1                          OLDSTATE_STEP_BAD_CAPREF_FLAG
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE PW_OLD = ',
     1                          OLDSTATE_STEP_BAD_PWOLD
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE PEQ_OLD = ',
     1                          OLDSTATE_STEP_BAD_PEQOLD
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE SIGEFF = ',
     1                          OLDSTATE_STEP_BAD_SIGEFF
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE FALLBACK = ',
     1                          OLDSTATE_STEP_BAD_FALLBACK
                     WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY FIRST BAD JELEM IGP = ',
     1                          OLDSTATE_STEP_FIRST_JELEM,
     2                          OLDSTATE_STEP_FIRST_IGP
                  END IF
                  OLDSTATE_STEP_LAST = KSTEP
                  OLDSTATE_STEP_INC_LAST = KINC
                  OLDSTATE_STEP_BAD_TOTAL = 0
                  OLDSTATE_STEP_BAD_CAPREF_FLAG = 0
                  OLDSTATE_STEP_BAD_PWOLD = 0
                  OLDSTATE_STEP_BAD_PEQOLD = 0
                  OLDSTATE_STEP_BAD_SIGEFF = 0
                  OLDSTATE_STEP_BAD_FALLBACK = 0
                  OLDSTATE_STEP_FIRST_JELEM = -999999
                  OLDSTATE_STEP_FIRST_IGP = -999999
                  OLDSTATE_AUDIT_COUNT = 0
               END IF
               IF (OLDSTATE_SEEN_STEP(JELEM,IGP) .NE. KSTEP .OR.
     1             OLDSTATE_SEEN_INC(JELEM,IGP) .NE. KINC) THEN
                  OLDSTATE_SEEN_STEP(JELEM,IGP) = KSTEP
                  OLDSTATE_SEEN_INC(JELEM,IGP) = KINC
                  OLDSTATE_BAD_COUNT = OLDSTATE_BAD_COUNT + 1
                  OLDSTATE_STEP_BAD_TOTAL = OLDSTATE_STEP_BAD_TOTAL + 1
                  IF (DABS(CAP_REF_FLAG) .LT. 0.5D0) THEN
                     OLDSTATE_STEP_BAD_CAPREF_FLAG =
     1                  OLDSTATE_STEP_BAD_CAPREF_FLAG + 1
                  END IF
                  IF (DABS(PW_OLD) .LT. 1.0D-20) THEN
                     OLDSTATE_STEP_BAD_PWOLD =
     1                  OLDSTATE_STEP_BAD_PWOLD + 1
                  END IF
                  IF (DABS(PEQ_OLD) .LT. 1.0D-20) THEN
                     OLDSTATE_STEP_BAD_PEQOLD =
     1                  OLDSTATE_STEP_BAD_PEQOLD + 1
                  END IF
                  IF (SIGEFF_OLD_NORM .LT. 1.0D-20) THEN
                     OLDSTATE_STEP_BAD_SIGEFF =
     1                  OLDSTATE_STEP_BAD_SIGEFF + 1
                  END IF
                  IF (CAP_REF_FALLBACK_THIS_CALL) THEN
                     OLDSTATE_STEP_BAD_FALLBACK =
     1                  OLDSTATE_STEP_BAD_FALLBACK + 1
                  END IF
                  IF (OLDSTATE_STEP_FIRST_JELEM .LT. 0) THEN
                     OLDSTATE_STEP_FIRST_JELEM = JELEM
                     OLDSTATE_STEP_FIRST_IGP = IGP
                  END IF
                  IF (DBG_CAPRAMP_OLDSTATE_SUMMARY_ONLY) THEN
                     IF (OLDSTATE_STEP_BAD_TOTAL .EQ. 1 .OR.
     1                   MOD(OLDSTATE_STEP_BAD_TOTAL,100) .EQ. 0) THEN
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY STEP KINC = ',
     1                             KSTEP, KINC
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE TOTAL = ',
     1                             OLDSTATE_STEP_BAD_TOTAL
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE CAPREF_FLAG = ',
     1                             OLDSTATE_STEP_BAD_CAPREF_FLAG
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE PW_OLD = ',
     1                             OLDSTATE_STEP_BAD_PWOLD
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE PEQ_OLD = ',
     1                             OLDSTATE_STEP_BAD_PEQOLD
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE SIGEFF = ',
     1                             OLDSTATE_STEP_BAD_SIGEFF
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY BAD UNIQUE FALLBACK = ',
     1                             OLDSTATE_STEP_BAD_FALLBACK
                        WRITE(*,*) 'CAPRAMP_UNIQUE_SUMMARY FIRST BAD JELEM IGP = ',
     1                             OLDSTATE_STEP_FIRST_JELEM,
     2                             OLDSTATE_STEP_FIRST_IGP
                     END IF
                  ELSE IF (OLDSTATE_AUDIT_COUNT .LT. 10) THEN
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD JELEM IGP = ',
     1                          JELEM, IGP
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD KSTEP KINC = ',
     1                          KSTEP, KINC
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD X Y = ',
     1                          X_GP, Y_GP
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD PW SN PC PEQ = ',
     1                          PW_GP, SN_GP, PC_GP, PEQ_GP
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD OLD PW SN PC PEQ = ',
     1                          PW_OLD, SN_OLD, PC_OLD, PEQ_OLD
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD CAPREF OLD USE = ',
     1                          CAP_REF_OLD, PEQ_REF
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD CAPREF_FLAG = ',
     1                          CAP_REF_FLAG
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD PEQCAP PEQUSE FORCE = ',
     1                          PEQ_CAPREF, PEQ_USE, PEQ_FORCE_USE
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD SIGEFF_NORM = ',
     1                          SIGEFF_OLD_NORM
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD CUR_OLD_NORM = ',
     1                          SIGEFF_NORM, SIGEFF_OLD_NORM
                     WRITE(*,*) 'CAPRAMP_OLDSTATE_BAD COUNT = ',
     1                          OLDSTATE_BAD_COUNT
                     OLDSTATE_AUDIT_COUNT = OLDSTATE_AUDIT_COUNT + 1
                  END IF
               END IF
            END IF
            IF (DBG_CAPRAMP_AUDIT .AND.
     1          CAPRAMP_AUDIT_COUNT .LT. CAPRAMP_AUDIT_MAX_COUNT
     2          .AND. KSTEP .GE. CAPRAMP_AUDIT_MIN_KSTEP
     3          .AND. ((DBG_CAPRAMP_AUDIT_FORCE_ONLY .AND.
     4          DABS(PEQ_FORCE_USE) .GT. 0.0D0) .OR.
     5          ((.NOT. DBG_CAPRAMP_AUDIT_FORCE_ONLY) .AND.
     6          (DABS(PEQ_FORCE_USE) .GT. 0.0D0 .OR.
     7          DABS(PEQ_CAPREF) .GT. 0.0D0)))) THEN
               RU_PEQ_NORM = 0.0D0
               RU_SIG_NORM = 0.0D0
               KUP_PEQ_NORM = 0.0D0
               KUS_PEQ_NORM = 0.0D0
               KUU_NORM = 0.0D0
               TMP_RU_MAX = 0.0D0
               CAPRAMP_LOCAL_MAX_DOF = 0
               DO I = 1, 8
                  TMP_RU = 0.0D0
                  TMP_KUU = 0.0D0
                  DO A = 1, 3
                     TMP_RU = TMP_RU - BU(A,I) * ALPHA_BIOT
     1                    * PEQ_FORCE_USE * VM(A) * DVOL
                     TMP_KUU = TMP_KUU + BU(A,I) * SIGEFF_GP(A)
     1                    * DVOL
                  END DO
                  TMP_RU_ABS = DABS(TMP_RU)
                  IF (TMP_RU_ABS .GT. TMP_RU_MAX) THEN
                     TMP_RU_MAX = TMP_RU_ABS
                     CAPRAMP_LOCAL_MAX_DOF = I
                  END IF
                  RU_PEQ_NORM = RU_PEQ_NORM + TMP_RU * TMP_RU
                  RU_SIG_NORM = RU_SIG_NORM + TMP_KUU * TMP_KUU
               END DO
               DO I = 1, 8
                  DO J = 1, 4
                     TMP_KUP = 0.0D0
                     TMP_KUS = 0.0D0
                     DO A = 1, 3
                        TMP_KUP = TMP_KUP - BU(A,I) * ALPHA_BIOT
     1                       * VM(A) * DPEQ_DPW_TAN_USE * N(J)
     2                       * DVOL
                        TMP_KUS = TMP_KUS - BU(A,I) * ALPHA_BIOT
     1                       * VM(A) * DPEQ_DSN_TAN_USE * N(J)
     2                       * DVOL
                     END DO
                     KUP_PEQ_NORM = KUP_PEQ_NORM + TMP_KUP * TMP_KUP
                     KUS_PEQ_NORM = KUS_PEQ_NORM + TMP_KUS * TMP_KUS
                  END DO
               END DO
               DO I = 1, 8
                  DO J = 1, 8
                     TMP_KUU = 0.0D0
                     DO A = 1, 3
                        DO B = 1, 3
                           TMP_KUU = TMP_KUU + BU(A,I) * DTAN(A,B)
     1                          * BU(B,J) * DVOL
                        END DO
                     END DO
                     KUU_NORM = KUU_NORM + TMP_KUU * TMP_KUU
                  END DO
               END DO
               RU_PEQ_NORM = DSQRT(RU_PEQ_NORM)
               RU_SIG_NORM = DSQRT(RU_SIG_NORM)
               KUP_PEQ_NORM = DSQRT(KUP_PEQ_NORM)
               KUS_PEQ_NORM = DSQRT(KUS_PEQ_NORM)
               KUU_NORM = DSQRT(KUU_NORM)
               SIGEFF_NORM = DSQRT(SIGEFF_GP(1)*SIGEFF_GP(1)
     1              + SIGEFF_GP(2)*SIGEFF_GP(2)
     2              + SIGEFF_GP(3)*SIGEFF_GP(3))
               PEQ_RU_RATIO = RU_PEQ_NORM / (RU_SIG_NORM + 1.0D-30)
               PEQ_STRESS_RATIO = DABS(ALPHA_BIOT * PEQ_FORCE_USE)
     1              / (SIGEFF_NORM + 1.0D-30)
               WRITE(*,*) 'CAPRAMP_AUDIT JELEM IGP = ', JELEM, IGP
               WRITE(*,*) 'CAPRAMP_AUDIT KSTEP KINC = ', KSTEP, KINC
               WRITE(*,*) 'CAPRAMP_AUDIT TIME1 TIME2 PERIOD = ',
     1                    UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME,
     2                    UPS_CUR_PERIOD
               WRITE(*,*) 'CAPRAMP_AUDIT MODE LAMBDA = ',
     1                    DBG_CAPRAMP_MODE_TAG, PEQ_RAMP_LAMBDA
               WRITE(*,*) 'CAPRAMP_AUDIT PROBE SEED TEST KSTEP = ',
     1                    CAPRAMP_PROBE_SEED_KSTEP,
     2                    CAPRAMP_PROBE_TEST_KSTEP
               WRITE(*,*) 'CAPRAMP_AUDIT TANGENT_SCALE = ',
     1                    CAPRAMP_TANGENT_SCALE
               WRITE(*,*) 'CAPRAMP_AUDIT FORCE_SCALE SIGN = ',
     1                    CAPRAMP_FORCE_SCALE, CAPRAMP_FORCE_SIGN
               WRITE(*,*) 'CAPRAMP_AUDIT WELLB_REG SCALE = ',
     1                    CAPRAMP_WELLB_FORCE_REG,
     2                    CAPRAMP_WELLB_REG_SCALE
               WRITE(*,*) 'CAPRAMP_AUDIT WELLB_REG X Y R = ',
     1                    CAPRAMP_WELLB_X, CAPRAMP_WELLB_Y,
     2                    CAPRAMP_WELLB_REG_DIST
               WRITE(*,*) 'CAPRAMP_AUDIT INVALID_MASK VALID_MASK = ',
     1                    CAPRAMP_INVALID_MASK, CAPRAMP_VALID_MASK
               WRITE(*,*) 'CAPRAMP_AUDIT PW SN PC PEQ = ',
     1                    PW_GP, SN_GP, PC_GP, PEQ_GP
               WRITE(*,*) 'CAPRAMP_AUDIT PEQ_OLD PW_OLD = ',
     1                    PEQ_OLD, PW_OLD
               WRITE(*,*) 'CAPRAMP_AUDIT CAP_REF PEQCAP PEQUSE = ',
     1                    PEQ_REF, PEQ_CAPREF, PEQ_USE
               WRITE(*,*) 'CAPRAMP_AUDIT PEQ_FORCE_USE = ',
     1                    PEQ_FORCE_USE
               WRITE(*,*) 'CAPRAMP_AUDIT DPEQ_DPW_USE DPEQ_DSN_USE = ',
     1                    DPEQ_DPW_USE, DPEQ_DSN_USE
               WRITE(*,*) 'CAPRAMP_AUDIT DPEQ_TAN_PW DPEQ_TAN_SN = ',
     1                    DPEQ_DPW_TAN_USE, DPEQ_DSN_TAN_USE
               WRITE(*,*) 'CAPRAMP_AUDIT NORMS RU KUP KUS KUU = ',
     1                    RU_PEQ_NORM, KUP_PEQ_NORM, KUS_PEQ_NORM,
     2                    KUU_NORM
               WRITE(*,*) 'CAPRAMP_AUDIT RU_SIG SIGEFF_NORM = ',
     1                    RU_SIG_NORM, SIGEFF_NORM
               WRITE(*,*) 'CAPRAMP_AUDIT RATIOS RU STRESS = ',
     1                    PEQ_RU_RATIO, PEQ_STRESS_RATIO
               WRITE(*,*) 'CAPRAMP_AUDIT FRONT_RU_RATIO_PRE = ',
     1                    CAPRAMP_FRONT_RU_RATIO_PRE
               WRITE(*,*) 'CAPRAMP_AUDIT LOCAL_MAX_U_DOF ABS_RU = ',
     1                    CAPRAMP_LOCAL_MAX_DOF, TMP_RU_MAX
               IF (RU_PEQ_NORM .GT. CAPRAMP_MAX_RU_PEQ) THEN
                  CAPRAMP_MAX_RU_PEQ = RU_PEQ_NORM
                  CAPRAMP_MAX_RU_JELEM = JELEM
                  CAPRAMP_MAX_RU_IGP = IGP
                  CAPRAMP_MAX_RU_STEP = KSTEP
                  CAPRAMP_MAX_RU_INC = KINC
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_RU STEP INC = ',
     1                       CAPRAMP_MAX_RU_STEP,
     2                       CAPRAMP_MAX_RU_INC
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_RU JELEM IGP = ',
     1                       CAPRAMP_MAX_RU_JELEM,
     2                       CAPRAMP_MAX_RU_IGP
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_RU VALUE = ',
     1                       CAPRAMP_MAX_RU_PEQ
               END IF
               IF (PEQ_RU_RATIO .GT. CAPRAMP_MAX_ETA_R) THEN
                  CAPRAMP_MAX_ETA_R = PEQ_RU_RATIO
                  CAPRAMP_MAX_ETA_R_JELEM = JELEM
                  CAPRAMP_MAX_ETA_R_IGP = IGP
                  CAPRAMP_MAX_ETA_R_STEP = KSTEP
                  CAPRAMP_MAX_ETA_R_INC = KINC
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_ETA_R STEP INC = ',
     1                       CAPRAMP_MAX_ETA_R_STEP,
     2                       CAPRAMP_MAX_ETA_R_INC
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_ETA_R JELEM IGP = ',
     1                       CAPRAMP_MAX_ETA_R_JELEM,
     2                       CAPRAMP_MAX_ETA_R_IGP
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_ETA_R VALUE = ',
     1                       CAPRAMP_MAX_ETA_R
               END IF
               IF (PEQ_STRESS_RATIO .GT. CAPRAMP_MAX_ETA_SIG) THEN
                  CAPRAMP_MAX_ETA_SIG = PEQ_STRESS_RATIO
                  CAPRAMP_MAX_ETA_S_JELEM = JELEM
                  CAPRAMP_MAX_ETA_S_IGP = IGP
                  CAPRAMP_MAX_ETA_S_STEP = KSTEP
                  CAPRAMP_MAX_ETA_S_INC = KINC
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_ETA_SIG STEP INC = ',
     1                       CAPRAMP_MAX_ETA_S_STEP,
     2                       CAPRAMP_MAX_ETA_S_INC
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_ETA_SIG JELEM IGP = ',
     1                       CAPRAMP_MAX_ETA_S_JELEM,
     2                       CAPRAMP_MAX_ETA_S_IGP
                  WRITE(*,*) 'CAPRAMP_AUDIT_MAX_ETA_SIG VALUE = ',
     1                       CAPRAMP_MAX_ETA_SIG
               END IF
               CAPRAMP_AUDIT_COUNT = CAPRAMP_AUDIT_COUNT + 1
            END IF
C Forced focused audit: whitelist + KSTEP/KINC is sufficient.  Print
C even when PEQ_FORCE_USE is zero so the closure/front history is visible.
            IF (CAPRAMP_RING_ACTIVE) THEN
               RU_PEQ_NORM = 0.0D0
               RU_SIG_NORM = 0.0D0
               TMP_RU_MAX = 0.0D0
               CAPRAMP_LOCAL_MAX_DOF = 0
               DO I = 1, 8
                  TMP_RU = 0.0D0
                  TMP_KUU = 0.0D0
                  DO A = 1, 3
                     TMP_RU = TMP_RU - BU(A,I) * ALPHA_BIOT
     1                    * PEQ_FORCE_USE * VM(A) * DVOL
                     TMP_KUU = TMP_KUU + BU(A,I) * SIGEFF_GP(A)
     1                    * DVOL
                  END DO
                  IF (DABS(TMP_RU) .GT. TMP_RU_MAX) THEN
                     TMP_RU_MAX = DABS(TMP_RU)
                     CAPRAMP_LOCAL_MAX_DOF = I
                  END IF
                  RU_PEQ_NORM = RU_PEQ_NORM + TMP_RU * TMP_RU
                  RU_SIG_NORM = RU_SIG_NORM + TMP_KUU * TMP_KUU
               END DO
               RU_PEQ_NORM = DSQRT(RU_PEQ_NORM)
               RU_SIG_NORM = DSQRT(RU_SIG_NORM)
               SIGEFF_NORM = DSQRT(SIGEFF_GP(1)*SIGEFF_GP(1)
     1              + SIGEFF_GP(2)*SIGEFF_GP(2)
     2              + SIGEFF_GP(3)*SIGEFF_GP(3))
               PEQ_RU_RATIO = RU_PEQ_NORM / (RU_SIG_NORM + 1.0D-30)
               PEQ_STRESS_RATIO = DABS(ALPHA_BIOT * PEQ_FORCE_USE)
     1              / (SIGEFF_NORM + 1.0D-30)
               MU_W_AUD = PROPS(5)
               RHON_AUD = PROPS(6)
               MU_N_AUD = PROPS(7)
               LAMW_AUD = 0.0D0
               LAMN_AUD = 0.0D0
               IF (DABS(MU_W_AUD) .GT. 1.0D-30)
     1            LAMW_AUD = KABS_GP * KRW_GP / MU_W_AUD
               IF (DABS(MU_N_AUD) .GT. 1.0D-30)
     1            LAMN_AUD = RHON_AUD * KABS_GP * KRN_GP / MU_N_AUD
               GPC_AUD_VEC(1) = DPC_DSN * GSN(1)
               GPC_AUD_VEC(2) = DPC_DSN * GSN(2)
               GTOT_AUD_VEC(1) = GPW(1) + GPC_AUD_VEC(1)
               GTOT_AUD_VEC(2) = GPW(2) + GPC_AUD_VEC(2)
               QW_AUD_VEC(1) = -LAMW_AUD * GPW(1)
               QW_AUD_VEC(2) = -LAMW_AUD * GPW(2)
               QN_AUD_VEC(1) = -LAMN_AUD * GTOT_AUD_VEC(1)
               QN_AUD_VEC(2) = -LAMN_AUD * GTOT_AUD_VEC(2)
               GPW_NORM_AUD = DSQRT(GPW(1)*GPW(1) + GPW(2)*GPW(2))
               GPC_NORM_AUD = DSQRT(GPC_AUD_VEC(1)*GPC_AUD_VEC(1)
     1              + GPC_AUD_VEC(2)*GPC_AUD_VEC(2))
               GTOT_NORM_AUD = DSQRT(GTOT_AUD_VEC(1)*GTOT_AUD_VEC(1)
     1              + GTOT_AUD_VEC(2)*GTOT_AUD_VEC(2))
               QW_NORM_AUD = DSQRT(QW_AUD_VEC(1)*QW_AUD_VEC(1)
     1              + QW_AUD_VEC(2)*QW_AUD_VEC(2))
               QN_NORM_AUD = DSQRT(QN_AUD_VEC(1)*QN_AUD_VEC(1)
     1              + QN_AUD_VEC(2)*QN_AUD_VEC(2))
               CALL UPS_TWOPHASE_CLOSURE(PW_GP, SN_GP, PROPS,
     1              SW_AUD, PC_AUD, KRW_AUD, KRN_AUD, PEQ_AUD,
     2              DPC_DSN_AUD, DKRW_DSN_AUD, DKRN_DSN_AUD,
     3              DPEQ_DPW_AUD, DPEQ_DSN_AUD, .FALSE.,
     4              SE_RAW_AUD, SE_CLAMP_AUD, DS_AUD,
     5              CHI_AUD, DCHI_DSN_AUD, DSE_DSN_AUD)
               CALL UPS_TWOPHASE_CLOSURE(PW_OLD, SN_OLD, PROPS,
     1              SW_OLD_AUD, PC_OLD_AUD, KRW_OLD_AUD, KRN_OLD_AUD,
     2              PEQ_OLD_AUD, DPC_DSN_OLD_AUD,
     3              DKRW_DSN_OLD_AUD, DKRN_DSN_OLD_AUD,
     4              DPEQ_DPW_OLD_AUD, DPEQ_DSN_OLD_AUD, .FALSE.,
     5              SE_RAW_OLD_AUD, SE_CLAMP_OLD_AUD, DS_OLD_AUD,
     6              CHI_OLD_AUD, DCHI_DSN_OLD_AUD, DSE_DSN_OLD_AUD)
               WRITE(*,*) 'CAPRAMP_RING_AUDIT JELEM IGP = ',
     1                    JELEM, IGP
               WRITE(*,*) 'CAPRAMP_RING_AUDIT KSTEP KINC = ',
     1                    KSTEP, KINC
               WRITE(*,*) 'CAPRAMP_RING_AUDIT STEP TOTAL LAMBDA = ',
     1                    UPS_CUR_STEP_TIME, UPS_CUR_TOTAL_TIME,
     2                    PEQ_RAMP_LAMBDA
               WRITE(*,*) 'CAPRAMP_RING_AUDIT XGP YGP = ', X_GP, Y_GP
               WRITE(*,*) 'CAPRAMP_RING_AUDIT OLD PW PEQ CAPREF = ',
     1                    PW_OLD, PEQ_OLD, PEQ_REF
               WRITE(*,*) 'CAPRAMP_RING_AUDIT OLD SN PC = ',
     1                    SN_OLD, PC_OLD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT PW PEQ PEQ_FORCE = ',
     1                    PW_GP, PEQ_GP, PEQ_FORCE_USE
               WRITE(*,*) 'CAPRAMP_RING_AUDIT SN SW PC = ',
     1                    SN_GP, 1.0D0-SN_GP, PC_GP
               WRITE(*,*) 'CAPRAMP_RING_AUDIT CLOS SE CHI = ',
     1                    SE_RAW_AUD, SE_CLAMP_AUD, CHI_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT CLOS KRN KRW = ',
     1                    KRN_AUD, KRW_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT CLOS DPC DKRN DKRW = ',
     1                    DPC_DSN_AUD, DKRN_DSN_AUD, DKRW_DSN_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT OLD CLOS SE CHI = ',
     1                    SE_RAW_OLD_AUD, SE_CLAMP_OLD_AUD,
     2                    CHI_OLD_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT OLD CLOS KRN KRW = ',
     1                    KRN_OLD_AUD, KRW_OLD_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT OLD CLOS DPC DKRN DKRW = ',
     1                    DPC_DSN_OLD_AUD, DKRN_DSN_OLD_AUD,
     2                    DKRW_DSN_OLD_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT DELTA CLOS PC KRN KRW = ',
     1                    PC_AUD-PC_OLD_AUD, KRN_AUD-KRN_OLD_AUD,
     2                    KRW_AUD-KRW_OLD_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT SCALES WB FRONT VALID = ',
     1                    CAPRAMP_WELLB_REG_SCALE,
     2                    CAPRAMP_PC_FRONT_SCALE, CAPRAMP_VALID_MASK
               WRITE(*,*) 'CAPRAMP_RING_AUDIT TFILTER BETA OLD NEW = ',
     1                    CAPRAMP_FRONT_TFILTER_BETA,
     2                    CAPRAMP_FRONT_TFILTER_OLD,
     3                    CAPRAMP_FRONT_TFILTER_NEW
               WRITE(*,*) 'CAPRAMP_RING_AUDIT TFILTER TARGET ACTIVE = ',
     1                    CAPRAMP_FRONT_TFILTER_TARGET,
     2                    CAPRAMP_FRONT_TFILTER_ACTIVE
               WRITE(*,*) 'CAPRAMP_RING_AUDIT SNJF BETA SNMECH = ',
     1                    CAPRAMP_SN_JUMP_BETA,
     2                    CAPRAMP_SN_JUMP_SN_MECH
               WRITE(*,*) 'CAPRAMP_RING_AUDIT JUMP DSN DPC DPEQ = ',
     1                    DELTA_SN, DELTA_PC, DELTA_PEQ
               WRITE(*,*) 'CAPRAMP_RING_AUDIT JUMP DPEQ_FORCE DPEQDSN = ',
     1                    DELTA_PEQ_FORCE_RAW, DPEQ_DSN
               WRITE(*,*) 'CAPRAMP_RING_AUDIT PRESS_INC DPW DPC DPEQ = ',
     1                    PW_GP-PW_OLD, DELTA_PC, DELTA_PEQ
               WRITE(*,*) 'CAPRAMP_RING_AUDIT GRAD GPW_XY = ',
     1                    GPW(1), GPW(2)
               WRITE(*,*) 'CAPRAMP_RING_AUDIT GRAD GPC_XY = ',
     1                    GPC_AUD_VEC(1), GPC_AUD_VEC(2)
               WRITE(*,*) 'CAPRAMP_RING_AUDIT GRAD GTOT_XY = ',
     1                    GTOT_AUD_VEC(1), GTOT_AUD_VEC(2)
               WRITE(*,*) 'CAPRAMP_RING_AUDIT MOB LAMW LAMN = ',
     1                    LAMW_AUD, LAMN_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT FLUX QW_XY = ',
     1                    QW_AUD_VEC(1), QW_AUD_VEC(2)
               WRITE(*,*) 'CAPRAMP_RING_AUDIT FLUX QN_XY = ',
     1                    QN_AUD_VEC(1), QN_AUD_VEC(2)
               WRITE(*,*) 'CAPRAMP_RING_AUDIT NORMS GPW GPC GTOT = ',
     1                    GPW_NORM_AUD, GPC_NORM_AUD,
     2                    GTOT_NORM_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT NORMS QW QN = ',
     1                    QW_NORM_AUD, QN_NORM_AUD
               WRITE(*,*) 'CAPRAMP_RING_AUDIT SIGEFF_NORM RU_SIG = ',
     1                    SIGEFF_NORM, RU_SIG_NORM
               WRITE(*,*) 'CAPRAMP_RING_AUDIT RU_PEQ ETA_R ETA_SIG = ',
     1                    RU_PEQ_NORM, PEQ_RU_RATIO,
     2                    PEQ_STRESS_RATIO
               WRITE(*,*) 'CAPRAMP_RING_AUDIT FRONT_RU_RATIO_PRE = ',
     1                    CAPRAMP_FRONT_RU_RATIO_PRE
               WRITE(*,*) 'CAPRAMP_RING_AUDIT LOCAL_DOF ABS_RU = ',
     1                    CAPRAMP_LOCAL_MAX_DOF, TMP_RU_MAX
            END IF
         END IF
      ELSE
         PEQ_USE = PEQ_GP - PEQ_REF
      END IF
      IF (.NOT. (DBG_R1B_PEQ_CAPREF .AND.
     1    DBG_R1B_PEQ_CAPREF_RAMP)) PEQ_FORCE_USE = PEQ_USE
      IF (.NOT. (DBG_R1B_PEQ_CAPREF .AND.
     1    DBG_R1B_PEQ_CAPREF_RAMP)) THEN
         DPEQ_DPW_TAN_USE = DPEQ_DPW_USE
         DPEQ_DSN_TAN_USE = DPEQ_DSN_USE
      END IF

      RU_PEQ_USE_OK = 0
      RU_SIGEFF_OK = 0
      RU_FINAL_OK = 0
      IF (PEQ_FORCE_USE .EQ. PEQ_FORCE_USE .AND.
     1    DABS(PEQ_FORCE_USE) .LE. 1.0D100) RU_PEQ_USE_OK = 1
      IF (PEQ_FORCE_USE .EQ. PEQ_FORCE_USE .AND.
     1    DABS(PEQ_FORCE_USE) .LE. 1.0D100)
     2    CP164_PEQ_FORCE_TERM_OK = 1
      IF (SIGEFF_GP(1) .EQ. SIGEFF_GP(1) .AND.
     1    DABS(SIGEFF_GP(1)) .LE. 1.0D100 .AND.
     2    SIGEFF_GP(2) .EQ. SIGEFF_GP(2) .AND.
     3    DABS(SIGEFF_GP(2)) .LE. 1.0D100 .AND.
     4    SIGEFF_GP(3) .EQ. SIGEFF_GP(3) .AND.
     5    DABS(SIGEFF_GP(3)) .LE. 1.0D100) RU_SIGEFF_OK = 1
      IF (RU_PEQ_USE_OK .EQ. 1 .AND.
     1    RU_SIGEFF_OK .EQ. 1) RU_FINAL_OK = 1

C --- direction vector for pore-pressure coupling
      VM(1) = 1.0D0
      VM(2) = 1.0D0
      VM(3) = 0.0D0

      CALL UPS_CP179B2_MECH_COUPLING_AUDIT(KSTEP, KINC, JELEM, IGP,
     1 UPS_CUR_TOTAL_TIME, X_GP, Y_GP, WT, DETJ, N, BU,
     2 PW_GP, SN_GP, PC_GP, PEQ_GP, PEQ_OLD, PEQ_FORCE_USE,
     3 DPEQ_DPW_TAN_USE, DPEQ_DSN_TAN_USE, DPEQ_DPW_USE,
     4 DPEQ_DSN_USE, CAPRAMP_FORCE_SCALE, CAPRAMP_TANGENT_SCALE,
     5 CAPRAMP_WELLB_REG_SCALE, CAPRAMP_VALID_MASK, SIGEFF_GP,
     6 PROPS, DVOL, VM)

      DBG_MECH_DECOMP = .FALSE.
      IF (DEBUG_UEL .EQ. 1 .AND. JELEM .EQ. 1 .AND.
     1    KSTEP .EQ. 2 .AND. KINC .EQ. 1 .AND. IGP .GE. 1
     2    .AND. IGP .LE. 4) THEN
         DBG_MECH_DECOMP = .TRUE.
      END IF

C --- internal force residual: RU += Bu^T * sigma' * dV
      DO I = 1, 8
         DO A = 1, 3
            TMP_RU = BU(A,I) * SIGEFF_GP(A) * DVOL
            IF (TMP_RU .EQ. TMP_RU .AND.
     1          DABS(TMP_RU) .LE. 1.0D100)
     2          CP164_RU_SIG_TERM_OK = 1
            RU(I) = RU(I) + TMP_RU
         END DO
      END DO

C --- effective pore-pressure coupling residual:
C     RU += - Bu^T * alpha * peq * m * dV
      DO I = 1, 8
         DO A = 1, 3
            TMP_RU = - BU(A,I) * ALPHA_BIOT * PEQ_FORCE_USE
     1            * VM(A) * DVOL
            IF (TMP_RU .EQ. TMP_RU .AND.
     1          DABS(TMP_RU) .LE. 1.0D100)
     2          CP164_RU_PEQ_TERM_OK = 1
            RU(I) = RU(I) + TMP_RU
         END DO
      END DO

C --- material stiffness: KUU += Bu^T * D * Bu * dV
      DO I = 1, 8
         DO J = 1, 8
            DO A = 1, 3
               DO B = 1, 3
                  KUU(I,J) = KUU(I,J)
     1                      + BU(A,I) * DTAN(A,B) * BU(B,J) * DVOL
                END DO
            END DO
         END DO
      END DO

      IF (DBG_MECH_DECOMP) THEN
         IF (IGP .EQ. 1) THEN
            DBG_SUM_RU8_XX = 0.0D0
            DBG_SUM_RU8_YY = 0.0D0
            DBG_SUM_RU8_XY = 0.0D0
            DBG_SUM_RU8_TOT = 0.0D0
            DBG_SUM_K88 = 0.0D0
         END IF
         B8(1) = BU(1,8)
         B8(2) = BU(2,8)
         B8(3) = BU(3,8)
         RU8_XX_GP = DVOL * B8(1) * SIGEFF_GP(1)
         RU8_YY_GP = DVOL * B8(2) * SIGEFF_GP(2)
         RU8_XY_GP = DVOL * B8(3) * SIGEFF_GP(3)
         RU8_TOT_GP = RU8_XX_GP + RU8_YY_GP + RU8_XY_GP
         K88_GP = 0.0D0
         DO A = 1, 3
            DO B = 1, 3
               K88_GP = K88_GP + DVOL * B8(A) * DTAN(A,B) * B8(B)
            END DO
         END DO
         DBG_SUM_RU8_XX = DBG_SUM_RU8_XX + RU8_XX_GP
         DBG_SUM_RU8_YY = DBG_SUM_RU8_YY + RU8_YY_GP
         DBG_SUM_RU8_XY = DBG_SUM_RU8_XY + RU8_XY_GP
         DBG_SUM_RU8_TOT = DBG_SUM_RU8_TOT + RU8_TOT_GP
         DBG_SUM_K88 = DBG_SUM_K88 + K88_GP
         IUDBG = 98
         WRITE(IUDBG,*) '=== DBG_MECH: GP NODE4/U2 DECOMP ==='
         WRITE(IUDBG,*) 'JELEM=', JELEM, ' KSTEP=', KSTEP,
     1                  ' KINC=', KINC, ' IGP=', IGP
         WRITE(IUDBG,*) 'DVOL   = ', DVOL
         WRITE(IUDBG,*) 'B8     = ', B8(1), B8(2), B8(3)
         WRITE(IUDBG,*) 'SIGEFF = ', SIGEFF_GP(1), SIGEFF_GP(2),
     1                  SIGEFF_GP(3)
         WRITE(IUDBG,*) 'RU8_xx = ', RU8_XX_GP
         WRITE(IUDBG,*) 'RU8_yy = ', RU8_YY_GP
         WRITE(IUDBG,*) 'RU8_xy = ', RU8_XY_GP
         WRITE(IUDBG,*) 'RU8_tot= ', RU8_TOT_GP
         WRITE(IUDBG,*) 'K88_gp = ', K88_GP
         IF (IGP .EQ. 4) THEN
            WRITE(IUDBG,*) '=== DBG_MECH: GP NODE4/U2 SUM ==='
            WRITE(IUDBG,*) 'SUM_RU8_xx = ', DBG_SUM_RU8_XX
            WRITE(IUDBG,*) 'SUM_RU8_yy = ', DBG_SUM_RU8_YY
            WRITE(IUDBG,*) 'SUM_RU8_xy = ', DBG_SUM_RU8_XY
            WRITE(IUDBG,*) 'SUM_RU8_tot= ', DBG_SUM_RU8_TOT
            WRITE(IUDBG,*) 'SUM_K88_gp  = ', DBG_SUM_K88
            WRITE(IUDBG,*) 'RU(8)      = ', RU(8)
            WRITE(IUDBG,*) 'KUU(8,8)   = ', KUU(8,8)
         END IF
         CALL FLUSH(IUDBG)
      END IF

C --- coupling tangent wrt pw:
C     KUP += - Bu^T * alpha * m * (dpeq/dpw) * N * dV
      DO I = 1, 8
         DO J = 1, 4
            DO A = 1, 3
               KUP(I,J) = KUP(I,J)
     1                  - BU(A,I) * ALPHA_BIOT * VM(A)
     2                  * DPEQ_DPW_TAN_USE * N(J) * DVOL
            END DO
         END DO
      END DO

C --- coupling tangent wrt Sn:
C     KUS += - Bu^T * alpha * m * (dpeq/dsn) * N * dV
      DO I = 1, 8
         DO J = 1, 4
            DO A = 1, 3
               KUS(I,J) = KUS(I,J)
     1                  - BU(A,I) * ALPHA_BIOT * VM(A)
     2                  * DPEQ_DSN_TAN_USE * N(J) * DVOL
            END DO
         END DO
      END DO

      RF8_SIG_GP = 0.0D0
      RF8_PEQ_GP = 0.0D0
      RF8_PW_GP = 0.0D0
      RF8_CAP_GP = 0.0D0
      RF8_PEQ_RAW_GP = 0.0D0
      RF8_PEQ_USE_GP = 0.0D0
      RF8_PEQ_BIAS_GP = 0.0D0
      RF8_PEQ_REF_GP = 0.0D0
      DO A = 1, 3
         RF8_SIG_GP = RF8_SIG_GP + BU(A,8) * SIGEFF_GP(A) * DVOL
         RF8_PEQ_GP = RF8_PEQ_GP
     1              - BU(A,8) * ALPHA_BIOT * PEQ_FORCE_USE
     2              * VM(A) * DVOL
         RF8_PW_GP = RF8_PW_GP
     1              - BU(A,8) * ALPHA_BIOT * PW_GP * VM(A) * DVOL
         RF8_CAP_GP = RF8_CAP_GP
     1              - BU(A,8) * ALPHA_BIOT * (PEQ_GP - PW_GP)
     2              * VM(A) * DVOL
         RF8_PEQ_RAW_GP = RF8_PEQ_RAW_GP
     1              - BU(A,8) * ALPHA_BIOT * PEQ_GP * VM(A) * DVOL
         RF8_PEQ_USE_GP = RF8_PEQ_USE_GP
     1              - BU(A,8) * ALPHA_BIOT * PEQ_FORCE_USE
     2              * VM(A) * DVOL
         RF8_PEQ_REF_GP = RF8_PEQ_REF_GP
     1              - BU(A,8) * ALPHA_BIOT * PEQ_REF * VM(A) * DVOL
      END DO
      RF8_PEQ_BIAS_GP = RF8_PEQ_USE_GP - RF8_PEQ_RAW_GP
      RF8_TOT_GP = RF8_SIG_GP + RF8_PEQ_GP

      IF (DBG_MECH_DECOMP) THEN
         IF (IGP .EQ. 1) THEN
            DBG_SUM_RF8_SIG = 0.0D0
            DBG_SUM_RF8_PEQ = 0.0D0
            DBG_SUM_RF8_TOT = 0.0D0
            DBG_SUM_RF8_PW = 0.0D0
            DBG_SUM_RF8_CAP = 0.0D0
            DBG_SUM_RF8_PEQ_RAW = 0.0D0
            DBG_SUM_RF8_PEQ_USE = 0.0D0
            DBG_SUM_RF8_PEQ_BIAS = 0.0D0
            DBG_SUM_RF8_PEQ_REF = 0.0D0
         END IF
         DBG_SUM_RF8_SIG = DBG_SUM_RF8_SIG + RF8_SIG_GP
         DBG_SUM_RF8_PEQ = DBG_SUM_RF8_PEQ + RF8_PEQ_GP
         DBG_SUM_RF8_TOT = DBG_SUM_RF8_TOT + RF8_TOT_GP
         DBG_SUM_RF8_PW = DBG_SUM_RF8_PW + RF8_PW_GP
         DBG_SUM_RF8_CAP = DBG_SUM_RF8_CAP + RF8_CAP_GP
         DBG_SUM_RF8_PEQ_RAW = DBG_SUM_RF8_PEQ_RAW + RF8_PEQ_RAW_GP
         DBG_SUM_RF8_PEQ_USE = DBG_SUM_RF8_PEQ_USE + RF8_PEQ_USE_GP
         DBG_SUM_RF8_PEQ_BIAS = DBG_SUM_RF8_PEQ_BIAS + RF8_PEQ_BIAS_GP
         DBG_SUM_RF8_PEQ_REF = DBG_SUM_RF8_PEQ_REF + RF8_PEQ_REF_GP
         IF (IGP .EQ. 4) THEN
            WRITE(IUDBG,*) '=== DBG_MECH: GP NODE4/U2 SOURCE ==='
            WRITE(IUDBG,*) 'PEQ_ZERO = ', DBG_R1B_PEQ_ZERO
            WRITE(IUDBG,*) 'PEQ_REF  = ', PEQ_REF
            WRITE(IUDBG,*) 'PW_GP        = ', PW_GP
            WRITE(IUDBG,*) 'PEQ_GP(raw)  = ', PEQ_GP
            WRITE(IUDBG,*) 'PEQ_USE      = ', PEQ_USE
            WRITE(IUDBG,*) 'RF8_sig_gp = ', RF8_SIG_GP
            WRITE(IUDBG,*) 'RF8_pw_gp   = ', RF8_PW_GP
            WRITE(IUDBG,*) 'RF8_cap_gp  = ', RF8_CAP_GP
            WRITE(IUDBG,*) 'RF8_peq_raw = ', RF8_PEQ_RAW_GP
            WRITE(IUDBG,*) 'RF8_peq_use = ', RF8_PEQ_USE_GP
            WRITE(IUDBG,*) 'RF8_peq_ref = ', RF8_PEQ_REF_GP
            WRITE(IUDBG,*) 'RF8_peq_bias= ', RF8_PEQ_BIAS_GP
            WRITE(IUDBG,*) 'RF8_peq_gp = ', RF8_PEQ_GP
            WRITE(IUDBG,*) 'RF8_tot_gp = ', RF8_TOT_GP
            WRITE(IUDBG,*) 'SUM_RF8_sig = ', DBG_SUM_RF8_SIG
            WRITE(IUDBG,*) 'SUM_RF8_pw  = ', DBG_SUM_RF8_PW
            WRITE(IUDBG,*) 'SUM_RF8_cap = ', DBG_SUM_RF8_CAP
            WRITE(IUDBG,*) 'SUM_RF8_peq_raw = ', DBG_SUM_RF8_PEQ_RAW
            WRITE(IUDBG,*) 'SUM_RF8_peq_use = ', DBG_SUM_RF8_PEQ_USE
            WRITE(IUDBG,*) 'SUM_RF8_peq_ref = ', DBG_SUM_RF8_PEQ_REF
            WRITE(IUDBG,*) 'SUM_RF8_peq_bias= ', DBG_SUM_RF8_PEQ_BIAS
            WRITE(IUDBG,*) 'SUM_RF8_peq = ', DBG_SUM_RF8_PEQ
            WRITE(IUDBG,*) 'SUM_RF8_tot = ', DBG_SUM_RF8_TOT
            WRITE(IUDBG,*) 'RU(8)       = ', RU(8)
         END IF
      END IF

      CP165_RU_EXIT_HIT = 1

      RETURN
      END


C ================================================================
C Assemble pw-block from the minimal pressure-form weak form
C ================================================================
C This routine implements the first physically meaningful wetting-phase
C pressure block:
C   S_pw * (pw - pw_old)/dt - div(lambda_w grad(pw)) = 0
C
C The storage term uses an equivalent constant storage coefficient
C STORW, while the diffusion term uses lambda_w = k * krw / mu_w.
C The first saturation coupling is retained through the derivative of
C lambda_w with respect to Sn, which contributes the KPS block. The
C first volumetric-strain coupling is retained through a Biot-type
C storage contribution, which contributes the KPU block.
C
C This is intentionally kept pressure-centric so that the pressure
C block can be validated independently before the remaining two-phase
C couplings are introduced.
      SUBROUTINE UPS_ASSEMBLE_RP_KP(WT, DETJ, DTIME,
     1 JELEM, KSTEP, KINC,
     2 N, DNX, DNY, BU,
     3 PW_GP, PW_OLD, GPW, PW_REF,
     4 EPSV_GP, EPSV_OLD,
     5 KABS_GP, DK_DU, KRW_GP, DKRW_DSN, PROPS,
     6 RP, KPU, KPP, KPS,
     7 CP164_RP_RES_TERM_OK,
     8 CP164_RP_PRESS_GRAD_TERM_OK,
     9 CP164_RP_MOBILITY_FLUX_TERM_OK,
     1 CP164_KABS_PERM_TERM_OK,
     2 CP165_RP_ENTER_HIT, CP165_RP_EXIT_HIT,
     3 CP165_RP_DUMMY_HIT)
      IMPLICIT NONE
      INTEGER I, J, A, JELEM, KSTEP, KINC
      INTEGER CP164_RP_RES_TERM_OK
      INTEGER CP164_RP_PRESS_GRAD_TERM_OK
      INTEGER CP164_RP_MOBILITY_FLUX_TERM_OK
      INTEGER CP164_KABS_PERM_TERM_OK
      INTEGER CP165_RP_ENTER_HIT, CP165_RP_EXIT_HIT
      INTEGER CP165_RP_DUMMY_HIT
      DOUBLE PRECISION WT, DETJ, DTIME
      DOUBLE PRECISION N(4), DNX(4), DNY(4), BU(3,8)
      DOUBLE PRECISION PW_GP, PW_OLD, GPW(2), PW_REF
      DOUBLE PRECISION EPSV_GP, EPSV_OLD
      DOUBLE PRECISION KABS_GP, DK_DU(8), KRW_GP, DKRW_DSN, PROPS(*)
      DOUBLE PRECISION RP(4), KPU(4,8), KPP(4,4), KPS(4,4)
      DOUBLE PRECISION STORW, MU_W, LAMW, DLAMW_DSN, DLAMW_DU
      DOUBLE PRECISION DVOL, DPDT, DEPSVDT
      DOUBLE PRECISION CP164_TERM
      DOUBLE PRECISION ALPHA_BIOT, VM(3)
      DOUBLE PRECISION DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG
      DOUBLE PRECISION DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX
      DOUBLE PRECISION DBG_SE_MIN, DBG_SN_SEED
      DOUBLE PRECISION DBG_P_REG_SCALE, DBG_S_REG_SCALE
      DOUBLE PRECISION DBG_GUARD_NONFINITE
      DOUBLE PRECISION DBG_LOC_MINIMAL
      DOUBLE PRECISION DBG_FIELD_CAPACITY_REG
      DOUBLE PRECISION DBG_FIELD_CAPACITY_ETA
      DOUBLE PRECISION DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG
      DOUBLE PRECISION DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA
      DOUBLE PRECISION DBG_FIELD_ANCHOR_REG
      DOUBLE PRECISION DBG_FIELD_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG
      DOUBLE PRECISION DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM
      DOUBLE PRECISION DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF
      DOUBLE PRECISION DBG_AUDIT_MODE_CODE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      COMMON /UPS_DIAG_CTRL/ DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG,
     1 DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX, DBG_SE_MIN,
     2 DBG_SN_SEED, DBG_P_REG_SCALE, DBG_S_REG_SCALE,
     3 DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL,
     4 DBG_FIELD_CAPACITY_REG, DBG_FIELD_CAPACITY_ETA,
     5 DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG,
     6 DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA,
     7 DBG_FIELD_ANCHOR_REG, DBG_FIELD_ANCHOR_ETA,
     8 DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG,
     9 DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA,
     1 DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM,
     2 DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF,
     3 DBG_AUDIT_MODE_CODE,
     4 DBG_FIELD_CAPACITY_AUDIT_RP_DONE,
     5 DBG_FIELD_CAPACITY_AUDIT_RS_DONE,
     6 DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP,
     7 DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP,
     8 DBG_FIELD_ANCHOR_AUDIT_RP_DONE,
     9 DBG_FIELD_ANCHOR_AUDIT_RS_DONE,
     1 DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP,
     2 DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      LOGICAL HAS_TIME_TERMS
      DOUBLE PRECISION DTIME_MIN
      DOUBLE PRECISION DTIME_EFF
      PARAMETER (DTIME_MIN=1.0D-12)
      LOGICAL DTIME_GUARD_PRINTED_RP
      LOGICAL FIELD_CAPACITY_AUDIT_PRINTED_RP
      DOUBLE PRECISION REG_P_EPS, CAP_P_EPS
      DOUBLE PRECISION CAP_P_ANCHOR_EPS, KPP_CAP_FROB
      DOUBLE PRECISION KPP_ANCHOR_FROB
      SAVE DTIME_GUARD_PRINTED_RP
      SAVE FIELD_CAPACITY_AUDIT_PRINTED_RP
      DATA DTIME_GUARD_PRINTED_RP /.FALSE./
      DATA FIELD_CAPACITY_AUDIT_PRINTED_RP /.FALSE./

      CP165_RP_ENTER_HIT = 1
      CP165_RP_DUMMY_HIT = 1

C --- read pressure-block material parameters
C PROPS(4) = STORW0
C PROPS(5) = MU_W0
C PROPS(3) = ALPHA_BIOT
      STORW = PROPS(4)
      MU_W  = PROPS(5)
      ALPHA_BIOT = PROPS(3)

      VM(1) = 1.0D0
      VM(2) = 1.0D0
      VM(3) = 0.0D0

C --- current Gauss-point volume weight
      DVOL = WT * DETJ
      HAS_TIME_TERMS = .TRUE.
      DTIME_EFF = DTIME
      IF (DTIME .LE. DTIME_MIN) THEN
         DTIME_EFF = DTIME_MIN
         IF (.NOT. DTIME_GUARD_PRINTED_RP) THEN
            WRITE(*,*) 'DTIME_GUARD ACTIVE (clamped): JELEM=', JELEM,
     1                 ' KSTEP=', KSTEP, ' KINC=', KINC,
     2                 ' DTIME=', DTIME,
     3                 ' DTIME_EFF=', DTIME_EFF
            DTIME_GUARD_PRINTED_RP = .TRUE.
         END IF
      END IF

      DPDT = (PW_GP - PW_OLD) / DTIME_EFF
      DEPSVDT = (EPSV_GP - EPSV_OLD) / DTIME_EFF

C --- wetting-phase mobility coefficient
      LAMW = KABS_GP * KRW_GP / MU_W

C --- derivative of mobility wrt Sn
C     current stage: k and mu_w treated as constants wrt Sn
      DLAMW_DSN = KABS_GP * DKRW_DSN / MU_W
      IF (KABS_GP .EQ. KABS_GP .AND.
     1    DABS(KABS_GP) .LE. 1.0D100 .AND.
     2    KABS_GP .GT. 0.0D0) CP164_KABS_PERM_TERM_OK = 1

      IF (HAS_TIME_TERMS) THEN
C ============================================================
C 1. Storage residual:
C    RP += N^T * STORW * (pw - pw_old)/dt * dV
C ============================================================
         DO I = 1, 4
            CP164_TERM = N(I) * STORW * DPDT * DVOL
            IF (CP164_TERM .EQ. CP164_TERM .AND.
     1          DABS(CP164_TERM) .LE. 1.0D100)
     2          CP164_RP_RES_TERM_OK = 1
            RP(I) = RP(I) + CP164_TERM
         END DO

C ============================================================
C 2. Storage tangent:
C    KPP += N^T * STORW/dt * N * dV
C ============================================================
         DO I = 1, 4
            DO J = 1, 4
               KPP(I,J) = KPP(I,J)
     1                  + N(I) * (STORW/DTIME_EFF) * N(J) * DVOL
            END DO
         END DO

C ============================================================
C 3. Volumetric-strain coupling residual:
C    RP += N^T * alpha * (epsv - epsv_old)/dt * dV
C ============================================================
         DO I = 1, 4
            CP164_TERM = N(I) * ALPHA_BIOT * DEPSVDT * DVOL
            IF (CP164_TERM .EQ. CP164_TERM .AND.
     1          DABS(CP164_TERM) .LE. 1.0D100)
     2          CP164_RP_RES_TERM_OK = 1
            RP(I) = RP(I) + CP164_TERM
         END DO

C ============================================================
C 4. KPU from volumetric-strain rate term:
C    KPU += N^T * alpha/dt * (m^T * Bu) * dV
C ============================================================
         DO I = 1, 4
            DO J = 1, 8
               DO A = 1, 3
                  KPU(I,J) = KPU(I,J)
     1                     + N(I) * (ALPHA_BIOT/DTIME_EFF)
     2                     * VM(A) * BU(A,J) * DVOL
               END DO
            END DO
         END DO
      END IF

C ============================================================
C 5. Diffusion residual:
C    RP += Bp^T * LAMW * grad(pw) * dV
C ============================================================
      DO I = 1, 4
         CP164_TERM = ( DNX(I)*LAMW*GPW(1)
     1           + DNY(I)*LAMW*GPW(2) ) * DVOL
         IF (CP164_TERM .EQ. CP164_TERM .AND.
     1       DABS(CP164_TERM) .LE. 1.0D100) THEN
            CP164_RP_PRESS_GRAD_TERM_OK = 1
            CP164_RP_MOBILITY_FLUX_TERM_OK = 1
         END IF
         RP(I) = RP(I) + CP164_TERM
      END DO

C ============================================================
C WP10-I1. Stress-permeability contribution to KPU:
C   d(lambda_w)/du_j = krw/mu_w * dKabs/du_j
C ============================================================
      DO I = 1, 4
         DO J = 1, 8
            DLAMW_DU = KRW_GP * DK_DU(J) / MU_W
            KPU(I,J) = KPU(I,J)
     1               + ( DNX(I) * DLAMW_DU * GPW(1)
     2                 + DNY(I) * DLAMW_DU * GPW(2) ) * DVOL
         END DO
      END DO

C 6. Diffusion tangent:
C    KPP += Bp^T * LAMW * Bp * dV
C ============================================================
      DO I = 1, 4
         DO J = 1, 4
            KPP(I,J) = KPP(I,J)
     1               + LAMW
     2               * ( DNX(I)*DNX(J) + DNY(I)*DNY(J) )
     3               * DVOL
          END DO
      END DO

C ============================================================
C 7. Saturation coupling tangent:
C    KPS += Bp^T * (dLAMW/dSn) * Ns * grad(pw) * dV
C ============================================================
      DO I = 1, 4
         DO J = 1, 4
            KPS(I,J) = KPS(I,J)
     1               + ( DNX(I) * DLAMW_DSN * N(J) * GPW(1)
     2                 + DNY(I) * DLAMW_DSN * N(J) * GPW(2) )
     3               * DVOL
         END DO
      END DO

C ============================================================
C 8. Consistent capacity support for pressure block
C    eps_p = eta_p * STORW / DTIME
C    Rp_cap = int N_a eps_p (pw - pw_old) dV
C    Kpp_cap = int N_a eps_p N_b dV
C    Here STORW is the storage coefficient (phi * c_t).
C ============================================================
      IF (DBG_P_CAPACITY_REG .GT. 0.5D0 .AND. HAS_TIME_TERMS
     1    .AND. DTIME .GT. 0.0D0) THEN
         CAP_P_EPS = DBG_P_CAPACITY_ETA * STORW / DTIME
         IF (CAP_P_EPS .GT. 0.0D0) THEN
            KPP_CAP_FROB = 0.0D0
            DO I = 1, 4
               RP(I) = RP(I)
     1               + N(I) * CAP_P_EPS * (PW_GP - PW_OLD) * DVOL
               DO J = 1, 4
                  KPP(I,J) = KPP(I,J)
     1                     + N(I) * CAP_P_EPS * N(J) * DVOL
                  KPP_CAP_FROB = KPP_CAP_FROB
     1                         + (N(I) * CAP_P_EPS * N(J) * DVOL)**2
               END DO
            END DO
            KPP_CAP_FROB = DSQRT(KPP_CAP_FROB)
            IF (DBG_AUDIT_MODE_CODE .GT. 0.5D0) THEN
               IF (DBG_AUDIT_MODE_CODE .LT. 1.5D0) THEN
                  IF (DBG_FIELD_CAPACITY_AUDIT_RP_DONE .LT. 0.5D0) THEN
               WRITE(*,*) 'FIELD_CAPACITY_G1_ACTIVE = 1'
               WRITE(*,*) 'DBG_FIELD_CAPACITY_REG = ',
     1              DBG_FIELD_CAPACITY_REG
               WRITE(*,*) 'DBG_FIELD_CAPACITY_ETA = ',
     1              DBG_FIELD_CAPACITY_ETA
               WRITE(*,*) 'DBG_P_CAPACITY_ETA     = ',
     1              DBG_P_CAPACITY_ETA
               WRITE(*,*) 'DTIME                  = ', DTIME
               WRITE(*,*) 'STORW                  = ', STORW
               WRITE(*,*) 'PW_GP                  = ', PW_GP
               WRITE(*,*) 'PW_OLD                 = ', PW_OLD
               WRITE(*,*) 'CAP_P_EPS              = ', CAP_P_EPS
               WRITE(*,*) '||Kpp_cap||_F          = ', KPP_CAP_FROB
                     DBG_FIELD_CAPACITY_AUDIT_RP_DONE = 1.0D0
                  END IF
               ELSE IF (KINC .EQ. 1) THEN
                  WRITE(*,*) 'FIELD_CAPACITY_G1_ACTIVE = 1'
                  WRITE(*,*) 'DBG_FIELD_CAPACITY_REG = ',
     1                 DBG_FIELD_CAPACITY_REG
                  WRITE(*,*) 'DBG_FIELD_CAPACITY_ETA = ',
     1                 DBG_FIELD_CAPACITY_ETA
                  WRITE(*,*) 'DBG_P_CAPACITY_ETA     = ',
     1                 DBG_P_CAPACITY_ETA
                  WRITE(*,*) 'DTIME                  = ', DTIME
                  WRITE(*,*) 'STORW                  = ', STORW
                  WRITE(*,*) 'PW_GP                  = ', PW_GP
                  WRITE(*,*) 'PW_OLD                 = ', PW_OLD
                  WRITE(*,*) 'CAP_P_EPS              = ', CAP_P_EPS
                  WRITE(*,*) '||Kpp_cap||_F          = ', KPP_CAP_FROB
               END IF
            END IF
         END IF
      END IF

C ============================================================
C 8b. Soft anchor support for pressure block
C     eps_p_anchor = eta_p_anchor * STORW / DTIME
C     Rp_anchor = int N_a eps_p_anchor (pw - pw_ref) dV
C     Kpp_anchor = int N_a eps_p_anchor N_b dV
C ============================================================
      IF (DBG_P_ANCHOR_REG .GT. 0.5D0 .AND. HAS_TIME_TERMS
     1    .AND. DTIME .GT. 0.0D0) THEN
         CAP_P_ANCHOR_EPS = DBG_P_ANCHOR_ETA * STORW / DTIME
         IF (CAP_P_ANCHOR_EPS .GT. 0.0D0) THEN
            KPP_ANCHOR_FROB = 0.0D0
            DO I = 1, 4
               RP(I) = RP(I)
     1               + N(I) * CAP_P_ANCHOR_EPS
     2               * (PW_GP - PW_REF) * DVOL
               DO J = 1, 4
                  KPP(I,J) = KPP(I,J)
     1                     + N(I) * CAP_P_ANCHOR_EPS * N(J) * DVOL
                  KPP_ANCHOR_FROB = KPP_ANCHOR_FROB
     1                         + (N(I) * CAP_P_ANCHOR_EPS
     2                         * N(J) * DVOL)**2
               END DO
            END DO
            KPP_ANCHOR_FROB = DSQRT(KPP_ANCHOR_FROB)
            IF (DBG_AUDIT_MODE_CODE .GT. 0.5D0) THEN
               IF (DBG_AUDIT_MODE_CODE .LT. 1.5D0) THEN
                  IF (DBG_FIELD_ANCHOR_AUDIT_RP_DONE .LT. 0.5D0) THEN
               WRITE(*,*) 'FIELD_ANCHOR_G2_ACTIVE = 1'
               WRITE(*,*) 'DBG_FIELD_ANCHOR_REG = ',
     1              DBG_FIELD_ANCHOR_REG
               WRITE(*,*) 'DBG_FIELD_ANCHOR_ETA = ',
     1              DBG_FIELD_ANCHOR_ETA
               WRITE(*,*) 'DBG_P_ANCHOR_ETA     = ',
     1              DBG_P_ANCHOR_ETA
               WRITE(*,*) 'DBG_P_ANCHOR_PTOP    = ',
     1              DBG_P_ANCHOR_PTOP
               WRITE(*,*) 'DBG_P_ANCHOR_PBOTTOM = ',
     1              DBG_P_ANCHOR_PBOTTOM
               WRITE(*,*) 'DBG_P_ANCHOR_H       = ',
     1              DBG_P_ANCHOR_H
               WRITE(*,*) 'PW_REF                = ', PW_REF
               WRITE(*,*) 'DTIME                  = ', DTIME
               WRITE(*,*) 'STORW                  = ', STORW
               WRITE(*,*) 'CAP_P_ANCHOR_EPS       = ',
     1              CAP_P_ANCHOR_EPS
               WRITE(*,*) '||Kpp_anchor||_F       = ',
     1              KPP_ANCHOR_FROB
                     DBG_FIELD_ANCHOR_AUDIT_RP_DONE = 1.0D0
                  END IF
               ELSE IF (KINC .EQ. 1) THEN
                  WRITE(*,*) 'FIELD_ANCHOR_G2_ACTIVE = 1'
                  WRITE(*,*) 'DBG_FIELD_ANCHOR_REG = ',
     1                 DBG_FIELD_ANCHOR_REG
                  WRITE(*,*) 'DBG_FIELD_ANCHOR_ETA = ',
     1                 DBG_FIELD_ANCHOR_ETA
                  WRITE(*,*) 'DBG_P_ANCHOR_ETA     = ',
     1                 DBG_P_ANCHOR_ETA
                  WRITE(*,*) 'DBG_P_ANCHOR_PTOP    = ',
     1                 DBG_P_ANCHOR_PTOP
                  WRITE(*,*) 'DBG_P_ANCHOR_PBOTTOM = ',
     1                 DBG_P_ANCHOR_PBOTTOM
                  WRITE(*,*) 'DBG_P_ANCHOR_H       = ',
     1                 DBG_P_ANCHOR_H
                  WRITE(*,*) 'PW_REF                = ', PW_REF
                  WRITE(*,*) 'DTIME                  = ', DTIME
                  WRITE(*,*) 'STORW                  = ', STORW
                  WRITE(*,*) 'CAP_P_ANCHOR_EPS       = ',
     1                 CAP_P_ANCHOR_EPS
                  WRITE(*,*) '||Kpp_anchor||_F       = ',
     1                 KPP_ANCHOR_FROB
               END IF
            END IF
         END IF
      END IF

C ============================================================
C 9. Weak diagonal regularization for pressure block
C    Rp_reg = eps_p * (pw - pw_old)
C    Kpp_reg = Kpp + eps_p * I
C ============================================================
      IF (DBG_REG_P_DIAG .GT. 0.5D0 .AND. HAS_TIME_TERMS) THEN
         REG_P_EPS = DBG_P_REG_SCALE * STORW / DTIME
         DO I = 1, 4
            RP(I) = RP(I) + REG_P_EPS * (PW_GP - PW_OLD) * DVOL
            KPP(I,I) = KPP(I,I) + REG_P_EPS * DVOL
         END DO
      END IF

      CP165_RP_EXIT_HIT = 1

      RETURN
      END


C ================================================================
C Assemble Sn-block from the minimal storage-form weak form
C ================================================================
C This routine now implements the first physically meaningful saturation
C block using:
C   - a time-storage term
C   - a first volumetric-strain coupling through KSU
C   - the minimal non-wetting flux term
C
C The storage coefficient is still treated as the simple equivalent
C quantity C_sn = phi * rho_n in this development stage. The volumetric-
C strain coupling is added in the explicit Biot-like form so that KSU
C can be validated independently before any more complex transport or
C permeability-strain couplings are introduced.
      SUBROUTINE UPS_ASSEMBLE_RS_KS(WT, DETJ, DTIME,
     1 JELEM, KSTEP, KINC,
     2 N, DNX, DNY, BU,
     3 GPW, SN_REF,
     4 SN_GP, SN_OLD, GSN, DSN_GP_DSN,
     5 EPSV_GP, EPSV_OLD,
     6 PHI_GP, KABS_GP, DK_DU, KRN_GP,
     7 DPC_DSN, D2PC_DSN2, DKRN_DSN, PROPS,
     8 RS, KSU, KSP, KSS,
     9 CP164_RS_RES_TERM_OK,
     1 CP164_RS_SAT_FLUX_TERM_OK,
     2 CP164_KABS_PERM_TERM_OK,
     3 CP165_RS_ENTER_HIT, CP165_RS_EXIT_HIT,
     4 CP165_RS_DUMMY_HIT)
      IMPLICIT NONE
      INTEGER I, J, A, JELEM, KSTEP, KINC
      INTEGER CP164_RS_RES_TERM_OK
      INTEGER CP164_RS_SAT_FLUX_TERM_OK
      INTEGER CP164_KABS_PERM_TERM_OK
      INTEGER CP165_RS_ENTER_HIT, CP165_RS_EXIT_HIT
      INTEGER CP165_RS_DUMMY_HIT
      DOUBLE PRECISION WT, DETJ, DTIME
      DOUBLE PRECISION N(4), DNX(4), DNY(4), BU(3,8)
      DOUBLE PRECISION GPW(2), GSN(2), DSN_GP_DSN
      DOUBLE PRECISION SN_REF, SN_GP, SN_OLD
      DOUBLE PRECISION EPSV_GP, EPSV_OLD
      DOUBLE PRECISION PHI_GP, KABS_GP, DK_DU(8), KRN_GP
      DOUBLE PRECISION DPC_DSN, D2PC_DSN2, DKRN_DSN, PROPS(*)
      DOUBLE PRECISION RS(4), KSU(4,8), KSP(4,4), KSS(4,4)
      DOUBLE PRECISION RHON, MU_N, BETA_PHI
      DOUBLE PRECISION CSN
      DOUBLE PRECISION LAMN, DLAMN_DSN, DLAMN_DU
      DOUBLE PRECISION DVOL, DSDT, DEPSVDT
      DOUBLE PRECISION CP164_TERM
      DOUBLE PRECISION GPC(2), GTOT(2)
      DOUBLE PRECISION VM(3)
      DOUBLE PRECISION DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG
      DOUBLE PRECISION DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX
      DOUBLE PRECISION DBG_SE_MIN, DBG_SN_SEED
      DOUBLE PRECISION DBG_P_REG_SCALE, DBG_S_REG_SCALE
      DOUBLE PRECISION DBG_GUARD_NONFINITE
      DOUBLE PRECISION DBG_LOC_MINIMAL
      DOUBLE PRECISION DBG_FIELD_CAPACITY_REG
      DOUBLE PRECISION DBG_FIELD_CAPACITY_ETA
      DOUBLE PRECISION DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG
      DOUBLE PRECISION DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA
      DOUBLE PRECISION DBG_FIELD_ANCHOR_REG
      DOUBLE PRECISION DBG_FIELD_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG
      DOUBLE PRECISION DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA
      DOUBLE PRECISION DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM
      DOUBLE PRECISION DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF
      DOUBLE PRECISION DBG_AUDIT_MODE_CODE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_DONE
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP
      DOUBLE PRECISION DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      COMMON /UPS_DIAG_CTRL/ DBG_SN_BOUNDS_ON, DBG_REG_P_DIAG,
     1 DBG_REG_S_DIAG, DBG_SN_MIN, DBG_SN_MAX, DBG_SE_MIN,
     2 DBG_SN_SEED, DBG_P_REG_SCALE, DBG_S_REG_SCALE,
     3 DBG_GUARD_NONFINITE, DBG_LOC_MINIMAL,
     4 DBG_FIELD_CAPACITY_REG, DBG_FIELD_CAPACITY_ETA,
     5 DBG_P_CAPACITY_REG, DBG_S_CAPACITY_REG,
     6 DBG_P_CAPACITY_ETA, DBG_S_CAPACITY_ETA,
     7 DBG_FIELD_ANCHOR_REG, DBG_FIELD_ANCHOR_ETA,
     8 DBG_P_ANCHOR_REG, DBG_S_ANCHOR_REG,
     9 DBG_P_ANCHOR_ETA, DBG_S_ANCHOR_ETA,
     1 DBG_P_ANCHOR_PTOP, DBG_P_ANCHOR_PBOTTOM,
     2 DBG_P_ANCHOR_H, DBG_S_ANCHOR_SNREF,
     3 DBG_AUDIT_MODE_CODE,
     4 DBG_FIELD_CAPACITY_AUDIT_RP_DONE,
     5 DBG_FIELD_CAPACITY_AUDIT_RS_DONE,
     6 DBG_FIELD_CAPACITY_AUDIT_RP_LAST_STEP,
     7 DBG_FIELD_CAPACITY_AUDIT_RS_LAST_STEP,
     8 DBG_FIELD_ANCHOR_AUDIT_RP_DONE,
     9 DBG_FIELD_ANCHOR_AUDIT_RS_DONE,
     1 DBG_FIELD_ANCHOR_AUDIT_RP_LAST_STEP,
     2 DBG_FIELD_ANCHOR_AUDIT_RS_LAST_STEP
      LOGICAL HAS_TIME_TERMS
      DOUBLE PRECISION DTIME_MIN
      DOUBLE PRECISION DTIME_EFF
      DOUBLE PRECISION DBG_RAW_SN_JUMP_REG
      DOUBLE PRECISION DBG_RAW_SN_JUMP_TOL
      DOUBLE PRECISION DBG_RAW_SN_JUMP_BETA_MIN
      DOUBLE PRECISION RAW_SN_DELTA, RAW_SN_BETA, SN_GP_RAW_USE
      DOUBLE PRECISION DSN_RAW_USE_DSN, RAW_SN_BRANCH_DISTANCE
      DOUBLE PRECISION KSS_TERM
      CHARACTER*32 DBG_RAW_SN_JUMP_REG_TAG
      CHARACTER*32 DBG_RAW_SN_JUMP_TOL_TAG
      CHARACTER*32 DBG_RAW_SN_JUMP_BETA_TAG
      INTEGER IOS_RAW_SN, RAW_SN_BRANCH_ID, RAW_SN_SWITCH_FLAG
      PARAMETER (DTIME_MIN=1.0D-12)
      LOGICAL DTIME_GUARD_PRINTED_RS
      LOGICAL RAW_SN_JUMP_AUDIT_PRINTED_RS
      LOGICAL FIELD_CAPACITY_AUDIT_PRINTED_RS
      DOUBLE PRECISION REG_S_EPS, CAP_S_EPS
      DOUBLE PRECISION CAP_S_ANCHOR_EPS, KSS_CAP_FROB
      DOUBLE PRECISION KSS_ANCHOR_FROB
      DOUBLE PRECISION WP10I3_KSS_STORAGE(4,4)
      DOUBLE PRECISION WP10I3_KSS_STRAIN(4,4)
      DOUBLE PRECISION WP10I3_KSS_MOBILITY(4,4)
      DOUBLE PRECISION WP10I3_KSS_PC_FIRST(4,4)
      DOUBLE PRECISION WP10I3_KSS_PC_SECOND(4,4)
      DOUBLE PRECISION WP10I3_KSS_CAPACITY(4,4)
      DOUBLE PRECISION WP10I3_KSS_ANCHOR(4,4)
      DOUBLE PRECISION WP10I3_KSS_DIAG(4,4)
      COMMON /WP10I3_KSS_AUDIT/ WP10I3_KSS_STORAGE,
     1 WP10I3_KSS_STRAIN, WP10I3_KSS_MOBILITY,
     2 WP10I3_KSS_PC_FIRST, WP10I3_KSS_PC_SECOND,
     3 WP10I3_KSS_CAPACITY, WP10I3_KSS_ANCHOR,
     4 WP10I3_KSS_DIAG
      SAVE DTIME_GUARD_PRINTED_RS
      SAVE RAW_SN_JUMP_AUDIT_PRINTED_RS
      SAVE FIELD_CAPACITY_AUDIT_PRINTED_RS
      DATA DTIME_GUARD_PRINTED_RS /.FALSE./
      DATA RAW_SN_JUMP_AUDIT_PRINTED_RS /.FALSE./
      DATA FIELD_CAPACITY_AUDIT_PRINTED_RS /.FALSE./

      CP165_RS_ENTER_HIT = 1
      CP165_RS_DUMMY_HIT = 1

C --- raw saturation update regularization for front-jump diagnostics.
C     This acts on the Sn storage/update path, not only on peq mechanics.
      DBG_RAW_SN_JUMP_REG = 0.0D0
      DBG_RAW_SN_JUMP_TOL = 5.0D-2
      DBG_RAW_SN_JUMP_BETA_MIN = 5.0D-2

      CALL GET_ENVIRONMENT_VARIABLE('DBG_RAW_SN_JUMP_REG',
     1                              DBG_RAW_SN_JUMP_REG_TAG)
      IF (LEN_TRIM(DBG_RAW_SN_JUMP_REG_TAG) .GT. 0) THEN
         READ(DBG_RAW_SN_JUMP_REG_TAG,*,IOSTAT=IOS_RAW_SN)
     1        DBG_RAW_SN_JUMP_REG
         IF (IOS_RAW_SN .NE. 0) DBG_RAW_SN_JUMP_REG = 0.0D0
      END IF

      CALL GET_ENVIRONMENT_VARIABLE('DBG_RAW_SN_JUMP_TOL',
     1                              DBG_RAW_SN_JUMP_TOL_TAG)
      IF (LEN_TRIM(DBG_RAW_SN_JUMP_TOL_TAG) .GT. 0) THEN
         READ(DBG_RAW_SN_JUMP_TOL_TAG,*,IOSTAT=IOS_RAW_SN)
     1        DBG_RAW_SN_JUMP_TOL
         IF (IOS_RAW_SN .NE. 0) DBG_RAW_SN_JUMP_TOL = 5.0D-2
      END IF

      CALL GET_ENVIRONMENT_VARIABLE('DBG_RAW_SN_JUMP_BETA_MIN',
     1                              DBG_RAW_SN_JUMP_BETA_TAG)
      IF (LEN_TRIM(DBG_RAW_SN_JUMP_BETA_TAG) .GT. 0) THEN
         READ(DBG_RAW_SN_JUMP_BETA_TAG,*,IOSTAT=IOS_RAW_SN)
     1        DBG_RAW_SN_JUMP_BETA_MIN
         IF (IOS_RAW_SN .NE. 0) DBG_RAW_SN_JUMP_BETA_MIN = 5.0D-2
      END IF

      IF (DBG_RAW_SN_JUMP_TOL .LE. 0.0D0)
     1   DBG_RAW_SN_JUMP_TOL = 5.0D-2
      IF (DBG_RAW_SN_JUMP_BETA_MIN .LT. 0.0D0)
     1   DBG_RAW_SN_JUMP_BETA_MIN = 0.0D0
      IF (DBG_RAW_SN_JUMP_BETA_MIN .GT. 1.0D0)
     1   DBG_RAW_SN_JUMP_BETA_MIN = 1.0D0

C --- non-wetting phase density (constant in this stage)
C PROPS(6) = RHO_N0
      RHON = PROPS(6)

C --- non-wetting phase viscosity (constant in this stage)
C PROPS(7) = MU_N0
      MU_N = PROPS(7)

C --- porosity-volumetric-strain coupling coefficient
C In this first validation stage we reuse the current Biot coefficient
C as a proxy so the development branch does not require a material-input
C reorder yet. If a dedicated coefficient is introduced later, this line
C can be switched to the new PROPS slot.
      BETA_PHI = PROPS(14)

      VM(1) = 1.0D0
      VM(2) = 1.0D0
      VM(3) = 0.0D0

C --- equivalent storage coefficient
      CSN = PHI_GP * RHON

C --- mobility coefficient
      LAMN = RHON * KABS_GP * KRN_GP / MU_N

C --- derivative of mobility wrt Sn
C     (current stage: k, rho_n, mu_n treated as constants)
      DLAMN_DSN = RHON * KABS_GP * DKRN_DSN / MU_N
      IF (KABS_GP .EQ. KABS_GP .AND.
     1    DABS(KABS_GP) .LE. 1.0D100 .AND.
     2    KABS_GP .GT. 0.0D0) CP164_KABS_PERM_TERM_OK = 1

C --- current Gauss-point volume weight
      DVOL = WT * DETJ
      HAS_TIME_TERMS = .TRUE.
      DTIME_EFF = DTIME
      IF (DTIME .LE. DTIME_MIN) THEN
         DTIME_EFF = DTIME_MIN
         IF (.NOT. DTIME_GUARD_PRINTED_RS) THEN
            WRITE(*,*) 'DTIME_GUARD ACTIVE (clamped): JELEM=', JELEM,
     1                 ' KSTEP=', KSTEP, ' KINC=', KINC,
     2                 ' DTIME=', DTIME,
     3                 ' DTIME_EFF=', DTIME_EFF
            DTIME_GUARD_PRINTED_RS = .TRUE.
         END IF
      END IF

      RAW_SN_DELTA = SN_GP - SN_OLD
      CALL UPS_EVAL_SN_RAW_USE_JET(SN_GP, SN_OLD,
     1 DBG_RAW_SN_JUMP_REG, DBG_RAW_SN_JUMP_TOL,
     2 DBG_RAW_SN_JUMP_BETA_MIN, SN_GP_RAW_USE, RAW_SN_BETA,
     3 DSN_RAW_USE_DSN, RAW_SN_BRANCH_ID,
     4 RAW_SN_BRANCH_DISTANCE, RAW_SN_SWITCH_FLAG)
      DSN_RAW_USE_DSN = DSN_RAW_USE_DSN * DSN_GP_DSN
      IF (DBG_RAW_SN_JUMP_REG .GT. 0.5D0 .AND.
     1    DABS(RAW_SN_DELTA) .GT. DBG_RAW_SN_JUMP_TOL) THEN
         IF (.NOT. RAW_SN_JUMP_AUDIT_PRINTED_RS) THEN
            WRITE(*,*) 'RAW_SN_JUMP_REG ACTIVE: JELEM=', JELEM,
     1                 ' KSTEP=', KSTEP, ' KINC=', KINC,
     2                 ' SN_OLD=', SN_OLD, ' SN_GP=', SN_GP,
     3                 ' DELTA=', RAW_SN_DELTA,
     4                 ' BETA=', RAW_SN_BETA
            RAW_SN_JUMP_AUDIT_PRINTED_RS = .TRUE.
         END IF
      END IF

      DSDT = (SN_GP_RAW_USE - SN_OLD) / DTIME_EFF
      DEPSVDT = (EPSV_GP - EPSV_OLD) / DTIME_EFF

      IF (HAS_TIME_TERMS) THEN
C ============================================================
C 1. Storage residual:
C    RS += N^T * CSN * (Sn - Sn_old)/dt * dV
C ============================================================
         DO I = 1, 4
            CP164_TERM = N(I) * CSN * DSDT * DVOL
            IF (CP164_TERM .EQ. CP164_TERM .AND.
     1          DABS(CP164_TERM) .LE. 1.0D100)
     2          CP164_RS_RES_TERM_OK = 1
            RS(I) = RS(I) + CP164_TERM
         END DO

C ============================================================
C 2. Volumetric-strain coupling residual:
C    RS += N^T * rho_n * Sn * beta_phi * (epsv - epsv_old)/dt * dV
C ============================================================
         DO I = 1, 4
            CP164_TERM = N(I) * RHON * SN_GP_RAW_USE
     1            * BETA_PHI * DEPSVDT * DVOL
            IF (CP164_TERM .EQ. CP164_TERM .AND.
     1          DABS(CP164_TERM) .LE. 1.0D100)
     2          CP164_RS_RES_TERM_OK = 1
            RS(I) = RS(I) + CP164_TERM
         END DO

C ============================================================
C 3. Storage and strain-saturation tangents.
C ============================================================
         DO I = 1, 4
            DO J = 1, 4
               KSS_TERM = N(I) * (CSN/DTIME_EFF)
     1                  * DSN_RAW_USE_DSN * N(J) * DVOL
               KSS(I,J) = KSS(I,J) + KSS_TERM
               WP10I3_KSS_STORAGE(I,J) =
     1            WP10I3_KSS_STORAGE(I,J) + KSS_TERM

               KSS_TERM = N(I) * RHON * BETA_PHI * DEPSVDT
     1                  * DSN_RAW_USE_DSN * N(J) * DVOL
               KSS(I,J) = KSS(I,J) + KSS_TERM
               WP10I3_KSS_STRAIN(I,J) =
     1            WP10I3_KSS_STRAIN(I,J) + KSS_TERM
            END DO
         END DO

C ============================================================
C 4. KSU from volumetric-strain coupling:
C    KSU += N^T * rho_n * Sn * beta_phi /dt * (m^T * Bu) * dV
C ============================================================
         DO I = 1, 4
            DO J = 1, 8
               DO A = 1, 3
                  KSU(I,J) = KSU(I,J)
     1                     + N(I) * RHON * SN_GP_RAW_USE * BETA_PHI
     2                     * (1.0D0/DTIME_EFF) * VM(A) * BU(A,J) * DVOL
               END DO
            END DO
         END DO
      END IF

C ============================================================
C 5. build grad(pc) and total driving gradient
C    grad(pc) = (dpc/dsn) * grad(sn)
C ============================================================
      GPC(1) = DPC_DSN * GSN(1)
      GPC(2) = DPC_DSN * GSN(2)

      GTOT(1) = GPW(1) + GPC(1)
      GTOT(2) = GPW(2) + GPC(2)

C ============================================================
C 6. flux residual
C    RS += Bs^T * lam_n * (grad(pw) + grad(pc)) * dV
C ============================================================
      DO I = 1, 4
         CP164_TERM = ( DNX(I) * LAMN * GTOT(1)
     1           + DNY(I) * LAMN * GTOT(2) ) * DVOL
         IF (CP164_TERM .EQ. CP164_TERM .AND.
     1       DABS(CP164_TERM) .LE. 1.0D100)
     2       CP164_RS_SAT_FLUX_TERM_OK = 1
         RS(I) = RS(I) + CP164_TERM
      END DO

C ============================================================
C WP10-I1. Stress-permeability contribution to KSU:
C   d(lambda_n)/du_j = rho_n*krn/mu_n * dKabs/du_j
C ============================================================
      DO I = 1, 4
         DO J = 1, 8
            DLAMN_DU = RHON * KRN_GP * DK_DU(J) / MU_N
            KSU(I,J) = KSU(I,J)
     1               + ( DNX(I) * DLAMN_DU * GTOT(1)
     2                 + DNY(I) * DLAMN_DU * GTOT(2) ) * DVOL
         END DO
      END DO

C 7. KSP : derivative wrt pw
C    Ksp += Bs^T * lam_n * Bp * dV
C ============================================================
      DO I = 1, 4
         DO J = 1, 4
            KSP(I,J) = KSP(I,J)
     1               + LAMN
     2               * ( DNX(I)*DNX(J) + DNY(I)*DNY(J) )
     3               * DVOL
         END DO
      END DO

C ============================================================
C 8. KSS level-1 : main capillary-gradient term
C    Kss^(1) += Bs^T * lam_n * (dpc/dsn) * Bs * dV
C ============================================================
      DO I = 1, 4
         DO J = 1, 4
            KSS_TERM = LAMN * DPC_DSN
     1               * (DNX(I)*DNX(J)+DNY(I)*DNY(J)) * DVOL
            KSS(I,J) = KSS(I,J) + KSS_TERM
            WP10I3_KSS_PC_FIRST(I,J) =
     1         WP10I3_KSS_PC_FIRST(I,J) + KSS_TERM
         END DO
      END DO

C ============================================================
C 9. KSS level-2 : mobility nonlinearity term
C    Kss^(2) += Bs^T * (dlam_n/dsn) * N_j * GTOT * dV
C ============================================================
      DO I = 1, 4
         DO J = 1, 4
            KSS_TERM = (DNX(I)*DLAMN_DSN*N(J)*GTOT(1)
     1               + DNY(I)*DLAMN_DSN*N(J)*GTOT(2)) * DVOL
            KSS(I,J) = KSS(I,J) + KSS_TERM
            WP10I3_KSS_MOBILITY(I,J) =
     1         WP10I3_KSS_MOBILITY(I,J) + KSS_TERM
         END DO
      END DO

C ============================================================
C 9b. KSS capillary-pressure curvature term.
C ============================================================
      DO I = 1, 4
         DO J = 1, 4
            KSS_TERM = LAMN * D2PC_DSN2 * N(J)
     1               * (DNX(I)*GSN(1)+DNY(I)*GSN(2)) * DVOL
            KSS(I,J) = KSS(I,J) + KSS_TERM
            WP10I3_KSS_PC_SECOND(I,J) =
     1         WP10I3_KSS_PC_SECOND(I,J) + KSS_TERM
         END DO
      END DO

C ============================================================
C 10. Consistent capacity support for saturation block
C     eps_s = eta_s * PHI_GP / DTIME
C     Rs_cap = int N_a eps_s (Sn - Sn_old) dV
C     Kss_cap = int N_a eps_s N_b dV
C ============================================================
      IF (DBG_S_CAPACITY_REG .GT. 0.5D0 .AND. HAS_TIME_TERMS
     1    .AND. DTIME .GT. 0.0D0) THEN
         CAP_S_EPS = DBG_S_CAPACITY_ETA * PHI_GP / DTIME
         IF (CAP_S_EPS .GT. 0.0D0) THEN
            KSS_CAP_FROB = 0.0D0
            DO I = 1, 4
               RS(I) = RS(I)
     1               + N(I) * CAP_S_EPS * (SN_GP - SN_OLD) * DVOL
               DO J = 1, 4
                  KSS_TERM = N(I) * CAP_S_EPS * N(J) * DVOL
                  KSS(I,J) = KSS(I,J) + KSS_TERM
                  WP10I3_KSS_CAPACITY(I,J) =
     1               WP10I3_KSS_CAPACITY(I,J) + KSS_TERM
                  KSS_CAP_FROB = KSS_CAP_FROB
     1                         + KSS_TERM**2
               END DO
            END DO
            KSS_CAP_FROB = DSQRT(KSS_CAP_FROB)
            IF (DBG_AUDIT_MODE_CODE .GT. 0.5D0) THEN
               IF (DBG_AUDIT_MODE_CODE .LT. 1.5D0) THEN
                  IF (DBG_FIELD_CAPACITY_AUDIT_RS_DONE .LT. 0.5D0) THEN
               WRITE(*,*) 'FIELD_CAPACITY_G1_ACTIVE = 1'
               WRITE(*,*) 'DBG_FIELD_CAPACITY_REG = ',
     1              DBG_FIELD_CAPACITY_REG
               WRITE(*,*) 'DBG_FIELD_CAPACITY_ETA = ',
     1              DBG_FIELD_CAPACITY_ETA
               WRITE(*,*) 'DBG_S_CAPACITY_ETA     = ',
     1              DBG_S_CAPACITY_ETA
               WRITE(*,*) 'DTIME                  = ', DTIME
               WRITE(*,*) 'PHI_GP                 = ', PHI_GP
               WRITE(*,*) 'SN_GP                  = ', SN_GP
               WRITE(*,*) 'SN_OLD                 = ', SN_OLD
               WRITE(*,*) 'CAP_S_EPS              = ', CAP_S_EPS
               WRITE(*,*) '||Kss_cap||_F          = ', KSS_CAP_FROB
                     DBG_FIELD_CAPACITY_AUDIT_RS_DONE = 1.0D0
                  END IF
               ELSE IF (KINC .EQ. 1) THEN
                  WRITE(*,*) 'FIELD_CAPACITY_G1_ACTIVE = 1'
                  WRITE(*,*) 'DBG_FIELD_CAPACITY_REG = ',
     1                 DBG_FIELD_CAPACITY_REG
                  WRITE(*,*) 'DBG_FIELD_CAPACITY_ETA = ',
     1                 DBG_FIELD_CAPACITY_ETA
                  WRITE(*,*) 'DBG_S_CAPACITY_ETA     = ',
     1                 DBG_S_CAPACITY_ETA
                  WRITE(*,*) 'DTIME                  = ', DTIME
                  WRITE(*,*) 'PHI_GP                 = ', PHI_GP
                  WRITE(*,*) 'SN_GP                  = ', SN_GP
                  WRITE(*,*) 'SN_OLD                 = ', SN_OLD
                  WRITE(*,*) 'CAP_S_EPS              = ', CAP_S_EPS
                  WRITE(*,*) '||Kss_cap||_F          = ', KSS_CAP_FROB
               END IF
            END IF
         END IF
      END IF

C ============================================================
C 10b. Soft anchor support for saturation block
C      eps_s_anchor = eta_s_anchor * PHI_GP / DTIME
C      Rs_anchor = int N_a eps_s_anchor (Sn - Sn_ref) dV
C      Kss_anchor = int N_a eps_s_anchor N_b dV
C ============================================================
      IF (DBG_S_ANCHOR_REG .GT. 0.5D0 .AND. HAS_TIME_TERMS
     1    .AND. DTIME .GT. 0.0D0) THEN
         CAP_S_ANCHOR_EPS = DBG_S_ANCHOR_ETA * PHI_GP / DTIME
         IF (CAP_S_ANCHOR_EPS .GT. 0.0D0) THEN
            KSS_ANCHOR_FROB = 0.0D0
            DO I = 1, 4
               RS(I) = RS(I)
     1               + N(I) * CAP_S_ANCHOR_EPS
     2               * (SN_GP - SN_REF) * DVOL
               DO J = 1, 4
                  KSS_TERM = N(I) * CAP_S_ANCHOR_EPS * N(J) * DVOL
                  KSS(I,J) = KSS(I,J) + KSS_TERM
                  WP10I3_KSS_ANCHOR(I,J) =
     1               WP10I3_KSS_ANCHOR(I,J) + KSS_TERM
                  KSS_ANCHOR_FROB = KSS_ANCHOR_FROB
     1                         + KSS_TERM**2
               END DO
            END DO
            KSS_ANCHOR_FROB = DSQRT(KSS_ANCHOR_FROB)
            IF (DBG_AUDIT_MODE_CODE .GT. 0.5D0) THEN
               IF (DBG_AUDIT_MODE_CODE .LT. 1.5D0) THEN
                  IF (DBG_FIELD_ANCHOR_AUDIT_RS_DONE .LT. 0.5D0) THEN
               WRITE(*,*) 'FIELD_ANCHOR_G2_ACTIVE = 1'
               WRITE(*,*) 'DBG_FIELD_ANCHOR_REG = ',
     1              DBG_FIELD_ANCHOR_REG
               WRITE(*,*) 'DBG_FIELD_ANCHOR_ETA = ',
     1              DBG_FIELD_ANCHOR_ETA
               WRITE(*,*) 'DBG_S_ANCHOR_ETA     = ',
     1              DBG_S_ANCHOR_ETA
               WRITE(*,*) 'DBG_S_ANCHOR_SNREF   = ',
     1              DBG_S_ANCHOR_SNREF
               WRITE(*,*) 'DTIME                  = ', DTIME
               WRITE(*,*) 'PHI_GP                 = ', PHI_GP
               WRITE(*,*) 'SN_REF                 = ', SN_REF
               WRITE(*,*) 'CAP_S_ANCHOR_EPS       = ',
     1              CAP_S_ANCHOR_EPS
               WRITE(*,*) '||Kss_anchor||_F       = ',
     1              KSS_ANCHOR_FROB
                     DBG_FIELD_ANCHOR_AUDIT_RS_DONE = 1.0D0
                  END IF
               ELSE IF (KINC .EQ. 1) THEN
                  WRITE(*,*) 'FIELD_ANCHOR_G2_ACTIVE = 1'
                  WRITE(*,*) 'DBG_FIELD_ANCHOR_REG = ',
     1                 DBG_FIELD_ANCHOR_REG
                  WRITE(*,*) 'DBG_FIELD_ANCHOR_ETA = ',
     1                 DBG_FIELD_ANCHOR_ETA
                  WRITE(*,*) 'DBG_S_ANCHOR_ETA     = ',
     1                 DBG_S_ANCHOR_ETA
                  WRITE(*,*) 'DBG_S_ANCHOR_SNREF   = ',
     1                 DBG_S_ANCHOR_SNREF
                  WRITE(*,*) 'DTIME                  = ', DTIME
                  WRITE(*,*) 'PHI_GP                 = ', PHI_GP
                  WRITE(*,*) 'SN_REF                 = ', SN_REF
                  WRITE(*,*) 'CAP_S_ANCHOR_EPS       = ',
     1                 CAP_S_ANCHOR_EPS
                  WRITE(*,*) '||Kss_anchor||_F       = ',
     1                 KSS_ANCHOR_FROB
               END IF
            END IF
         END IF
      END IF

C ============================================================
C 11. Weak diagonal regularization for saturation block
C     Rs_reg = eps_s * (sn - sn_old)
C     Kss_reg = Kss + eps_s * I
C ============================================================
      IF (DBG_REG_S_DIAG .GT. 0.5D0 .AND. HAS_TIME_TERMS) THEN
         REG_S_EPS = DBG_S_REG_SCALE * CSN / DTIME
         DO I = 1, 4
            RS(I) = RS(I) + REG_S_EPS * (SN_GP - SN_OLD) * DVOL
            KSS_TERM = REG_S_EPS * DVOL
            KSS(I,I) = KSS(I,I) + KSS_TERM
            WP10I3_KSS_DIAG(I,I) =
     1         WP10I3_KSS_DIAG(I,I) + KSS_TERM
         END DO
      END IF

      CP165_RS_EXIT_HIT = 1

      RETURN
      END


C ================================================================
C Select immutable committed capillary reference state.
C No SAVE, module or file state is permitted in this routine.
C ================================================================
      SUBROUTINE UPS_CAPREF_COMMITTED_SELECT(CAP_REF_IN,
     1 CAP_REF_VALID_IN, PEQ_OLD, PW_OLD, CAP_REF_USE,
     2 CAP_REF_VALID_OUT, CAP_REF_FALLBACK_FLAG)
      IMPLICIT NONE
      DOUBLE PRECISION CAP_REF_IN, CAP_REF_VALID_IN
      DOUBLE PRECISION PEQ_OLD, PW_OLD, CAP_REF_USE
      DOUBLE PRECISION CAP_REF_VALID_OUT, CAP_REF_FALLBACK_FLAG

      CAP_REF_FALLBACK_FLAG = 0.0D0
      IF (CAP_REF_VALID_IN .GE. 0.5D0) THEN
         CAP_REF_USE = CAP_REF_IN
      ELSE
         CAP_REF_USE = PEQ_OLD - PW_OLD
         CAP_REF_FALLBACK_FLAG = 1.0D0
      END IF
      CAP_REF_VALID_OUT = 1.0D0

      RETURN
      END


C ================================================================
C Build new state vector for one gauss point
C Layout:
C 1 PW, 2 SN, 3 SW, 4 PC, 5 PEQ, 6 EPSV,
C 7 PHI, 8 KABS, 9 CF, 10 SIGXX, 11 SIGYY, 12 SIGXY,
C Per-element SVARS are packed as four Gauss-point blocks:
C   element SVARS index = (IGP-1)*NSVARGP + local_index
C   NSVARGP = 48 and NGAUSS = 4, so Abaqus Variables must be >= 192.
C The local per-GP map currently used by the UEL is:
C  1 PW_OLD, 2 SN_OLD, 3 SW_OLD, 4 PC_OLD, 5 PEQ_OLD
C  6 EPSV_OLD, 7 PHI_OLD, 8 KABS_OLD, 9 CF_OLD
C 10 SIGEFF_XX_OLD, 11 SIGEFF_YY_OLD, 12 SIGEFF_XY_OLD
C 13 CAP_REF, 14 CAPREF_INIT_FLAG
C 15:32 diagnostic slots, not persistent physics state.
C 33 OUT_PW, 34 OUT_SN, 35 OUT_PC, 36 OUT_PEQ, 37 OUT_KABS
C 38 OUT_EPSV, 39 OUT_SIGXX, 40 OUT_SIGYY, 41 OUT_SIGXY
C 42 OUT_VALID, 43 OUT_SOURCE, 44 OUT_TIME, 45 OUT_KINC
C 46:48 reserved OUT-state slots.
C ================================================================
C The state layout is fixed intentionally. Future developers should
C append new quantities only after this block, so the meaning of the
C first 14 entries remains stable across versions.
      SUBROUTINE UPS_BUILD_SVARS_NEW(PW_GP, SN_GP, SW_GP, PC_GP,
     1 PEQ_GP, EPSV_GP, PHI_GP, KABS_GP, CF_GP, SIGEFF_GP,
     2 CAP_REF_USE, CAP_REF_VALID_OUT, SV_GP_NEW)

      IMPLICIT NONE
      INTEGER I
      DOUBLE PRECISION PW_GP, SN_GP, SW_GP, PC_GP, PEQ_GP
      DOUBLE PRECISION EPSV_GP, PHI_GP, KABS_GP, CF_GP
      DOUBLE PRECISION SIGEFF_GP(3), SV_GP_NEW(48)
      DOUBLE PRECISION CAP_REF_USE, CAP_REF_VALID_OUT

      SV_GP_NEW(1)  = PW_GP
      SV_GP_NEW(2)  = SN_GP
      SV_GP_NEW(3)  = SW_GP
      SV_GP_NEW(4)  = PC_GP
      SV_GP_NEW(5)  = PEQ_GP
      SV_GP_NEW(6)  = EPSV_GP
      SV_GP_NEW(7)  = PHI_GP
      SV_GP_NEW(8)  = KABS_GP
      SV_GP_NEW(9)  = CF_GP
      SV_GP_NEW(10) = SIGEFF_GP(1)
      SV_GP_NEW(11) = SIGEFF_GP(2)
      SV_GP_NEW(12) = SIGEFF_GP(3)
      SV_GP_NEW(13) = CAP_REF_USE
      SV_GP_NEW(14) = CAP_REF_VALID_OUT
      DO I = 15, 48
         SV_GP_NEW(I) = 0.0D0
      END DO

      RETURN
      END


C ================================================================
C Read one gauss-point state block
C ================================================================
C The read/write pair below centralises all SVARS indexing logic. If
C the state storage ever changes, these two routines should be updated
C together, not scattered through the main UEL body.
      SUBROUTINE UPS_SVARS_READ(SVARS, NSVARS, IGP, NSVARGP, SV_GP_OLD)
      IMPLICIT NONE
      INTEGER NSVARS, IGP, NSVARGP, I, IOFF
      DOUBLE PRECISION SVARS(NSVARS), SV_GP_OLD(NSVARGP)

      IOFF = (IGP-1)*NSVARGP

      DO I = 1, NSVARGP
         IF (IOFF + I .LE. NSVARS) THEN
            SV_GP_OLD(I) = SVARS(IOFF + I)
         ELSE
            SV_GP_OLD(I) = 0.0D0
         END IF
      END DO

      RETURN
      END


C ================================================================
C Write one gauss-point state block
C ================================================================
      SUBROUTINE UPS_SVARS_WRITE(SVARS, NSVARS, IGP, NSVARGP, SV_GP_NEW)
      IMPLICIT NONE
      INTEGER NSVARS, IGP, NSVARGP, I, IOFF
      DOUBLE PRECISION SVARS(NSVARS), SV_GP_NEW(NSVARGP)

      IOFF = (IGP-1)*NSVARGP

      DO I = 1, NSVARGP
         IF (IOFF + I .LE. NSVARS) THEN
            SVARS(IOFF + I) = SV_GP_NEW(I)
         END IF
      END DO

      RETURN
      END


C ================================================================
C Sanitize a Gauss-point state block for pivot-ring diagnostics
C ================================================================
      SUBROUTINE UPS_SANITIZE_SVARS_BLOCK(SV_GP_OLD, NSVARGP,
     1     PW_SAFE, KABS_SAFE, NREPLACED)
      IMPLICIT NONE
      INTEGER NSVARGP, NREPLACED, I
      DOUBLE PRECISION SV_GP_OLD(NSVARGP)
      DOUBLE PRECISION PW_SAFE, KABS_SAFE
      DOUBLE PRECISION SN_SAFE, SW_SAFE, PC_SAFE, PEQ_SAFE
      DOUBLE PRECISION EPSV_SAFE, PHI_SAFE, CF_SAFE
      DOUBLE PRECISION SIGEFF_SAFE
      LOGICAL BAD

      SN_SAFE    = 0.1D0
      SW_SAFE    = 0.9D0
      PC_SAFE    = 0.0D0
      PEQ_SAFE   = 0.0D0
      EPSV_SAFE  = 0.0D0
      PHI_SAFE   = 0.15D0
      CF_SAFE    = 1.0D-9
      SIGEFF_SAFE = 0.0D0
      NREPLACED = 0

      DO I = 1, NSVARGP
         BAD = (SV_GP_OLD(I) .NE. SV_GP_OLD(I)) .OR.
     1         (DABS(SV_GP_OLD(I)) .GT. 1.0D100)
         IF (.NOT. BAD) CYCLE
         NREPLACED = NREPLACED + 1
         IF (I .EQ. 1) THEN
            SV_GP_OLD(I) = PW_SAFE
         ELSE IF (I .EQ. 2) THEN
            SV_GP_OLD(I) = SN_SAFE
         ELSE IF (I .EQ. 3) THEN
            SV_GP_OLD(I) = SW_SAFE
         ELSE IF (I .EQ. 4) THEN
            SV_GP_OLD(I) = PC_SAFE
         ELSE IF (I .EQ. 5) THEN
            SV_GP_OLD(I) = PEQ_SAFE
         ELSE IF (I .EQ. 6) THEN
            SV_GP_OLD(I) = EPSV_SAFE
         ELSE IF (I .EQ. 7) THEN
            SV_GP_OLD(I) = PHI_SAFE
         ELSE IF (I .EQ. 8) THEN
            SV_GP_OLD(I) = KABS_SAFE
         ELSE IF (I .EQ. 9) THEN
            SV_GP_OLD(I) = CF_SAFE
         ELSE IF (I .EQ. 10 .OR. I .EQ. 11 .OR. I .EQ. 12) THEN
            SV_GP_OLD(I) = SIGEFF_SAFE
         ELSE IF (I .EQ. 13) THEN
            SV_GP_OLD(I) = PEQ_SAFE
         ELSE
            SV_GP_OLD(I) = 0.0D0
         END IF
      END DO

      RETURN
      END


C ================================================================
C Scatter block residual/tangent to node-major ordering
C ================================================================
C The scattering routine is the final bridge between the block form
C used in the derivation and the flat 16x16 matrix required by Abaqus.
C The explicit index arrays IU/IP/IS keep the mapping obvious.
      SUBROUTINE UPS_SCATTER_TO_ELEMENT(RU, RP, RS,
     1 KUU, KUP, KUS, KPU, KPP, KPS, KSU, KSP, KSS,
     2 IU, IP, IS, RE, KE)

      IMPLICIT NONE
      INTEGER I, J
      INTEGER IU(8), IP(4), IS(4)
      DOUBLE PRECISION RU(8), RP(4), RS(4), RE(16)
      DOUBLE PRECISION KE(16,16)
      DOUBLE PRECISION KUU(8,8), KUP(8,4), KUS(8,4)
      DOUBLE PRECISION KPU(4,8), KPP(4,4), KPS(4,4)
      DOUBLE PRECISION KSU(4,8), KSP(4,4), KSS(4,4)

      CALL UPS_ZERO_VEC(RE,16)
      CALL UPS_ZERO_MAT(KE,16,16)

C --- residual
      DO I = 1, 8
         RE(IU(I)) = RE(IU(I)) + RU(I)
      END DO
      DO I = 1, 4
         RE(IP(I)) = RE(IP(I)) + RP(I)
         RE(IS(I)) = RE(IS(I)) + RS(I)
      END DO

C --- KUU
      DO I = 1, 8
         DO J = 1, 8
            KE(IU(I),IU(J)) = KE(IU(I),IU(J)) + KUU(I,J)
         END DO
      END DO

C --- KUP, KUS
      DO I = 1, 8
         DO J = 1, 4
            KE(IU(I),IP(J)) = KE(IU(I),IP(J)) + KUP(I,J)
            KE(IU(I),IS(J)) = KE(IU(I),IS(J)) + KUS(I,J)
         END DO
      END DO

C --- KPU, KPP, KPS
      DO I = 1, 4
         DO J = 1, 8
            KE(IP(I),IU(J)) = KE(IP(I),IU(J)) + KPU(I,J)
         END DO
         DO J = 1, 4
            KE(IP(I),IP(J)) = KE(IP(I),IP(J)) + KPP(I,J)
            KE(IP(I),IS(J)) = KE(IP(I),IS(J)) + KPS(I,J)
         END DO
      END DO

C --- KSU, KSP, KSS
      DO I = 1, 4
         DO J = 1, 8
            KE(IS(I),IU(J)) = KE(IS(I),IU(J)) + KSU(I,J)
         END DO
         DO J = 1, 4
            KE(IS(I),IP(J)) = KE(IS(I),IP(J)) + KSP(I,J)
            KE(IS(I),IS(J)) = KE(IS(I),IS(J)) + KSS(I,J)
         END DO
      END DO

      RETURN
      END


C ================================================================
C Build debug probe path in the current TEMP/TMP directory
C ================================================================
      SUBROUTINE UPS_BUILD_DBG_PATH(DBG_PATH)
      IMPLICIT NONE
      CHARACTER*(*) DBG_PATH
      DBG_PATH = 'C:/Users/Ldd/AppData/Local/Temp/dbg_mech_probe.txt'
      RETURN
      END


C ================================================================
C Copy residual to RHS
C ================================================================
C Abaqus expects RHS in its own storage shape, so we perform a direct
C copy after block assembly. No extra physics should happen here.
      SUBROUTINE UPS_COPY_RE_TO_RHS(RE, RHS, MLVARX, NRHS, NDOFEL)
      IMPLICIT NONE
      INTEGER MLVARX, NRHS, NDOFEL, I, IOS
      DOUBLE PRECISION RE(NDOFEL), RHS(MLVARX,NRHS)
      DOUBLE PRECISION RHS_SIGN
      CHARACTER*32 RHS_SIGN_TAG

      RHS_SIGN = -1.0D0
      RHS_SIGN_TAG = ' '
      CALL GET_ENVIRONMENT_VARIABLE('DBG_MECH_RHS_SIGN',
     1                              RHS_SIGN_TAG)
      IF (RHS_SIGN_TAG(1:1) .NE. ' ') THEN
         READ(RHS_SIGN_TAG,*,IOSTAT=IOS) RHS_SIGN
         IF (IOS .NE. 0) RHS_SIGN = -1.0D0
      END IF

      DO I = 1, NDOFEL
         RHS(I,1) = RHS_SIGN * RE(I)
      END DO

      RETURN
      END


C ================================================================
C Copy tangent to AMATRX
C ================================================================
C This dense copy is intentionally simple. It makes the first version
C of the skeleton easy to verify and avoids premature optimisation.
      SUBROUTINE UPS_COPY_KE_TO_AMATRX(KE, AMATRX, NDOFEL)
      IMPLICIT NONE
      INTEGER NDOFEL, I, J
      DOUBLE PRECISION KE(NDOFEL,NDOFEL), AMATRX(NDOFEL,NDOFEL)

      DO I = 1, NDOFEL
         DO J = 1, NDOFEL
            AMATRX(I,J) = KE(I,J)
         END DO
      END DO

      RETURN
      END










